var e=`{"ch/1/title":"現在與過去","ch/2/title":"現在完成與過去","ch/3/title":"未來","ch/4/title":"助動詞 · 祈使句","ch/5/title":"條件句 · 假設語氣","ch/6/title":"被動語態","ch/7/title":"間接引述","ch/8/title":"疑問句 · 助動詞","ch/9/title":"動名詞 · 不定詞","ch/10/title":"冠詞 · 名詞","ch/11/title":"代名詞 · 限定詞","ch/12/title":"關係子句","ch/13/title":"形容詞 · 副詞","ch/14/title":"連接詞 · 介系詞","g1/title":"正在做的事","g1/summary":"現在 · 最近正在做的事用 am / is / are + -ing","g1/forms.0.label":"肯定","g1/forms.1.label":"否定","g1/forms.2.label":"疑問","g1/points.0.h":"和中文不同的地方","g1/points.0.t":"中文會說\\"我現在吃飯\\"，用\\"正在\\"\\"著\\"表示進行中。英文的 I eat 是\\"平常會吃\\"的意思，所以現在正在吃要說 I'm eating。","g1/points.1.h":"\\"最近\\"也可以","g1/points.1.t":"不一定是剛好這一刻，最近在做的事也用進行式。I'm learning English these days. 即使此刻沒有在讀書也可以。","g1/points.2.h":"-ing 的加法","g1/points.2.t":"大多數直接加 (work → working)。以 e 結尾要去掉 e (make → making)。以短母音 + 一個子音結尾，要重複子音 (sit → sitting, run → running)。","g1/examples.0.ko":"我現在正在看書。","g1/examples.1.ko":"他正在講電話。","g1/examples.2.ko":"我們正在等公車。","g1/examples.3.ko":"他們這週在家上班。","g1/examples.4.ko":"你有在聽我說話嗎？","g1/mistake.why":"很容易只加 -ing 而漏掉 am · is · are。進行式一定要有 be 動詞。","g1/quiz.0.ko":"聽！有人在敲門。","g1/quiz.0.why":"Listen! 是\\"現在聽得到\\"的訊號。是正在進行的事，所以用 is knocking。","g1/quiz.1.ko":"安靜點！寶寶在睡覺。","g1/quiz.1.why":"現在正在睡，主詞 the baby 是單數，所以用 is sleeping。只寫 sleeping 會漏掉 be 動詞。","g1/quiz.2.q":"\\"現在正在下雨。\\"用英文怎麼說？","g1/quiz.2.why":"現在正在下，所以用 is raining。It rains 的意思是\\"(那裡) 常常下雨\\"。","g1/quiz.3.ko":"你有在聽我說話嗎？","g1/quiz.3.why":"you 的 be 動詞是 are。進行式的疑問句要把 be 動詞移到最前面。","g1/quiz.4.ko":"我正坐在公司附近的咖啡廳裡。","g1/quiz.4.why":"sit 以短母音 + 一個子音結尾，所以 t 要再寫一次。sitting。","g2/title":"經常做的事","g2/summary":"經常 · 常做的事、一直如此的事實用動詞原形。he · she · it 要加 -s","g2/forms.0.label":"肯定","g2/forms.1.label":"否定","g2/forms.2.label":"疑問","g2/points.0.h":"用在哪裡","g2/points.0.t":"用於習慣(I drink coffee every morning)、日常作息 · 職業(She works at a hospital)、一直如此的事實(Water boils at 100 degrees)。不是此刻，而是\\"平常\\"的事。","g2/points.1.h":"he · she · it 要加 -s","g2/points.1.t":"主詞不是我 · 你 · 我們 · 他們，而是\\"一個人 · 一個東西\\"時，動詞要加 -s。這是中文沒有的規則，所以最常出錯。以 -s · -sh · -ch · -o 結尾加 -es，子音 + y 結尾變 -ies，have 變 has。","g2/points.2.h":"否定 · 疑問用 do · does","g2/points.2.t":"用了 does，-s 就由 does 負責，動詞要回到原形。She doesn't works ✕ → She doesn't work ○。","g2/points.3.h":"常搭配的詞","g2/points.3.t":"很適合搭配 always · usually · often · sometimes · never、every day、on weekends 這類表示\\"多常發生\\"的詞。","g2/examples.0.ko":"我每天早上都喝咖啡。","g2/examples.1.ko":"Jake 住在布魯克林。","g2/examples.2.ko":"辦公室 9 點開門。","g2/examples.3.ko":"她不吃肉。","g2/examples.4.ko":"你搭地鐵上班嗎？","g2/mistake.why":"主詞是 he · she · it 時，動詞要加 -s。說的時候也一定要發出 -s 的音。","g2/quiz.0.ko":"我姊姊在銀行工作。","g2/quiz.0.why":"my sister 是 she，所以用 works。","g2/quiz.1.ko":"我不喜歡咖啡，只喝茶。","g2/quiz.1.why":"主詞是 I，所以用 don't + 原形。","g2/quiz.2.ko":"Jake 住在布魯克林嗎？","g2/quiz.2.why":"Jake 是 he，所以用 Does。動詞回到原形 live。","g2/quiz.3.ko":"那家店星期日晚上 10 點關門。","g2/quiz.3.why":"是固定的時間表，而且 the store 是 it，所以用 closes。","g2/quiz.4.q":"\\"他不吃肉。\\"用英文怎麼說？","g2/quiz.4.why":"he 用 doesn't，後面的動詞是原形 eat。","g3/title":"進行 vs 簡單，不用進行式的動詞","g3/summary":"現在 · 暫時的事用 -ing，平常 · 一直如此的事用原形。know · want · like 這類\\"狀態\\"不用 -ing","g3/forms.0.label":"暫時 · 現在","g3/forms.1.label":"平常 · 一直","g3/points.0.h":"是暫時，還是一直","g3/points.0.t":"I'm living with a friend 是\\"暫時和朋友住\\"，I live in Seoul 是\\"住在首爾\\"(一直)。有 today · this week · now 時適合 -ing，有 usually · every day 時適合原形。","g3/points.1.h":"不用進行式的動詞","g3/points.1.t":"心情 · 想法 · 擁有這類\\"狀態\\"不會\\"正在進行\\"，所以不用 -ing。know · understand · believe · want · need · like · love · hate · mean · belong。I know ○ · I'm knowing ✕。","g3/points.2.h":"依意思兩種都可以","g3/points.2.t":"have 是\\"擁有\\"時是狀態(I have a car)，是\\"吃 · 度過\\"時是動作(I'm having lunch)。think 也是，\\"認為\\"用 I think she's right，\\"考慮中\\"用 I'm thinking about it。","g3/examples.0.ko":"我平常走路上班，今天搭計程車。","g3/examples.1.ko":"她在醫院工作。現在正在睡覺。","g3/examples.2.ko":"我懂你的意思。","g3/examples.3.ko":"我正在和 Jake 吃午餐。等一下可以再打給你嗎？","g3/examples.4.ko":"你覺得呢？ — 我正在考慮。","g3/mistake.why":"know 是\\"已經知道的狀態\\"，所以不用 -ing。I'm knowing 是錯的。","g3/quiz.0.ko":"我懂你的意思。","g3/quiz.0.why":"know 是狀態，不用進行式。主詞是 I，所以用 know。","g3/quiz.1.ko":"Rosa 通常晚上工作，但這週是白天工作。","g3/quiz.1.why":"usually 是平常，所以用 works；this week 是暫時，所以用 is working。","g3/quiz.2.ko":"噓！我正在聽廣播。","g3/quiz.2.why":"Shh! 是正在進行的訊號。am listening。","g3/quiz.3.ko":"抱歉，我現在不能講電話。我正在吃晚餐。","g3/quiz.3.why":"have 是\\"吃\\"這個動作時，可以用進行式。","g3/quiz.4.ko":"這個包包是我的。","g3/quiz.4.why":"belong(屬於)是狀態，不用 -ing。this bag 是 it，所以用 belongs。","g4/title":"過去簡單式","g4/summary":"已經結束的過去之事用動詞過去式。規則動詞加 -ed，不規則動詞要另外記","g4/forms.0.label":"肯定","g4/forms.1.label":"否定","g4/forms.2.label":"疑問","g4/points.0.h":"什麼時候用","g4/points.0.t":"yesterday · last week · in 2020 · two days ago 這類\\"結束的時間\\"很明確的事。當時發生，當時就結束了。","g4/points.1.h":"規則動詞 -ed","g4/points.1.t":"work → worked, live → lived (以 e 結尾只加 -d), study → studied (子音 + y → -ied), stop → stopped (短母音 + 子音 → 重複子音)。發音有 [t] · [d] · [id] 三種 (worked · lived · wanted)。","g4/points.2.h":"不規則動詞","g4/points.2.t":"越常用的動詞越是不規則。go → went, see → saw, come → came, get → got, have → had, make → made, take → took, tell → told。多聽多說來熟悉。","g4/points.3.h":"用了 did 就用原形","g4/points.3.t":"否定 · 疑問句中，did 已經表示過去。所以後面的動詞是原形。Did you went? ✕ → Did you go? ○","g4/examples.0.ko":"我上週搬到紐約了。","g4/examples.1.ko":"我們晚餐吃了披薩。","g4/examples.2.ko":"他沒來參加派對。","g4/examples.3.ko":"你睡得好嗎？","g4/examples.4.ko":"我兩天前見過他。","g4/mistake.why":"did 已經表示過去，所以後面的動詞是原形。","g4/quiz.0.ko":"昨晚我看了一部很棒的電影。","g4/quiz.0.why":"last night 是已結束的時間。see 的過去式是 saw (不規則)。","g4/quiz.1.ko":"她 2020 年住在首爾。","g4/quiz.1.why":"in 2020 是已結束的時間。live 以 e 結尾，所以只加 -d。","g4/quiz.2.ko":"你昨天打電話給我了嗎？","g4/quiz.2.why":"問過去的事時用 Did + 原形。","g4/quiz.3.ko":"我們今天早上沒有錯過公車。","g4/quiz.3.why":"didn't 後面接原形 miss。","g4/quiz.4.q":"\\"我昨天很早就睡了。\\"用英文怎麼說？","g4/quiz.4.why":"go 的過去式是 went。沒有 goed 這個字。","g5/title":"過去進行式","g5/summary":"過去某個時間點正在做的事用 was / were + -ing","g5/forms.0.label":"肯定","g5/forms.1.label":"否定","g5/forms.2.label":"疑問","g5/points.0.h":"用在哪裡","g5/points.0.t":"是過去\\"那時\\"正在進行的事。At 10 last night, I was watching TV 的意思是昨晚 10 點那一刻正在看電視。可能在那之前就開始，之後也還在繼續。","g5/points.1.h":"和過去簡單式的差別","g5/points.1.t":"I watched TV 是\\"看了電視\\"(從頭到尾做完的事)，I was watching TV 是\\"那時正在看電視\\"(在那一刻的當中)。","g5/points.2.h":"選 was · were","g5/points.2.t":"I · he · she · it 用 was，we · you · they 用 were。不用進行式的動詞(know · want · like)在過去也不用 -ing。I knew ○ · I was knowing ✕","g5/examples.0.ko":"昨晚 10 點我正在看電視。","g5/examples.1.ko":"雨下了一整個早上。","g5/examples.2.ko":"午休時你在做什麼？","g5/examples.3.ko":"我們不是在講你！","g5/examples.4.ko":"她穿著一件紅色洋裝。","g5/mistake.why":"we · you · they 要用 were。說話時很容易含糊成 was。","g5/quiz.0.ko":"早上 8 點我正在吃早餐。","g5/quiz.0.why":"是過去某一刻正在做的事，主詞是 I，所以用 was having。","g5/quiz.1.ko":"午夜時你在做什麼？","g5/quiz.1.why":"you 用 were。","g5/quiz.2.ko":"他們 7 點時正在等公車。","g5/quiz.2.why":"they 用 were，後面接 -ing。","g5/quiz.3.ko":"抱歉，我剛才沒在聽。可以再說一次嗎？","g5/quiz.3.why":"剛才沒在聽 = I wasn't listening。","g5/quiz.4.q":"\\"昨天這個時候我正在工作。\\"用英文怎麼說？","g5/quiz.4.why":"是過去某一刻正在做的事，所以用 was working。","g6/title":"過去簡單式 vs 過去進行式","g6/summary":"長時間在做的事(was -ing)中，有短暫的事(過去式)插進來。while 後面常接進行中的事，when 後面常接短暫的事","g6/forms.0.label":"進行中 + 插入的事","g6/forms.1.label":"依序發生的事","g6/points.0.h":"長的事 vs 短的事","g6/points.0.t":"像背景一樣持續的事用 was / were -ing，在其中\\"忽然\\"發生的事用過去式。I was taking a shower when the lights went out.","g6/points.1.h":"when 和 while","g6/points.1.t":"while 是\\"在……期間\\"，後面常接進行中的事(-ing)。when 後面常接短暫的事。放在句首時要加逗號。","g6/points.2.h":"兩個都用過去式的話","g6/points.2.t":"When he came in, everyone stood up. 是\\"他一進來大家就站起來\\"(依序發生)。When he came in, everyone was standing. 是\\"他進來時大家已經站著了\\"。","g6/examples.0.ko":"我正在煮飯時電話響了。","g6/examples.1.ko":"她走路回家時開始下雨了。","g6/examples.2.ko":"我們正在看電影時停電了。","g6/examples.3.ko":"我看到他的時候，他正在講電話。","g6/examples.4.ko":"老闆一進來，大家就不說話了。","g6/mistake.why":"長時間在做的事(煮飯)用 -ing，忽然插進來的事(電話)用過去式。顛倒過來會很不自然。","g6/quiz.0.ko":"你打電話來的時候我正在看電視。","g6/quiz.0.why":"在電話插進來之前就已經在看了，所以用 was watching。","g6/quiz.1.ko":"我們吃晚餐時停電了。","g6/quiz.1.why":"while 後面接進行中的事。we 用 were。","g6/quiz.2.ko":"我回到家時她正在睡覺。","g6/quiz.2.why":"在我回來之前她就已經在睡了，所以用 was sleeping。","g6/quiz.3.ko":"她一打開門就發現了一個大箱子。","g6/quiz.3.why":"是開門之後依序發生的事，所以兩個都用過去式。","g6/quiz.4.q":"\\"走著走著跌倒了。\\"用英文怎麼說？","g6/quiz.4.why":"在走路中(was walking)，跌倒(fell)插了進來。","g7/title":"現在完成式 ① 經驗 · 結果","g7/summary":"過去的事和現在有關聯時用 have / has + 過去分詞。表示有沒有做過(經驗)，以及所以現在如何(結果)","g7/forms.0.label":"肯定","g7/forms.1.label":"否定 · 疑問","g7/forms.2.label":"過去分詞","g7/points.0.h":"中文沒有的時態","g7/points.0.t":"中文用一個\\"看過了\\"就能全部表達，但英文在重視\\"什麼時候看的\\"時用過去式(I saw it yesterday)，重視\\"到現在有沒有看過 · 所以現在如何\\"時用現在完成式(I've seen it)。","g7/points.1.h":"經驗","g7/points.1.t":"用 Have you ever…? / I've never… 來說\\"你有沒有做過……？\\"。不說是什麼時候。I've been to Japan twice.","g7/points.2.h":"結果","g7/points.2.t":"表示因為過去的事，所以現在是這樣。I've lost my keys 是\\"弄丟了，所以現在沒有\\"。I lost my keys 只是說弄丟過這件事 (現在可能已經找到了)。","g7/points.3.h":"been 和 gone","g7/points.3.t":"She's been to Paris 是\\"去過\\"(已經回來了)，She's gone to Paris 是\\"去巴黎了\\"(現在人在那裡)。","g7/examples.0.ko":"你有去看過棒球比賽嗎？","g7/examples.1.ko":"我從來沒吃過墨西哥菜。","g7/examples.2.ko":"糟了，我的皮夾不見了！","g7/examples.3.ko":"她那部電影看了三遍。","g7/examples.4.ko":"他回家了。不在這裡。","g7/mistake.why":"如果說出像 yesterday 這樣已結束的時間，就不是現在完成式，而是過去式 (第 11 課會詳細說明)。","g7/quiz.0.ko":"你吃過泡菜嗎？","g7/quiz.0.why":"問經驗用 Have you ever + 過去分詞。","g7/quiz.1.ko":"我手機不見了。可以用你的嗎？","g7/quiz.1.why":"是弄丟所以現在沒有的結果，用 have lost。","g7/quiz.2.ko":"她去過倫敦兩次。","g7/quiz.2.why":"去過的經驗用 has been to。she 用 has。","g7/quiz.3.ko":"我從來沒騎過馬。","g7/quiz.3.why":"have 後面接過去分詞 ridden。","g7/quiz.4.ko":"Tom 在哪？ — 他去商店了。馬上就回來。","g7/quiz.4.why":"去了所以現在不在這裡，用 has gone。","g8/title":"現在完成式 ② just · already · yet","g8/summary":"剛剛(just) · 已經(already) · 還(yet)很適合搭配現在完成式","g8/forms.0.items.0":"I've just finished. (剛剛)","g8/forms.1.items.0":"She's already left. (已經)","g8/forms.2.items.0":"Have you eaten yet? (已經了嗎)","g8/forms.2.items.1":"I haven't eaten yet. (還沒)","g8/points.0.h":"just = 剛剛","g8/points.0.t":"放在 have 和過去分詞之間。I've just sent it. 在美式英文中，也常像 I just sent it 這樣用過去式。","g8/points.1.h":"already = 已經","g8/points.1.t":"有\\"比預期更早發生\\"的感覺。位置和 just 一樣。The movie has already started.","g8/points.2.h":"yet = 已經了嗎 · 還沒","g8/points.2.t":"疑問句中是\\"已經……了嗎\\"，否定句中是\\"還沒\\"。一定放在句尾。Have you finished yet? / I haven't finished yet.","g8/points.3.h":"常見的錯誤","g8/points.3.t":"\\"還沒吃\\"很容易說成 I didn't eat yet，但基本說法是 I haven't eaten yet。美式口語中也聽得到 didn't … yet。","g8/examples.0.ko":"我剛剛把檔案寄出去了。","g8/examples.1.ko":"會議已經開始了。","g8/examples.2.ko":"你吃午餐了嗎？","g8/examples.3.ko":"我還沒決定。","g8/examples.4.ko":"她已經看過新的 logo 了。","g8/mistake.why":"already 要放在 have 和過去分詞之間。不要插在受詞前面。","g8/quiz.0.ko":"我不餓。剛剛吃過了。","g8/quiz.0.why":"剛剛 = just，放在 have 和過去分詞之間。","g8/quiz.1.ko":"你作業寫完了嗎？","g8/quiz.1.why":"疑問句尾的\\"已經……了嗎\\"用 yet。","g8/quiz.2.ko":"我還沒打電話給她。","g8/quiz.2.why":"否定句尾的\\"還沒\\"用 yet。","g8/quiz.3.ko":"快點！火車已經來了！","g8/quiz.3.why":"比預期更早 = already。","g8/quiz.4.q":"\\"我還沒看那部電影。\\"用英文怎麼說？","g8/quiz.4.why":"haven't + 過去分詞 seen + 句尾加 yet。","g9/title":"現在完成式 ③ for · since","g9/summary":"從過去開始、持續到現在的事用現在完成式 + for(一段時間) · since(起始點)","g9/forms.0.label":"for + 一段時間","g9/forms.0.items.0":"I've lived here for three years. (三年了)","g9/forms.1.label":"since + 起始點","g9/forms.1.items.0":"I've lived here since 2023. (從 2023 年起)","g9/forms.2.label":"疑問","g9/points.0.h":"常見的錯誤","g9/points.0.t":"\\"我住在這裡三年了\\"很容易說成 I live here for three years。說到持續到現在的一段時間時，要說 I've lived here for three years。","g9/points.1.h":"for 和 since","g9/points.1.t":"for 後面接\\"多長時間\\"(two hours · ten years)，since 後面接\\"從什麼時候起\\"(Monday · 2020 · I was a child)。","g9/points.2.t":"問到現在為止的時間長度用 How long have you…?。How long are you here? 的意思會變成\\"你會待多久？\\"(未來)。","g9/examples.0.ko":"我認識她十年了。","g9/examples.1.ko":"他從 2014 年起就在這裡工作。","g9/examples.2.ko":"你開那輛車開了幾年了？","g9/examples.3.ko":"我們自從大學以後就沒見過面。","g9/examples.4.ko":"已經冷了一個星期了。","g9/mistake.why":"用 since · for 表示持續到現在的事，就是現在完成式。","g9/quiz.0.ko":"我當護理師五年了。","g9/quiz.0.why":"five years 是一段時間，所以用 for。","g9/quiz.1.ko":"她從 2018 年起就住在首爾。","g9/quiz.1.why":"2018 是起始點，所以用 since。","g9/quiz.2.ko":"你認識 Jake 多久了？","g9/quiz.2.why":"到現在為止的時間長度用 How long have you + 過去分詞。","g9/quiz.3.ko":"我們從高中就是朋友了。","g9/quiz.3.why":"用 since 表示持續到現在，所以是現在完成式，we 用 have been。","g9/quiz.4.q":"\\"我住這間房子兩年了。\\"用英文怎麼說？","g9/quiz.4.why":"是持續到現在的一段時間，所以用現在完成式 + for two years。","g10/title":"現在完成進行式","g10/summary":"從過去開始、一直到現在都\\"持續進行\\"的事用 have / has been + -ing","g10/forms.0.label":"肯定","g10/forms.1.label":"否定","g10/forms.2.label":"疑問","g10/points.0.h":"用在哪裡","g10/points.0.t":"一直在做、現在還在做，或剛剛才停下來的事。I've been waiting for an hour 是\\"已經等了一個小時\\"。","g10/points.1.h":"看得到痕跡時","g10/points.1.t":"看得到剛才做的事所留下的痕跡時也可以用。Your eyes are red. Have you been crying? (你剛才在哭嗎？)","g10/points.2.h":"和現在完成式的差別","g10/points.2.t":"I've been painting the room 是\\"正在漆\\"(可能還沒漆完)，I've painted the room 是\\"漆完了\\"(結果)。說出幾個 · 幾次時用現在完成式 (I've written three emails)。","g10/points.3.h":"狀態動詞在這裡也不用","g10/examples.0.ko":"你讓我等了一個小時了！","g10/examples.1.ko":"從早上就一直在下雨。","g10/examples.2.ko":"你學英文多久了？","g10/examples.3.ko":"你看起來很累。最近都工作到很晚嗎？","g10/examples.4.ko":"她從去年開始學韓文。","g10/mistake.why":"說到持續到現在的一段時間(two hours)，要用現在完成進行式。把\\"已經等了兩個小時\\"直接照字面翻就會錯。","g10/quiz.0.ko":"我已經等公車等了 20 分鐘了。","g10/quiz.0.why":"到現在已經持續 20 分鐘，所以用 have been waiting。","g10/quiz.1.ko":"雨下了一整天。路都濕了。","g10/quiz.1.why":"從早上一直持續到現在，所以用 has been raining。","g10/quiz.2.ko":"你學英文多久了？","g10/quiz.2.why":"How long have you been + -ing。","g10/quiz.3.ko":"你的手好髒。你剛才在做什麼？","g10/quiz.3.why":"是看到痕跡而發問的現在完成進行式。you 用 have。","g10/quiz.4.ko":"我今天早上寫了三封電子郵件。","g10/quiz.4.why":"是說出幾封的結果，所以用現在完成式 written。","g11/title":"現在完成式 vs 過去簡單式","g11/summary":"說出已結束的時間(yesterday · last year · ago · when)用過去式，說到持續到現在的時間長度或現在的結果用現在完成式","g11/forms.0.label":"過去","g11/forms.0.items.0":"I lost my keys yesterday. (昨天的事，現在不確定)","g11/forms.1.label":"現在完成","g11/forms.1.items.0":"I've lost my keys. (所以現在沒有)","g11/points.0.h":"看得到已結束的時間就用過去式","g11/points.0.t":"yesterday · last week · in 2020 · two days ago · When…? 要用過去式。When have you arrived? ✕ → When did you arrive? ○","g11/points.1.h":"還沒結束的期間用現在完成式","g11/points.1.t":"today · this week · this year 這類還沒結束的期間內發生的事，用現在完成式比較自然。I've had three coffees today.","g11/points.2.h":"對話用現在完成式開頭，再用過去式說細節","g11/points.2.t":"Have you ever been to Japan? — Yes, I went there last summer. 問經驗時用現在完成式，說什麼時候 · 怎麼樣時用過去式。","g11/examples.0.ko":"我昨天把鑰匙弄丟了，後來找到了。","g11/examples.1.ko":"我把鑰匙弄丟了。可以幫我一起找嗎？","g11/examples.2.ko":"你去過日本嗎？ — 有，去年夏天去的。","g11/examples.3.ko":"她今天喝了三杯咖啡。","g11/examples.4.ko":"你什麼時候到的？","g11/mistake.why":"When 是在問已結束的時間，所以用過去式。","g11/quiz.0.ko":"我上週見過他。","g11/quiz.0.why":"last week 是已結束的時間，所以用過去式 saw。","g11/quiz.1.ko":"你見過名人嗎？","g11/quiz.1.why":"沒說是什麼時候的經驗，用現在完成式。","g11/quiz.2.ko":"我們 2022 年搬到釜山。","g11/quiz.2.why":"in 2022 是已結束的時間，所以用過去式。","g11/quiz.3.ko":"你什麼時候開始學英文的？","g11/quiz.3.why":"用 When 問已結束的時間，所以用 did。","g11/quiz.4.q":"\\"我去年看了那部電影。\\"用英文怎麼說？","g11/quiz.4.why":"last year 不和現在完成式一起用。用過去式 saw。","g12/title":"過去完成式","g12/summary":"比過去某個時間點\\"更早\\"發生的事用 had + 過去分詞","g12/forms.0.label":"肯定","g12/forms.1.label":"否定","g12/forms.2.label":"疑問","g12/points.0.h":"過去的過去","g12/points.0.t":"是兩件過去的事當中先發生的那一件。When I got to the station, the train had left. (我到車站時，火車已經開走了)","g12/points.1.h":"順序很清楚的話，用過去式就夠了","g12/points.1.t":"用 before · after 就能看出順序時，只用過去式也可以。The train left before I got there.","g12/points.2.h":"意思會不一樣","g12/points.2.t":"When I arrived, she left. 是\\"我一到她就離開了\\"(依序發生)，When I arrived, she had left. 是\\"我到的時候她已經走了\\"。","g12/examples.0.ko":"我到車站時，火車已經開走了。","g12/examples.1.ko":"搬來這裡之前，我從來沒看過雪。","g12/examples.2.ko":"我們到的時候，她已經吃過了。","g12/examples.3.ko":"派對之前你就見過他了嗎？","g12/examples.4.ko":"我發現我把手機忘在家裡了。","g12/mistake.why":"在我到達\\"之前\\"就已經開始了，所以用 had started。","g12/quiz.0.ko":"我們到的時候，派對已經結束了。","g12/quiz.0.why":"在我們到達之前就結束了，所以用 had ended。","g12/quiz.1.ko":"去日本之前，我從來沒吃過壽司。","g12/quiz.1.why":"had 後面接過去分詞 tried。","g12/quiz.2.ko":"他把鑰匙弄丟了，所以進不去。","g12/quiz.2.why":"弄丟比進不去更早發生，所以用 had lost。","g12/quiz.3.ko":"我起床時大家都已經出門了。","g12/quiz.3.why":"在我起床之前就已經出門了，所以用 had gone。","g12/quiz.4.q":"\\"我到的時候電影已經開始了。\\"用英文怎麼說？","g12/quiz.4.why":"比到達更早開始，所以用 had already started。","g13/title":"過去完成進行式，時態總覽","g13/summary":"一直持續到過去某個時間點的事用 had been + -ing。把到目前為止學的八個時態一次整理","g13/forms.1.label":"時態總覽","g13/forms.1.items.0":"現在 I work · 現在進行 I'm working","g13/forms.1.items.1":"過去 I worked · 過去進行 I was working","g13/forms.1.items.2":"現在完成 I've worked · 現在完成進行 I've been working","g13/forms.1.items.3":"過去完成 I'd worked · 過去完成進行 I'd been working","g13/points.0.h":"用在哪裡","g13/points.0.t":"一直持續到過去某一個時間點的事。就像把現在完成進行式(have been -ing)往過去挪一格。When I met her, she'd been living in Paris for five years.","g13/points.1.h":"痕跡","g13/points.1.t":"說明過去看到的痕跡的原因時也可以用。His eyes were red. He'd been crying.","g13/points.2.h":"選時態的三個問題","g13/points.2.t":"① 是現在還是過去？ ② 那一刻正在進行嗎(進行)？ ③ 是從那之前就持續下來的嗎(完成)？ 用這三個問題就能分出八個時態。","g13/examples.0.ko":"我等了一個小時，她終於來了。","g13/examples.1.ko":"他們結婚前交往了兩年。","g13/examples.2.ko":"他工作了一整夜，所以很累。","g13/examples.3.ko":"她的眼睛是紅的。她剛才在哭。","g13/examples.4.ko":"你搬家之前在那裡住了多久？","g13/mistake.why":"說到持續到他來\\"之前\\"的一段時間(two hours)，要用 had been -ing。","g13/quiz.0.ko":"我等了 20 分鐘，公車終於來了。","g13/quiz.0.why":"是持續到公車來的那個過去時間點的一段時間，所以用 had been waiting。","g13/quiz.1.ko":"地上是濕的。剛才一直在下雨。","g13/quiz.1.why":"是過去看到的痕跡(濕的地面)的原因，所以用 had been raining。","g13/quiz.2.ko":"她搬到倫敦之前學了三年英文。","g13/quiz.2.why":"是持續到搬家那個過去時間點的事，所以用 had been studying。","g13/quiz.3.q":"\\"我現在正在工作。\\"用英文怎麼說？","g13/quiz.3.why":"現在 + 正在進行 = 現在進行式。","g13/quiz.4.q":"\\"我在這裡工作三年了。\\"用英文怎麼說？","g13/quiz.4.why":"持續到現在 + 進行中 = 現在完成進行式。","g14/title":"用現在式說的未來","g14/summary":"已經約好的事用現在進行式(I'm meeting)，時刻表 · 行程用現在簡單式(The train leaves)來說未來","g14/forms.0.label":"約定 · 計畫","g14/forms.1.label":"時刻表 · 行程","g14/points.0.h":"約好的事用現在進行式","g14/points.0.t":"已經和人約好，或已經買好票的事，用現在進行式來說。會搭配 tomorrow · next week 這類表示未來的詞。I'm flying to Busan on Friday.","g14/points.1.h":"時刻表用現在簡單式","g14/points.1.t":"火車 · 飛機 · 電影 · 課程這類固定的時刻表用現在簡單式。My class starts at nine tomorrow.","g14/points.2.t":"這是問對方計畫時最自然的說法。What are you doing this weekend? (這個週末你要做什麼？)","g14/examples.0.ko":"明天我和 Jake 約了吃午餐。","g14/examples.1.ko":"這個週末你要做什麼？","g14/examples.2.ko":"我們的飛機早上 6 點起飛。","g14/examples.3.ko":"那家店明天 10 點開門。","g14/examples.4.ko":"星期六我要辦派對，你能來嗎？","g14/mistake.why":"和人約好的事，用現在進行式比較自然。現在簡單式用在時刻表。","g14/quiz.0.ko":"今晚你要做什麼？","g14/quiz.0.why":"是問計畫的 What are you doing…?。","g14/quiz.1.ko":"電影 8 點 30 分開始。別遲到。","g14/quiz.1.why":"是固定的時刻表，所以用現在簡單式 starts。","g14/quiz.2.ko":"明天下午 3 點我要見 Dana。已經寫進行程了。","g14/quiz.2.why":"是和人約好的事，所以用 'm meeting。","g14/quiz.3.ko":"我們的火車 7 點 15 分出發。","g14/quiz.3.why":"是火車時刻表，所以用現在簡單式 leaves。","g14/quiz.4.q":"\\"我下週要去釜山 (票已經買好了)。\\"用英文怎麼說？","g14/quiz.4.why":"是已經決定好的事，所以用現在進行式 I'm going。","g15/summary":"說話當下決定的事 · 提議 · 承諾 · 預測用 will + 動詞原形","g15/forms.0.label":"肯定","g15/forms.1.label":"否定","g15/forms.2.label":"疑問","g15/points.0.h":"當場決定時","g15/points.0.t":"不是事先計畫，而是說話當下決定的事。The phone's ringing. — I'll get it!","g15/points.1.h":"提議 · 承諾 · 請求","g15/points.2.h":"憑想法做的預測","g15/points.2.t":"I think it'll rain. / You'll love this movie. 很適合搭配 I think · probably · I'm sure。","g15/points.3.h":"已約好的事不用","g15/points.3.t":"已經約好的事，用 I'm meeting (第 14 課) 比較自然。I'll meet Jake tomorrow 聽起來像\\"(剛決定的) 那我就去見他\\"。","g15/examples.0.ko":"好冷。我來關窗。","g15/examples.1.ko":"別擔心。我不會告訴任何人。","g15/examples.2.ko":"你可以幫我搬這個箱子嗎？","g15/examples.3.ko":"我覺得你會喜歡這部電影。","g15/examples.4.ko":"在這裡等。我 5 分鐘後回來。","g15/mistake.why":"will 後面接動詞原形，不加 to。","g15/quiz.0.ko":"電話響了。 — 我來接！","g15/quiz.0.why":"是當場決定的事，所以用 I'll get it。","g15/quiz.1.ko":"我再也不會遲到了，我保證。","g15/quiz.1.why":"will not 縮寫是 won't。","g15/quiz.2.ko":"你願意嫁給我嗎？","g15/quiz.2.why":"是詢問請求 · 提議的 Will you…?。","g15/quiz.3.ko":"我覺得明天會下雨。","g15/quiz.3.why":"是憑想法做的預測，所以用 will + 原形。","g15/quiz.4.q":"\\"好冷。我來開暖氣。\\"用英文怎麼說？","g15/quiz.4.why":"是說話當下決定的事，所以用 I'll turn on。","g16/summary":"事先決定好的計畫，和憑眼前證據做的預測用 be going to，說話當下決定的事用 will","g16/forms.0.items.0":"I'm going to study tonight. (之前就計畫好了)","g16/forms.0.items.1":"Look at the clouds. It's going to rain. (證據)","g16/forms.1.items.0":"Okay, I'll study with you. (剛決定)","g16/points.0.h":"計畫","g16/points.0.t":"說話之前就已經決定的事用 be going to。I'm going to buy a new laptop. (我早就打算買了)","g16/points.1.h":"看得到證據的預測","g16/points.1.t":"看著眼前的證據所做的預測也用 be going to。Look at those clouds! It's going to rain. 憑想法 · 感覺做的預測用 will (I think it'll rain)。","g16/points.2.h":"同一段對話中兩種都用","g16/points.2.t":"A: We need milk. B: Oh, I'll get some. (當場決定) → 隔天 B: I'm going to get milk after work. (已經決定好的計畫)","g16/points.3.h":"發音","g16/points.3.t":"說話時 going to 聽起來像 gonna。寫的時候要寫成 going to。","g16/examples.0.ko":"我打算從下週開始跑步。","g16/examples.1.ko":"看那些雲。快下雨了。","g16/examples.2.ko":"小心！你要跌倒了！","g16/examples.3.ko":"咖啡沒了。 — 真的嗎？我去買。","g16/examples.4.ko":"畢業後你打算做什麼？","g16/mistake.wrong":"(電話剛響起時) I'm going to answer it!","g16/mistake.why":"是電話響起的當下決定的事，所以用 will。","g16/quiz.0.ko":"看天空！要下雪了。","g16/quiz.0.why":"是看著眼前的證據(天空)所做的預測，所以用 is going to。","g16/quiz.1.ko":"我決定了。今年夏天我要學游泳。","g16/quiz.1.why":"是已經下定決心的計畫，所以用 be going to。","g16/quiz.2.ko":"有人來了。 — 我去開門。","g16/quiz.2.why":"是當場決定的事，所以用 I'll。","g16/quiz.3.ko":"小心！那個玻璃杯要掉下來了！","g16/quiz.3.why":"是根據眼前看到的證據做的預測，所以用 is going to。","g16/quiz.4.q":"\\"畢業後我要去旅行 (早就計畫好了)。\\"用英文怎麼說？","g16/quiz.4.why":"是之前就決定好的計畫，所以用 I'm going to travel。","g17/title":"未來進行式 · 未來完成式","g17/summary":"未來某個時間點正在做的事用 will be -ing，到未來某個時間點為止已經完成的事用 will have + 過去分詞","g17/forms.0.label":"未來進行式","g17/forms.1.label":"未來完成式","g17/points.0.h":"未來進行式","g17/points.0.t":"是未來某一刻\\"正在進行\\"的事。就像把過去進行式(was -ing)搬到未來。At 9 tonight, I'll be watching the game.","g17/points.1.h":"未來完成式","g17/points.1.t":"是到未來某個時間\\"為止已經完成\\"的事。很適合搭配 by (到……為止) · by then · by the time。By 2030, I'll have paid off my loan.","g17/points.2.h":"委婉的問法","g17/points.2.t":"Will you be using the car tonight? 是不讓人聽起來像請求，只是在問對方的計畫。","g17/examples.0.ko":"下週的這個時候，我會躺在海灘上。","g17/examples.1.ko":"8 點不要打電話給我。我會在開車。","g17/examples.2.ko":"星期五之前我就會把專案完成了。","g17/examples.3.ko":"等你到這裡的時候，我已經把晚餐做好了。","g17/examples.4.ko":"今晚你會用車嗎？","g17/mistake.why":"by (到……為止) 到那時\\"已經完成\\"的事，所以用 will have finished。","g17/quiz.0.ko":"明天 10 點我會在考試。","g17/quiz.0.why":"是未來某一刻正在進行的事，所以用 will be taking。","g17/quiz.1.ko":"到今年年底，我會讀完 50 本書。","g17/quiz.1.why":"是到那時為止已經完成的事，所以用 will have read。","g17/quiz.2.ko":"7 點不要來。我們會在吃晚餐。","g17/quiz.2.why":"7 點時正吃到一半，所以用 will be having。","g17/quiz.3.ko":"等你到的時候，電影已經開始了。","g17/quiz.3.why":"在你到達之前就已經開始了，所以用 will have started。","g17/quiz.4.q":"\\"明天這個時候我會在飛機上。\\"用英文怎麼說？","g17/quiz.4.why":"是未來某一刻正在進行的事，所以用 will be flying。","g18/title":"when · as soon as 後面的現在式","g18/summary":"when · as soon as · before · after · until 後面，即使是未來的事也用現在式","g18/forms.0.label":"用現在式","g18/points.0.h":"和中文不同的地方","g18/points.0.t":"\\"到家的時候打給你\\"中的\\"到家\\"雖然是未來的事，但英文在 when 後面要用現在式。I'll call you when I get home.","g18/points.1.h":"規則相同的詞","g18/points.1.t":"when · as soon as (一……就……) · before · after · until (直到……為止) · once (一旦……) 後面全都用現在式。","g18/points.2.h":"強調已經全部做完時用現在完成式","g18/points.2.t":"I'll tell you when I've finished. (等我全部做完再告訴你)","g18/examples.0.ko":"我到家就打給你。","g18/examples.1.ko":"她一來我就開始開會。","g18/examples.2.ko":"在我回來之前，請在這裡等。","g18/examples.3.ko":"我們在電影開始前先吃吧。","g18/examples.4.ko":"我看完之後，就把那本書借你。","g18/mistake.why":"when 後面即使是未來的事，也用現在式來說。","g18/quiz.0.ko":"我到首爾就打給你。","g18/quiz.0.why":"when 後面用現在式 get。","g18/quiz.1.ko":"雨一停我們就出去吧。","g18/quiz.1.why":"as soon as 後面用現在式 stops。","g18/quiz.2.ko":"在我說可以之前，不要開門。","g18/quiz.2.why":"until 後面用現在式 tell。","g18/quiz.3.ko":"出門前記得關燈。","g18/quiz.3.why":"before 後面用現在式 leave。","g18/quiz.4.q":"\\"下課後見吧。\\"用英文怎麼說？","g18/quiz.4.why":"when 後面用現在式，class 是 it，所以用 finishes。","g19/summary":"表示能夠做到用 can，過去一直都能做到的事用 could，其他時態或做成過一次的事用 be able to","g19/forms.0.label":"現在 · 過去","g19/forms.1.label":"未來 · 完成","g19/forms.2.label":"做成過一次的事","g19/points.0.t":"用於能力(I can drive)、可能(You can park here)、許可(Can I go now?)。否定是 can't (cannot)。","g19/points.1.t":"是過去\\"一直\\"具備的能力。She could speak three languages when she was ten.","g19/points.2.t":"can 不能放在 will · have 後面。所以未來 · 完成式要改成 be able to。I'll be able to come. / I haven't been able to sleep.","g19/points.3.h":"做成過一次的事","g19/points.3.t":"過去\\"在當時那一次\\"做成了困難的事，用 was able to 比 could 自然。The fire spread, but everyone was able to escape. 否定用 couldn't 也可以。","g19/examples.0.ko":"我會說一點西班牙語。","g19/examples.1.ko":"你聽得到我說話嗎？","g19/examples.2.ko":"我小時候跑得很快。","g19/examples.3.ko":"我昨晚睡不著。","g19/examples.4.ko":"你明天可以來嗎？","g19/mistake.why":"will 後面不能再接 can。要改成 be able to。","g19/quiz.0.ko":"你會游泳嗎？","g19/quiz.0.why":"是問能力的 Can you…?。","g19/quiz.1.ko":"她六歲時就能讀英文書了。","g19/quiz.1.why":"是過去一直具備的能力，所以用 could。","g19/quiz.2.ko":"希望我能去你的派對。","g19/quiz.2.why":"will 後面要改成 be able to。","g19/quiz.3.ko":"考試很難，但我通過了。","g19/quiz.3.why":"是當時做成了一次的事，所以用 was able to。","g19/quiz.4.q":"\\"我昨晚睡不著。\\"用英文怎麼說？","g19/quiz.4.why":"過去的否定是 couldn't (或 wasn't able to)。","g20/title":"could (可能性 · 提議)","g20/summary":"could 也用於\\"有可能是……\\"(可能性)、\\"可以……啊\\"(提議)、\\"可以請你……嗎？\\"(禮貌的請求)","g20/forms.0.label":"可能性","g20/forms.1.label":"提議 · 請求","g20/forms.2.label":"過去的可能性","g20/points.0.h":"可能性","g20/points.0.t":"意思是現在或未來\\"有可能\\"。把握比 can 小。That could be Jake at the door.","g20/points.1.h":"提議","g20/points.1.t":"在多種方法當中，委婉地提出其中一個時使用。We could order pizza. (我們可以叫披薩)","g20/points.2.h":"禮貌的請求","g20/points.2.t":"Could you…? 比 Can you…? 更有禮貌。Could you send me the file?","g20/points.3.t":"意思是過去\\"本來可以，但沒有做\\"。You could have told me! (你本來可以告訴我的啊！)","g20/examples.0.ko":"帶把傘。等一下可能會下雨。","g20/examples.1.ko":"今晚我們也可以去看電影。","g20/examples.2.ko":"可以請你把鹽遞給我嗎？","g20/examples.3.ko":"答案可能就在這本書裡。","g20/examples.4.ko":"你本來可以告訴我的啊！","g20/mistake.why":"could 後面接動詞原形，不加 to。","g20/quiz.0.ko":"好無聊。 — 可以去散步啊。","g20/quiz.0.why":"是委婉的提議，所以用 could + 原形。","g20/quiz.1.ko":"可以請你開一下窗戶嗎？","g20/quiz.1.why":"是禮貌的請求 Could you…?。","g20/quiz.2.ko":"別吃那個。可能壞掉了。","g20/quiz.2.why":"表示可能性的 could + 原形 be。","g20/quiz.3.ko":"你為什麼不問我？我本來可以幫你的！","g20/quiz.3.why":"過去本來可以做卻沒做的事，用 could have + 過去分詞。","g20/quiz.4.q":"\\"那可能是 Jake。\\"用英文怎麼說？","g20/quiz.4.why":"could 後面接原形 be。","g21/title":"must · can't (確信)","g21/summary":"推測幾乎確定時用 must (一定是……)，推測不可能時用 can't (不可能是……)","g21/forms.0.items.0":"You must be tired. (你一定很累)","g21/forms.0.items.1":"He must be working. (他一定在工作)","g21/forms.1.items.0":"That can't be true. (那不可能是真的)","g21/points.0.h":"根據證據的推測","g21/points.0.t":"憑眼前的理由下結論\\"一定是這樣\\"時用 must。You've worked all day. You must be tired. 和表示義務的 must (第 24 課) 形式相同。","g21/points.1.h":"相反是 can't","g21/points.1.t":"\\"不可能\\"這種強烈的確信用 can't。She just ate. She can't be hungry. 在美式英文中，must not 也用來表示\\"大概不是……\\"這種較弱的推測 (He must not be home)。","g21/points.2.h":"用中文來比喻","g21/points.2.t":"像\\"你一定很累吧\\"\\"想必餓了\\"這類句尾的\\"一定……吧\\"\\"想必\\"，和 must 很像。","g21/points.3.h":"正在進行的事","g21/points.3.t":"must be -ing 是\\"現在一定正在……\\"。The lights are on. He must be working.","g21/examples.0.ko":"你走了一整天。一定很累吧。","g21/examples.1.ko":"那個人不可能是 Jake。他在芝加哥。","g21/examples.2.ko":"你養了三隻狗呢。你一定很喜歡動物。","g21/examples.3.ko":"燈都關了。大家一定都在睡覺。","g21/examples.4.ko":"你該不會是認真的吧！","g21/mistake.why":"must 後面接原形 be。","g21/quiz.0.ko":"她一整天什麼都沒吃。一定餓了。","g21/quiz.0.why":"憑證據(一整天沒吃)確信的推測，所以用 must。","g21/quiz.1.ko":"不可能！我一個小時前才看到他。","g21/quiz.1.why":"確信不可能用 can't。","g21/quiz.2.ko":"你中了巴黎旅行？你一定超興奮！","g21/quiz.2.why":"是推測一定如此，所以用 must。","g21/quiz.3.ko":"電話一直響，都沒人接。大家一定都出去了。","g21/quiz.3.why":"是憑證據確信的推測，所以用 must be。","g21/quiz.4.q":"\\"你該不會是認真的吧！(不可能是認真的)\\"用英文怎麼說？","g21/quiz.4.why":"是表示不可能的 can't + 原形 be。","g22/summary":"五五波的\\"也許是\\"這種推測用 may · might (可能是……)。might 的把握更小一點","g22/forms.0.label":"肯定","g22/forms.1.label":"否定","g22/forms.1.items.0":"I might not go. (我可能不去)","g22/forms.2.label":"進行","g22/points.0.h":"把握的大小","g22/points.0.t":"must (幾乎確定) > may (也許) ≥ might (說不定) > can't (不可能)。日常對話中常用 might。","g22/points.1.h":"還沒決定的未來","g22/points.1.t":"也可以用在還沒決定的事。I might go to the party. (我可能會去，還不知道)","g22/points.2.h":"否定","g22/points.2.t":"may not · might not 是\\"可能不是\\"。may not 也有\\"不可以\\"(不許可) 的意思，所以要看前後文來區分。","g22/points.3.h":"疑問句不一樣","g22/points.3.t":"像 Might it rain? 這樣問很不自然。要問 Do you think it'll rain?。","g22/examples.0.ko":"帶把傘去。可能會下雨。","g22/examples.1.ko":"我可能會晚到一點。","g22/examples.2.ko":"她可能不會來參加派對。","g22/examples.3.ko":"Jake 在哪？ — 他可能在廚房。","g22/examples.4.ko":"我們明年可能會搬到釜山。","g22/mistake.why":"把 maybe 和 might 一起用會重複，像是\\"也許可能\\"。只用一個就好。","g22/quiz.0.ko":"還不確定，但今晚我可能會去健身房。","g22/quiz.0.why":"是還不知道的事，所以用 might。","g22/quiz.1.ko":"不用等我。我可能會晚到。","g22/quiz.1.why":"表示有可能的 may + 原形。","g22/quiz.2.ko":"他可能不喜歡這個禮物。我們先問問他吧。","g22/quiz.2.why":"表示可能不是的 might not。","g22/quiz.3.ko":"我的手機在哪？ — 可能在你的包包裡。","g22/quiz.3.why":"might 後面接原形 be。","g22/quiz.4.q":"\\"她可能不會來。\\"用英文怎麼說？","g22/quiz.4.why":"否定是 might not + 原形。","g23/summary":"推測過去的事時，用 must have done (一定是那樣)、might have done (可能是那樣)、can't have done (不可能是那樣)","g23/forms.0.label":"形式","g23/forms.0.items.0":"助動詞 + have + 過去分詞","g23/forms.1.label":"例句","g23/points.0.h":"現在對過去所做的推測","g23/points.0.t":"推測是現在做的，但對象是過去的事。所以助動詞後面要接 have + 過去分詞。","g23/points.1.h":"三個等級","g23/points.1.t":"must have (幾乎確定) > might · may · could have (也許) > can't · couldn't have (不可能)。","g23/points.2.h":"發音與拼寫","g23/points.2.t":"說話時聽起來像 must've · might've。寫成 must of 是錯誤的拼法。","g23/examples.0.ko":"地是濕的。一定下過雨了。","g23/examples.1.ko":"她遲到了。可能錯過公車了。","g23/examples.2.ko":"他不可能已經做完了。他 10 分鐘前才開始。","g23/examples.3.ko":"我找不到鑰匙。一定是忘在辦公室了。","g23/examples.4.ko":"那一定嚇壞了！","g23/mistake.why":"過去的推測是 must + have + 過去分詞。","g23/quiz.0.ko":"Jake 不接電話。一定是睡著了。","g23/quiz.0.why":"是對過去的事很確信，所以用 must have + 過去分詞 fallen。","g23/quiz.1.ko":"我不知道 Rosa 在哪裡。她可能去上班了。","g23/quiz.1.why":"表示可能是那樣的 might have + 過去分詞。","g23/quiz.2.ko":"Mina 不可能拿了你的筆。她今天不在這裡。","g23/quiz.2.why":"表示不可能是那樣的 can't have + 過去分詞。","g23/quiz.3.ko":"你走了 20 公里？你一定累壞了！","g23/quiz.3.why":"是對過去的事很確信的 must have been。","g23/quiz.4.q":"\\"他不可能忘了那件事。\\"用英文怎麼說？","g23/quiz.4.why":"是 can't have + 過去分詞 forgotten。","g24/summary":"表示必須做的是 must · have to。must 用於說話者自己定下的義務，have to 多用於因規則 · 情況而不得不做的事","g24/forms.0.label":"現在","g24/forms.1.label":"過去 · 未來","g24/forms.1.items.0":"I had to wait. (must 沒有過去式)","g24/forms.2.label":"疑問","g24/points.0.h":"語感差別","g24/points.0.t":"must 是\\"我一定要做\\"(自己決定的)，have to 是\\"因為規則 · 情況而不得不做\\"。I must call my mom. / I have to wear a suit at work. 在美式英文對話中，have to 用得多得多。","g24/points.1.h":"過去 · 未來用 have to","g24/points.1.t":"must 沒有過去 · 未來的形式。I had to leave early. / You'll have to wait.","g24/points.2.t":"口語中也常說 I've got to go. (我得走了)。聽起來像 gotta。","g24/examples.0.ko":"我明天得早起。","g24/examples.1.ko":"你一定要試試這個蛋糕。超好吃！","g24/examples.2.ko":"她這個週末得工作。","g24/examples.3.ko":"我們不得不等了兩個小時。","g24/examples.4.ko":"你現在就得走嗎？","g24/mistake.why":"must 沒有過去式。過去的義務用 had to。","g24/quiz.0.ko":"我開車時必須戴眼鏡。","g24/quiz.0.why":"主詞是 I，所以用 have to。","g24/quiz.1.ko":"昨天我得工作到很晚。","g24/quiz.1.why":"過去的義務用 had to。","g24/quiz.2.ko":"她得那麼早走嗎？","g24/quiz.2.why":"have to 的疑問句是 Does she have to…?。","g24/quiz.3.ko":"你一定要看這部電影。超棒！","g24/quiz.3.why":"是說話者強烈推薦的 must + 原形。","g24/quiz.4.q":"\\"你得等一下了。\\"用英文怎麼說？","g24/quiz.4.why":"will 後面不能接 must，所以改成 have to。","g25/summary":"must not 是\\"不可以做\\"(禁止)，don't have to 是\\"不用做\\"(沒有必要)。意思正好相反，要小心","g25/forms.0.label":"禁止","g25/forms.0.items.1":"You can't park here. (美式口語)","g25/forms.1.label":"沒有必要","g25/forms.2.label":"疑問","g25/points.0.h":"容易搞混的地方","g25/points.0.t":"must not 和 don't have to 都有 not，形式相近，所以容易搞混。must not = 不可以做，don't have to = 不用做(做也可以)。","g25/points.1.t":"是\\"有必要做\\"的意思。don't need to 和 don't have to 意思相同。疑問句是 Do I need to…?","g25/points.2.h":"美式英文的禁止","g25/points.2.t":"日常生活中，禁止也常用 can't。You can't park here. (這裡不可以停車)","g25/examples.0.ko":"不可以告訴任何人。這是祕密。","g25/examples.1.ko":"如果你忙，不用來也沒關係。","g25/examples.2.ko":"不用急。我們有時間。","g25/examples.3.ko":"我需要帶什麼嗎？","g25/examples.4.ko":"這裡不可以停車。這是消防車道。","g25/mistake.wrong":"(在免費活動中) You must not pay.","g25/mistake.why":"\\"不用做\\" 是 don't have to。must not pay 會變成\\"不可以付錢\\"這種奇怪的意思。","g25/quiz.0.ko":"這是免費的。你不用付錢。","g25/quiz.0.why":"沒有必要付錢，所以用 don't have to。","g25/quiz.1.ko":"不可以碰那個。很燙！","g25/quiz.1.why":"是不可以做的禁止，所以用 must not。","g25/quiz.2.ko":"明天是星期日。我不用早起。","g25/quiz.2.why":"沒有必要做，所以用 don't have to，主詞是 I，所以用 don't。","g25/quiz.3.ko":"我需要帶護照嗎？","g25/quiz.3.why":"need to 的疑問句是 Do I need to…?。","g25/quiz.4.q":"\\"你什麼都不用說。\\"用英文怎麼說？","g25/quiz.4.why":"表示沒有必要的 don't have to。","g26/summary":"表示做比較好的建議用 should，表示不做會有麻煩的強烈警告用 had better ('d better)","g26/points.0.h":"should = 建議","g26/points.0.t":"是\\"你最好……\\"\\"應該要……\\"的意思。不是強迫。I think you should take a break.","g26/points.1.h":"had better = 警告","g26/points.1.t":"用在眼前的事，帶有不做就會發生壞事的感覺。雖然有 had 看起來像過去，但指的是現在 · 接下來的事。否定是 had better not。","g26/points.2.h":"注意語氣","g26/points.2.t":"對長輩或上司說 had better 可能聽起來很沒禮貌。建議用 should 或 You might want to… 會比較委婉。","g26/examples.0.ko":"你看起來很累。最好早點睡。","g26/examples.1.ko":"吃那麼多糖不好。","g26/examples.2.ko":"我要打給她嗎？ — 嗯，打吧。","g26/examples.3.ko":"快下雨了。我們最好進去。","g26/examples.4.ko":"你最好別再遲到了！","g26/mistake.why":"had better 後面接原形，不加 to。","g26/quiz.0.ko":"你發燒了。最好去看醫生。","g26/quiz.0.why":"建議用 should + 原形。","g26/quiz.1.ko":"電影 5 分鐘後開始。我得趕快了！","g26/quiz.1.why":"不趕快會有麻煩，所以用 'd better + 原形。","g26/quiz.2.ko":"晚上最好別喝咖啡。你會睡不著。","g26/quiz.2.why":"表示最好不要做的建議是 shouldn't。","g26/quiz.3.ko":"我要帶禮物去嗎？ — 嗯，好主意。","g26/quiz.3.why":"徵求建議時用 Should I…?。","g26/quiz.4.q":"\\"你最好別再遲到了！\\"用英文怎麼說？","g26/quiz.4.why":"had better 的否定是 had better not + 原形。","g27/title":"should have done (後悔)","g27/summary":"對過去的事感到後悔 · 惋惜時，用 should have done (早該做的)、shouldn't have done (早知道就不要做)","g27/forms.0.label":"早該做的","g27/forms.1.label":"早知道就不要","g27/forms.2.label":"發音","g27/points.0.h":"後悔","g27/points.0.t":"早該做卻沒做的事用 should have + 過去分詞。I should have left earlier. (我早該早點出門的)","g27/points.1.h":"早知道就不要","g27/points.1.t":"做了但本來不該做的事用 shouldn't have。I shouldn't have eaten so much.","g27/points.2.h":"收到禮物時","g27/points.2.t":"You shouldn't have! 是表示感謝的說法，意思是\\"你太客氣了，不用這樣的！\\"","g27/examples.0.ko":"我早該搭計程車的。","g27/examples.1.ko":"你不該告訴他的。","g27/examples.2.ko":"我們早該訂位的。","g27/examples.3.ko":"我太飽了。早知道就不吃最後一塊了。","g27/examples.4.ko":"你買花送我？你太客氣了！","g27/mistake.why":"對過去的事後悔，用 should + have + 過去分詞。","g27/quiz.0.ko":"我考試沒過。早知道就更用功讀書了。","g27/quiz.0.why":"是對沒做的事後悔，所以用 should have + 過去分詞。","g27/quiz.1.ko":"對不起。我不該說那句話的。","g27/quiz.1.why":"是對做過的事後悔的 shouldn't have。","g27/quiz.2.ko":"我錯過火車了。早知道就早點出門。","g27/quiz.2.why":"should have 才對。should of 只是發音相近的錯誤拼法。","g27/quiz.3.ko":"你早該打給我的！我很擔心。","g27/quiz.3.why":"是早該做卻沒做的事，所以用 should have。","g27/quiz.4.q":"\\"我早該帶傘的。\\"用英文怎麼說？","g27/quiz.4.why":"是 should have + 過去分詞 brought。","g28/title":"would · used to (過去的習慣)","g28/summary":"以前是那樣但現在不是了用 used to，像回憶般說起以前常做的動作時也可以用 would","g28/points.0.t":"意思是過去的習慣或狀態現在已經不是了。I used to smoke. (以前抽菸，現在不抽了)","g28/points.1.t":"只用於過去反覆做的\\"動作\\"。狀態(live · have · like)不能用。I would live in Seoul ✕","g28/points.2.h":"否定 · 疑問","g28/points.2.t":"有 did 時要用 use to (不加 d)。I didn't use to… / Did you use to…?","g28/points.3.h":"容易混淆的詞","g28/points.3.t":"和 be used to -ing (習慣於……) 是不同的東西 (第 56 課會說明)。","g28/examples.0.ko":"我以前住在釜山。","g28/examples.1.ko":"她以前不喜歡咖啡，現在一天喝三杯。","g28/examples.2.ko":"你以前彈過鋼琴嗎？","g28/examples.3.ko":"我小時候，奶奶常常會講古老的故事給我聽。","g28/examples.4.ko":"這裡以前有一間書店。","g28/mistake.why":"肯定句是 used to。說話時 d 的音可能聽不清楚，但寫的時候要加上去。","g28/quiz.0.ko":"我以前頭髮很長，現在很短。","g28/quiz.0.why":"是以前的狀態，所以用 used to。狀態不能用 would。","g28/quiz.1.ko":"你以前住在這裡嗎？","g28/quiz.1.why":"有 did 時用 use to。","g28/quiz.2.ko":"小時候我們每天都在外面玩。","g28/quiz.2.why":"是以前反覆做的動作，所以用 would (used to 也可以)。","g28/quiz.3.ko":"這裡以前有一座公園。現在是停車場。","g28/quiz.3.why":"是以前存在的狀態，所以用 used to。","g28/quiz.4.q":"\\"我以前不能吃辣。\\"用英文怎麼說？","g28/quiz.4.why":"否定是 didn't use to (不加 d)。","g29/title":"請求 · 提議 · 祈使句","g29/summary":"請求用 Can you…? · Could you…? · Would you mind -ing?，提議用 Let's · Why don't we · Shall I，命令則以原形動詞開頭","g29/forms.0.label":"請求","g29/forms.1.label":"提議","g29/forms.2.label":"命令","g29/points.0.h":"禮貌程度的順序","g29/points.0.t":"Can you…? < Could you…? < Would you mind -ing?(可以請您…嗎？) 回答 Would you mind…? 時，要說「好啊，我來做」是 No, not at all.，因為對方問的是「你介意嗎？」。","g29/points.1.h":"提議","g29/points.1.t":"Let's + 原形(我們…吧)、Let's not(我們別…吧)、Why don't we…?(要不要…？)、Shall I…?(要我來…嗎？)。","g29/points.2.h":"祈使句","g29/points.2.t":"不需要主詞，直接以原形動詞開頭。「不要…」用 Don't + 原形。加上 Please 語氣會更柔和。","g29/examples.0.ko":"可以請你把檔案傳給我嗎？","g29/examples.1.ko":"可以請你關一下門嗎？","g29/examples.2.ko":"我們休息一下吧。","g29/examples.3.ko":"要不要叫披薩？","g29/examples.4.ko":"別擔心，我來處理。","g29/mistake.why":"mind 後面接 -ing。","g29/quiz.0.ko":"可以請你開一下窗戶嗎？","g29/quiz.0.why":"mind 後面是 -ing。","g29/quiz.1.ko":"太晚了，我們回家吧。","g29/quiz.1.why":"提議用 Let's + 原形。","g29/quiz.2.ko":"別碰那個！很燙。","g29/quiz.2.why":"「不要…」的命令用 Don't + 原形。","g29/quiz.3.ko":"可以幫我一下嗎？——當然可以。","g29/quiz.3.why":"對方問的是「你介意嗎？」，所以 No 才是「不介意」。","g29/quiz.4.q":"「要不要休息一下？」用英文怎麼說？","g29/quiz.4.why":"提議用 Why don't we + 原形。","g30/summary":"真的有可能發生的條件用 If + 現在式，結果用 will。條件子句裡不用 will","g30/forms.0.label":"基本","g30/forms.1.label":"一貫的事實 · 命令","g30/points.0.h":"條件用現在式","g30/points.0.t":"即使是「明天下雨的話」，也是 If it will rain ✕ → If it rains ○。和 when · as soon as(第18課)是同樣的規則。","g30/points.1.h":"結果子句的形式","g30/points.1.t":"未來的結果用 will，一貫的事實用現在式(If you heat ice, it melts)，請求 · 命令用祈使句(If you see Jake, tell him)。","g30/points.2.h":"逗號","g30/points.2.t":"If 子句放前面要加逗號，放後面就不加。","g30/points.3.h":"when 和 if","g30/points.3.t":"when 用在一定會發生的事，if 用在不確定會不會發生的事。When I get home, I'll call you. / If I see her, I'll tell her.","g30/examples.0.ko":"如果明天下雨，我就待在家。","g30/examples.1.ko":"你要是告訴別人，我會生氣的。","g30/examples.2.ko":"如果你看到 Jake，叫他打電話給我。","g30/examples.3.ko":"把冰加熱，它就會融化。","g30/examples.4.ko":"如果他們說不行，你打算怎麼辦？","g30/mistake.why":"if 條件子句裡，即使是未來的事也用現在式。","g30/quiz.0.ko":"如果你餓了，冰箱裡有披薩。","g30/quiz.0.why":"if 條件子句用現在式。","g30/quiz.1.ko":"如果明天下雨，比賽就會取消。","g30/quiz.1.why":"即使是未來的事，if 子句也用現在式 rains。","g30/quiz.2.ko":"只要認真讀書，你就會考上。","g30/quiz.2.why":"未來的結果用 will。","g30/quiz.3.ko":"如果你見到 Mina，幫我問候她。","g30/quiz.3.why":"不確定會不會發生的條件用 If。","g30/quiz.4.q":"「如果你晚到，就打電話給我。」用英文怎麼說？","g30/quiz.4.why":"if 子句用現在式 you're，結果用祈使句。","g31/summary":"與現在事實相反或不太可能發生的事，用 If + 過去式，would + 原形。形式是過去式，意思卻是現在 · 未來","g31/forms.0.label":"基本","g31/forms.1.label":"be 動詞","g31/points.0.h":"過去式，卻在說現在","g31/points.0.t":"If I had money 的意思是「(現在沒錢，)如果有錢的話」。過去式是在表示「和現實有一點距離」。","g31/points.1.h":"和 If I do 的差別","g31/points.1.t":"If it rains tomorrow 是真的可能發生的事，If I won the lottery 是幾乎不會發生的事。覺得可能性很低時，就用過去式。","g31/points.2.t":"be 動詞不論主詞是誰，大多用 were。If I were you…(如果我是你)。口語中也會聽到 If I was…。","g31/points.3.h":"用 could · might 代替 would","g31/points.3.t":"「就能…」用 could，「也許會…」用 might。If I had a car, I could drive you.","g31/examples.0.ko":"如果有更多時間，我就去學吉他。","g31/examples.1.ko":"如果我是你，我就會去做那件事。","g31/examples.2.ko":"如果你中了樂透，會做什麼？","g31/examples.3.ko":"如果她住得近一點，我們就能更常見面。","g31/examples.4.ko":"如果我是你，我不會那樣做。","g31/mistake.why":"if 子句不用 would，要用過去式。","g31/quiz.0.ko":"如果我很有錢，我就去環遊世界。","g31/quiz.0.why":"與現在事實相反，所以 if 子句用過去式 were。","g31/quiz.1.ko":"如果你多用功一點，就會考上。","g31/quiz.1.why":"結果子句用 would + 原形。","g31/quiz.2.ko":"如果你有一百萬美元，你會做什麼？","g31/quiz.2.why":"if 子句用過去式 had。","g31/quiz.3.ko":"如果我是你，我就會打電話給她。","g31/quiz.3.why":"If I were you 是固定說法。","g31/quiz.4.q":"「(我現在沒有車，)如果我有車，就能載你。」用英文怎麼說？","g31/quiz.4.why":"是與現在相反的想像，所以 if 子句用 had，結果用 could。","g32/summary":"想像與過去相反的情況時，用 If + had 過去分詞，would have + 過去分詞(要是當初…就會…了)","g32/forms.0.label":"基本","g32/forms.1.label":"發音","g32/points.0.h":"與過去相反","g32/points.0.t":"想像一件已經過去、無法改變的事如果相反會怎樣。If I had left earlier, I wouldn't have missed the train. (實際上是太晚出門，錯過了)","g32/points.1.h":"中文的說法","g32/points.1.t":"就是「要是當初…就會…了」，用在後悔或慶幸的時候。","g32/points.2.h":"if 子句禁用 would","g32/points.2.t":"If I would have known ✕ → If I had known ○。美式口語中有時聽得到，但被視為錯誤的形式。","g32/points.3.h":"混合使用","g32/points.3.t":"過去的條件 + 現在的結果也可以。If I had taken that job, I'd be rich now.","g32/examples.0.ko":"如果我早知道，就會告訴你了。","g32/examples.1.ko":"如果早一點出門，就不會錯過火車了。","g32/examples.2.ko":"如果你當初邀請她，她就會來了。","g32/examples.3.ko":"要是沒下雨，我們就去海邊了。","g32/examples.4.ko":"要是沒遇見你，我現在的人生一定很無聊。","g32/mistake.why":"if 子句是 had + 過去分詞。","g32/quiz.0.ko":"如果當初更用功，就考上了。","g32/quiz.0.why":"與過去相反的條件用 had + 過去分詞。","g32/quiz.1.ko":"如果你當初開口，我就會幫你了。","g32/quiz.1.why":"結果子句用 would have + 過去分詞。","g32/quiz.2.ko":"如果當初用地圖，就不會迷路了。","g32/quiz.2.why":"結果子句用 wouldn't have + 過去分詞。","g32/quiz.3.ko":"如果她沒錯過公車，就不會遲到了。","g32/quiz.3.why":"if 子句用 hadn't + 過去分詞。","g32/quiz.4.q":"「如果我早知道，就會來了。」用英文怎麼說？","g32/quiz.4.why":"if 子句用 had known，結果子句用 would have come。","g33/summary":"希望現在不是這樣時用 wish + 過去式，對過去的事感到可惜時用 wish + had 過去分詞。if only 的語氣更強烈","g33/forms.0.label":"現在","g33/forms.1.label":"過去","g33/points.0.h":"與現在不同","g33/points.0.t":"wish 後面用過去式，意思是「要是現在…就好了」。I wish I lived near the sea. (實際上不住在海邊)","g33/points.1.h":"對過去的遺憾","g33/points.1.t":"wish 後面用 had + 過去分詞，意思是「要是當初…就好了」。I wish I hadn't said that.","g33/points.2.h":"如果能夠","g33/points.2.t":"I wish I could…(要是能…就好了)。I wish I could speak French.","g33/points.3.h":"wish 和 hope","g33/points.3.t":"對未來可能發生的事的期望用 hope。I hope you pass. 對方做了令人不耐的事而希望他改變，則用 wish + would (I wish you would stop)。","g33/examples.0.ko":"要是有更大的房子就好了。","g33/examples.1.ko":"要是你在這裡就好了。","g33/examples.2.ko":"要是我能像你一樣做菜就好了。","g33/examples.3.ko":"早知道就不要吃那麼多了。","g33/examples.4.ko":"要是我知道他的號碼就好了！","g33/mistake.why":"wish 後面時態要往過去退一格。can → could。","g33/quiz.0.ko":"要是我再高一點就好了。","g33/quiz.0.why":"是與現在不同的願望，所以用過去式 were。","g33/quiz.1.ko":"昨晚真該去那場派對的。聽說很好玩。","g33/quiz.1.why":"是對過去的遺憾，所以用 had + 過去分詞。","g33/quiz.2.ko":"要是我會說日文就好了。","g33/quiz.2.why":"wish 後面的 can 要改成 could。","g33/quiz.3.ko":"希望你明天考試通過。","g33/quiz.3.why":"對未來可能發生的事的期望用 hope。","g33/quiz.4.q":"「早知道就不要說那句話了。」用英文怎麼說？","g33/quiz.4.why":"是對過去的遺憾，所以用 hadn't + 過去分詞。","g34/summary":"unless(除非…)、in case(以防萬一…)、as long as(只要…)後面也和 if 一樣，未來的事用現在式表示","g34/points.0.t":"和 if … not 一樣。You'll be late unless you hurry. = …if you don't hurry. unless 後面不再加 not。","g34/points.1.h":"in case 和 if 不一樣","g34/points.1.t":"Take an umbrella in case it rains. 是「可能會下雨，先帶著」，Take an umbrella if it rains. 是「下雨的話再帶」。","g34/points.2.t":"表示「只要…就…」的條件。","g34/points.3.h":"三個都用現在式","g34/points.3.t":"unless it rains · in case it rains · as long as you come. 後面不用 will。","g34/examples.0.ko":"如果不下雨，我就去爬山。","g34/examples.1.ko":"帶件外套吧，以防天氣變冷。","g34/examples.2.ko":"只要你小心開，就可以用我的車。","g34/examples.3.ko":"除非你想說，否則我不會告訴任何人。","g34/examples.4.ko":"把我的號碼記下來，以防你需要幫忙。","g34/mistake.why":"unless 本身已經有 not 的意思。","g34/quiz.0.ko":"如果不塞車，我七點到。","g34/quiz.0.why":"「如果不…」用 unless。","g34/quiz.1.ko":"帶點現金吧，以防他們不收信用卡。","g34/quiz.1.why":"「以防萬一，先做準備」用 in case。","g34/quiz.2.ko":"只要打電話給我，你可以玩到很晚。","g34/quiz.2.why":"「只要…」用 as long as。","g34/quiz.3.ko":"你要是不快一點，就會錯過公車。","g34/quiz.3.why":"unless 後面不加 not，用現在式。","g34/quiz.4.q":"「帶把傘，以防下雨。」用英文怎麼說？","g34/quiz.4.why":"事先預防用 in case + 現在式。","g35/summary":"比起「是誰做的」，更在意「什麼事發生了、變成怎樣」時，用被動語態 be + 過去分詞","g35/forms.0.label":"現在 · 過去","g35/forms.1.label":"否定 · 疑問","g35/forms.2.label":"動作的人","g35/points.0.h":"什麼時候用","g35/points.0.t":"不知道是誰做的、顯而易見、或不重要的時候。My bike was stolen.(不知道是誰偷的) / Coffee is grown in Brazil.","g35/points.1.h":"造句方法","g35/points.1.t":"把受詞提到主詞的位置，動詞改成 be 動詞 + 過去分詞。They clean the office every day. → The office is cleaned every day.","g35/points.2.h":"動作的人用 by","g35/points.2.t":"只有一定要說時才加 by (by 在第③課會再談)。大部分情況都省略。","g35/points.3.h":"和中文不同的地方","g35/points.3.t":"中文說「這座橋是1990年建的」也很自然，但英文主詞是物品時要用被動語態。The bridge built in 1990 ✕","g35/examples.0.ko":"全世界都在使用英語。","g35/examples.1.ko":"這座橋建於1990年。","g35/examples.2.ko":"我的腳踏車昨晚被偷了。","g35/examples.3.ko":"辦公室每天傍晚都會打掃。","g35/examples.4.ko":"包裹昨天送到了嗎？","g35/mistake.why":"be 後面要接過去分詞 stolen，容易和過去式 stole 搞混。","g35/quiz.0.ko":"米在許多亞洲國家都有種植。","g35/quiz.0.why":"米是被種植的，所以用 is + 過去分詞 grown。","g35/quiz.1.ko":"艾菲爾鐵塔建於1889年。","g35/quiz.1.why":"是過去事情的被動，所以用 was built。","g35/quiz.2.ko":"我昨天在地鐵上被偷了皮夾。","g35/quiz.2.why":"用 was + 過去分詞 stolen。","g35/quiz.3.ko":"這些餅乾是手工做的嗎？","g35/quiz.3.why":"被動語態的疑問句把 be 動詞放前面。cookies 是複數，所以用 Are。","g35/quiz.4.q":"「這輛車是在韓國製造的。」用英文怎麼說？","g35/quiz.4.why":"車是被製造的，所以用 was made。","g36/title":"各種時態的被動語態","g36/summary":"被動語態也有各種時態的形式。進行式是 is being done，完成式是 has been done，未來式是 will be done","g36/forms.0.label":"進行","g36/forms.1.label":"完成","g36/forms.2.label":"未來","g36/points.0.h":"造句方法","g36/points.0.t":"保留原本時態的形式，只把最後的動詞改成 be + 過去分詞。They are cleaning the room. → The room is being cleaned.","g36/points.1.h":"進行式用 being","g36/points.1.t":"表示現在「正在被…」。Sorry, the elevator is being fixed.","g36/points.2.h":"完成式用 been","g36/points.2.t":"表示因此現在是這個結果。My flight has been canceled.","g36/points.3.h":"未來 · 助動詞","g36/points.3.t":"will · can · must 後面接 be + 過去分詞(第37課會詳細說明)。","g36/examples.0.ko":"這星期正在粉刷廚房。","g36/examples.1.ko":"我的班機被取消了。","g36/examples.2.ko":"新橋明年會完工。","g36/examples.3.ko":"我到的時候，車子正在修理。","g36/examples.4.ko":"票都賣完了。","g36/mistake.why":"房間不會自己打掃，所以要用被動進行式 is being cleaned。","g36/quiz.0.ko":"現在道路正在施工，換條路走吧。","g36/quiz.0.why":"現在正在被修，所以用 is being repaired。","g36/quiz.1.ko":"我們的訂單還沒送到。","g36/quiz.1.why":"完成式被動語態是 hasn't been + 過去分詞。","g36/quiz.2.ko":"優勝者明天會公布。","g36/quiz.2.why":"未來式被動語態是 will be + 過去分詞。","g36/quiz.3.ko":"暴風雨來的時候，我的車正在洗。","g36/quiz.3.why":"是過去正在被進行的事，所以用 was being washed。","g36/quiz.4.q":"「會議被取消了。」用英文怎麼說？","g36/quiz.4.why":"完成式被動語態是 has been canceled。","g37/title":"助動詞被動語態 · 以人為主詞的被動語態","g37/summary":"助動詞後面接 be + 過去分詞(can be done)。give · send · tell 這類有兩個受詞的動詞，也常用以人為主詞的被動語態(I was given…)","g37/forms.0.label":"助動詞","g37/forms.1.label":"以人為主詞","g37/points.0.h":"助動詞 + be + 過去分詞","g37/points.0.t":"can · could · will · must · should · might 後面接 be + 過去分詞。This medicine must be kept in the fridge.","g37/points.1.h":"過去用 have been","g37/points.1.t":"助動詞 + have been + 過去分詞。The package should have been delivered yesterday.","g37/points.2.h":"以人為主詞","g37/points.2.t":"They gave me a gift. 把 me 提到主詞位置，就是 I was given a gift. 英文覺得以人為主詞的說法更自然。","g37/points.3.h":"常用說法","g37/points.3.t":"I was told…(我聽說…)、We were offered…(我們被提供了…)、I wasn't invited.(我沒被邀請)","g37/examples.0.ko":"這個問題是可以解決的。","g37/examples.1.ko":"報告必須在星期五前完成。","g37/examples.2.ko":"我得到了第二次機會。","g37/examples.3.ko":"有人叫我們在外面等。","g37/examples.4.ko":"包裹昨天就該送到了。","g37/mistake.why":"事情不會自己做，所以要用 can be done。","g37/quiz.0.ko":"這扇門晚上必須上鎖。","g37/quiz.0.why":"門是被鎖上的，所以用 must be + 過去分詞。","g37/quiz.1.ko":"我拿到一張免費的票。","g37/quiz.1.why":"以人為主詞的被動語態是 was given。","g37/quiz.2.ko":"那個問題今天無法解決。","g37/quiz.2.why":"用 can't be + 過去分詞。","g37/quiz.3.ko":"她上星期被提供了那份工作。","g37/quiz.3.why":"她是接受提議的一方，所以用 was offered。","g37/quiz.4.q":"「我聽說了那個消息(有人告訴我)。」用英文怎麼說？","g37/quiz.4.why":"我是被告知的一方，所以用 was told。","g38/summary":"大家都這麼說的傳聞 · 資訊用 It is said that… / He is said to…，已經規定好或約好要做的事用 be supposed to","g38/points.0.t":"意思是「據說…」，常用在新聞 · 文章中。同樣意思也可以用 He is said to be…。口語中也常用 People say…。","g38/points.1.h":"同一個句型的動詞","g38/points.2.h":"be supposed to ① 規定的事","g38/points.2.t":"是規則 · 預定。You're supposed to take off your shoes here. (這裡是要脫鞋的)","g38/points.3.h":"be supposed to ② 本來應該…卻沒有","g38/points.3.t":"過去式的意思是「本來應該…(但沒做)」。He was supposed to call me.","g38/examples.0.ko":"據說那座城堡鬧鬼。","g38/examples.1.ko":"聽說他是這個社區最有錢的人。","g38/examples.2.ko":"您應該要繫上安全帶。","g38/examples.3.ko":"火車本來應該中午到的。","g38/examples.4.ko":"現在是要我怎麼辦？","g38/mistake.why":"是 be supposed to。容易漏掉 be 動詞和 -d。","g38/quiz.0.ko":"據說他會說五種語言。","g38/quiz.0.why":"是 It is said that…。","g38/quiz.1.ko":"聽說她非常聰明。","g38/quiz.1.why":"以人為主詞時用 is said to be。","g38/quiz.2.ko":"在電影院應該要關掉手機。","g38/quiz.2.why":"是 be supposed to。","g38/quiz.3.ko":"Jake 本來應該打電話給我，但他沒打。","g38/quiz.3.why":"是過去本來該做卻沒做的事，所以用 was supposed to。","g38/quiz.4.q":"「在這裡應該要脫鞋。」用英文怎麼說？","g38/quiz.4.why":"用 be supposed to + 原形。","g39/summary":"請別人代勞的事用 have + 物品 + 過去分詞(I had my hair cut)。口語中也用 get","g39/forms.2.label":"不好的事","g39/points.0.h":"和中文不同的地方","g39/points.0.t":"中文說「我剪頭髮了」就行，但說 I cut my hair 聽起來像是「我自己剪的」。如果是在美髮店剪的，要說 I had my hair cut / I got my hair cut。","g39/points.1.h":"順序","g39/points.1.t":"是 have + 物品 + 過去分詞。I had cut my hair ✕ (會變成過去完成式) → I had my hair cut ○","g39/points.2.t":"口語中更常用 get。I need to get my eyes checked.","g39/points.3.h":"遭遇的事","g39/points.3.t":"不是自己請人做，而是遭遇的事也能用。She had her bag stolen. (她的包包被偷了)","g39/examples.0.ko":"我昨天去剪頭髮了(在美髮店)。","g39/examples.1.ko":"下星期請人來粉刷廚房。","g39/examples.2.ko":"去檢查一下視力吧。","g39/examples.3.ko":"你在哪裡做的指甲？","g39/examples.4.ko":"他在地鐵上被偷了皮夾。","g39/mistake.why":"別人幫你做的事用 have / get + 物品 + 過去分詞。","g39/quiz.0.ko":"我上星期把車送去修了。","g39/quiz.0.why":"請人代勞的事用 had + 物品 + 過去分詞。","g39/quiz.1.ko":"她要去拍照。","g39/quiz.1.why":"用 get + 物品 + 過去分詞 taken。","g39/quiz.2.ko":"你在哪裡剪頭髮？","g39/quiz.2.why":"cut 的過去分詞還是 cut。","g39/quiz.3.ko":"他在演唱會上被偷了手機。","g39/quiz.3.why":"遭遇的事也用 had + 物品 + 過去分詞。","g39/quiz.4.q":"「我昨天在美髮店剪了頭髮。」用英文怎麼說？","g39/quiz.4.why":"是請美髮店做的事，所以用 had my hair cut。","g40/summary":"轉述別人的話時用 He said (that) + 句子。說話的時間是過去的話，轉述的內容時態也要往過去退一格","g40/forms.0.label":"往過去退一格","g40/points.0.h":"往過去退一格","g40/points.0.t":"說話的時間(said)是過去，所以轉述的內容也要往後退一格。am · is → was，will → would，can → could，過去式 → had + 過去分詞。","g40/points.1.h":"人 · 時間 · 地點也要改","g40/points.2.h":"that 可以省略","g40/points.2.t":"He said he was tired. 口語中常省略 that。","g40/points.3.h":"直接引述","g40/points.3.t":"連同雙引號直接引述是 He said, \\"I'm tired.\\"。對話中更常用轉述的說法。","g40/examples.0.ko":"他說他累了。","g40/examples.1.ko":"她說晚點會打電話。","g40/examples.2.ko":"Jake 說他不能來參加派對。","g40/examples.3.ko":"他們說已經吃過了。","g40/examples.4.ko":"Dana 說會議被取消了。","g40/mistake.why":"said 後面不能直接接人。要接人的話用 told me (第41課會詳細說明)。","g40/quiz.0.why":"am 往過去退一格，變成 was。","g40/quiz.1.why":"will 往過去退一格，變成 would。","g40/quiz.2.why":"can't 往過去退一格，變成 couldn't。","g40/quiz.3.why":"過去式 lost 再往過去退一格，變成 had lost。","g40/quiz.4.q":"\\"I'm busy today.\\" (上星期說的話) → She said she was busy ___.","g40/quiz.4.why":"說話的那天不是今天，所以 today 要改成 that day。","g41/title":"不改時態的情況 · say vs tell","g41/summary":"現在仍然是事實，或轉述的動詞是現在式時，可以不改時態。tell 後面一定要接人(tell me)，say 後面則接內容","g41/forms.0.label":"也可以不改","g41/forms.0.items.0":"He said he lives in Seoul. (現在還住在首爾)","g41/forms.0.items.1":"The email says I can stay. (現在邊讀邊轉述)","g41/points.0.h":"現在仍然正確的話","g41/points.0.t":"現在仍是事實時，時態可以保持不變。\\"I love New York.\\" → She said she loves New York. 改成往過去退一格也不算錯。","g41/points.1.h":"轉述的動詞是現在式","g41/points.1.t":"用 says · has said 轉述時不改時態。Mr. Han says I can stay. (現在正讀著信)","g41/points.2.t":"tell 後面一定要接人(tell me · tell Jake)。say 後面直接接內容，要接人的話用 say to me。","g41/points.3.h":"固定說法","g41/points.3.t":"tell the truth · tell a lie · tell a story · tell a joke 即使沒有人也用 tell，say hello · say sorry · say yes 則用 say。","g41/examples.0.ko":"她說她喜歡紐約(現在還喜歡)。","g41/examples.1.ko":"電子郵件上寫說我可以再多待一年。","g41/examples.2.ko":"他跟我說他很忙。","g41/examples.3.ko":"你跟她說了什麼？","g41/examples.4.ko":"不要告訴任何人。一個字都別說。","g41/mistake.why":"要接對方(me)就用 tell。tell the truth 是固定說法。","g41/quiz.0.ko":"他跟我說他很累。","g41/quiz.0.why":"後面直接接人(me)，所以用 told。","g41/quiz.1.ko":"她說她會晚到。","g41/quiz.1.why":"沒有接人，直接接內容，所以用 said。","g41/quiz.2.ko":"他有跟你說那個消息嗎？","g41/quiz.2.why":"後面直接接人(you)，所以用 tell。","g41/quiz.3.ko":"要永遠說實話。","g41/quiz.3.why":"tell the truth 是固定說法。","g41/quiz.4.q":"「他說他住在首爾(現在還住在首爾)。」用英文怎麼說？","g41/quiz.4.why":"現在仍是事實，所以 lives 不變，沒有接人所以用 said。","g42/title":"間接問句","g42/summary":"把問句放進句子裡時，不用疑問句的順序，而是「疑問詞 + 主詞 + 動詞」的順序。Do you know where she lives?","g42/forms.0.label":"疑問詞問句","g42/forms.1.label":"是 · 否問句","g42/points.0.h":"順序會改變","g42/points.0.t":"放進句子裡的問句用敘述句的順序。Do you know where is the station? ✕ → Do you know where the station is? ○","g42/points.1.h":"do · does · did 要拿掉","g42/points.1.t":"Where does he work? → I don't know where he works. (拿掉 does，work 加 -s)","g42/points.2.h":"是 · 否問句用 if · whether","g42/points.3.h":"禮貌的問法","g42/points.3.t":"對陌生人說 Could you tell me where…? 比 Where is…? 更有禮貌。","g42/examples.0.ko":"你知道車站在哪裡嗎？","g42/examples.1.ko":"可以告訴我現在幾點嗎？","g42/examples.2.ko":"我不知道他在哪裡工作。","g42/examples.3.ko":"我想知道她喜不喜歡我。","g42/examples.4.ko":"你記得我們是什麼時候見面的嗎？","g42/mistake.why":"句子裡的問句要拿掉 does，用敘述句的順序。","g42/quiz.0.ko":"你知道她住哪裡嗎？","g42/quiz.0.why":"句子裡的問句用主詞 + 動詞的順序。","g42/quiz.1.ko":"可以告訴我這個多少錢嗎？","g42/quiz.1.why":"拿掉 does，costs 要加 -s。","g42/quiz.2.ko":"我想知道他會不會來派對。","g42/quiz.2.why":"是 · 否問句用 if 放進句子裡。","g42/quiz.3.ko":"我不記得把鑰匙放在哪裡了。","g42/quiz.3.why":"拿掉 did，用主詞 + 動詞的順序。","g42/quiz.4.q":"「你知道洗手間在哪裡嗎？」用英文怎麼說？","g42/quiz.4.why":"句子裡要用 the restroom is 的順序。","g43/summary":"轉述命令用 tell + 人 + to do，轉述請求用 ask + 人 + to do。「不要…」用 not to do","g43/forms.0.label":"命令","g43/forms.1.label":"請求","g43/forms.2.label":"不要","g43/points.0.h":"轉述命令時","g43/points.0.t":"用 told + 人 + to + 原形。不用改時態，很方便。","g43/points.1.h":"轉述請求時","g43/points.1.t":"用 asked + 人 + to。像 Could you…? 這類禮貌的請求，也用 asked 轉述。","g43/points.2.h":"「不要…」的話","g43/points.2.t":"把 not 放在 to 前面。He told me not to worry.","g43/points.3.h":"同一個句型","g43/points.3.t":"want · would like · remind · advise + 人 + to。I want you to come. (第52課會再談)","g43/examples.0.ko":"醫生叫我多休息。","g43/examples.1.ko":"她請我幫忙。","g43/examples.2.ko":"Dana 叫我們不要遲到。","g43/examples.3.ko":"可以請你叫 Jake 打電話給我嗎？","g43/examples.4.ko":"媽媽總是叫我多吃一點。","g43/mistake.why":"「不要…」的話用 not to + 原形。","g43/quiz.0.ko":"她叫我把門關上。","g43/quiz.0.why":"用 tell + 人 + to + 原形。","g43/quiz.1.ko":"他請我不要遲到。","g43/quiz.1.why":"「不要…」的請求用 not to + 原形。","g43/quiz.2.ko":"可以請你叫他回我電話嗎？","g43/quiz.2.why":"轉述請求用 ask + 人 + to。","g43/quiz.3.ko":"老師叫我們把作業寫完。","g43/quiz.3.why":"用 tell + 人 + to + 原形。","g43/quiz.4.q":"「媽媽叫我不要擔心。」用英文怎麼說？","g43/quiz.4.why":"用 told + 人 + not to + 原形。","g44/title":"疑問句的造法","g44/summary":"疑問詞問的是「主詞」時，維持敘述句的順序(Who called?)；問的是「受詞」時，要用 do · does · did(Who did you call?)","g44/forms.0.label":"問主詞","g44/forms.1.label":"問受詞","g44/forms.2.label":"be · 助動詞","g44/points.0.h":"基本順序","g44/points.0.t":"疑問詞 + 助動詞(do · be · can…) + 主詞 + 動詞。Where do you live? / What are you doing?","g44/points.1.h":"問主詞時不用 do","g44/points.1.t":"問是誰做的(主詞)時，不用 do · did。Who called you?(誰打電話給你？) / Who did you call?(你打電話給誰？)","g44/points.2.t":"問發生了什麼事時，what 是主詞，所以 What did happen? ✕ → What happened? ○","g44/points.3.h":"疑問詞 + 名詞","g44/examples.0.ko":"今天早上誰打電話給你？","g44/examples.1.ko":"今天早上你打電話給誰？","g44/examples.2.ko":"發生什麼事了？","g44/examples.3.ko":"她說了什麼？","g44/examples.4.ko":"有多少人來參加派對？","g44/mistake.why":"what 是主詞，所以不用 did。","g44/quiz.0.ko":"誰打破了窗戶？——是 Jake。","g44/quiz.0.why":"問的是誰(主詞)，所以不用 did，直接用 broke。","g44/quiz.1.ko":"你在派對上遇到了誰？","g44/quiz.1.why":"問的是誰(受詞)，所以用 did + 主詞 + 原形。","g44/quiz.2.ko":"怎麼了？你為什麼在哭？","g44/quiz.2.why":"what 是主詞，所以是 What happened?。","g44/quiz.3.ko":"哪一路公車到機場？","g44/quiz.3.why":"which bus 是主詞，所以不用 does，直接用 goes。","g44/quiz.4.q":"「是誰做了這個蛋糕？」用英文怎麼說？","g44/quiz.4.why":"who 是主詞，所以不用 did，直接用 made。","g45/title":"否定疑問句","g45/summary":"Don't you…? · Isn't it…? 這類用否定來問的句子，表達驚訝 · 確認 · 邀請。回答時英文只看「事實」來選 Yes · No，和中文的「對／不」不同","g45/forms.0.label":"形式","g45/forms.1.label":"邀請","g45/points.0.h":"語感","g45/points.0.t":"是「不是理所當然嗎？」(確認)、「咦，不是嗎？」(驚訝)、「為什麼不…呢？」(邀請)。Isn't this view amazing? (這景色不是很美嗎？)","g45/points.1.h":"回答的陷阱","g45/points.1.t":"中文會回答「對，我不累」或「不，我不累」，要看你同意的是哪一句話；英文則是事實「不累」就用 No。Aren't you tired? — No, I'm not.(對，我不累) / Yes, I am.(不，我累)","g45/points.2.t":"不是在問理由，而是「要不要…？」的邀請(和第29課的 Why don't we…? 一樣)。","g45/examples.0.ko":"你不喜歡咖啡嗎？","g45/examples.1.ko":"這景色不是很美嗎？","g45/examples.2.ko":"你不累嗎？——對，我不累。","g45/examples.3.ko":"你沒收到我的訊息嗎？","g45/examples.4.ko":"要不要休息一下？","g45/mistake.right":"Aren't you hungry? — No, I'm not. (我不餓)","g45/mistake.why":"回答要依事實。不餓的話就是 No, I'm not。","g45/quiz.0.ko":"你不想跟我們一起去嗎？","g45/quiz.0.why":"you + 一般動詞 want 的否定疑問句是 Don't you。","g45/quiz.1.q":"Aren't you cold? — ___ (不冷)","g45/quiz.1.why":"事實是「不冷」，所以是 No, I'm not。","g45/quiz.2.ko":"她昨天沒打電話給你嗎？","g45/quiz.2.why":"過去事情的否定疑問句用 Didn't。","g45/quiz.3.ko":"你看起來很累。要不要早點回家？","g45/quiz.3.why":"邀請用 Why don't you…?。","g45/quiz.4.q":"「這個不是很好吃嗎？」用英文怎麼說？","g45/quiz.4.why":"是 be 動詞 is 的否定疑問句 Isn't this…?。","g46/title":"簡短回答 (I think so · So do I · Neither do I)","g46/summary":"簡短回答時只留下助動詞。So do I(我也是)、Neither do I(我也不)、I think so(我想是)","g46/forms.0.label":"簡短回答","g46/forms.1.label":"我也 · 我也不","g46/points.0.h":"用助動詞回應","g46/points.0.t":"用前一句的助動詞(do · be · can · have…)簡短回應。Yes, I do. / No, she can't.","g46/points.1.h":"So + 助動詞 + 主詞","g46/points.1.t":"意思是「我也是」。要配合前一句選助動詞。I'm hungry. — So am I. / I went there. — So did I. 口語中也常用 Me too。","g46/points.2.h":"Neither + 助動詞 + 主詞","g46/points.2.t":"意思是「我也不」。口語用 Me neither.。回應否定句時用 Me too 是錯的。","g46/points.3.t":"「我想是 · 希望如此」。否定是 I don't think so · I hope not (I hope so not ✕)。","g46/examples.0.ko":"我喜歡這首歌。——我也是！","g46/examples.1.ko":"我不會做菜。——我也不會。","g46/examples.2.ko":"Mina 會來嗎？——我想會。","g46/examples.3.ko":"明天會下雨嗎？——希望不會。","g46/examples.4.ko":"你報告寫完了嗎？——寫完了。","g46/mistake.why":"回應否定句的「我也不」要用 neither。","g46/quiz.0.ko":"我累了。——我也是。","g46/quiz.0.why":"前一句是 I'm，所以用 So am I。","g46/quiz.1.ko":"我沒去派對。——我也沒去。","g46/quiz.1.why":"前一句是 didn't，所以用 Neither did I。","g46/quiz.2.ko":"我會說西班牙文。——我也會。","g46/quiz.2.why":"前一句是 can，所以用 So can I。","g46/quiz.3.ko":"會下雪嗎？——希望不會。","g46/quiz.3.why":"「希望不會」是 I hope not。","g46/quiz.4.q":"I don't like spicy food. — ___ (我也不喜歡)","g46/quiz.4.why":"回應否定句的「我也不」是 Me neither。","g47/title":"附加問句","g47/summary":"接在句尾用來確認「對吧？」的說法。前面是肯定就加否定，前面是否定就加肯定","g47/forms.0.label":"基本","g47/forms.1.label":"一般動詞","g47/forms.2.label":"特殊","g47/points.0.h":"造句方法","g47/points.0.t":"把前一句的助動詞換成相反的(肯定 ↔ 否定)，主詞用代名詞代替。Jake is here, isn't he?","g47/points.1.h":"一般動詞用 do","g47/points.2.h":"語調","g47/points.2.t":"句尾下降是「對吧？」(確認)，上升是「是嗎？」(真的不知道而問)。","g47/points.3.h":"依事實回答","g47/points.3.t":"You're not busy, are you? — No, I'm not.(對，我不忙)。和否定疑問句(第45課)一樣。","g47/examples.0.ko":"天氣真好，對吧？","g47/examples.1.ko":"你會來派對，對吧？","g47/examples.2.ko":"她住在布魯克林，對吧？","g47/examples.3.ko":"你沒跟他說，對吧？","g47/examples.4.ko":"我們休息一下，好嗎？","g47/mistake.why":"前面是一般動詞 like，所以用 don't you。isn't it 不能隨便亂加。","g47/quiz.0.ko":"你是首爾人，對吧？","g47/quiz.0.why":"前面是 You're(肯定)，所以用 aren't you。","g47/quiz.1.ko":"他會開車，對吧？","g47/quiz.1.why":"can(肯定)，所以用 can't he。","g47/quiz.2.ko":"他們沒來，對吧？","g47/quiz.2.why":"didn't(否定)，所以用 did they。","g47/quiz.3.ko":"我遲到了，對吧？","g47/quiz.3.why":"I'm 的附加問句比較特殊，是 aren't I。","g47/quiz.4.q":"「你喜歡咖啡，對吧？」用英文怎麼說？","g47/quiz.4.why":"you + 一般動詞 like，所以用 don't you。","g48/title":"強調 do · 代替動詞的助動詞","g48/summary":"在動詞前加 do · does · did 表示「真的…」的強調；不想重複同一個動詞時，只留下助動詞","g48/forms.0.label":"強調","g48/forms.1.label":"代替","g48/points.0.h":"強調的 do","g48/points.0.t":"對方懷疑或想法相反時，用來加重語氣說「我真的…」。do 要重讀。I did lock the door! (我真的有鎖門！)","g48/points.1.h":"形式","g48/points.1.t":"do · does · did + 原形。She does work hard. (✕ does works)","g48/points.2.h":"代替動詞的助動詞","g48/points.2.t":"不重複前面出現過的動詞，用助動詞回應。Do you like it? — I do. / Have you finished? — I have.","g48/points.3.h":"熱情的邀請","g48/points.3.t":"像 Do come in!(快請進！)這樣熱情邀請時也能用。","g48/examples.0.ko":"我真的很喜歡你的新髮型！","g48/examples.1.ko":"她今天看起來真的很累。","g48/examples.2.ko":"我真的有打電話！是你沒接啊。","g48/examples.3.ko":"誰要吃披薩？——我！","g48/examples.4.ko":"他說會做完，也真的做完了。","g48/mistake.why":"does 後面接原形 work。","g48/quiz.0.ko":"我真的很喜歡這首歌！","g48/quiz.0.why":"I 的強調是 do + 原形。","g48/quiz.1.ko":"他今天看起來真的很開心。","g48/quiz.1.why":"he 的強調是 does + 原形。","g48/quiz.2.ko":"是誰打破了杯子？——是我。對不起！","g48/quiz.2.why":"用 did 代替 broke(過去式)。","g48/quiz.3.ko":"我沒想到會考上，但我考上了。","g48/quiz.3.why":"用 did 代替 passed。","g48/quiz.4.q":"「我真的有鎖門！」用英文怎麼說？","g48/quiz.4.why":"強調用 did + 原形 lock。","g49/title":"以介系詞結尾的問句","g49/summary":"像 Who are you talking to? 這樣，英文問句常把介系詞留在句尾。對話中這樣說很自然","g49/forms.0.label":"留在句尾的介系詞","g49/points.0.h":"介系詞在句尾","g49/points.0.t":"talk to someone → Who are you talking to? 漏掉介系詞就錯了。Who are you talking? ✕","g49/points.1.h":"正式用法","g49/points.1.t":"To whom are you talking? 是非常拘謹的書面語，對話中幾乎不用。","g49/points.2.h":"常用問句","g49/points.2.t":"Where are you from?(你是哪裡人？) / What is it for?(這是做什麼用的？) / What are you waiting for?(你還在等什麼？) / What's it about?(內容是關於什麼？)","g49/points.3.h":"間接問句也一樣","g49/points.3.t":"像 I don't know who she's talking to. 一樣留在句尾。","g49/examples.0.ko":"你在跟誰講電話？","g49/examples.1.ko":"你在看什麼？","g49/examples.2.ko":"你是哪裡人？","g49/examples.3.ko":"這個按鈕是做什麼用的？","g49/examples.4.ko":"你跟誰一起去的？","g49/mistake.why":"因為是 wait for someone，所以 for 要留在句尾。","g49/quiz.0.ko":"你在笑什麼？","g49/quiz.0.why":"因為是 laugh at something，所以 at 留在句尾。","g49/quiz.1.ko":"你跟誰去看電影？","g49/quiz.1.why":"因為是 go with someone，所以 with 留在句尾。","g49/quiz.2.ko":"這本書是關於什麼的？——關於太空。","g49/quiz.2.why":"因為是 a book about something，所以 about 留在句尾。","g49/quiz.3.ko":"你還在等什麼？去吧！","g49/quiz.3.why":"因為是 wait for，所以 for 留在句尾。","g49/quiz.4.q":"「你剛才在跟誰說話？」用英文怎麼說？","g49/quiz.4.why":"因為是 talk to，所以 to 留在句尾，問句順序是 were you。","g50/title":"動詞 + -ing","g50/summary":"enjoy · finish · mind · avoid · keep · suggest 這類動詞後面接的是 -ing，不是 to","g50/forms.0.label":"接 -ing 的動詞","g50/points.0.h":"只接 -ing 的動詞","g50/points.1.h":"為什麼是 -ing","g50/points.1.t":"這些動詞給人的感覺是在處理「已經在做或做過的事」。而望向未來的 want · hope 後面接 to (第51課)。","g50/points.2.h":"否定","g50/points.2.t":"用 not + -ing。I enjoy not working on weekends.","g50/points.3.h":"片語動詞後面也接 -ing","g50/examples.0.ko":"我喜歡煮東西給朋友吃。","g50/examples.1.ko":"你吃完了嗎？","g50/examples.2.ko":"可以請你等幾分鐘嗎？","g50/examples.3.ko":"他一直打電話給我。","g50/examples.4.ko":"我無法想像住在別的地方。","g50/mistake.why":"enjoy 後面接 -ing。","g50/quiz.0.ko":"我真的很喜歡住在紐約。","g50/quiz.0.why":"enjoy 後面接 -ing。","g50/quiz.1.ko":"可以請你關一下門嗎？","g50/quiz.1.why":"mind 後面接 -ing。","g50/quiz.2.ko":"她在午夜寫完了報告。","g50/quiz.2.why":"finish 後面接 -ing。","g50/quiz.3.ko":"他提議搭計程車。","g50/quiz.3.why":"suggest 後面接 -ing。","g50/quiz.4.q":"「他一直問同樣的問題。」用英文怎麼說？","g50/quiz.4.why":"keep 後面接 -ing，主詞是 he，所以用 keeps。","g51/title":"動詞 + to","g51/summary":"want · decide · hope · plan · need · promise · refuse 這類動詞後面接 to + 原形。它們是望向「未來要做的事」的動詞","g51/forms.0.label":"接 to 的動詞","g51/forms.1.label":"否定","g51/points.0.h":"望向未來","g51/points.0.t":"want · hope · plan · decide 指向還沒發生的事，所以帶有「朝向未來」感覺的 to 很適合。(第50課的 enjoy · finish 接 -ing)","g51/points.1.h":"否定用 not to","g51/points.1.t":"I decided not to go.(我決定不去)。和 I didn't decide to go.(我沒決定要去)意思不同。","g51/points.2.t":"He seems to be tired.(他好像很累) / I can't afford to buy it.(我買不起)","g51/points.3.t":"比 want to 更有禮貌。I'd like to order now.","g51/examples.0.ko":"我決定留在紐約。","g51/examples.1.ko":"希望很快能再見到你。","g51/examples.2.ko":"她答應不告訴任何人。","g51/examples.3.ko":"我買不起新車。","g51/examples.4.ko":"他最近看起來很開心。","g51/mistake.why":"want 後面接 to + 原形。","g51/quiz.0.ko":"我決定找新工作。","g51/quiz.0.why":"decide 後面接 to + 原形。","g51/quiz.1.ko":"她拒絕收那筆錢。","g51/quiz.1.why":"refuse 後面接 to + 原形。","g51/quiz.2.ko":"我們打算下個月去濟州島。","g51/quiz.2.why":"plan 後面接 to + 原形。","g51/quiz.3.ko":"我不會再遲到了，我保證。","g51/quiz.3.why":"否定用 not to + 原形。","g51/quiz.4.q":"「他好像很累。」用英文怎麼說？","g51/quiz.4.why":"seem 後面接 to be，主詞是 he，所以用 seems。","g52/title":"動詞 + 人 + to","g52/summary":"want · ask · expect · help · encourage + 人 + to do。表示「希望別人…」或叫別人做事的說法","g52/forms.0.label":"基本","g52/points.0.h":"常見的錯誤","g52/points.0.t":"「我希望你來」很容易照字面說成 I want that you come ✕。英文是 I want you to come.。","g52/points.1.h":"同一個句型的動詞","g52/points.1.t":"want · would like · ask · tell(第43課) · expect · allow · encourage · remind · advise · teach。","g52/points.2.h":"help 可以省略 to","g52/points.2.t":"Can you help me (to) move this? 美式英語中省略 to 的說法更常見。","g52/points.3.h":"否定","g52/points.3.t":"I want you not to worry. 也可以，但對話中 I don't want you to worry. 更自然。","g52/examples.0.ko":"我希望你見見我的父母。","g52/examples.1.ko":"Dana 期待我們星期五前完成。","g52/examples.2.ko":"爸爸鼓勵我去留學看看。","g52/examples.3.ko":"可以幫我搬這個箱子嗎？","g52/examples.4.ko":"我希望你不要擔心。","g52/mistake.why":"want 後面不接 that 子句。要用 want + 人 + to。","g52/quiz.0.ko":"我希望你見見我姊姊。","g52/quiz.0.why":"用 would like + 人 + to。","g52/quiz.1.ko":"我的老闆要我把報告完成。","g52/quiz.1.why":"用 want + 人 + to。","g52/quiz.2.ko":"可以幫我搬這張桌子嗎？","g52/quiz.2.why":"help + 人 後面可以省略 to，用原形。","g52/quiz.3.ko":"老師又提醒我們要帶書來。","g52/quiz.3.why":"用 remind + 人 + to。","g52/quiz.4.q":"「我希望你快樂。」用英文怎麼說？","g52/quiz.4.why":"用 want + 人 + to be。","g53/title":"意思會改變的動詞 (remember · stop · try)","g53/summary":"remember · forget · stop · try 後面接 -ing 是「已經做過 · 在做的事」，接 to 是「未來要做的事」，意思不同","g53/forms.0.items.0":"remember -ing (記得做過) · remember to (別忘了去做)","g53/forms.1.items.0":"stop -ing (停止正在做的事) · stop to (停下來去做)","g53/forms.2.items.0":"try -ing (試著做做看) · try to (努力想做)","g53/points.0.h":"規則","g53/points.0.t":"-ing 是「已經存在 · 正在做的事」(第50課)，to 是「未來要做的事」(第51課)。意思就靠這個感覺來區分。","g53/points.1.t":"I remember meeting her.(我記得見過她) / Remember to call her.(別忘了打電話給她) / I'll never forget seeing the ocean.(我永遠忘不了第一次看到海)","g53/points.2.t":"He stopped smoking.(他戒菸了) / He stopped to smoke.(他停下來去抽菸)","g53/points.3.t":"Try turning it off and on.(試著關掉再打開) / I tried to open the door, but it was locked.(我想打開門，但門鎖住了)","g53/examples.0.ko":"我記得在機場見過你。","g53/examples.1.ko":"別忘了鎖門。","g53/examples.2.ko":"她停止了哭泣。","g53/examples.3.ko":"我停下來一下去買咖啡。","g53/examples.4.ko":"試著把手機關掉再開機。","g53/mistake.why":"是提醒別忘了未來要做的事，所以用 to。","g53/quiz.0.ko":"我永遠忘不了第一次看到海的樣子。","g53/quiz.0.why":"是忘不了已經做過的事，所以用 -ing。","g53/quiz.1.ko":"出門前別忘了關燈。","g53/quiz.1.why":"是未來要做的事，所以用 to。","g53/quiz.2.ko":"老師一進來，他就停止說話了。","g53/quiz.2.why":"停下的是正在說的話，所以用 -ing。","g53/quiz.3.ko":"印表機不能用。試著關掉再打開。","g53/quiz.3.why":"是試試看的意思，所以用 try -ing。","g53/quiz.4.q":"「我記得見過她。」用英文怎麼說？","g53/quiz.4.why":"是記得已經做過的事，所以用 remember -ing。","g54/summary":"喜歡用 like + -ing/to，更喜歡用 prefer A to B，這次寧可做什麼用 would rather + 原形","g54/points.0.t":"後面接 -ing 和 to 都可以。美式英語也常用 to。不過 would like 一定接 to (I'd like to go)。","g54/points.1.t":"意思是「比起 B 更喜歡 A」。比較對象前面不用 than，而用 to。I prefer cats to dogs.","g54/points.2.t":"意思是「(這次)寧可…」。後面不加 to，直接接原形，比較用 than。I'd rather walk than take a taxi.","g54/points.3.h":"委婉的拒絕","g54/points.3.t":"I'd rather not.(我寧可不要)是委婉的拒絕。","g54/examples.0.ko":"我喜歡煮東西給朋友吃。","g54/examples.1.ko":"比起咖啡，我更喜歡茶。","g54/examples.2.ko":"今晚我寧可待在家。","g54/examples.3.ko":"她說她寧可走路也不想搭計程車。","g54/examples.4.ko":"你想談那件事嗎？——我寧可不要。","g54/mistake.why":"是 prefer A to B。than 是和 would rather 一起用的。","g54/quiz.0.ko":"比起開車，我更喜歡走路。","g54/quiz.0.why":"是 prefer A to B。","g54/quiz.1.ko":"今晚我寧可待在家。","g54/quiz.1.why":"would rather 後面接原形。","g54/quiz.2.ko":"我寧可走路，也不想等公車。","g54/quiz.2.why":"是 would rather A than B。","g54/quiz.3.ko":"你想喝點什麼嗎？","g54/quiz.3.why":"would like 後面一定接 to。","g54/quiz.4.q":"「我寧可不談那件事。」用英文怎麼說？","g54/quiz.4.why":"用 would rather not + 原形。","g55/title":"介系詞 + -ing","g55/summary":"介系詞(at · of · about · for · without · instead of · before · after…)後面接動詞時，要改成 -ing","g55/forms.0.label":"常用搭配","g55/points.0.h":"介系詞後面是名詞的位置","g55/points.0.t":"介系詞後面要接名詞，所以動詞要改成 -ing，變得像名詞。good at cook ✕ → good at cooking ○","g55/points.1.h":"to 是介系詞的時候","g55/points.1.t":"look forward to · be used to(第56課) · get used to 裡的 to 是介系詞，所以後面接 -ing。I look forward to seeing you. (✕ to see)","g55/points.2.h":"常用搭配","g55/points.3.h":"before · after 也是介系詞","g55/points.3.t":"before going to bed(睡前)、after eating(吃完後)。","g55/examples.0.ko":"我不擅長帶領團隊。","g55/examples.1.ko":"謝謝你幫我搬家。","g55/examples.2.ko":"她沒打招呼就走了。","g55/examples.3.ko":"我們別擔心了，來做個計畫吧。","g55/examples.4.ko":"我對學韓文有興趣。","g55/mistake.why":"介系詞 in 後面接 -ing。","g55/quiz.0.ko":"她真的很會記人名。","g55/quiz.0.why":"介系詞 at 後面接 -ing。","g55/quiz.1.ko":"謝謝你邀請我。","g55/quiz.1.why":"介系詞 for 後面接 -ing。","g55/quiz.2.ko":"他連外套都沒帶就出門了。","g55/quiz.2.why":"介系詞 without 後面接 -ing。","g55/quiz.3.ko":"期待見到你。","g55/quiz.3.why":"look forward to 裡的 to 是介系詞，所以接 -ing。","g55/quiz.4.q":"「睡前要刷牙。」用英文怎麼說？","g55/quiz.4.why":"介系詞 before 後面接 -ing。","g56/summary":"be used to -ing 是「習慣…」，get used to -ing 是「逐漸習慣…」。和第28課的 used to(以前…)是不同的說法","g56/forms.0.label":"已經習慣的狀態","g56/forms.1.label":"正在習慣中","g56/forms.2.label":"比較","g56/forms.2.items.0":"I used to live alone. (以前我一個人住)","g56/points.0.h":"be used to = 已經習慣的狀態","g56/points.0.t":"I'm used to waking up early. (我習慣早起)","g56/points.1.h":"get used to = 逐漸習慣的過程","g56/points.1.t":"It took me a month to get used to the subway. (我花了一個月才習慣搭地鐵)","g56/points.2.h":"to 是介系詞","g56/points.2.t":"所以後面接 -ing 或名詞。I'm used to work ✕ → I'm used to working ○ / I'm used to the cold ○","g56/points.3.h":"和 used to 區分","g56/points.3.t":"I used to drink coffee.(以前喝，現在不喝) / I'm used to drinking coffee.(我習慣喝咖啡)","g56/examples.0.ko":"我習慣和室友一起住。","g56/examples.1.ko":"她還不習慣這種寒冷。","g56/examples.2.ko":"別擔心，你很快就會習慣的。","g56/examples.3.ko":"我正在習慣在家工作。","g56/examples.4.ko":"我花了幾個星期才習慣在這裡開車。","g56/mistake.why":"be used to 裡的 to 是介系詞，所以後面接 -ing。","g56/quiz.0.ko":"我不習慣吃這麼多。","g56/quiz.0.why":"be used to 後面接 -ing。","g56/quiz.1.ko":"別擔心，你很快就會習慣的。","g56/quiz.1.why":"逐漸習慣是 get used to。","g56/quiz.2.ko":"我以前住在釜山，現在住在首爾。","g56/quiz.2.why":"「以前是…」用 used to + 原形(第28課)。","g56/quiz.3.ko":"她正在習慣靠左行駛。","g56/quiz.3.why":"get used to 後面接 -ing。","g56/quiz.4.q":"「我習慣早起。」用英文怎麼說？","g56/quiz.4.why":"用 be used to + -ing。","g57/title":"表示目的的 to · so that","g57/summary":"「為了…」用 to + 原形(in order to)；主詞不同，或需要 can · will 時，用 so that + 句子","g57/forms.0.label":"to + 原形","g57/points.0.h":"to + 原形 = 目的","g57/points.0.t":"I came here to see you.(我來這裡是為了見你)。就是中文的「為了…」。for + 動詞原形 ✕ (I came here for see you ✕)","g57/points.1.t":"語氣稍微拘謹。否定是 in order not to · so as not to。","g57/points.2.t":"後面常接主詞 + can · will · could。I'll write it down so that I don't forget.","g57/points.3.h":"for + 名詞","g57/points.3.t":"目的是名詞時用 for。I went out for coffee. = I went out to get coffee.","g57/examples.0.ko":"我提早來是為了幫你搬家。","g57/examples.1.ko":"她正在存錢買車。","g57/examples.2.ko":"把窗戶打開，讓味道散掉。","g57/examples.3.ko":"我會把它寫下來，免得忘記。","g57/examples.4.ko":"我提早出門是為了避開塞車。","g57/mistake.why":"用動詞說明目的時用 to + 原形。for 後面接名詞。","g57/quiz.0.ko":"我打電話來是要談會議的事。","g57/quiz.0.why":"目的用 to + 原形。","g57/quiz.1.ko":"我們去咖啡廳喝咖啡。","g57/quiz.1.why":"目的是名詞(coffee)，所以用 for。","g57/quiz.2.ko":"說大聲一點，讓大家都聽得到。","g57/quiz.2.why":"後面接主詞 + can，所以用 so that。","g57/quiz.3.ko":"他搭計程車是為了不要遲到。","g57/quiz.3.why":"目的的否定用 so as not to。","g57/quiz.4.q":"「我來是為了見你。」用英文怎麼說？","g57/quiz.4.why":"目的用 to + 原形。","g58/summary":"see · hear · watch + 人 + 原形/-ing，make(強迫) · let(允許) · have(請託) + 人 + 原形","g58/forms.0.label":"看見和聽見","g58/forms.1.label":"使役","g58/points.0.h":"see + 人 + 原形","g58/points.0.t":"是從頭到尾整個過程都看到的時候。I saw him cross the street. (我看到他走完整條馬路)","g58/points.1.h":"see + 人 + -ing","g58/points.1.t":"是看到對方「正在」做的時候。I saw him crossing the street. (我看到他正在過馬路)","g58/points.2.h":"make · let · have + 人 + 原形","g58/points.2.t":"不用 to。make 是強迫，let 是允許，have 是請託。She made me wait. (✕ made me to wait)","g58/points.3.t":"常用來表示「讓我來…」的提議。Let me think. / Let me know.","g58/examples.0.ko":"我看到 Noah 在修架子。","g58/examples.1.ko":"我聽到有人在樓上唱歌。","g58/examples.2.ko":"媽媽逼我吃蔬菜。","g58/examples.3.ko":"讓我來幫你。","g58/examples.4.ko":"我會叫 Jake 回電給你。","g58/mistake.why":"make · let · have 後面不用 to，直接接原形。","g58/quiz.0.ko":"老闆要我留到很晚。","g58/quiz.0.why":"用 make + 人 + 原形。","g58/quiz.1.ko":"讓我給你看個東西。","g58/quiz.1.why":"用 let + 人 + 原形。","g58/quiz.2.ko":"我聽到有人在敲門。","g58/quiz.2.why":"用 hear + 人 + 原形(或 -ing)。","g58/quiz.3.ko":"我父母週末讓我玩到很晚。","g58/quiz.3.why":"用 let + 人 + 原形。","g58/quiz.4.q":"「媽媽要我打掃房間。」用英文怎麼說？","g58/quiz.4.why":"用 make + 人 + 原形。","g59/title":"可數 · 不可數名詞","g59/summary":"可以一個一個數的名詞(a cat, two cats)和不可數名詞(water, money, advice)，搭配的用詞不一樣","g59/forms.0.label":"可數","g59/forms.1.label":"不可數","g59/forms.2.label":"計量單位","g59/points.0.h":"不可數名詞","g59/points.0.t":"是整塊的東西或抽象概念。water · milk · rice · money · time · information · advice · furniture · homework · news。不加 a/an，也不加 -s。","g59/points.1.h":"和中文不同的地方","g59/points.1.t":"有些東西中文看起來可以數，英文卻是不可數的。advice(建議) · information(資訊) · furniture(家具) · luggage(行李) · homework(作業)。an advice ✕ · informations ✕","g59/points.2.h":"要數就加單位","g59/points.2.t":"a piece of advice · a piece of furniture · two cups of coffee (of 和第③課是同樣的畫面)。","g59/points.3.h":"兩種都可以的詞","g59/points.3.t":"a coffee(一杯咖啡) · coffee(咖啡這種飲料)，a light(一盞燈) · light(光)。意思會稍微不同。","g59/examples.0.ko":"我需要一些建議。","g59/examples.1.ko":"你有多少錢？","g59/examples.2.ko":"我買了很多家具。","g59/examples.3.ko":"可以給我一杯水嗎？","g59/examples.4.ko":"我養了兩隻貓和一隻狗。","g59/mistake.why":"advice 是不可數名詞，不能加 a/an。","g59/quiz.0.ko":"我今晚有很多作業。","g59/quiz.0.why":"homework 不可數，所以不加 -s。","g59/quiz.1.ko":"我們還有多少時間？","g59/quiz.1.why":"time 不可數，所以用 much。","g59/quiz.2.ko":"她給了我一些很好的建議。","g59/quiz.2.why":"advice 不可數，所以用 some。","g59/quiz.3.ko":"我告訴你一則資訊。","g59/quiz.3.why":"information 不可數，所以用 a piece of 來數。","g59/quiz.4.q":"「家具太多了。」用英文怎麼說？","g59/quiz.4.why":"furniture 不可數，所以用 is · much。","g60/summary":"a/an 用在「(多個之中的)一個」，或第一次提到的東西。看的不是拼字，而是第一個「發音」是母音就用 an","g60/forms.0.items.0":"a cat · a university (讀作 yu 的音，[j] 音) · a one-way ticket","g60/forms.1.items.0":"an apple · an hour (讀作 aʊr，h 不發音) · an MBA (讀作 em-bee-ay)","g60/forms.2.label":"每","g60/points.0.h":"第一次提到時","g60/points.0.t":"是聽的人還不知道的「某一個」。I saw a cat. The cat was black. (第二次之後用 the，第61課)","g60/points.1.h":"用發音來選","g60/points.1.t":"看的不是字母，而是第一個發音是母音就用 an。an hour · an honest man (h 不發音) / a university · a European city ([j] 音)","g60/points.2.h":"職業 · 種類","g60/points.2.t":"說職業時一定要加 a/an。I'm a designer. (✕ I'm designer) 中文沒有冠詞，所以很容易漏掉。","g60/points.3.h":"「每…」","g60/points.3.t":"once a day(一天一次)，60 km an hour(時速60公里)。","g60/examples.0.ko":"我是來自首爾的設計師。","g60/examples.1.ko":"到那裡要花一個小時。","g60/examples.2.ko":"她在波士頓的一所大學讀書。","g60/examples.3.ko":"我需要一把傘。","g60/examples.4.ko":"我一星期去三次健身房。","g60/mistake.why":"說職業時一定要加 a/an。","g60/quiz.0.ko":"她是個誠實的人。","g60/quiz.0.why":"honest 的 h 不發音，所以以母音音開頭，要用 an。","g60/quiz.1.ko":"我等了一個小時。","g60/quiz.1.why":"hour 讀作 [aʊr]，以母音音開頭，所以用 an。","g60/quiz.2.ko":"他就讀首爾的一所大學。","g60/quiz.2.why":"university 以 [ju] 的音開頭，所以用 a。","g60/quiz.3.ko":"我哥哥是工程師。","g60/quiz.3.why":"職業要加 a/an，engineer 以母音音開頭，所以用 an。","g60/quiz.4.q":"「我是護理師。」用英文怎麼說？","g60/quiz.4.why":"職業要加 a。","g61/title":"the ① 雙方都知道的東西","g61/summary":"說話的人和聽的人都知道「是哪一個」時，就用 the。第一次提到用 a，再次提到用 the","g61/forms.0.label":"再次提到時","g61/forms.1.label":"從情境得知時","g61/forms.2.label":"後面有修飾時","g61/points.0.h":"第一次用 a，之後用 the","g61/points.0.t":"I saw a cat. The cat was black. 第二次起指的是「剛才那隻貓」，所以用 the。","g61/points.1.h":"從情境得知時","g61/points.1.t":"在同一個房間裡說 Close the door.（那扇門），在家裡說 Where's the remote?（我們家那個遙控器）。即使是第一次提到，只要明顯知道是哪一個，也用 the。","g61/points.2.h":"後面修飾、限定為唯一一個時","g61/points.2.t":"the man in the gray jacket（穿灰色外套的那個男人）、the café across the street（對面街上的那間咖啡廳）。","g61/points.3.h":"中文裡沒有的東西","g61/points.3.t":"中文不一定要說「那個」，但英文在可數的單數名詞前，幾乎一定要加 a · the · my 之類的詞。","g61/examples.0.ko":"我買了一盞檯燈。那盞檯燈是黃色的。","g61/examples.1.ko":"可以幫我關一下窗戶嗎？","g61/examples.2.ko":"洗手間在哪裡？","g61/examples.3.ko":"對面街上那間咖啡廳的咖啡很好喝。","g61/examples.4.ko":"你餵貓了嗎？","g61/mistake.why":"這是再次提到已經說過的貓，所以用 the。","g61/quiz.0.ko":"我在派對上認識了一個男生。那個男生來自芝加哥。","g61/quiz.0.why":"這是再次提到已經說過的男生，所以用 The。","g61/quiz.1.ko":"可以幫我關燈嗎？我想睡覺了。","g61/quiz.1.why":"指的是這個房間的那盞燈，雙方都知道，所以用 the。","g61/quiz.2.ko":"我需要一支新手機。我的壞掉了。","g61/quiz.2.why":"是還沒確定的某一支，所以用 a。","g61/quiz.3.ko":"那個穿紅色洋裝的女生是誰？","g61/quiz.3.why":"後面的修飾把範圍限定為唯一一個，所以用 the。","g61/quiz.4.q":"\\"我昨天看了一部電影。那部電影真的很好看。\\"用英文怎麼說？","g61/quiz.4.why":"第一次提到用 a movie，再次提到用 the movie。","g62/title":"the ② 唯一的東西 · 樂器 · the + 形容詞","g62/summary":"世上獨一無二的東西（the sun）、演奏樂器（play the piano）、一群人（the rich）、最高級（the best）都要用 the","g62/forms.0.label":"唯一","g62/forms.1.label":"樂器 · 群體","g62/forms.2.label":"最高級 · 序數","g62/points.0.h":"唯一的東西","g62/points.0.t":"the sun, the moon, the world, the internet, the sea。每個人想到的都是同一個。","g62/points.1.h":"樂器與運動","g62/points.1.t":"「演奏樂器」是 play the + 樂器。運動不加冠詞：play soccer · play tennis。","g62/points.2.h":"the + 形容詞 = 那一類人","g62/points.2.t":"the rich（有錢人）、the elderly（長者）、the young（年輕人）。當複數使用：The rich are…","g62/points.3.h":"最高級 · 序數 · same","g62/points.3.t":"the best, the first, the last, the same 都是限定為唯一一個，所以要用 the。","g62/examples.0.ko":"看看月亮！超亮的。","g62/examples.1.ko":"Noah 鋼琴彈得真好。","g62/examples.2.ko":"這個座位是給長者坐的。","g62/examples.3.ko":"這是附近最好吃的披薩。","g62/examples.4.ko":"我們居然同一天生日！","g62/mistake.why":"樂器要加 the，運動不加冠詞。","g62/quiz.0.ko":"太陽從東邊升起。","g62/quiz.0.why":"太陽只有一個，所以用 The。","g62/quiz.1.ko":"你會彈吉他嗎？","g62/quiz.1.why":"演奏樂器是 play the + 樂器。","g62/quiz.2.ko":"下班後去打網球吧。","g62/quiz.2.why":"運動不用冠詞。","g62/quiz.3.ko":"今天是我人生中最棒的一天！","g62/quiz.3.why":"最高級 best 前面要用 the。","g62/quiz.4.q":"\\"年輕人很常用手機。\\"用英文怎麼說？","g62/quiz.4.why":"the + 形容詞是「那一類人」，不加 -s。","g63/title":"不加冠詞 (school · work · home)","g63/summary":"像 school · work · home · bed 這種為了「該處本來的用途」而去的地方，不加冠詞","g63/forms.0.label":"不加冠詞","g63/forms.1.label":"餐點 · 星期 · 月份","g63/forms.2.label":"當作建築物時","g63/forms.2.items.0":"go to the school（因為有事要去學校那棟建築）","g63/points.0.h":"為了本來的用途時","g63/points.0.t":"去讀書是 go to school，去上班是 go to work，去睡覺是 go to bed。說的是那個地方的「活動」。","g63/points.1.h":"home 很特別","g63/points.1.t":"go home · at home · come home。不用 to（go to home ✕）。","g63/points.2.h":"當作建築物時用 the","g63/points.2.t":"家長去找老師談話，是 go to the school（去那所學校的建築）。","g63/points.3.h":"餐點 · 星期 · 月份","g63/points.3.t":"have breakfast, on Monday, in July 都不加冠詞。","g63/examples.0.ko":"我搭地鐵上班。","g63/examples.1.ko":"她在學校待到三點。","g63/examples.2.ko":"晚了。回家吧。","g63/examples.3.ko":"我通常半夜十二點睡覺。","g63/examples.4.ko":"媽媽去學校見老師了。","g63/mistake.why":"home 前面不用冠詞，也不用 to。","g63/quiz.0.ko":"晚了。我要回家了。","g63/quiz.0.why":"home 前面沒有冠詞，也沒有 to。","g63/quiz.1.ko":"他還在公司。六點下班。","g63/quiz.1.why":"人在上班的地方是 at work。","g63/quiz.2.ko":"你通常幾點睡？","g63/quiz.2.why":"去睡覺是 go to bed。","g63/quiz.3.ko":"一起吃午餐吧。","g63/quiz.3.why":"餐點不用冠詞。","g63/quiz.4.q":"\\"孩子們在學校（上課）。\\"用英文怎麼說？","g63/quiz.4.why":"人在學校讀書是 at school。","g64/title":"泛指的說法 (Dogs… vs The dogs…)","g64/summary":"要說「一般來說是這樣」時，用不加冠詞的複數（Dogs）或不可數名詞（Coffee）。加了 the 就變成「那個特定的」","g64/forms.0.label":"泛指","g64/forms.1.label":"特指","g64/points.0.h":"泛指時不加冠詞","g64/points.0.t":"I like dogs.（喜歡狗這種動物）/ I like the dogs.（喜歡那些狗）","g64/points.1.h":"不可數名詞也一樣","g64/points.2.h":"中文母語者常犯的錯","g64/points.2.t":"「我喜歡狗」很容易說成 I like dog ✕ / I like the dog（那隻狗）。泛指要用複數 dogs。","g64/points.3.h":"縮小範圍就用 the","g64/points.3.t":"people（泛指一般人）/ the people in my office（我辦公室裡的人）。","g64/examples.0.ko":"貓非常獨立。","g64/examples.1.ko":"我喜歡咖啡，但不喜歡公司的咖啡。","g64/examples.2.ko":"人生太短，不該拿來擔心。","g64/examples.3.ko":"這棟大樓裡的人真的很親切。","g64/examples.4.ko":"你怕狗嗎？","g64/mistake.why":"泛指喜歡「狗這種動物」時，用不加冠詞的複數。","g64/quiz.0.ko":"我真的很喜歡貓（貓這種動物）。","g64/quiz.0.why":"泛指要用不加冠詞的複數。","g64/quiz.1.ko":"睡眠對健康很重要。","g64/quiz.1.why":"不可數名詞泛指時不加冠詞。","g64/quiz.2.ko":"這間咖啡廳的音樂真好聽。","g64/quiz.2.why":"指的是這間咖啡廳特定的音樂，所以用 the。","g64/quiz.3.ko":"人們通常都很親切。","g64/quiz.3.why":"泛指一般人，所以不加冠詞，用 People。","g64/quiz.4.q":"\\"我喜歡恐怖片。\\"用英文怎麼說？","g64/quiz.4.why":"是泛指喜歡的東西，所以用不加冠詞的複數。","g65/title":"地名與 the","g65/summary":"大部分國家 · 城市 · 街道 · 公園的名稱不加 the，但河 · 海 · 複數名稱 · 含 \\"States/Kingdom\\" 的名稱要加 the","g65/forms.0.label":"不加 the","g65/forms.1.label":"要加 the","g65/points.0.h":"基本上不加冠詞","g65/points.0.t":"國家 · 城市 · 州 · 街道 · 公園 · 廣場 · 機場大多不加 the。I live in Seoul. / Let's meet in Central Park.","g65/points.1.h":"要加 the 的名稱","g65/points.1.t":"河 · 海 · 沙漠（the Han River, the Pacific）、複數名稱（the Philippines, the Alps）、含 States · Kingdom · Republic 的國家（the United States, the UK）。","g65/points.2.h":"含 of 的名稱","g65/points.2.t":"像 the Statue of Liberty（自由女神像）這種用 of 連接的名稱，常常要加 the。","g65/points.3.h":"要背起來的","g65/points.3.t":"the Netherlands, the Bronx（紐約的一區）。與其背規則，多聽比較快。","g65/examples.0.ko":"我來自韓國，她來自菲律賓。","g65/examples.1.ko":"我們去哈德遜河搭船吧。","g65/examples.2.ko":"我們在中央公園野餐了。","g65/examples.3.ko":"她去年搬到美國了。","g65/examples.4.ko":"你看過自由女神像嗎？","g65/mistake.why":"城市名稱不加 the。","g65/quiz.0.ko":"我表哥住在英國。","g65/quiz.0.why":"含 Kingdom 的國名要加 the。","g65/quiz.1.ko":"我們在漢江搭了船。","g65/quiz.1.why":"河的名稱要加 the。","g65/quiz.2.ko":"我沒去過日本。","g65/quiz.2.why":"國名通常不加 the。","g65/quiz.3.ko":"我們在時代廣場見面吧。","g65/quiz.3.why":"廣場名稱不加 the。","g65/quiz.4.q":"\\"她來自美國。\\"用英文怎麼說？","g65/quiz.4.why":"含 States 的國名要加 the。","g66/title":"容易搞混的單複數名詞","g66/summary":"news 雖然有 -s 但是單數，police · people 雖然沒有 -s 但是複數。jeans · glasses 這種成對的東西永遠是複數","g66/forms.0.label":"單數","g66/forms.1.label":"複數","g66/forms.2.label":"計算","g66/points.0.h":"有 -s 但是單數","g66/points.1.h":"沒有 -s 但是複數","g66/points.2.h":"成對的東西","g66/points.2.t":"jeans · pants · glasses · scissors · shorts 永遠是複數。要數一個時用 a pair of。","g66/points.3.h":"金額 · 時間 · 距離的總量是單數","g66/points.3.t":"Ten dollars is a lot. / Two hours is too long. 把它們當作一個整體的量。","g66/examples.0.ko":"這個消息真棒！","g66/examples.1.ko":"警方正在找那個小偷。","g66/examples.2.ko":"我的眼鏡在桌上。","g66/examples.3.ko":"我買了一條牛仔褲。","g66/examples.4.ko":"一件 T 恤 50 美元太貴了。","g66/mistake.why":"news 雖然有 -s，但是不可數的單數。","g66/quiz.0.ko":"那個消息讓人很驚訝。","g66/quiz.0.why":"news 是單數，所以用 was。","g66/quiz.1.ko":"警察來了。","g66/quiz.1.why":"police 是複數，所以用 are。","g66/quiz.2.ko":"我的太陽眼鏡在哪裡？","g66/quiz.2.why":"glasses 是成對的東西，所以是複數，用 are。","g66/quiz.3.ko":"我需要一雙新鞋。","g66/quiz.3.why":"成對的東西要用 a pair of 來數。","g66/quiz.4.q":"\\"人們真的很親切。\\"用英文怎麼說？","g66/quiz.4.why":"people 沒有 -s 也是複數。","g67/title":"名詞 + 名詞 · 's","g67/summary":"前面的名詞修飾後面的名詞時用名詞 + 名詞（a coffee cup），人或動物的所有物用 's（Mina's cat）","g67/forms.0.label":"名詞 + 名詞","g67/points.0.h":"名詞 + 名詞","g67/points.0.t":"前面的名詞說明「是哪一種」。a coffee cup（咖啡杯）、a phone case（手機殼）。前面的名詞通常用單數（a shoes store ✕ → a shoe store）。","g67/points.1.h":"數字 + 名詞 + 名詞","g67/points.1.t":"a ten-minute walk（十分鐘的路程）、a five-dollar bill。要用連字號，而且用單數（✕ ten-minutes）。","g67/points.2.h":"'s = 人 · 動物的所有物","g67/points.2.t":"Jake's guitar, the cat's bed。複數以 -s 結尾時只加 '：my parents' house。","g67/points.3.h":"表示地點的 's","g67/points.3.t":"像 at Leo's（在 Leo 的店裡）、at my mom's（在我媽媽家）一樣，也可以省略後面的名詞。","g67/examples.0.ko":"可以借我手機充電器嗎？","g67/examples.1.ko":"從這裡走到咖啡廳要五分鐘。","g67/examples.2.ko":"這是我媽媽的旅行箱。","g67/examples.3.ko":"貓的床在窗邊。","g67/examples.4.ko":"我們在 Leo 的店見吧。","g67/mistake.why":"放在名詞前面修飾的數字 + 名詞要用單數。","g67/quiz.0.ko":"開車到機場要三十分鐘。","g67/quiz.0.why":"修飾用的數字 + 名詞要用連字號，而且用單數。","g67/quiz.1.ko":"孩子們的房間在哪裡？","g67/quiz.1.why":"複數以 -s 結尾時只加 '。","g67/quiz.2.ko":"我需要一支新牙刷。","g67/quiz.2.why":"名詞 + 名詞合成了一個詞。","g67/quiz.3.ko":"這是 Mina 的包包嗎？","g67/quiz.3.why":"人的所有物用 's。","g67/quiz.4.q":"\\"公車站在哪裡？\\"用英文怎麼說？","g67/quiz.4.why":"名詞 + 名詞，說成 bus stop。","g68/summary":"主詞和受詞是同一個人時，用 myself · yourself 這類反身代名詞。也用來強調「親自 · 獨自」","g68/forms.0.label":"形式","g68/forms.1.label":"用法","g68/forms.2.label":"固定說法","g68/points.0.h":"主詞 = 受詞","g68/points.0.t":"I hurt myself.（我讓自己受傷 = 我受傷了）。I hurt me ✕","g68/points.1.h":"親自 · 親手","g68/points.1.t":"I painted the wall myself.（我親手漆的牆）","g68/points.2.h":"by + 反身代名詞 = 獨自","g68/points.2.t":"He lives by himself.（他獨自生活）= alone。","g68/points.3.h":"固定說法","g68/points.3.t":"Help yourself.（請自行取用）· Enjoy yourself.（玩得開心）· Make yourself at home.（請當自己家）· Take care of yourself.（好好照顧自己）","g68/examples.0.ko":"小心。別割到自己。","g68/examples.1.ko":"餅乾請自行取用。","g68/examples.2.ko":"這件洋裝是我自己做的。","g68/examples.3.ko":"她一個人住在布魯克林。","g68/examples.4.ko":"請當自己家！","g68/mistake.why":"主詞（I）和受詞是同一個人時，用 myself。","g68/quiz.0.ko":"他踢足球時受傷了。","g68/quiz.0.why":"和主詞 he 是同一個人，所以用 himself。","g68/quiz.1.ko":"這間房子是我們自己蓋的。","g68/quiz.1.why":"we 的反身代名詞是 ourselves。","g68/quiz.2.ko":"請當自己家。","g68/quiz.2.why":"Make yourself at home 是固定說法。","g68/quiz.3.ko":"她喜歡一個人旅行。","g68/quiz.3.why":"獨自要說 by herself。","g68/quiz.4.q":"\\"派對上玩得開心！\\"用英文怎麼說？","g68/quiz.4.why":"Enjoy yourself 是固定說法。","g69/summary":"「我的一個朋友」是 a friend of mine，「我自己的 · 屬於我的」是 my own，「獨自」是 on my own","g69/points.0.t":"my friend 是「（特定的）我的朋友」，a friend of mine 是「我的朋友之一」。a my friend ✕","g69/points.1.h":"所有格代名詞","g69/points.1.t":"mine · yours · his · hers · ours · theirs。of 後面要接所有格代名詞（a friend of me ✕）。","g69/points.2.t":"強調「是我自己的，不是別人的」。I want my own room. / She started her own company.","g69/points.3.t":"意思是「不靠別人幫忙，獨自完成」。I did it on my own.","g69/examples.0.ko":"Noah 是我的朋友。","g69/examples.1.ko":"她的一位表親在那間醫院工作。","g69/examples.2.ko":"這是我自己的食譜。","g69/examples.3.ko":"她終於有自己的房子了。","g69/examples.4.ko":"我自己修好了架子。","g69/mistake.why":"a 和 my 不能一起用。","g69/quiz.0.ko":"Jake 是我的好朋友。","g69/quiz.0.why":"of 後面要接所有格代名詞 mine。","g69/quiz.1.ko":"我想有一天開自己的公司。","g69/quiz.1.why":"屬於自己的要說 my own。","g69/quiz.2.ko":"這是你自己做的嗎？","g69/quiz.2.why":"獨自要說 on my own · on your own。","g69/quiz.3.ko":"我們的一位鄰居是知名的廚師。","g69/quiz.3.why":"of 後面要接所有格代名詞 ours。","g69/quiz.4.q":"\\"那是他自己的想法。\\"用英文怎麼說？","g69/quiz.4.why":"屬於他自己的要說 his own。","g70/summary":"第一次提到「有～」時用 there is · there are，指已經提過的東西，或說天氣 · 時間 · 距離時用 it is","g70/forms.0.label":"有","g70/points.0.t":"用來告知「有」新的東西。後面的名詞是單數用 is，複數用 are。There are many people here.","g70/points.1.t":"用來再次指已經提過的東西，或像天氣 · 時間 · 日期 · 距離這種沒有其他主詞的情況。It's raining.","g70/points.2.h":"搭配使用","g70/points.2.t":"There's a new café on my street. It's really cozy.（有 → 它）","g70/points.3.h":"中文母語者常犯的錯","g70/points.3.t":"「這裡有一隻貓」很容易說成 Here has a cat ✕ / It has a cat ✕。要說 There's a cat here.","g70/examples.0.ko":"對面街上有一間咖啡廳。","g70/examples.1.ko":"我們大樓裡有兩隻貓。","g70/examples.2.ko":"請問這附近有藥局嗎？","g70/examples.3.ko":"今天真的好熱。","g70/examples.4.ko":"我真的很喜歡這間咖啡廳。非常溫馨。","g70/mistake.why":"告知「有～」時用 there is。it has 是「它擁有」的意思。","g70/quiz.0.ko":"演唱會上有很多人。","g70/quiz.0.why":"過去式的「有」+ 複數 people，所以用 There were。","g70/quiz.1.ko":"外面很冷。穿上外套。","g70/quiz.1.why":"天氣用 It's。","g70/quiz.2.ko":"請問這附近有不錯的餐廳嗎？","g70/quiz.2.why":"問有沒有時用 Is there…?","g70/quiz.3.ko":"現在幾點？— 九點半。","g70/quiz.3.why":"時間用 It's。","g70/quiz.4.q":"\\"冰箱裡有一些牛奶。\\"用英文怎麼說？","g70/quiz.4.why":"「有」是 there is，milk 不可數，所以用 is。","g71/summary":"「一些 · 幾個」用 some。否定句和疑問句通常用 any，但邀請或請求時，即使是疑問句也用 some","g71/forms.0.items.1":"Would you like some tea?（邀請時）","g71/forms.1.items.1":"Call me any time.（任何時候）","g71/points.0.t":"可數的複數（some apples）和不可數名詞（some water）都能用。表示不說明確切數量的「一些 · 幾個」。","g71/points.1.t":"用在否定句（I don't have any money）和疑問句（Do you have any questions?）。not any = 一個也沒有。","g71/points.2.h":"疑問句卻用 some","g71/points.2.t":"期待對方回答「好」而邀請或請求時，用 some。Would you like some coffee? / Can I have some water?","g71/points.3.h":"肯定句裡的 any","g71/points.3.t":"如果是「任何一個 · 隨便哪個」的意思，肯定句也用 any。You can sit in any seat.","g71/examples.0.ko":"我包包裡有一些口香糖。","g71/examples.1.ko":"你有問題嗎？","g71/examples.2.ko":"牛奶一點都不剩了。","g71/examples.3.ko":"要不要來點咖啡？","g71/examples.4.ko":"任何時候都可以打給我。","g71/mistake.why":"否定句用 any。not any 合起來就是「一個也沒有」的意思。","g71/quiz.0.ko":"你有兄弟姊妹嗎？","g71/quiz.0.why":"這是不知道有沒有而發問的疑問句，所以用 any。","g71/quiz.1.ko":"抱歉。我身上一點現金都沒有。","g71/quiz.1.why":"這是否定句，所以用 any。","g71/quiz.2.ko":"要不要吃點蛋糕？","g71/quiz.2.why":"邀請時，即使是疑問句也用 some。","g71/quiz.3.ko":"冰箱裡有一些水。","g71/quiz.3.why":"肯定句 + 不可數的 water，所以用 some。","g71/quiz.4.q":"\\"請隨便坐哪個位子。\\"用英文怎麼說？","g71/quiz.4.why":"如果是「任何一個」的意思，肯定句也用 any。","g72/summary":"「一個也沒有」在名詞前用 no，單獨使用時用 none。「什麼都沒有」是 nothing，「沒有人」是 no one","g72/forms.0.label":"名詞前","g72/forms.1.label":"單獨","g72/points.0.h":"no + 名詞","g72/points.0.t":"no 一定放在名詞前面。I have no time. = I don't have any time. 用 no 聽起來比較斬釘截鐵。","g72/points.1.t":"後面不接名詞，單獨使用。\\"How much money do you have?\\" \\"None.\\" none of + the · my · these + 名詞 = ～當中沒有任何東西 · 任何人","g72/points.2.t":"nothing 是「什麼都沒有」，no one（= nobody）是「沒有人」。要用單數動詞：Nothing is wrong. / No one knows.","g72/points.3.h":"否定只用一次","g72/points.3.t":"「沒有人來」要說 No one came.，不能說 No one didn't come ✕。英文的否定只用一次。","g72/examples.0.ko":"我沒有時間可以浪費。","g72/examples.1.ko":"沒有人找得到那個按鈕。","g72/examples.2.ko":"沒有任何使用者完成第一頁。","g72/examples.3.ko":"程式碼裡沒有任何問題。","g72/examples.4.ko":"還剩幾片餅乾？— 一片都沒有。","g72/mistake.why":"nobody · nothing · no one 本身就是否定。不要再加 not。","g72/quiz.0.ko":"我完全不知道。","g72/quiz.0.why":"在名詞 idea 前面，所以用 no。","g72/quiz.1.ko":"咖啡還剩多少？— 一點都沒有。","g72/quiz.1.why":"後面不接名詞、單獨使用，所以用 None。","g72/quiz.2.ko":"我的朋友沒有一個來。","g72/quiz.2.why":"在 of + 特定的一群人前面，所以用 None。","g72/quiz.3.ko":"盒子裡什麼都沒有。是空的。","g72/quiz.3.why":"「什麼都沒有」是 nothing。","g72/quiz.4.q":"\\"沒有人接電話。\\"用英文怎麼說？","g72/quiz.4.why":"No one 本身已經是否定，所以不要再加 not。","g73/summary":"可數名詞用 many · a few，不可數名詞用 much · a little。去掉 a 就變成「幾乎沒有」的意思","g73/forms.0.label":"可數","g73/forms.0.items.0":"many people · a few friends · few chances（幾乎沒有）","g73/forms.1.label":"不可數","g73/forms.1.items.0":"much time · a little money · little hope（幾乎沒有）","g73/forms.1.items.1":"a lot of 兩者都 OK：a lot of people · a lot of time","g73/points.0.t":"many 用於可數的複數（many users），much 用於不可數名詞（much time）。much 主要用在否定句和疑問句：I don't have much time. / How much is it?","g73/points.1.h":"肯定句用 a lot of","g73/points.1.t":"肯定句裡的「很多」通常用 a lot of。I have a lot of work. 比 I have much work. 自然。","g73/points.2.t":"「有一些」帶有正面的感覺。a few 用於可數名詞（a few days），a little 用於不可數名詞（a little sugar）。","g73/points.3.h":"沒有 a 的時候","g73/points.3.t":"few · little 帶有「幾乎沒有」的遺憾感。I have a few friends.（我有一些朋友）↔ I have few friends.（我幾乎沒有朋友）","g73/examples.0.ko":"我沒有很多時間。","g73/examples.1.ko":"上週有多少使用者打電話來？","g73/examples.2.ko":"只有幾個人感到滿意。","g73/examples.3.ko":"一個小小的改變就能帶來很大的不同。","g73/examples.4.ko":"現在幾乎沒有希望了。","g73/mistake.why":"people 是可數的複數，所以用 many。much 用於不可數名詞。","g73/quiz.0.ko":"你需要多少錢？","g73/quiz.0.why":"money 不可數，所以用 much。","g73/quiz.1.ko":"我在首爾有幾個朋友。","g73/quiz.1.why":"可數的 friends 有一些，所以用 a few。","g73/quiz.2.ko":"可以在我的咖啡裡加一點牛奶嗎？","g73/quiz.2.why":"不可數的 milk 一點點，所以用 a little。","g73/quiz.3.ko":"派對上的人太多了。","g73/quiz.3.why":"people 是可數的複數，所以用 many。","g73/quiz.4.q":"\\"他幾乎沒有朋友。\\"用英文怎麼說？","g73/quiz.4.why":"沒有 a，只用 few，就是「幾乎沒有」。","g74/summary":"「～當中的全部 · 大部分 · 一部分」是 all · most · some 後面接 of + the · my · these + 名詞。泛指時不加 of","g74/forms.0.label":"特定的一群","g74/forms.1.label":"泛指","g74/points.0.h":"加 of 的時候","g74/points.0.t":"說特定一群當中的一部分時，用 of + the · my · this 之類的詞 + 名詞。Most of my friends live in Seoul.（我朋友當中的大部分）","g74/points.1.h":"不加 of","g74/points.1.t":"泛指人 · 狗之類的一般類別時，不加 of，直接接名詞。Most people ✓ / Most of people ✕（和 64 課泛指的說法是同一個原理）","g74/points.2.h":"代名詞前面","g74/points.2.t":"us · you · them · it 前面一定要加 of。all of us ✓ / all us ✕。all 也可以不加 of，說成 all the students。","g74/points.3.h":"動詞的單複數","g74/points.3.t":"配合 of 後面的名詞。Most of the cake is gone.（單數）/ Most of the guests are here.（複數）","g74/examples.0.ko":"我們大家都超興奮的。","g74/examples.1.ko":"我爸爸做的菜大多很特別。","g74/examples.2.ko":"她的家人當中有幾位不會說韓語。","g74/examples.3.ko":"大部分的人都喜歡音樂。","g74/examples.4.ko":"那些人全都來參加派對了。","g74/mistake.why":"泛指一般人時，不加 of，說 Most people。Most of 用在加了 the · my 之類的詞的特定一群人前面。","g74/quiz.0.ko":"我大部分的朋友都住在首爾。","g74/quiz.0.why":"my friends 是特定的一群，所以用 Most of。","g74/quiz.1.ko":"大部分的人都喜歡披薩。","g74/quiz.1.why":"泛指一般人，所以不加 of，用 Most。","g74/quiz.2.ko":"我們大家都去了海邊。","g74/quiz.2.why":"代名詞 us 前面要加 of。","g74/quiz.3.ko":"蛋糕少了一部分。","g74/quiz.3.why":"of 後面的 the cake 是不可數的單一個體，所以用 is。","g74/quiz.4.q":"\\"那些學生當中有幾個遲到了。\\"用英文怎麼說？","g74/quiz.4.why":"Some of + the students + 複數動詞 were。","g75/summary":"在兩者之間，「兩個都」是 both，「兩者之一 · 哪一個都可以」是 either，「兩個都不」是 neither","g75/forms.0.label":"兩個都 · 其中一個 · 兩個都不","g75/forms.1.label":"代名詞","g75/points.0.t":"是兩個都的意思。用複數動詞。Both of you love hiking. both A and B = A 和 B 兩個都。","g75/points.1.t":"是兩者中任選一個的意思。後面接單數名詞：either day。either A or B = A 或 B。放在否定句句尾表示「也」：I don't like it either.","g75/points.2.t":"是兩個都不的意思。本身已經是否定，所以不加 not。Neither of us is good at it. neither A nor B = A 和 B 都不是。","g75/points.3.h":"中文母語者常犯的錯","g75/points.3.t":"「我們兩個都不去」如果說成 Both of us don't go，會很彆扭。Neither of us is going. 才自然。","g75/examples.0.ko":"你們兩個都喜歡爬山嘛。","g75/examples.1.ko":"我們兩個都很不會準備派對。","g75/examples.2.ko":"巧克力或草莓，隨便買哪一個都行。","g75/examples.3.ko":"兩個我都喜歡。","g75/examples.4.ko":"我不吃肉。— 我也不吃。","g75/mistake.why":"「兩個都沒來」用 neither 一次說完。Both … not 可能會被理解成「不是兩個都來了」。","g75/quiz.0.ko":"我爸媽兩個人都是老師。","g75/quiz.0.why":"兩個都 + 複數動詞 are，所以用 Both。","g75/quiz.1.ko":"兩張椅子隨便坐哪一張都可以。","g75/quiz.1.why":"兩者中任選一個 + 單數 chair，所以用 either。","g75/quiz.2.ko":"我們兩個都不知道答案。","g75/quiz.2.why":"是兩個都不，所以用 Neither。不需要另外加 not。","g75/quiz.3.ko":"我不喜歡恐怖片。— 我也不喜歡。","g75/quiz.3.why":"否定句句尾的「也」是 either。","g75/quiz.4.q":"\\"她咖啡和茶都不喝。\\"用英文怎麼說？","g75/quiz.4.why":"A 和 B 都不是，就用 neither A nor B。不要再加 doesn't。","g76/summary":"「每一個」是 every + 單數，「全部」是 all + 複數。「整個 · 整體」是 the whole + 單數","g76/forms.0.label":"每一個","g76/forms.0.items.0":"every day · every table（單數）","g76/forms.0.items.1":"all the tables · all my life（複數 · 不可數）","g76/forms.1.label":"整體","g76/forms.1.items.1":"everyone · everything = every + one · thing（單數動詞）","g76/points.0.t":"是一個一個、毫無遺漏的「每一個」。後面接單數名詞 + 單數動詞：Every guest has a seat.","g76/points.1.t":"是作為一整群的「所有 · 全部」。和複數或不可數名詞一起用：All the guests are here. / all the money","g76/points.2.t":"是一個東西的「整個 · 完整」。放在 the · my 後面：the whole cake（整個蛋糕）、my whole life（我的一輩子）","g76/points.3.t":"every day 是「每天」，all day 是「一整天」。I practiced every day. / I worked all day.","g76/examples.0.ko":"全家人都來了。","g76/examples.1.ko":"我每天都練習這場演講。","g76/examples.2.ko":"就這樣而已。","g76/examples.3.ko":"每個人都很親切。","g76/examples.4.ko":"我工作了一整天。","g76/mistake.why":"every 後面接單數名詞和單數動詞。要用複數說的話，是 All the guests are here.","g76/quiz.0.ko":"每個學生都有一台筆電。","g76/quiz.0.why":"單數 student + has，所以用 Every。","g76/quiz.1.ko":"她一個人吃掉了整個披薩。","g76/quiz.1.why":"整個披薩要用 the whole。","g76/quiz.2.ko":"我一整天都待在家。","g76/quiz.2.why":"一整天是 all day。every day 是每天。","g76/quiz.3.ko":"大家都到了。我們開始吧。","g76/quiz.3.why":"everyone 搭配單數動詞 is。","g76/quiz.4.q":"\\"我每天都運動。\\"用英文怎麼說？","g76/quiz.4.why":"每天是 every + 單數 day。","g77/summary":"each 是一個一個分開看，every 是不漏掉地看整體。兩者都和單數名詞一起用","g77/forms.0.items.1":"They cost $5 each.（每一個）","g77/points.0.t":"一個一個分開看。兩個的時候也能用：Each hand has five fingers.（兩隻手）each of + 複數名詞 = ～各自","g77/points.1.t":"把三個以上的東西毫無遺漏地合起來看：Every user found it. 沒有 every of ✕，所以要說 every one of。","g77/points.2.h":"數字 + every","g77/points.2.t":"「每隔～」用 every：every three hours（每三小時）、every other day（每隔一天）","g77/points.3.h":"放在句尾的 each","g77/points.3.t":"each 也可以放在句尾：The tickets are $10 each.（一張 10 美元）every 不能這樣用。","g77/examples.0.ko":"現在每個按鈕都變大了。","g77/examples.1.ko":"每位使用者都試過兩個版本。","g77/examples.2.ko":"每個人都更快找到了新按鈕。","g77/examples.3.ko":"每次見面，我都很失禮。","g77/examples.4.ko":"這個藥請每六小時服用一次。","g77/mistake.why":"every 後面不能直接接 of。要說 each of 或 every one of。","g77/quiz.0.ko":"每個房間都有窗戶。","g77/quiz.0.why":"of 前面要用 each。不能用 every of。","g77/quiz.1.ko":"公車每十分鐘來一班。","g77/quiz.1.why":"數字 +「每隔～」用 every。","g77/quiz.2.ko":"這些蘋果一個一美元。","g77/quiz.2.why":"句尾的「每一個」用 each。","g77/quiz.3.ko":"她兩隻手各戴著一枚戒指。","g77/quiz.3.why":"把兩隻手一隻一隻分開看，所以用 each。both 要和 hands（複數）一起用。","g77/quiz.4.q":"\\"我給每位朋友各寫了一張卡片。\\"用英文怎麼說？","g77/quiz.4.why":"「～各自」是 each of + 複數名詞。","g78/summary":"接在名詞後面說明是「哪一種」人或東西時，人用 who，東西用 which，兩者都能用 that","g78/forms.0.label":"人","g78/forms.1.label":"東西 · 動物","g78/points.0.h":"接在後面修飾","g78/points.0.t":"中文是像「住在紐約的男朋友」這樣放在前面修飾，英文則像 a boyfriend who lives in New York，接在名詞後面。","g78/points.1.t":"人用 who，東西 · 動物用 which，that 兩者都可以。美式英語的日常對話中，東西比較常用 that。","g78/points.2.h":"主詞的位置","g78/points.2.t":"who · that 扮演後面動詞的主詞。the girl who lives next door（住在隔壁的那個女孩）","g78/points.3.h":"中文母語者常犯的錯","g78/points.3.t":"關係代名詞後面不要再寫一次主詞。the man who he works at a bank ✕ → the man who works at a bank ✓","g78/examples.0.ko":"Park 女士的兒子在銀行上班。","g78/examples.1.ko":"我有個住在紐約的男朋友！","g78/examples.2.ko":"那就是我媽媽擔心的問題。","g78/examples.3.ko":"這裡是賣最好吃辣炒年糕的路邊攤。","g78/examples.4.ko":"請問往機場的公車在哪裡？","g78/mistake.why":"who 已經扮演主詞了。不要再用 he。","g78/quiz.0.ko":"我有個住在釜山的朋友。","g78/quiz.0.why":"friend 是人，所以用 who。","g78/quiz.1.ko":"這是改變我人生的一本書。","g78/quiz.1.why":"book 是東西，所以用 that。","g78/quiz.2.ko":"打電話給你的那位女士是我們的主管。","g78/quiz.2.why":"woman 是人，所以用 who。","g78/quiz.3.ko":"我需要一支拍照效果好的手機。","g78/quiz.3.why":"phone 是東西，所以用 that。","g78/quiz.4.q":"\\"我喜歡很會唱歌的人。\\"用英文怎麼說？","g78/quiz.4.why":"人 + who + 動詞。不要再用 they。","g79/title":"關係代名詞的省略 (the man I met)","g79/summary":"who · that · which 後面緊接著另一個主詞時，可以省略關係代名詞：the man (who) I met","g79/forms.0.label":"可以省略","g79/forms.1.label":"不能省略","g79/forms.1.items.0":"the man who called me（who 是主詞）","g79/points.0.h":"什麼時候可以省略","g79/points.0.t":"關係代名詞後面緊接著新的主詞（I · you · Noah）時，可以省略。the photo you sent = the photo that you sent. 日常對話中幾乎都會省略。","g79/points.1.h":"不能省略的情況","g79/points.1.t":"關係代名詞後面直接接動詞時，它是主詞，所以不能省略。the man who called me ✓ / the man called me ✕（會變成「那個男人打電話給我」）","g79/points.2.h":"介系詞放在最後","g79/points.2.t":"介系詞留在後面：the client I told you about（我跟你說過的客戶）。和 49課 Who are you talking to? 是同一個原理。","g79/points.3.h":"像中文一樣簡短","g79/points.3.t":"「你寄的照片」是 the photo you sent。只是順序反過來，簡短地直接接上去，就像中文一樣。","g79/examples.0.ko":"你寄的照片太棒了。","g79/examples.1.ko":"這是媽媽給我的韓服。","g79/examples.2.ko":"你記得我說過的那位客戶嗎？","g79/examples.3.ko":"你做的蛋糕真的很好吃。","g79/examples.4.ko":"那個人就是你昨天見的男生嗎？","g79/mistake.why":"who 後面直接接動詞（helped）時，who 是主詞，不能省略。","g79/quiz.0.ko":"我們昨晚看的那部電影很無聊。","g79/quiz.0.why":"是 the movie (that) we watched。不要再用 it。","g79/quiz.1.ko":"這就是你想買的包包嗎？","g79/quiz.1.why":"是 the bag (that) you wanted to buy。是東西，所以不能用 who。","g79/quiz.2.ko":"坐在我旁邊的那個女生是我表妹。","g79/quiz.2.why":"who 後面直接接動詞，所以不能省略 who。","g79/quiz.3.ko":"她就是我一起去濟州島的朋友。","g79/quiz.3.why":"是 went to Jeju with the friend，所以介系詞 with 留在最後。","g79/quiz.4.q":"\\"我昨天買的那本書在哪裡？\\"用英文怎麼說？","g79/quiz.4.why":"是 the book (that) I bought。不要再用 it。","g80/summary":"連接「～的」時用 whose，接在地點名詞後面表示「～的地方」用 where","g80/points.0.t":"是前面名詞的「～的」。a friend whose dad is a chef = 爸爸是廚師的朋友（那個朋友的爸爸）。人 · 東西都能用。","g80/points.1.t":"接在地點名詞後面，表示「～的地方」。the town where I grew up = 我長大的小鎮。where 後面要接完整的主詞 + 動詞。","g80/points.2.h":"與 which 比較","g80/points.2.t":"the café where we met ✓ / the café which we met ✕ / the café which we met at ✓（at 留在最後）。where 等於 at · in which。","g80/points.3.h":"容易搞混","g80/points.3.t":"不要把 whose 和 who's（who is）搞混。發音相同，但 whose 是「誰的 · ～的」。","g80/examples.0.ko":"這裡是 Mina 最初開始工作的辦公室。","g80/examples.1.ko":"我想要一個能做出數百萬人會用的成果的團隊。","g80/examples.2.ko":"我有個朋友，他爸爸是廚師。","g80/examples.3.ko":"那裡就是我們第一次見面的咖啡廳。","g80/examples.4.ko":"首爾是我長大的城市。","g80/mistake.why":"像「那個女孩的媽媽」這種「～的」要用 whose。who's 是 who is 的縮寫。","g80/quiz.0.ko":"這裡是我遛狗的公園。","g80/quiz.0.why":"地點 park 後面的「～的地方」，所以用 where。","g80/quiz.1.ko":"我認識一個姊姊是演員的男生。","g80/quiz.1.why":"是「那個男生的姊姊」，所以用 whose。","g80/quiz.2.ko":"你記得我們住過的那間飯店嗎？","g80/quiz.2.why":"stayed 後面沒有 at，所以用 where。","g80/quiz.3.ko":"手機響的那位學生得出去。","g80/quiz.3.why":"是「那位學生的手機」，所以用 whose。","g80/quiz.4.q":"\\"這裡是我出生的醫院。\\"用英文怎麼說？","g80/quiz.4.why":"地點 + where + 主詞 + 動詞。","g81/title":"補充說明的關係子句 (, which)","g81/summary":"對已經知道是誰 · 是什麼的名詞補充資訊時，用逗號 + who · which。這時不能用 that，也不能省略","g81/forms.0.label":"補充說明","g81/forms.1.label":"整個句子","g81/forms.1.items.0":"She said sorry, which surprised me.（, which = 前面整個句子）","g81/points.0.h":"逗號的意思","g81/points.0.t":"有逗號就是「補充說明」。拿掉也能知道是誰。My mom, who lives in Seoul, is visiting.（媽媽只有一位，所以說明只是附帶的）","g81/points.1.h":"沒有逗號時","g81/points.1.t":"和 78課一樣，沒有逗號的關係子句是用來挑出「哪一個」。my sister who lives in LA（好幾位姊妹中住在 LA 的那位）↔ my sister, who lives in LA,（只有一位姊姊，住在 LA 只是附帶的）","g81/points.2.h":"that ✕ · 省略 ✕","g81/points.2.t":"補充說明的關係子句不用 that，也不能省略 who · which。Seoul, that is my hometown ✕ → Seoul, which is my hometown ✓","g81/points.3.h":", which = 前面的句子","g81/points.3.t":"which 也可以指前面整個句子：He came on time, which was a surprise.（他準時來了 = 令人驚訝的事）","g81/examples.0.ko":"一開始很討厭我的 Ms. Yoon 寄了花給我。","g81/examples.1.ko":"那個差點關門的 app，現在經營得非常好。","g81/examples.2.ko":"平常很冷靜的 Mr. Han 非常興奮。","g81/examples.3.ko":"她道歉了，這讓我很驚訝。","g81/examples.4.ko":"爸爸的演講只有短短四句話，但大家都哭了。","g81/mistake.why":"逗號後面補充說明的關係子句不能用 that。東西 · 地點用 which。","g81/quiz.0.ko":"我爸爸是廚師，他每個星期天都會做菜。","g81/quiz.0.why":"逗號後面是人，所以用 who。不能用 that。","g81/quiz.1.ko":"首爾是我的故鄉，非常忙碌。","g81/quiz.1.why":"逗號後面說明地點，所以用 which。","g81/quiz.2.ko":"他忘了我的生日，這讓我很難過。","g81/quiz.2.why":"指前面整個句子的是 , which。","g81/quiz.3.ko":"在夜間工作的 Rosa 現在正在睡覺。","g81/quiz.3.why":"逗號後面是人，所以用 who。","g81/quiz.4.q":"\\"我的車很舊了，但還是跑得很好。\\"用英文怎麼說？","g81/quiz.4.why":"在兩個逗號之間用 , which … , 補充說明。","g82/title":"介系詞 + 關係代名詞 · what","g82/summary":"關係子句的介系詞通常放在最後，正式場合則移到前面，變成 at which · with whom。「～的事物」只用一個 what 就能表達","g82/forms.0.label":"介系詞的位置","g82/forms.0.items.0":"the table we had dinner at（日常）","g82/forms.0.items.1":"the table at which we had dinner（正式）","g82/forms.0.items.2":"the person with whom I work（正式，指人用 whom）","g82/points.0.h":"日常放在最後","g82/points.0.t":"對話中介系詞放在最後：the city I grew up in, the people I work with. 和 79課一樣，關係代名詞也會省略。","g82/points.1.h":"正式放在前面","g82/points.1.t":"在文章或演講中，介系詞要移到前面：the city in which I grew up. 這時只能用 which · whom，不能用 that（in that ✕）。","g82/points.2.t":"what 前面沒有名詞，單獨表示「～的事物」。What I need is coffee.（我需要的是咖啡）= The thing that I need is coffee.","g82/points.3.h":"中文母語者常犯的錯","g82/points.3.t":"「我想要的東西」很容易寫成 the thing what I want ✕。沒有名詞時用 what I want ✓，有名詞時用 the thing (that) I want ✓","g82/examples.0.ko":"這就是我們第一次一起吃晚餐的那張餐桌。","g82/examples.1.ko":"我需要的是你誠實的想法。","g82/examples.2.ko":"那就是我害怕的事。","g82/examples.3.ko":"你是我想要和你分享一切的人。","g82/examples.4.ko":"你說的話真的幫了我很大的忙。","g82/mistake.why":"what 本身就是「～的事物」，前面不放名詞。要用名詞的話，是 The thing (that) I need。","g82/quiz.0.ko":"這是我出生的那間房子。","g82/quiz.0.why":"把介系詞移到前面就是 in which。不能用 in that。","g82/quiz.1.ko":"我需要的是一個長假。","g82/quiz.1.why":"「～的事物」是 What。","g82/quiz.2.ko":"這是你在找的東西嗎？","g82/quiz.2.why":"前面沒有名詞，所以用 what。","g82/quiz.3.ko":"她就是我一起去巴黎的朋友。","g82/quiz.3.why":"日常對話中介系詞 with 留在最後。","g82/quiz.4.q":"\\"你說的話不是真的。\\"用英文怎麼說？","g82/quiz.4.why":"「你說的話」是 What you said。","g83/title":"用 -ing · -ed 縮短 (the man sitting there)","g83/summary":"who is sitting 縮短成 sitting，which was written 縮短成 written。主動做的用 -ing，被動承受的用 -ed（過去分詞）","g83/forms.0.label":"-ing（正在做的）","g83/forms.1.label":"-ed（被做的 · 承受的）","g83/points.0.t":"名詞自己正在做的動作。the girl sitting next to me（坐在我旁邊的女孩）。是 who is sitting 的縮短。","g83/points.1.t":"名詞所承受的事 · 所處的狀態。a letter written in English（用英文寫的信）。不規則動詞要用過去分詞：made · written · held · built","g83/points.2.h":"用在哪裡","g83/points.2.t":"新聞 · 廣播 · 菜單這類需要簡短表達的地方很常用。Passengers waiting for Flight 22… / Pasta made fresh every day","g83/points.3.h":"中文母語者常犯的錯","g83/points.3.t":"「廚師做的蛋糕」很容易說成 a cake making by a chef ✕。蛋糕是被做出來的一方，所以用 made ✓","g83/examples.0.ko":"你看這個。這是一位韓國廚師寫的書。","g83/examples.1.ko":"這是每年秋天在首爾舉辦的料理課。","g83/examples.2.ko":"站在機器後面的那個男人是誰？","g83/examples.3.ko":"等公車的人看起來很冷。","g83/examples.4.ko":"我很喜歡每天現做的義大利麵。","g83/mistake.why":"麵包是被賣的一方，所以用 -ed（sold）。如果用 -ing，就變成麵包自己在賣東西。","g83/quiz.0.ko":"正在和 Leo 說話的女士是我們的主管。","g83/quiz.0.why":"那位女士自己正在說話，所以用 -ing。","g83/quiz.1.ko":"這是 1990 年拍的照片。","g83/quiz.1.why":"照片是被拍的一方，所以用過去分詞 taken。","g83/quiz.2.ko":"提早寫完考卷的學生可以先離開。","g83/quiz.2.why":"學生自己寫完，所以用 -ing（students who finish）。","g83/quiz.3.ko":"我買了一輛在韓國製造的車。","g83/quiz.3.why":"車是被製造的一方，所以用 made。","g83/quiz.4.q":"\\"站在窗邊的那個男人是我爸爸。\\"用英文怎麼說？","g83/quiz.4.why":"那個男人自己站著，所以縮短成 standing。","g84/summary":"帶給人情緒的一方用 -ing（boring · surprising），感受到情緒的人用 -ed（bored · surprised）","g84/forms.0.label":"-ing（帶來的一方）","g84/forms.1.label":"-ed（感受的人）","g84/points.0.t":"意思是它「帶來」那種情緒。The movie was boring.（電影讓人覺得無聊）","g84/points.1.t":"意思是人「感受到」那種情緒。I was bored.（我覺得無聊）人當主詞時，大多用 -ed。","g84/points.2.h":"成對記憶","g84/points.3.h":"中文母語者常犯的錯","g84/points.3.t":"「我很無聊」如果說成 I'm boring，會變成「我是個無聊的人」。要說 I'm bored ✓","g84/examples.0.ko":"那真是令人震驚的消息。","g84/examples.1.ko":"我好混亂。這裡是首爾還是紐約？","g84/examples.2.ko":"說實話，我不覺得意外。","g84/examples.3.ko":"那真是一段令人興奮的時光。","g84/examples.4.ko":"沒有你，公司會很無聊。","g84/mistake.why":"感受到興趣的人用 -ed。如果用 interesting，就變成「我是個有趣的人」。","g84/quiz.0.ko":"電影太無聊了，我睡著了。","g84/quiz.0.why":"電影帶來無聊的感覺，所以用 boring。","g84/quiz.1.ko":"我好期待這趟旅行！","g84/quiz.1.why":"是我感受到興奮，所以用 excited。","g84/quiz.2.ko":"他的故事真令人驚訝。","g84/quiz.2.why":"故事帶來驚訝的感覺，所以用 surprising。","g84/quiz.3.ko":"你看起來很累。昨晚睡得好嗎？","g84/quiz.3.why":"人感受到疲倦，所以用 tired。","g84/quiz.4.q":"\\"我對那個結果很失望。\\"用英文怎麼說？","g84/quiz.4.why":"是我感受到失望，所以用 disappointed。","g85/title":"形容詞 vs 副詞 (good · well)","g85/summary":"修飾名詞，或放在 be · look 後面時用形容詞；說明動詞「怎麼」做時用副詞（大多是 -ly）。good 的副詞是 well","g85/forms.0.label":"形容詞","g85/forms.1.label":"副詞","g85/forms.1.items.1":"不規則：good → well · fast → fast · hard → hard","g85/points.0.h":"形容詞","g85/points.0.t":"修飾名詞（a slow walk），或放在 be · look · feel · sound · seem 後面：You look tired. / That sounds great.","g85/points.1.h":"副詞","g85/points.1.t":"修飾動詞，說明「怎麼做」。大多是形容詞 + -ly：slow → slowly, careful → carefully, easy → easily","g85/points.2.t":"good 是形容詞，well 是副詞。She's a good cook. / She cooks well. 但表示「健康的」的 well 是形容詞：I don't feel well.","g85/points.3.h":"形式相同的詞","g85/points.3.t":"fast · hard · late · early 的形容詞和副詞是同一個形式。He works hard.（hardly 是「幾乎不」，意思不同）","g85/examples.0.ko":"你在首爾做得真好。","g85/examples.1.ko":"花園看起來真漂亮。","g85/examples.2.ko":"請仔細想一想。","g85/examples.3.ko":"坐下來，慢慢呼吸。","g85/examples.4.ko":"Daniel 很會傾聽。","g85/mistake.why":"修飾動詞 sings，所以用副詞 well。","g85/quiz.0.ko":"他英文說得很好。","g85/quiz.0.why":"修飾動詞 speaks，所以用副詞 well。","g85/quiz.1.ko":"開車小心點。路面結冰了。","g85/quiz.1.why":"修飾動詞 drive，所以用副詞 carefully。","g85/quiz.2.ko":"這碗湯聞起來好香！","g85/quiz.2.why":"smell 後面要接形容詞 good。","g85/quiz.3.ko":"抱歉。我今天有點不舒服。","g85/quiz.3.why":"是表示「健康的」的 well。","g85/quiz.4.q":"\\"她工作很努力。\\"用英文怎麼說？","g85/quiz.4.why":"hard 的副詞也是 hard。hardly 是「幾乎不」。","g86/title":"比較級","g86/summary":"比較兩者時，短的形容詞用 -er than，長的形容詞用 more … than。good → better, bad → worse","g86/forms.0.label":"短的詞","g86/forms.1.label":"長的詞 · 不規則","g86/points.0.t":"一個音節（cheap）和以 -y 結尾的兩個音節（busy → busier）要加 -er。短母音 + 子音要多寫一個子音：big → bigger","g86/points.1.t":"兩個音節以上的長詞，前面加 more：more expensive, more interesting. 相反的是 less：less expensive","g86/points.2.h":"多多少","g86/points.2.t":"要強調差距時，前面加 much · a lot · a little · even：much bigger, a little cheaper. very bigger ✕","g86/points.3.h":"別重複使用","g86/points.3.t":"「更忙」不能把 more 和 -er 疊在一起寫成 more busier ✕。只用一個：busier ✓ 或 more expensive ✓","g86/examples.0.ko":"首爾會比紐約好嗎？","g86/examples.1.ko":"紐約比首爾貴。","g86/examples.2.ko":"這裡的披薩好吃多了。","g86/examples.3.ko":"首爾晚上比較安全。","g86/examples.4.ko":"選那條會讓你更快樂的路。","g86/mistake.why":"cheap 是短的詞，只加 -er。不要同時用 more 和 -er。","g86/quiz.0.ko":"我弟弟比我高。","g86/quiz.0.why":"tall 是短的詞，所以是 taller。","g86/quiz.1.ko":"這次考試比上次更難。","g86/quiz.1.why":"difficult 是長的詞，所以是 more difficult。","g86/quiz.2.ko":"我今天感覺比昨天好。","g86/quiz.2.why":"good · well 的比較級是 better。","g86/quiz.3.ko":"新手機貴多了。","g86/quiz.3.why":"強調比較級時用 much。不能用 very。","g86/quiz.4.q":"\\"今天比昨天更熱。\\"用英文怎麼說？","g86/quiz.4.why":"hot 是短母音 + 子音，所以多加一個 t，變成 hotter。","g87/summary":"「和～一樣…」是 as … as，「越…就越…」是 the + 比較級, the + 比較級","g87/forms.1.label":"the 比較級, the 比較級","g87/points.0.t":"兩邊相同時使用。中間放原級（big, fast）。as bigger as ✕","g87/points.1.t":"是「不像～那麼…」的意思。Seoul isn't as expensive as New York. = Seoul is cheaper than New York.","g87/points.2.t":"一邊增加，另一邊也跟著變化。The more you practice, the better you get.（越練習，就會變得越好）","g87/points.3.h":"簡短說法","g87/points.3.t":"也可以不加動詞，簡短地說：The sooner, the better.（越快越好）/ The bigger, the better.","g87/examples.0.ko":"越想到首爾，我就越害怕。","g87/examples.1.ko":"你沒有看起來那麼忙嘛。","g87/examples.2.ko":"首爾沒有你感覺的那麼遠。","g87/examples.3.ko":"越早說越好。","g87/examples.4.ko":"你和你爸爸一樣固執。","g87/mistake.why":"as … as 中間放的不是比較級，而是原級。","g87/quiz.0.ko":"我的包包和你的一樣重。","g87/quiz.0.why":"用 as … as 配成一組。","g87/quiz.1.ko":"越用功，學到的越多。","g87/quiz.1.why":"the + 比較級 more。","g87/quiz.2.ko":"這支手機沒有那支那麼貴。","g87/quiz.2.why":"as … as 中間放原級。","g87/quiz.3.ko":"一到就打給我。","g87/quiz.3.why":"「一～就」是 as soon as（18課）。","g87/quiz.4.q":"\\"越快越好。\\"用英文怎麼說？","g87/quiz.4.why":"是 the + 比較級, the + 比較級。","g88/title":"最高級","g88/summary":"三者以上當中的「最」，用 the + -est 或 the most。範圍用 in（地點 · 團體）· of（多個當中）","g88/forms.0.label":"短的詞","g88/forms.1.label":"長的詞 · 範圍","g88/points.0.t":"和比較級（86課）規則相同。短的詞用 -est，長的詞用 most。前面一定要有 the，或 my · his 之類的詞。","g88/points.1.t":"在地點 · 團體之中用 in：the tallest building in Seoul. 在多個之中用 of：the best of the three","g88/points.2.h":"和 ever 搭配","g88/points.2.t":"「到目前為止最～的」是最高級 + I've ever：the best pizza I've ever had（7課的現在完成式）","g88/points.3.t":"「最～的其中之一」是 one of the + 最高級 + 複數：one of the hardest decisions","g88/examples.0.ko":"這是布魯克林最濃的咖啡。","g88/examples.1.ko":"那是我人生中最大的機會。","g88/examples.2.ko":"那是我做過最好的決定。","g88/examples.3.ko":"對你來說最重要的是什麼？","g88/examples.4.ko":"這是世界上最大的城市之一。","g88/mistake.why":"smart 是短的詞，只加 -est。不要同時用 most 和 -est。","g88/quiz.0.ko":"今天是一年當中最熱的一天。","g88/quiz.0.why":"hot → hottest。要多加一個 t。","g88/quiz.1.ko":"她是我認識的人當中最親切的。","g88/quiz.1.why":"kind 是短的詞，所以是 kindest。","g88/quiz.2.ko":"這是世界上最美的城市。","g88/quiz.2.why":"地點範圍用 in。","g88/quiz.3.ko":"那是我看過最爛的電影。","g88/quiz.3.why":"bad 的最高級是 worst。","g88/quiz.4.q":"\\"他是我們隊上跑最快的選手之一。\\"用英文怎麼說？","g88/quiz.4.why":"是 one of the + 最高級 + 複數名詞。","g89/title":"副詞的位置 · 頻率副詞","g89/summary":"always · usually · often · sometimes · never 放在一般動詞前面、be 動詞 · 助動詞後面","g89/forms.0.label":"頻率（100% → 0%）","g89/forms.1.label":"位置","g89/forms.1.items.0":"I always walk here.（一般動詞前面）","g89/forms.1.items.1":"He is never late. · I've never felt this way.（be · 助動詞後面）","g89/points.0.h":"一般動詞前面","g89/points.0.t":"I usually drink coffee. / She never eats breakfast. 放在主詞和動詞之間。","g89/points.1.h":"be · 助動詞後面","g89/points.1.t":"放在 be 動詞，或 can · will · have 之類的助動詞後面：I'm always tired. / I've never been to Paris.","g89/points.2.h":"sometimes 位置自由","g89/points.2.t":"sometimes · usually 也可以放在句首或句尾：Sometimes I cook. / I cook sometimes.","g89/points.3.h":"方式 · 地點 · 時間","g89/points.3.t":"slowly · here · yesterday 這類副詞通常放在句尾，順序是方式 → 地點 → 時間：She walked slowly to the café yesterday.","g89/examples.0.ko":"你從來不等任何人。","g89/examples.1.ko":"你還總是說等待是浪費時間。","g89/examples.2.ko":"我通常會說些不著邊際的話。","g89/examples.3.ko":"我從來沒有對任何人有過這種感覺。","g89/examples.4.ko":"我有時候是個膽小鬼。","g89/mistake.why":"always 放在一般動詞 go 前面。","g89/quiz.0.ko":"她從來不吃早餐。","g89/quiz.0.why":"never 放在一般動詞前面，主詞是 She，所以用 eats。","g89/quiz.1.ko":"他常常上班遲到。","g89/quiz.1.why":"often 放在 be 動詞後面。","g89/quiz.2.ko":"我從來沒去過日本。","g89/quiz.2.why":"never 放在助動詞 have 後面。","g89/quiz.3.ko":"我們通常星期五去看電影。","g89/quiz.3.why":"usually 放在一般動詞 go 前面。","g89/quiz.4.q":"\\"我早上總是喝咖啡。\\"用英文怎麼說？","g89/quiz.4.why":"always 放在一般動詞 drink 前面。","g90/summary":"still 是「仍然」，yet 在否定句 · 疑問句中是「還 · 已經」，already 是「已經 · 早就」","g90/points.0.t":"從以前到現在「仍然持續」。本以為會結束卻繼續時：It's still raining. 在否定句中放在 not 前面：I still don't know.","g90/points.1.t":"在否定句中是「還（沒）」，在疑問句中是「已經」。通常放在句尾：Has he called yet? / He hasn't called yet.（8課的現在完成式）","g90/points.2.t":"比預期更早「已經」發生了。放在 have 後面或句尾：I've already told him. / You're here already?","g90/points.3.h":"語氣差異","g90/points.3.t":"「還沒決定」可以說 I haven't decided yet ✓ 或 I still haven't decided ✓。still 聽起來比較焦急。","g90/examples.0.ko":"你現在決定了嗎？","g90/examples.1.ko":"還沒。我還是不知道。","g90/examples.2.ko":"首爾已經是星期天晚上了。","g90/examples.3.ko":"我已經訂好計畫了。","g90/examples.4.ko":"已經半夜十二點了？","g90/mistake.why":"否定句中的「還」是 yet。already 用在「已經做了」的肯定句。","g90/quiz.0.ko":"Rosa 還在睡？都中午了！","g90/quiz.0.why":"「仍然持續」是 still。","g90/quiz.1.ko":"我還沒寫完報告。","g90/quiz.1.why":"否定句句尾的「還」是 yet。","g90/quiz.2.ko":"別擔心。我已經付過錢了。","g90/quiz.2.why":"「已經 · 早就」是 already。","g90/quiz.3.ko":"你見過 Grace 了嗎？","g90/quiz.3.why":"疑問句句尾的「已經」是 yet。","g90/quiz.4.q":"\\"他還在生我的氣。\\"用英文怎麼說？","g90/quiz.4.why":"「仍然持續」是 still。","g91/summary":"\\"足夠\\"是 enough：放在形容詞後面、名詞前面。\\"太…而無法…\\"是 too + 形容詞 + to","g91/forms.0.items.0":"old enough · good enough (形容詞 + enough)","g91/forms.0.items.1":"enough time · enough people (enough + 名詞)","g91/forms.1.items.1":"too tired to decide (累到無法決定)","g91/points.0.h":"enough 的位置","g91/points.0.t":"放在形容詞 · 副詞後面：big enough, fast enough。放在名詞前面：enough money。enough big ✕","g91/points.1.t":"意思是\\"過度 · 太\\"，帶有負面感。It's too hot.(熱到有問題)和 very hot(非常熱)不一樣。","g91/points.2.h":"和 to 搭配","g91/points.2.t":"too … to = 太～而無法…：I'm too tired to cook. / … enough to = 足夠～而能夠…：She's old enough to drive.","g91/points.3.h":"中文母語者常犯的錯","g91/points.3.t":"中文的\\"太好了！\\"是讚嘆，但 It's too good 聽起來可能像\\"好過頭了，反而有問題\\"。開心時要說 It's so good · really good (第92課)。","g91/examples.0.ko":"那太複雜了。","g91/examples.1.ko":"兩間辦公室都有足夠的優秀人才。","g91/examples.2.ko":"我今晚累到無法做決定。","g91/examples.3.ko":"你的時間夠嗎？","g91/examples.4.ko":"她已經到了可以開車的年紀。","g91/mistake.why":"enough 放在形容詞後面。只有修飾名詞時才像 enough money 一樣放在前面。","g91/quiz.0.ko":"這杯咖啡太燙了，我沒辦法喝。","g91/quiz.0.why":"\\"太～而無法…\\"是 too … to。","g91/quiz.1.ko":"椅子夠大家坐嗎？","g91/quiz.1.why":"名詞前面的\\"足夠的\\"用 enough。","g91/quiz.2.ko":"他不夠高，搆不到架子。","g91/quiz.2.why":"形容詞後面接 enough to。","g91/quiz.3.ko":"我今晚太累了，沒辦法出門。","g91/quiz.3.why":"too + 形容詞 + to。","g91/quiz.4.q":"「我的錢不夠買車。」用英文怎麼說？","g91/quiz.4.why":"名詞 money 前面用 enough。","g92/summary":"\\"真的 · 好\\"：形容詞前面用 so，(a) 形容詞 + 名詞前面用 such。quite · pretty 是\\"相當\\"","g92/forms.0.items.0":"so crazy · so excited (so + 形容詞)","g92/forms.0.items.1":"such a crazy idea · such good people (such + a + 形容詞 + 名詞)","g92/forms.1.label":"相當","g92/forms.1.items.0":"pretty smart · quite excited (美式英語會話更常用 pretty)","g92/points.0.t":"只強調形容詞 · 副詞：It's so good. / You did so well.","g92/points.1.t":"連形容詞 + 名詞整個一起強調：such a good idea, such nice people。單數時要用 such a。so a good idea ✕","g92/points.2.t":"意思是\\"太～所以…\\"：It was so cold that we stayed home. / It was such a cold day that we stayed home.","g92/points.3.t":"意思是\\"相當\\"。美式英語會話裡超常用 pretty：It's pretty good.(滿不錯的) quite 的感覺稍微沉穩一點：quite difficult","g92/examples.0.ko":"老實說，這想法真的很瘋狂。","g92/examples.1.ko":"不過這也是個相當聰明的點子。","g92/examples.2.ko":"我好興奮！","g92/examples.3.ko":"團隊也相當興奮。","g92/examples.4.ko":"您真是個好老闆。","g92/mistake.why":"強調 a + 形容詞 + 名詞時用 such。so 只強調形容詞：The party was so good.","g92/quiz.0.ko":"她真是個親切的人。","g92/quiz.0.why":"在 a + 形容詞 + 名詞前面，所以用 such。","g92/quiz.1.ko":"那部電影太好笑了，我笑到流淚。","g92/quiz.1.why":"形容詞 funny 前面，所以是 so … that。","g92/quiz.2.ko":"考試滿簡單的，我考了90分。","g92/quiz.2.why":"\\"相當\\"是 pretty。","g92/quiz.3.ko":"他們是很好的鄰居。","g92/quiz.3.why":"在形容詞 + 複數名詞前面，所以用 such。複數沒有 a。","g92/quiz.4.q":"「真是個好主意！」用英文怎麼說？","g92/quiz.4.why":"順序是 such + a + 形容詞 + 名詞。","g93/summary":"\\"雖然～ · 儘管～\\"：後面接句子用 although，接名詞 · -ing 用 in spite of · despite","g93/forms.0.label":"+ 句子","g93/forms.0.items.1":"Even though I practiced, I forgot my speech. (語氣更強)","g93/forms.1.label":"+ 名詞 · -ing","g93/points.0.t":"後面接主詞 + 動詞。even though 的語氣更強，像\\"儘管…還是\\"。though 在會話裡也可以放句尾：It's cold, though.","g93/points.1.t":"後面接名詞或 -ing。despite 後面不加 of：despite the rain ✓ / despite of the rain ✕","g93/points.2.h":"不能和 but 並用 ✕","g93/points.2.t":"中文習慣說\\"雖然…但是…\\"，所以容易把 although 和 but 一起用。Although it rained, but we went ✕ → Although it rained, we went ✓","g93/points.3.h":"中文母語者常犯的錯","g93/points.3.t":"很容易在 in spite of 後面接句子。in spite of it was raining ✕ → in spite of the rain ✓ / although it was raining ✓","g93/examples.0.ko":"雖然天氣陰陰的，但風景很美。","g93/examples.1.ko":"就算有雲，晚霞也會很美的。","g93/examples.2.ko":"儘管練習了一整個星期，我還是忘了要說的話。","g93/examples.3.ko":"儘管下雨，大家還是來了。","g93/examples.4.ko":"今天很漫長。不過還是很開心。","g93/mistake.why":"although 本身已經包含\\"雖然\\"的意思。不要再加 but。","g93/quiz.0.ko":"雖然很晚了，我們還是繼續聊。","g93/quiz.0.why":"後面接句子(it was late)，所以用 Although。","g93/quiz.1.ko":"儘管塞車，我還是準時到了。","g93/quiz.1.why":"後面接名詞(the traffic)，所以用 Despite。","g93/quiz.2.ko":"儘管感冒了，他還是去上班了。","g93/quiz.2.why":"in spite of 這三個單字是一組。","g93/quiz.3.ko":"她非常有錢。不過她並不快樂。","g93/quiz.3.why":"放在句尾的\\"不過\\"是 though。","g93/quiz.4.q":"「雖然下雨，我們還是去爬山了。」用英文怎麼說？","g93/quiz.4.why":"放句首用 although，不和 but 並用。","g94/summary":"用句子說原因用 because，用名詞說原因用 because of。結果用 so(所以)","g94/forms.0.label":"原因","g94/forms.0.items.0":"I forgot my speech because I'm nervous. (+ 句子)","g94/forms.0.items.1":"I'm crying because of you. (+ 名詞)","g94/forms.1.label":"結果","g94/forms.1.items.0":"I was scared, so I waited. (所以)","g94/points.0.h":"because + 句子","g94/points.0.t":"後面接主詞 + 動詞：because I love you。會話中也可以單獨回答，像 Why? — Because …","g94/points.1.h":"because of + 名詞","g94/points.1.t":"後面接名詞 · 代名詞：because of the rain, because of you。because of it was raining ✕","g94/points.2.t":"用來連接結果。原因, so 結果：It was raining, so we stayed home. because 和 so 不會用在同一個句子裡。","g94/points.3.h":"中文母語者常犯的錯","g94/points.3.t":"中文的\\"因為\\"後面可以接句子，也可以接名詞(因為下雨、因為你)，所以容易說成 because the rain ✕。名詞前面要用 because of the rain ✓","g94/examples.0.ko":"我太緊張了，忘了要說的話。","g94/examples.1.ko":"當然是因為你啊！","g94/examples.2.ko":"我很害怕，所以就等著。","g94/examples.3.ko":"因為下雨，我們在裡面等。","g94/examples.4.ko":"因為去了首爾，我就再也等不下去了。","g94/mistake.why":"because 和 so 不會用在同一個句子裡。像 It rained, so we stayed home. 這樣，只選一個。","g94/quiz.0.ko":"因為暴風雨，飛機誤點了。","g94/quiz.0.why":"後面接名詞(the storm)，所以用 because of。","g94/quiz.1.ko":"我很累，所以早早就睡了。","g94/quiz.1.why":"後面接句子(I was tired)，所以用 because。","g94/quiz.2.ko":"天氣很冷，所以我穿了外套。","g94/quiz.2.why":"原因, so 結果。","g94/quiz.3.ko":"都是因為你，我才遲到了啦！","g94/quiz.3.why":"代名詞 you 前面，所以用 because of。","g94/quiz.4.q":"「我肚子餓，所以點了披薩。」用英文怎麼說？","g94/quiz.4.why":"原因, so 結果。because 和 so 不會一起用。","g95/summary":"～的時候 when、～的期間 while、直到～ until、～之前 before、～之後 after。就算是未來的事，也用現在式","g95/forms.0.label":"連接詞","g95/forms.1.label":"未來也用現在式","g95/forms.1.items.0":"I'll call you when I arrive. (when I will arrive ✕，第18課)","g95/points.0.t":"when 是\\"～的時候\\"，指某個時間點；while 是\\"～的期間\\"，指持續的一段時間。While I was cooking, the phone rang. (第6課)","g95/points.1.t":"表示\\"直到～\\"一直持續：I'll wait until you come back. not … until = 到～才…：I didn't listen until it was too late.","g95/points.2.t":"後面可以接句子，也可以接名詞 · -ing：before you leave / before leaving / after dinner","g95/points.3.h":"未來用現在式","g95/points.3.t":"在這些詞後面，就算是未來的事也用現在式：When you get to Seoul, call me. (第18課學過的規則)","g95/examples.0.ko":"我在你這個年紀的時候，也說過一樣的話。","g95/examples.1.ko":"我在首爾的時候，誰來煮飯？","g95/examples.2.ko":"我到太遲了才聽進去。","g95/examples.3.ko":"趁我還沒改變心意之前，趕快申請。","g95/examples.4.ko":"下課後，回家煮飯給我吃。","g95/mistake.why":"when · before · after · until 後面，就算是未來的事也用現在式。","g95/quiz.0.ko":"吃東西之前先洗手。","g95/quiz.0.why":"\\"～之前\\"是 before。","g95/quiz.1.ko":"我跑步的時候在聽音樂。","g95/quiz.1.why":"\\"～的期間\\"是 while。","g95/quiz.2.ko":"我們在這裡等到雨停吧。","g95/quiz.2.why":"\\"直到～\\"是 until。","g95/quiz.3.ko":"到家的時候打給我。","g95/quiz.3.why":"when 後面就算是未來也用現在式 get。","g95/quiz.4.q":"「吃完晚餐後去散步吧。」用英文怎麼說？","g95/quiz.4.why":"\\"～之後\\"是 after。後面直接接名詞 dinner 也可以。","g96/summary":"\\"持續多久\\"用 for + 時間長度，\\"在什麼時候期間\\"用 during + 名詞，\\"在～的期間\\"用 while + 句子","g96/forms.0.label":"for + 時間長度","g96/forms.1.label":"during + 名詞 / while + 句子","g96/points.0.t":"說明持續多久，放在用數字表示的時間長度前面：for three days。(和第9課現在完成式的 for 一樣)","g96/points.1.t":"說明\\"何時\\"發生，放在某件事 · 某個時期的名稱前面：during the summer, during lunch。during three days ✕","g96/points.2.t":"後面接主詞 + 動詞：while we were eating。during we were eating ✕","g96/points.3.h":"全放在一個句子裡","g96/examples.0.ko":"我會在首爾待三個月。","g96/examples.1.ko":"你在首爾的期間，紐約那邊由 Daniel 負責。","g96/examples.2.ko":"兩個城市的時間重疊的時候，我們就線上見面。","g96/examples.3.ko":"開會期間請不要使用手機。","g96/examples.4.ko":"我在倫敦住了三年。","g96/mistake.why":"用數字表示的時間長度前面用 for。during 用在像 the night 這種時期的名稱前面。","g96/quiz.0.ko":"我認識她十年了。","g96/quiz.0.why":"在數字表示的時間長度前面，所以用 for。","g96/quiz.1.ko":"他看電影的時候睡著了。","g96/quiz.1.why":"名詞 the movie 前面的\\"在～期間\\"是 during。","g96/quiz.2.ko":"你不在的時候有人打電話來。","g96/quiz.2.why":"後面接句子，所以用 while。","g96/quiz.3.ko":"連續下了兩天雨。","g96/quiz.3.why":"在數字表示的時間長度前面，所以用 for。","g96/quiz.4.q":"「假期期間，我讀了很多書。」用英文怎麼說？","g96/quiz.4.why":"在時期的名稱 the vacation 前面，所以用 during。","g97/summary":"by 是\\"最晚到那時候為止(截止)\\"，until 是\\"一直到那時候\\"","g97/forms.0.label":"by (截止)","g97/forms.1.label":"until (持續)","g97/points.0.t":"在那個時間之前，隨時做完一次就可以。指截止 · 期限：Send it by Monday.(最晚星期一前寄出)","g97/points.1.t":"到那個時間為止，動作 · 狀態一直持續：I'll wait until 5.(我會一直等到5點) 會話中也說 till。","g97/points.2.h":"分辨方法","g97/points.2.t":"像\\"完成 · 抵達 · 交出\\"這種一次就結束的動詞，適合搭配 by；像\\"等待 · 停留 · 工作\\"這種持續的動詞，適合搭配 until。","g97/points.3.t":"後面接句子時用 by the time：By the time we arrived, the party was over.(等我們到的時候，派對已經結束了)","g97/examples.0.ko":"我最晚6點要到 JFK 機場！","g97/examples.1.ko":"我們要跳舞跳到午夜！","g97/examples.2.ko":"Kimchi 會和我們一起住到12月。","g97/examples.3.ko":"星期五以前把行李都打包好。","g97/examples.4.ko":"等你回來的時候，咖啡廳就會有新菜單了。","g97/mistake.why":"寄出是做一次就結束的事，所以截止用 by。until 用在持續進行的事。","g97/quiz.0.ko":"我會在辦公室待到晚上7點。","g97/quiz.0.why":"一直待到7點，所以是 until。","g97/quiz.1.ko":"請在星期五以前還書。","g97/quiz.1.why":"還書是做一次就結束的截止期限，所以用 by。","g97/quiz.2.ko":"那間店開到晚上10點。","g97/quiz.2.why":"一直開到10點，所以是 until。","g97/quiz.3.ko":"等我到家的時候，大家都已經睡了。","g97/quiz.3.why":"後面接句子的\\"等到～的時候\\"是 By the time。","g97/quiz.4.q":"「我明天以前必須完成報告。」用英文怎麼說？","g97/quiz.4.why":"完成是截止期限，所以用 by。","g98/title":"時間的 at · on · in","g98/summary":"時刻用 at，日期 · 星期用 on，月 · 季節 · 年這類較長的時間用 in。就是介系詞 at · on · in 的畫面","g98/forms.1.label":"不加的詞","g98/forms.1.items.0":"next week · last year · this morning · every day (不加介系詞)","g98/points.0.h":"at = 一個點","g98/points.0.t":"是時鐘上的一個點：at 7:30, at noon, at midnight, at night (at ②)","g98/points.1.h":"on = 日曆上的一格","g98/points.1.t":"放在日曆的一格上：on Friday, on October 1st, on Christmas Day (on ②)","g98/points.2.h":"in = 長時間之內","g98/points.2.t":"在月 · 季節 · 年 · 一天中的一段這類寬廣的時間之內：in December, in the spring, in the morning (in ②)","g98/points.3.h":"不加介系詞的詞","g98/points.3.t":"next · last · this · every 前面不用介系詞：See you next Monday. on next Monday ✕","g98/examples.0.ko":"飛機是9點吧？","g98/examples.1.ko":"我10月1日回來。","g98/examples.2.ko":"婚禮在春天。","g98/examples.3.ko":"12月見。","g98/examples.4.ko":"首爾時間晚上打給我。","g98/mistake.why":"next · last · this · every 前面不用 at · on · in。","g98/quiz.0.ko":"會議下午3點開始。","g98/quiz.0.why":"時刻用 at。","g98/quiz.1.ko":"我的生日在5月。","g98/quiz.1.why":"月份用 in。","g98/quiz.2.ko":"我們星期六見面吧。","g98/quiz.2.why":"星期用 on。","g98/quiz.3.ko":"我通常早上念書。","g98/quiz.3.why":"一天中的一段(the morning)用 in。","g98/quiz.4.q":"「下星期五見。」用英文怎麼說？","g98/quiz.4.why":"next 前面不用介系詞。","g99/title":"地點的 at · on · in","g99/summary":"一個地點用 at，表面 · 樓層 · 螢幕上用 on，空間 · 城市 · 國家之內用 in","g99/forms.0.items.0":"at the door · at the office · at the airport (地點)","g99/forms.0.items.1":"on the 12th floor · on the wall · on the screen (表面 · 樓層)","g99/forms.1.items.0":"in the meeting room · in the car · in Seoul · in Korea (空間之內)","g99/points.0.h":"at = 地點","g99/points.0.t":"像地圖上的一個點，指\\"那裡\\"：at the door, at the bus stop, at work, at home (at ①)","g99/points.1.h":"on = 表面 · 樓層","g99/points.1.t":"貼著表面，或在樓層 · 街道上：on the wall, on the 12th floor, on the screen, on the bus (on ①)","g99/points.2.h":"in = 空間之內","g99/points.2.t":"四周封閉的空間或寬廣的區域之內：in the box, in the kitchen, in Seoul (in ①)","g99/points.3.h":"同一個地方，不同的說法","g99/points.3.t":"We're at the office.(人在公司這個地點) / We're in the office.(人在辦公室的建築裡面)。依你想表達的重點來選。","g99/examples.0.ko":"我們的辦公室在12樓。","g99/examples.1.ko":"我們大家都在辦公室。","g99/examples.2.ko":"Ms. Hill 在芝加哥。","g99/examples.3.ko":"Dana 在螢幕上。","g99/examples.4.ko":"有人到門口了。","g99/mistake.why":"城市 · 國家這種寬廣空間之內用 in。at 用在地圖上的一個地點。","g99/quiz.0.ko":"牆上掛著一幅畫。","g99/quiz.0.why":"貼在牆的表面上，所以用 on。","g99/quiz.1.ko":"她正在公車站等車。","g99/quiz.1.why":"公車站是一個地點，所以用 at。","g99/quiz.2.ko":"我的父母住在釜山。","g99/quiz.2.why":"在城市之內，所以用 in。","g99/quiz.3.ko":"他的辦公室在5樓。","g99/quiz.3.why":"樓層用 on。","g99/quiz.4.q":"「鑰匙在車子裡。」用英文怎麼說？","g99/quiz.4.why":"在車子這個空間之內，所以用 in。沒有移動，所以不能用 into。","g100/summary":"\\"像～\\"：名詞前面用 like，句子前面用 as。\\"好像～似的\\"用 as if。as + 名詞是\\"身為～\\"","g100/forms.0.label":"像～","g100/forms.0.items.0":"Seoul at night looks like New York. (like + 名詞)","g100/forms.0.items.1":"As you said, we found a way. (as + 句子)","g100/forms.0.items.2":"It feels as if I've lived two lives. (as if + 句子)","g100/forms.1.label":"身為～","g100/points.0.h":"like + 名詞","g100/points.0.t":"意思是\\"像～ · ～一樣的\\"：You cook like a chef. / You're like this bridge. 會話中 like + 句子也很常見：like I said","g100/points.1.h":"as + 句子","g100/points.1.t":"意思是\\"如同～ · 按照～\\"：As you know, … / Do as I say. 書寫時 as 更正確。","g100/points.2.t":"意思是\\"好像～似的\\"：He acts as if he owns the place. 強調並非事實時用過去式：as if I were a kid (第31課假設語氣)","g100/points.3.h":"as = 身為～","g100/points.3.t":"as + 名詞是\\"身為～(身分)\\"：I work as a designer.(我的工作是設計師) like a designer 是\\"像設計師一樣(其實不是)\\"。","g100/examples.0.ko":"夜晚的首爾像紐約一樣。","g100/examples.1.ko":"今年好像活了兩輩子一樣。","g100/examples.2.ko":"就像你在雨中說的，我們找到辦法了。","g100/examples.3.ko":"你就像這座橋一樣。","g100/examples.4.ko":"我不是以廚師的身分，而是以學生的身分來到這裡。","g100/mistake.why":"真實的職業 · 身分用 as。like a doctor 的意思會變成\\"明明不是醫生卻像醫生一樣\\"。","g100/quiz.0.ko":"她唱歌像天使一樣。","g100/quiz.0.why":"名詞前面的\\"像～\\"是 like。","g100/quiz.1.ko":"他說話的樣子好像什麼都知道。","g100/quiz.1.why":"\\"好像～似的\\" + 句子是 as if。","g100/quiz.2.ko":"我大學時當過服務生。","g100/quiz.2.why":"真實的職業用 as。","g100/quiz.3.ko":"如我所說，那間店星期日休息。","g100/quiz.3.why":"\\"如同～ · 按照～\\" + 句子是 As。","g100/quiz.4.q":"「今天好像夏天一樣。」用英文怎麼說？","g100/quiz.4.why":"名詞 summer 前面，所以用 like。as if 後面必須接句子。","grp/A/title":"基本三個","grp/B/title":"方向","grp/C/title":"關係","grp/D/title":"上 · 下 · 經過","grp/E/title":"片語動詞的關鍵","grp/F/title":"收尾","prep/in/core":"框框之內","prep/in/coreText":"是有邊框的空間，以及其中的一個點。不只像房間 · 箱子這種四周封閉的地方，城市 · 國家 · 一個月這類有界線的東西，都被看作\\"容器\\"。in 的五種意思都是從這個容器來的。","prep/in/meanings.0":"空間之內","prep/in/meanings.1":"期間之內","prep/in/meanings.2":"過了一段時間之後","prep/in/meanings.3":"處於某種狀態","prep/in/meanings.4":"方式","prep/on/core":"接觸表面","prep/on/coreText":"是接觸並附著在某個表面上的畫面。不只是放在上面，像牆壁 · 天花板這樣在側面或下面，只要接觸著，就是 on。六種意思都是從這個\\"接觸\\"來的。","prep/on/meanings.0":"接觸表面","prep/on/meanings.1":"日期","prep/on/meanings.2":"倚靠依賴","prep/on/meanings.3":"主題","prep/on/meanings.4":"運作 · 進行中","prep/on/meanings.5":"媒介 · 交通工具","prep/at/core":"一個點","prep/at/coreText":"是沒有面積、被點出來的\\"一個點\\"。不論是地點還是時間，不談裡面的情形，只說\\"就在那裡\\"這個位置時，就用 at。四種意思都是從這個點來的。","prep/at/meanings.0":"一個點的地點","prep/at/meanings.1":"一個點的時刻","prep/at/meanings.2":"靶心","prep/at/meanings.3":"數值 · 程度","prep/to/core":"指向抵達點的箭頭","prep/to/coreText":"是出發後\\"抵達\\"某個點的箭頭。at 是停在那個點上的畫面，to 則是飛向那個點並碰到的畫面。四種意思都是從這個箭頭的前端來的。","prep/to/meanings.0":"抵達點","prep/to/meanings.1":"接收的人","prep/to/meanings.2":"終點 · 範圍","prep/to/meanings.3":"結果 · 配合","prep/for/core":"伸手朝向","prep/for/coreText":"是朝著某樣東西伸出手的畫面。to 是抵達並碰到的箭頭，for 則是就算還沒碰到，也是\\"為了它 · 朝著它\\"的心意。六種意思都是從這裡來的。","prep/for/meanings.0":"想要的東西","prep/for/meanings.1":"為了 · 接收的人","prep/for/meanings.2":"期間","prep/for/meanings.3":"交換 · 價格","prep/for/meanings.4":"贊成","prep/for/meanings.5":"前往的地方","prep/from/core":"從出發點離開","prep/from/coreText":"是從某個點出發、離開的箭頭。to 是箭頭的前端(抵達)，from 則是箭頭的尾端(出發)。三種意思都是從這個出發點來的。","prep/from/meanings.0":"出發點","prep/from/meanings.1":"來源 · 材料","prep/from/meanings.2":"分開","prep/of/core":"隸屬於整體的部分","prep/of/coreText":"是從大塊東西切下來的一片，或\\"隸屬於\\"某物的畫面。A of B 是\\"隸屬於 B 的 A\\"。順序和中文的\\"B 的 A\\"相反。四種意思都是從這個隸屬來的。","prep/of/meanings.0":"整體的一部分","prep/of/meanings.1":"所屬之處 · 性質","prep/of/meanings.2":"內容物 · 材料","prep/of/meanings.3":"原因 · 對象","prep/with/core":"並排一起","prep/with/coreText":"是兩個東西並排貼在一起的畫面。和人一起、和手裡拿的工具一起、和身上帶的特徵一起、和某種心情 · 狀態一起。四種意思都是從\\"在一起\\"來的。","prep/with/meanings.0":"一起","prep/with/meanings.1":"工具","prep/with/meanings.2":"具有","prep/with/meanings.3":"原因 · 狀態","prep/by/core":"就在旁邊","prep/by/coreText":"是緊貼在某物旁邊的畫面。\\"經過\\"旁邊就是手段，在旁邊做事就是做事的人，到了旁邊就是期限，測量與旁邊的距離就是差距。五種意思都是從\\"旁邊\\"來的。","prep/by/meanings.0":"就在旁邊","prep/by/meanings.1":"手段","prep/by/meanings.2":"做事的人","prep/by/meanings.3":"期限","prep/by/meanings.4":"差距 · 單位","prep/about/core":"繞著周圍","prep/about/coreText":"是繞著某個東西周圍一圈的畫面。話題繞著某件事打轉就是主題，在人的周圍縈繞就是那個人身上有的感覺，在數字周圍打轉就是\\"大約\\"。三種意思都是從這個周圍來的。","prep/about/meanings.0":"主題","prep/about/meanings.1":"周圍 · 具有～","prep/about/meanings.2":"大約 · 正要做","prep/over/core":"覆蓋上方並越過的弧形","prep/over/coreText":"是圓弧狀覆蓋在某物上方並越過的弧形(拱形)。從上面蓋住或越過就是\\"覆蓋 · 越過\\"，超過基準線就是\\"超過的數量\\"，一直越到最後就是\\"結束\\"，橫跨在一件事上就是\\"在…期間\\"，從上面俯視就是\\"掌控\\"。","prep/over/meanings.0":"覆蓋 · 越過","prep/over/meanings.1":"超過的數量","prep/over/meanings.2":"結束 · 重新","prep/over/meanings.3":"在…期間","prep/over/meanings.4":"掌控","prep/under/core":"被蓋在下面","prep/under/coreText":"是被蓋在某物正下方的畫面。和 over 相反。在下面的空間就是\\"下面\\"，在基準線之下就是\\"未滿\\"，在沉重的力量或事情之下就是\\"在影響 · 進行之下\\"。","prep/under/meanings.0":"下面","prep/under/meanings.1":"未滿","prep/under/meanings.2":"在影響 · 進行之下","prep/above/core":"離開的上方","prep/above/coreText":"是沒有接觸、隔著距離的上方。和覆蓋或越過的 over 不同，只說高度上的差別。","prep/above/meanings.0":"離開的上方","prep/below/core":"離開的下方","prep/below/coreText":"是沒有接觸、隔著距離的下方。和緊貼在正下方蓋著的 under 不同，只說高度上的差別。","prep/below/meanings.0":"離開的下方","prep/through/core":"穿過管道通過","prep/through/coreText":"是穿過管道或隧道，從這一邊通到那一邊的畫面。穿過空間就是\\"貫穿\\"，穿過時間就是\\"從頭到尾\\"，把某物當作通道通過就是\\"經由 · 多虧\\"。","prep/through/meanings.0":"貫穿","prep/through/meanings.1":"從頭到尾","prep/through/meanings.2":"經由","prep/across/core":"橫越過去","prep/across/coreText":"是在平坦的面上從這一端橫越到那一端的畫面。橫越的動作就是\\"橫越\\"，橫越後所在的位置就是\\"對面\\"，遍布整個寬廣的面就是\\"到處\\"。","prep/across/meanings.0":"橫越","prep/across/meanings.1":"對面 · 到處","prep/along/core":"順著長度並排","prep/along/coreText":"是順著道路 · 河流這類長形事物的\\"長度方向\\"並排移動的畫面。順著路走就是\\"沿著\\"，和某人並肩一起前進就是\\"一同進行\\"。","prep/along/meanings.0":"沿著","prep/along/meanings.1":"一同進行","prep/around/core":"繞著周圍轉","prep/around/coreText":"是繞著某個東西周圍轉圈的畫面。在外面繞一圈就是\\"周圍\\"，到處走動就是\\"四處\\"，在數字附近打轉就是\\"大約\\"。","prep/around/meanings.0":"周圍","prep/around/meanings.1":"四處","prep/around/meanings.2":"大約","prep/up/core":"往上升","prep/up/coreText":"是從下往上升起的箭頭。身體或東西上升就是\\"往上\\"，數量或聲音升高就是\\"增加\\"，一直滿到頂端就是\\"全部到底\\"，在眼前冒出來就是\\"靠近並出現\\"。是片語動詞裡最常出現的詞。","prep/up/meanings.0":"往上","prep/up/meanings.1":"增加","prep/up/meanings.2":"全部到底","prep/up/meanings.3":"靠近並出現","prep/down/core":"往下降","prep/down/coreText":"是從上往下降的箭頭。和 up 相反。身體或東西下降就是\\"往下\\"，數量 · 聲音 · 速度下降就是\\"減少 · 變弱\\"，落在紙上固定住就是\\"寫下來固定\\"。","prep/down/meanings.0":"往下","prep/down/meanings.1":"減少 · 變弱","prep/down/meanings.2":"寫下來固定","prep/out/core":"從裡面到外面","prep/out/coreText":"是原本在框框裡面的東西跑到外面的箭頭。和 in 相反。身體出去就是\\"往外\\"，全都流光、變空就是\\"消失 · 用完\\"，毫無保留全部拿出來就是\\"徹底到底\\"，原本藏著的東西露出來就是\\"顯露\\"。","prep/out/meanings.0":"往外","prep/out/meanings.1":"消失 · 用完","prep/out/meanings.2":"徹底到底","prep/out/meanings.3":"顯露","prep/off/core":"原本貼著而分離","prep/off/coreText":"是原本貼在表面上的東西\\"啪\\"地掉下來的畫面。和 on 相反。東西掉落就是\\"掉下來\\"，人從出發點離開就是\\"離開\\"，電力 · 連線斷掉就是\\"關掉 · 停止\\"，從工作或價格上扣掉就是\\"休息 · 減掉\\"。","prep/off/meanings.0":"掉下來","prep/off/meanings.1":"離開","prep/off/meanings.2":"關掉 · 停止","prep/off/meanings.3":"休息 · 減掉","prep/into/core":"從外面進到裡面","prep/into/coreText":"是從外面越過邊界\\"唰\\"地進到裡面的箭頭。是 in(在裡面)加上 to(朝向)的詞。進到空間裡面就是\\"進入\\"，進到另一種樣子 · 狀態，或深深投入某事，就是\\"變成 · 沉迷\\"。","prep/into/meanings.0":"進入","prep/into/meanings.1":"變成 · 沉迷","prep/away/core":"漸漸遠離","prep/away/coreText":"是從基準點漸漸遠離的箭頭。距離變遠就是\\"遠離\\"，遠到看不見就是\\"消失\\"。給人從現在這裡離開的感覺。","prep/away/meanings.0":"遠離","prep/away/meanings.1":"消失","prep/back/core":"回到原處","prep/back/coreText":"是沿著來時的路倒回來的箭頭。回到原本所在的地方 · 狀態就是\\"回到原位\\"，把收到的東西送回給對方就是\\"回敬\\"。","prep/back/meanings.0":"回到原位","prep/back/meanings.1":"回敬","prep/against/core":"從相反方向對抗","prep/against/coreText":"是兩股力量從相反方向互相碰撞的畫面。對抗想法 · 規則就是\\"反對\\"，身體靠到牆上使力就是\\"倚靠 · 撞上\\"，擋在危險前面，或貼著背景而變得清楚，就是\\"對照\\"。","prep/against/meanings.0":"反對","prep/against/meanings.1":"倚靠 · 撞上","prep/against/meanings.2":"對照","prep/between/core":"兩者之間","prep/between/coreText":"是夾在兩個點 · 兩個人 · 兩個時刻之間的畫面。當兩邊可以一個一個清楚指出來時使用。","prep/between/meanings.0":"兩者之間","prep/among/core":"多者之間","prep/among/coreText":"是置身於許多東西混在一起的群體之中的畫面。是不逐一細分的群體\\"當中\\"。","prep/among/meanings.0":"多者之間","prep/behind/core":"後方","prep/behind/coreText":"是在某個東西後方的畫面。身體或進度在後面就是\\"在後面 · 落後\\"，站在後面推著背就是\\"在背後支持\\"。和 in front of(在前面)相反。","prep/behind/meanings.0":"在後面 · 落後","prep/behind/meanings.1":"在背後支持","prep/beyond/core":"另一邊","prep/beyond/coreText":"是越過線或邊界，在它另一邊的畫面。看得見的山的另一邊，或想像 · 極限的另一邊，都是 beyond。","prep/beyond/meanings.0":"另一邊 · 超出","prep/within/core":"範圍之內","prep/within/coreText":"是停留在既定界線內側的畫面。比 in 更有\\"不越線\\"的感覺。是時間 · 距離 · 預算的限度之內。","prep/within/meanings.0":"範圍之內","prep/without/core":"沒有","prep/without/coreText":"和 with(一起)相反。是該在身邊的東西不在的畫面。","prep/without/meanings.0":"沒有","prep/before/core":"前 · 先","prep/before/coreText":"是在時間或順序上位於前面的畫面。比作為基準的事情更早發生。","prep/before/meanings.0":"前 · 先","prep/after/core":"後 · 跟隨","prep/after/coreText":"是在時間或順序上位於後面的畫面。接在作為基準的事情之後，或跟在某人後面。look after(照顧，片語動詞第59個)也是這個畫面。","prep/after/meanings.0":"後 · 跟隨","prep/onto/core":"上到表面上","prep/onto/coreText":"是 on(接觸表面)加上 to(朝向)的詞。是從下面或旁邊移動，上到表面並接觸的畫面。和 into(進入裡面)成對。","prep/onto/meanings.0":"上到表面上","p1/title":"空間之內","p1/why":"在箱子 · 房間這種四周封閉的地方之內，就用 in。城市 · 國家也是地圖上劃了界線的\\"容器\\"，所以說 in Seoul, in Korea。車子是把身體縮進去坐的空間，所以說 in the car。公車 · 火車的地板可以在上面走動，所以說 on the bus (之後在 on ⑥ 再見)。","p1/examples.0.ko":"鑰匙在包包裡。","p1/examples.1.ko":"他住在首爾。","p1/examples.2.ko":"我們在車子裡等吧。外面很冷。","p1/examples.3.ko":"箱子裡有一隻貓！","p1/compare":"at the station 是車站這個\\"一個點\\"(碰面的地方)，in the station 是車站建築\\"裡面\\"。之後在 at ① 再看。","p1/quiz.0.ko":"你的手機在抽屜裡。","p1/quiz.0.why":"抽屜是四周封閉的空間。","p1/quiz.1.ko":"我的父母住在釜山。","p1/quiz.1.why":"城市是有界線的容器，所以用 in。","p1/quiz.2.ko":"上車！我們遲到了。","p1/quiz.2.why":"車子是把身體放進去坐的空間。如果是公車就說 get on the bus。","p2/title":"期間之內","p2/why":"時間也可以看作容器。月 · 年 · 季節 · 早上這種有長度的時間，事情是放在裡面的，所以用 in。in May 是 5 月這個箱子之內，in 2026 是 2026 年這個箱子之內。如果像一天一樣是日曆的一格就用 on (on Monday，on ②)，如果是時鐘的一個點就用 at (at 7，at ②)。","p2/examples.0.ko":"我的生日在5月。","p2/examples.1.ko":"我在2026年搬到了紐約。","p2/examples.2.ko":"這裡冬天常下大雪。","p2/examples.3.ko":"我通常早上運動。","p2/compare":"是 in the morning · in the afternoon · in the evening，只有夜晚是 at night。這是固定說法，要另外記 (之後在 at ② 再看)。","p2/quiz.0.ko":"我們是在2024年認識的。","p2/quiz.0.why":"一年是有長度的時間容器，所以用 in。","p2/quiz.1.ko":"我早上喝咖啡。","p2/quiz.1.why":"早上是幾個小時長的容器，所以是 in the morning。","p2/quiz.2.ko":"我晚上睡不著。","p2/quiz.2.why":"早上 · 下午 · 傍晚用 in，只有夜晚是 at night。","p3/title":"過了一段時間之後","p3/why":"畫一個從現在開始的\\"時間容器\\"。in ten minutes 是 10 分鐘的容器裝滿時，也就是 10 分鐘之後。用在過去的事上，意思是事情都裝進了那個容器裡，所以是\\"花了～時間\\"(I finished it in ten minutes = 10 分鐘就做完了)。","p3/examples.0.ko":"火車 10 分鐘後開。","p3/examples.1.ko":"我一個小時後回來。","p3/examples.2.ko":"電影 5 分鐘後開始。快點！","p3/examples.3.ko":"他花了兩個星期就學會開車。","p3/compare":"in two days 是\\"從現在起\\"兩天後，after two days 是\\"發生某件事之後\\"的兩天後。講過去的事時要用 after。He left, and after two days he called me.","p3/quiz.0.ko":"晚餐 5 分鐘後就好了。","p3/quiz.0.why":"從現在起 5 分鐘的容器裝滿 = 5 分鐘後，所以用 in。","p3/quiz.1.ko":"他離開了，兩天後打電話給我。","p3/quiz.1.why":"在過去的故事裡，\\"那件事之後\\"的兩天後是 after。","p3/quiz.2.ko":"我那本書三天就讀完了。","p3/quiz.2.why":"事情都裝進了三天的容器裡 = 花了三天。","p4/title":"處於某種狀態","p4/why":"容器不只是空間 · 時間。愛 · 麻煩 · 匆忙這類\\"狀態\\"，也被看作包住人的容器。in love 是整個人沉浸在愛這個容器裡，in trouble 是被困在麻煩的處境裡。中文也說\\"陷入愛河\\"、\\"身陷困境\\"，把狀態當成場所來說。","p4/examples.0.ko":"他們兩個墜入愛河了。","p4/examples.1.ko":"抱歉，我現在很趕。","p4/examples.2.ko":"你有大麻煩了！","p4/examples.3.ko":"廚房一團亂。","p4/compare":"in danger(處於危險中) ↔ out of danger(脫離危險)。從容器裡面出來到外面，就是 out of (之後在 out ① 再看)。","p4/quiz.0.ko":"我現在不能講電話，我很趕。","p4/quiz.0.why":"人是在匆忙這個狀態之內。","p4/quiz.1.ko":"他愛上了同事。","p4/quiz.1.why":"陷在愛這個容器裡面。","p4/quiz.2.ko":"病人現在脫離危險了。會好起來的。","p4/quiz.2.why":"從危險這個容器裡出來到外面了，所以用 out of。","p5/title":"方式","p5/why":"語言 · 金錢 · 顏色 · 字跡這類\\"表達的手段\\"也被看作容器。in English 是把想法裝進英語這個容器裡來說，in cash 是把錢裝進現金這個容器裡來付。說明\\"裝在什麼裡面\\"呈現時，就用 in。","p5/examples.0.ko":"你可以用英文說嗎？","p5/examples.1.ko":"我付現。","p5/examples.2.ko":"請用筆寫名字。","p5/examples.3.ko":"她穿著黑色的衣服。","p5/compare":"pay in cash(用現金) · pay by card(用卡)。卡不是裝東西的容器而是\\"手段\\"，所以用 by (之後在 by ② 再看)。","p5/quiz.0.ko":"您要付現嗎？","p5/quiz.0.why":"現金是裝錢的容器，所以是 in cash。","p5/quiz.1.ko":"那部電影是法語發音，有韓文字幕。","p5/quiz.1.why":"用什麼語言呈現，要用 in。","p5/quiz.2.ko":"我可以刷卡嗎？","p5/quiz.2.why":"卡是手段，所以是 by card。","p6/title":"接觸表面","p6/why":"on 是\\"接觸\\"表面的畫面。不只是放在上面，掛在牆上的畫(on the wall)、貼在天花板上的蜘蛛(on the ceiling)、戴在手指上的戒指(on my finger)也都是接觸著，所以是 on。比中文的\\"在…上面\\"範圍更廣。如果沒有接觸、浮在上方，就是 over · above (之後在 above · below 再看)。","p6/examples.0.ko":"鑰匙在桌上。","p6/examples.1.ko":"牆上掛著一幅畫。","p6/examples.2.ko":"看！天花板上有蜘蛛。","p6/examples.3.ko":"她手指上戴著戒指。","p6/compare":"on the table 是接觸著桌面，in the drawer 是放在抽屜容器裡面。同樣是家具，差別在於是接觸著，還是放在裡面。","p6/quiz.0.ko":"杯子在桌上。","p6/quiz.0.why":"接觸著桌面。","p6/quiz.1.ko":"牆上掛著一個時鐘。","p6/quiz.1.why":"貼著牆面掛著，所以是 on。別誤以為是 in。","p6/quiz.2.ko":"餅乾在盒子裡。","p6/quiz.2.why":"放在盒子裡面，所以是 in。","p7/title":"日期","p7/why":"想像一下日曆。每一天都是日曆上的\\"一格\\"，行程就放在那一格上。所以一天 · 星期 · 日期 · 特別的日子都用 on。on Monday, on May 5th, on my birthday。像月 · 年這種裝著很多格的長時間是容器，所以用 in (in ②)。","p7/examples.0.ko":"星期一見！","p7/examples.1.ko":"我的班機是3月3日。","p7/examples.2.ko":"你生日要做什麼？","p7/examples.3.ko":"那間店每個星期日都休息。","p7/compare":"in the morning(早上)用 in，但 on Friday morning(星期五早上)用 on。一旦帶上特定的某一天，就是 on 勝出。","p7/quiz.0.ko":"派對在星期六。","p7/quiz.0.why":"星期是日曆的一格，所以用 on。","p7/quiz.1.ko":"我是6月10日出生的。","p7/quiz.1.why":"日期是日曆的一格，所以用 on。","p7/quiz.2.ko":"我們是在2019年認識的。","p7/quiz.2.why":"一年是裝著很多格的容器，所以用 in (in ②)。","p8/title":"倚靠依賴","p8/why":"把身體靠在某物上，就是接觸那個面並把重量放上去。所以\\"倚靠 · 依賴\\"是 on。depend on(取決於～)、rely on(信賴依靠)、live on(靠～維生)都是把重量放在上面的畫面。based on(以～為基礎)也是建立在上面的意思。","p8/examples.0.ko":"要看天氣。","p8/examples.1.ko":"你可以相信我。","p8/examples.2.ko":"學生常常靠泡麵過日子。","p8/examples.3.ko":"那部電影是根據真實故事改編的。","p8/compare":"count on(指望)也是同樣的畫面(在片語動詞清單裡)。只說 It depends. 的話，意思是\\"看情況\\"。","p8/quiz.0.ko":"我們的計畫取決於預算。","p8/quiz.0.why":"重量放在預算上面的畫面，所以是 depend on。","p8/quiz.1.ko":"這本書是根據他的人生寫成的。","p8/quiz.1.why":"建立在他的人生之上的故事，所以是 based on。","p8/quiz.2.ko":"我的祖父母住在釜山。","p8/quiz.2.why":"住在哪裡用 in (in ①)。live on 是\\"靠～維生\\"。","p9/title":"主題","p9/why":"是談話或文章緊貼在某個主題\\"上面\\"，不離開那個主題的畫面。a book on history 是寫在歷史這個面上的書。也用在\\"以某事為對象\\"的事：work on the logo(做標誌設計)、focus on(專注於～)。","p9/examples.0.ko":"我在讀一本關於色彩設計的書。","p9/examples.1.ko":"她做了一場關於氣候變遷的演講。","p9/examples.2.ko":"你的標誌做得真好！","p9/examples.3.ko":"我們專注在核心問題上吧。","p9/compare":"about 是\\"關於～的種種\\"，on 是\\"以～為主題深入探討\\"。和朋友閒聊常用 about，演講 · 論文 · 書常用 on (之後在 about ① 再看)。","p9/quiz.0.ko":"他寫了一本關於韓國歷史的書。","p9/quiz.0.why":"書的主題用 on。","p9/quiz.1.ko":"你的簡報做得真好！","p9/quiz.1.why":"以某事為對象的工作，要用 on。","p9/quiz.2.ko":"我們只是聊了聊週末的計畫。","p9/quiz.2.why":"輕鬆的閒聊，用 about 比較自然。","p10/title":"運作 · 進行中","p10/why":"打開開關，兩片金屬就會互相接觸(on)。要接觸電才會通，所以\\"接觸著\\"就變成\\"開著 · 運轉中\\"。著火的 on fire、排班在值勤的 on duty、正在促銷的 on sale，也是同樣的畫面。","p10/examples.0.ko":"電視開著。","p10/examples.1.ko":"大樓著火了！","p10/examples.2.ko":"我今晚值班。","p10/examples.3.ko":"這雙鞋正在特價。","p10/compare":"相反是 off (分開 → 關掉)。The TV is off. 之後在 off ③ 再見。","p10/quiz.0.ko":"誰開著燈？現在凌晨2點耶！","p10/quiz.0.why":"開著的狀態是 on。","p10/quiz.1.ko":"打911！我家著火了！","p10/quiz.1.why":"正著火燃燒中，所以是 on fire。","p10/quiz.2.ko":"電視關著。是我關的。","p10/quiz.2.why":"分開、斷掉的狀態是 off。","p11/title":"媒介 · 交通工具","p11/why":"on 也可以是\\"搭上平台\\"的畫面。公車 · 火車 · 飛機 · 船的地板很寬，可以在上面走動，所以是 on the bus。車子 · 計程車是把身體縮進去的容器，所以是 in the car (in ①)。TV · 廣播 · 電話 · 網路也是話語和影像\\"承載在上面\\"傳送的平台，所以是 on TV, on the phone, on the internet。","p11/examples.0.ko":"我在公車上。快到了。","p11/examples.1.ko":"抱歉，我剛才在講電話。","p11/examples.2.ko":"今晚電視上有什麼好看的嗎？","p11/examples.3.ko":"我在網路上找到那個食譜。","p11/compare":"get on the bus(上公車) · get off the bus(下公車)，get in the car(上車) · get out of the car(下車)。依交通工具的大小，on · in 會有所不同。","p11/quiz.0.ko":"她現在在講電話。","p11/quiz.0.why":"電話是話語承載來回的平台，所以是 on the phone。","p11/quiz.1.ko":"我把雨傘忘在火車上了。","p11/quiz.1.why":"火車是可以在上面走動的大型交通工具，所以用 on。","p11/quiz.2.ko":"上計程車。快點！","p11/quiz.2.why":"計程車是把身體放進去坐的容器，所以用 in。","p12/title":"一個點的地點","p12/why":"是在地圖上釘下一根圖釘的畫面。像 at the door, at the bus stop 這樣，只把\\"在哪裡\\"說成一個地點時用 at。同一個車站，說成碰面的地點就是 at the station，說成車站建築裡面就是 in the station (和 in ① 比較)。派對 · 演唱會這種人群聚集的活動，也被看作一個點，所以用 at。","p12/examples.0.ko":"有人到門口了。","p12/examples.1.ko":"我們在公車站見面吧。","p12/examples.2.ko":"我在派對上看到她了。","p12/examples.3.ko":"在下一個轉角左轉。","p12/compare":"at home · at work · at school 是固定說法，意思是\\"人在家 · 公司 · 學校這個地點\\"(不加冠詞)。","p12/quiz.0.ko":"我在入口等你。","p12/quiz.0.why":"入口是一個點，所以用 at。","p12/quiz.1.ko":"我們是在演唱會上認識的。","p12/quiz.1.why":"人群聚集的活動被看作一個點，所以用 at。","p12/quiz.2.ko":"她住在東京。","p12/quiz.2.why":"城市是有界線的容器，所以用 in。","p13/title":"一個點的時刻","p13/why":"是時鐘指針指到的\\"一個點\\"。像 at 7, at noon, at midnight，時刻是沒有面積的點，所以用 at。和一天(on ②) · 月 · 年(in ②)並排看，大小依序是點 → 格 → 容器。只有夜晚是 at night。","p13/examples.0.ko":"會議9點30分開始。","p13/examples.1.ko":"中午一起吃午餐吧。","p13/examples.2.ko":"我通常午夜才睡。","p13/examples.3.ko":"晚上一個人走路很危險。","p13/compare":"at 7 (點) → on Monday (格) → in May (容器)。週末在美式英語是 on the weekend，在英式英語是 at the weekend。","p13/quiz.0.ko":"那間店晚上10點關門。","p13/quiz.0.why":"時刻是一個點，所以用 at。","p13/quiz.1.ko":"我晚上睡不著。","p13/quiz.1.why":"夜晚是固定說法 at night。","p13/quiz.2.ko":"我的生日在星期五。","p13/quiz.2.why":"星期是日曆的一格，所以用 on。","p14/title":"靶心","p14/why":"射箭時會瞄準靶上的\\"一個點\\"對吧。視線 · 話語 · 東西朝著某個點飛過去的畫面，就是 at。look at(朝著那個點看)、laugh at(朝著某人笑 = 嘲笑)、throw at(為了打中而丟)、shout at(對某人大吼)。因為帶有瞄準的意思，有時會有帶攻擊性的感覺。","p14/examples.0.ko":"看看這張照片！","p14/examples.1.ko":"別笑我。","p14/examples.2.ko":"他朝窗戶丟了一顆球。","p14/examples.3.ko":"你為什麼對我大吼？","p14/compare":"throw the ball to me 是為了\\"讓我接\\"而丟(to ②)，throw the ball at me 是為了\\"打中我\\"而丟。","p14/quiz.0.ko":"別再盯著我看了！","p14/quiz.0.why":"視線朝向我這個靶心，所以用 at。","p14/quiz.1.ko":"大家都被他的笑話逗笑了。","p14/quiz.1.why":"笑所朝向的靶心用 at。","p14/quiz.2.ko":"把球丟給我。我來接。","p14/quiz.2.why":"為了讓人接而丟，就用 to。at 是為了打中而丟。","p15/title":"數值 · 程度","p15/why":"是刻度尺上的\\"一個點\\"。像速度 · 溫度 · 價格 · 年齡這樣，說刻度上的某一點時就用 at。at 100 km/h(以時速 100 公里)、at 30 degrees、at half price、at the age of 20。也用在程度 · 水準：at full speed(全速)、at best(最多也只是)。","p15/examples.0.ko":"車子以時速120公里行駛。","p15/examples.1.ko":"水在100度沸騰。","p15/examples.2.ko":"我用半價買到了。","p15/examples.3.ko":"她四歲開始學鋼琴。","p15/compare":"It costs $10. 是價格本身，I bought it at $10. 是說\\"在那個價格這個點上\\"買的。特價中是 on sale (on ⑤)。","p15/quiz.0.ko":"那列火車時速300公里。","p15/quiz.0.why":"是速度刻度上的一個點，所以用 at。","p15/quiz.1.ko":"水在0度結冰。","p15/quiz.1.why":"是溫度刻度上的一個點，所以用 at。","p15/quiz.2.ko":"這雙鞋這星期在特價。","p15/quiz.2.why":"販售進行中，所以是 on sale (on ⑤)。","p16/title":"in · on · at 一覽","p16/why":"這三個介系詞是大小不同的三個畫面。at 是沒有面積的點，on 是接觸的面 · 格，in 是包圍的容器。時間：at 7 (時刻) → on Monday (一天) → in May (一個月 · 年)。地點：at the bus stop (地點) → on the wall (表面) → in the room (容器)。搞混時，想想\\"我現在是把它看成點 · 面 · 容器中的哪一個？\\"","p16/examples.0.ko":"演講在3點，3樓5號室舉行。","p16/examples.1.ko":"我是1998年5月5日早上6點出生的。","p16/examples.2.ko":"她在紐約第五大道上的一間咖啡廳。","p16/examples.3.ko":"星期五中午見。","p16/compare":"在美式英語裡，街道用 on (on Fifth Avenue)，確切的地址用 at (at 25 Fifth Avenue)。","p16/quiz.0.ko":"演唱會在星期六晚上8點。","p16/quiz.0.why":"星期是格所以用 on，時刻是點所以用 at。","p16/quiz.1.ko":"天花板上停著一隻蒼蠅。","p16/quiz.1.why":"接觸著天花板的表面，所以是 on。","p16/quiz.2.ko":"我們是2020年搬到這裡的。","p16/quiz.2.why":"一年是容器，所以用 in。","p17/title":"抵達點","p17/why":"是箭頭飛過去\\"碰到\\"某個點的畫面。像 go to school, fly to Chicago 這樣，移動的抵達點就是 to。at(在那個點上)是停住的畫面，to 是往那個點去的畫面。I'm at the station.(我在車站) · I'm going to the station.(我要去車站)","p17/examples.0.ko":"我搭公車去學校。","p17/examples.1.ko":"我們明天去芝加哥。","p17/examples.2.ko":"歡迎來到紐約！","p17/examples.3.ko":"請問車站怎麼走？","p17/compare":"go home · come here · go there 不用 to。因為 home · here · there 本身已經有\\"到那裡\\"的意思。","p17/quiz.0.ko":"我要去健身房。","p17/quiz.0.why":"是前往的抵達點，所以用 to。","p17/quiz.1.ko":"我現在在車站。你在哪？","p17/quiz.1.why":"不是去，而是停在那個點上，所以用 at。","p17/quiz.2.ko":"她去年搬到釜山了。","p17/quiz.2.why":"是搬過去之後抵達的地方，所以用 to。","p18/title":"接收的人","p18/why":"箭頭的前端如果是\\"人\\"，那個人就是接收的一方。give it to me(遞給我)、send an email to Dana、talk to you(話傳到你那裡)、explain to them。是東西或話語\\"抵達\\"那個人的畫面。","p18/examples.0.ko":"你可以把這個給 Jake 嗎？","p18/examples.1.ko":"我把檔案寄給 Dana 了。","p18/examples.2.ko":"我得跟你談談。","p18/examples.3.ko":"請再向我解釋一次。","p18/compare":"give it to me 是接收的人(to)，buy it for me 是為我做的事(for)。遞過去而抵達就用 to，為了我就用 for (之後在 to vs for 再看)。","p18/quiz.0.ko":"我把書借給 Mina 了。","p18/quiz.0.why":"書傳到 Mina 那裡，所以用 to。","p18/quiz.1.ko":"你在跟誰講電話？","p18/quiz.1.why":"話語抵達的對象用 to。","p18/quiz.2.ko":"我為你做了蛋糕。","p18/quiz.2.why":"是為你做的，所以用 for。","p19/title":"終點 · 範圍","p19/why":"是箭頭停下來的終點。from A to B 是從 A 出發、在 B 停下來的範圍。from 9 to 5(從9點到5點)、from Monday to Friday、to the end(到最後)。數數時也是 count to ten(數到十)。","p19/examples.0.ko":"我從9點工作到5點。","p19/examples.1.ko":"那間店從星期一開到星期六。","p19/examples.2.ko":"我們把電影看完吧。","p19/examples.3.ko":"數到十再睜開眼睛。","p19/compare":"在美式英語裡，也常用 from Monday through Friday(包含星期五) (之後在 through ② 再看)。until 5 的意思是\\"一直到5點\\"。","p19/quiz.0.ko":"博物館從10點開到6點。","p19/quiz.0.why":"是範圍的終點，所以用 to。","p19/quiz.1.ko":"把那本書讀完。","p19/quiz.1.why":"是走到終點，所以是 to the end。","p19/quiz.2.ko":"博物館10點開門。","p19/quiz.2.why":"是開門的時刻，所以用 at (at ②)。","p20/title":"結果 · 配合","p20/why":"是箭頭抵達的地方是\\"結果\\"或\\"搭檔\\"的時候。to my surprise 是事情發展到抵達我的驚訝 = 令人驚訝的是。smash it to pieces 是碎掉變成碎片的結果，dance to music 是動作\\"貼合\\"音樂的畫面。","p20/examples.0.ko":"令我驚訝的是，她答應了。","p20/examples.1.ko":"他們隨著音樂跳舞。","p20/examples.2.ko":"花瓶摔得粉碎。","p20/examples.3.ko":"看了那部電影後，我哭了。","p20/compare":"To be honest(老實說)的 to 是加在動詞前面的 to，和這個意思不同。to 後面接名詞是介系詞，接原形動詞是 to 不定詞 (第9章會學)。","p20/quiz.0.ko":"令我驚訝的是，考試很簡單。","p20/quiz.0.why":"抵達了驚訝這個結果，所以是 To my surprise。","p20/quiz.1.ko":"你可以跟著這首歌跳舞嗎？","p20/quiz.1.why":"配合音樂用 to。","p20/quiz.2.ko":"盤子掉下來摔得粉碎。","p20/quiz.2.why":"碎掉的結果是碎片，所以是 to pieces。","p21/title":"想要的東西","p21/why":"是朝著想要的東西伸出手，但還沒碰到的畫面。wait for(期待它到來而等待)、look for(尋找)、ask for(要求給予)、go for a walk(為了散步而出門)。想要得到的對象會接在 for 後面。","p21/examples.0.ko":"我在等公車。","p21/examples.1.ko":"您在找什麼？","p21/examples.2.ko":"我們去散步吧。","p21/examples.3.ko":"別怕開口求助。","p21/compare":"look at 是視線已經碰到那個點(at ③)，look for 是還沒找到而四處尋找，find 是找到了。","p21/quiz.0.ko":"我等你等了一個小時！","p21/quiz.0.why":"是期待它到來而等待的 wait for。","p21/quiz.1.ko":"她在找她的鑰匙。","p21/quiz.1.why":"還沒找到、正在找，所以是 look for。","p21/quiz.2.ko":"看看這張照片！","p21/quiz.2.why":"是看眼前的東西，所以用 at。","p22/title":"為了 · 接收的人","p22/why":"是把心意朝向某個人的畫面。a gift for you(給你的禮物)、cook for my family(為家人做飯)、work for a company(為公司工作 = 在公司上班)。是讓那個人\\"得到好處\\"的事。","p22/examples.0.ko":"我買了這份禮物要給你。","p22/examples.1.ko":"我煮了晚餐給大家一起吃。","p22/examples.2.ko":"她在一間設計公司上班。","p22/examples.3.ko":"不好意思，我是在幫朋友占位子。","p22/compare":"give it to me 是遞過去而抵達(to ②)，buy it for me 是為我買。Day 30 會把兩個並排來看。","p22/quiz.0.ko":"我買了花要給媽媽。","p22/quiz.0.why":"是為媽媽買的，所以用 for。","p22/quiz.1.ko":"他在一間大銀行上班。","p22/quiz.1.why":"為公司工作是 work for。","p22/quiz.2.ko":"請把這封信交給 Dana。","p22/quiz.2.why":"信傳到 Dana 那裡，所以用 to。","p23/title":"期間","p23/why":"是朝著時間方向延伸的長度。for three years 是\\"三年這麼長\\"。常和現在完成式(第9課)一起出現：I've lived here for two years. 說明\\"持續多久\\"的\\"長度\\"時，就用 for。","p23/examples.0.ko":"我住在這裡兩年了。","p23/examples.1.ko":"我們等了一個小時。","p23/examples.2.ko":"她要去日本一個星期。","p23/examples.3.ko":"我已經很久沒見到他了。","p23/compare":"for + 長度(for two hours)，during + 事情發生的時候(during the movie)，since + 起點(since 2020)。第96課會再整理。","p23/quiz.0.ko":"我認識她十年了。","p23/quiz.0.why":"ten years 是長度，所以用 for。","p23/quiz.1.ko":"我從2016年就認識她了。","p23/quiz.1.why":"2016 是起點，所以用 since。","p23/quiz.2.ko":"我看電影看到睡著了。","p23/quiz.2.why":"是電影這件事進行的期間，所以用 during。","p24/title":"交換 · 價格","p24/why":"想得到什麼而伸出手時，會拿出相應的代價。所以交換的東西 · 價格就是 for。buy it for $10(花10美元買)、thank you for the coffee(為了收到的咖啡道謝)、sorry for being late(為遲到而抱歉)。","p24/examples.0.ko":"我花50美元買了這件外套。","p24/examples.1.ko":"謝謝你的咖啡。","p24/examples.2.ko":"抱歉我遲到了。","p24/examples.3.ko":"我可以把這個換成小尺寸嗎？","p24/compare":"Thank you for 後面接名詞或 -ing (Thank you for helping me)。價格本身是 It's $50.，付那個價錢買的是 bought it for $50。","p24/quiz.0.ko":"謝謝你幫忙。","p24/quiz.0.why":"感謝的原因(收到的東西)用 for。","p24/quiz.1.ko":"我把舊腳踏車賣了100美元。","p24/quiz.1.why":"是交換的價錢，所以用 for。","p24/quiz.2.ko":"我用半價買到了。","p24/quiz.2.why":"是半價這個價格刻度上的點，所以用 at (at ④)。","p25/title":"贊成","p25/why":"身體\\"朝向\\"某個想法傾斜，就是站在那一邊。Are you for or against the plan?(你贊成還是反對？)、I'm all for it.(我完全贊成)、vote for(投票給～)。相反是 against (之後在 against ① 再看)。","p25/examples.0.ko":"你贊成還是反對那個想法？","p25/examples.1.ko":"我完全贊成！","p25/examples.2.ko":"你投給誰了？","p25/examples.3.ko":"大多數人贊成興建新公園。","p25/compare":"for ↔ against。開會時會用 Who's for this?(誰贊成？)請大家舉手。","p25/quiz.0.ko":"我贊成那個計畫。就這麼做吧！","p25/quiz.0.why":"傾向那一邊，所以用 for。","p25/quiz.1.ko":"十個人贊成，兩個人反對。","p25/quiz.1.why":"投贊成票是 vote for。","p25/quiz.2.ko":"你贊成還是反對新規定？","p25/quiz.2.why":"for 的相反是 against。","p26/title":"前往的地方","p26/why":"是還沒抵達，\\"朝著那邊\\"出發的畫面。leave for Busan(往釜山出發)、head for home(朝家的方向走)、the train for Chicago(開往芝加哥的火車)。和說抵達點的 to (to ①)不同，說的是出發當下的\\"方向\\"。","p26/examples.0.ko":"我們明天出發去釜山。","p26/examples.1.ko":"這是開往芝加哥的火車嗎？","p26/examples.2.ko":"很晚了。我們回家吧。","p26/examples.3.ko":"她一個小時前出門上班了。","p26/compare":"leave for Busan(往釜山出發) · go to Busan(去釜山) · leave Busan(離開釜山)。leave 後面直接接地點，意思是\\"離開那裡\\"。","p26/quiz.0.ko":"他今天早上動身前往倫敦了。","p26/quiz.0.why":"是朝著倫敦出發，所以是 leave for。","p26/quiz.1.ko":"這是開往市區的公車嗎？","p26/quiz.1.why":"開往哪裡用 for。","p26/quiz.2.ko":"我們下星期去釜山。","p26/quiz.2.why":"go 後面的抵達點用 to。","p27/title":"出發點","p27/why":"是箭頭的尾端，出發點。from Seoul(從首爾出發)、from 9 to 5(從9點，和 to ③ 成對)、I'm from Korea(我來自韓國 = 韓國人)。說明是從哪裡離開、開始的。","p27/examples.0.ko":"我是韓國人。","p27/examples.1.ko":"從首爾起飛的班機延誤了。","p27/examples.2.ko":"離這裡10分鐘的路程。","p27/examples.3.ko":"那間店從早上9點開始營業。","p27/compare":"Where are you from? 是\\"你是哪裡人？\\"，Where did you come from? 是\\"你剛剛從哪裡來？\\"。出身是 be from，剛出發的地方是 come from。","p27/quiz.0.ko":"您是哪裡人？","p27/quiz.0.why":"出身 · 出發點是 from。","p27/quiz.1.ko":"從車站到你家有多遠？","p27/quiz.1.why":"出發點 from，抵達點 to。","p27/quiz.2.ko":"那班火車從首爾開到釜山。","p27/quiz.2.why":"抵達點是 to。","p28/title":"來源 · 材料","p28/why":"事物「從哪裡來」也是一個出發點。a letter from Mom(媽媽寄來的信)、hear from you(收到你的消息)、Cheese is made from milk.(起司是用牛奶做的)。原料變了形、看不出原樣時,就用 made from。","p28/examples.0.ko":"Jake 傳訊息給我了。","p28/examples.1.ko":"好幾週沒有她的消息了。","p28/examples.2.ko":"紙是用木頭做的。","p28/examples.3.ko":"這句引言出自一本老書。","p28/compare":"原料變形、看不出來時用 made from(wine is made from grapes),原料還看得出來時用 made of(a table made of wood)。","p28/quiz.0.ko":"我收到老闆寄來的電子郵件。","p28/quiz.0.why":"電子郵件的來源,所以用 from。","p28/quiz.1.ko":"葡萄酒是用葡萄做的。","p28/quiz.1.why":"葡萄變了形、看不出來,所以用 made from。","p28/quiz.2.ko":"這張桌子是用木頭做的。","p28/quiz.2.why":"木頭還看得出來,所以用 made of。","p29/title":"隔開","p29/why":"這是從出發點被「拉開、分離」的畫面。stop A from -ing(阻止 A 做~)、protect A from B(保護 A 不受 B 傷害)、keep A away from B(讓 A 遠離 B)。意思是把人從危險或某個行為中隔開。","p29/examples.0.ko":"因為下雨,我們沒辦法出門。","p29/examples.1.ko":"防曬乳能保護皮膚不被陽光傷害。","p29/examples.2.ko":"藥請放在小孩拿不到的地方。","p29/examples.3.ko":"沒有什麼能阻止我去挑戰。","p29/compare":"stop A from -ing 的 from 後面接 -ing。different from(和~不同)也是「分開」的畫面。","p29/quiz.0.ko":"噪音害我睡不著。","p29/quiz.0.why":"把人和睡眠隔開了,所以是 keep A from -ing。","p29/quiz.1.ko":"戴上帽子,免得被太陽曬到。","p29/quiz.1.why":"讓人遠離危險、保護他,所以是 protect from。","p29/quiz.2.ko":"他怕黑。","p29/quiz.2.why":"害怕的對象用 afraid of(of 會在 ④ 再看到)。","p30/why":"to 是箭頭「碰到」的地方,for 是「為了那一邊、期盼著」而朝向的心意。give it to me(遞到我手上)/ buy it for me(為我買)。go to Busan(抵達釜山)/ leave for Busan(朝釜山出發)。talk to him(話傳到他那裡)/ wait for him(期盼他來而等待)。搞不清楚時,問自己「遞過去碰到了嗎?」(to)、「是為了他嗎?」(for)。","p30/examples.0.ko":"我把書給了 Mina。","p30/examples.1.ko":"我買了書要給 Mina。","p30/examples.2.ko":"往芝加哥的火車 6 點出發。中午會抵達芝加哥。","p30/examples.3.ko":"把檔案寄給 Dana。她說開會要用。","p30/compare":"give · send · lend · show · tell 這類「遞給」的動詞搭 to,buy · make · cook · get 這類「做給、找給」的動詞搭 for。","p30/quiz.0.ko":"可以借我車嗎?","p30/quiz.0.why":"車子轉到我這裡,所以用 to。","p30/quiz.1.ko":"爸爸為我們做了晚餐。","p30/quiz.1.why":"是為我們做的,所以用 for。","p30/quiz.2.ko":"把計畫向 Jake 解釋一下。","p30/quiz.2.why":"解釋傳到 Jake 那裡,所以用 to。","p31/title":"整體的一部分","p31/why":"從大塊(B)切下來的一小塊(A)就是 A of B。one of my friends(我的朋友之一)、a piece of cake(一塊蛋糕)、some of the money(一部分錢)。英文的順序是「部分 of 整體」。","p31/examples.0.ko":"她是我最好的朋友之一。","p31/examples.1.ko":"我可以吃一塊蛋糕嗎?","p31/examples.2.ko":"大部分學生都通過了。","p31/examples.3.ko":"我們當中有幾個人今晚要出門。","p31/compare":"one of 後面接複數名詞。one of my friends ○ · one of my friend ✕。因為整體一定是好幾個。","p31/quiz.0.ko":"他是隊上最強的球員之一。","p31/quiz.0.why":"好幾個當中的一個,用 one of。","p31/quiz.1.ko":"我吃了半個披薩。","p31/quiz.1.why":"從整體切出來的一半,所以是 half of。","p31/quiz.2.ko":"她是韓國人嗎?","p31/quiz.2.why":"出身地用 from(from ①)。","p32/title":"所屬 · 性質","p32/why":"A「附屬於」B 時就是 A of B。the door of the car(車門)、the end of the movie(電影的結尾)、the capital of Korea(韓國的首都)。人的性質也可以這樣掛上去,如 a man of few words(寡言的人)。","p32/examples.0.ko":"這首歌的名字是什麼?","p32/examples.1.ko":"我住在那條路的盡頭。","p32/examples.2.ko":"首爾是韓國的首都。","p32/examples.3.ko":"他是個話不多的人。","p32/compare":"人或動物的東西用 's(Jake's car),物品或地點的一部分用 of(the roof of the house)比較自然。","p32/quiz.0.ko":"那本書的書名是什麼?","p32/quiz.0.why":"書名附屬於書,所以用 of。","p32/quiz.1.ko":"我們坐在房間後面。","p32/quiz.1.why":"後面附屬於房間,所以用 of。","p32/quiz.2.ko":"他本來是釜山人。","p32/quiz.2.why":"出身地用 from。","p33/title":"內容物 · 材料","p33/why":"容器或單位裡裝了什麼,放在 of 後面。a cup of coffee(一杯咖啡)、a bottle of water、a bunch of flowers(一束花)、a lot of people。不可數的東西(水 · 咖啡 · 麵粉)要用這種裝它的單位來數(59 課會再看到)。","p33/examples.0.ko":"可以給我一杯咖啡嗎?","p33/examples.1.ko":"他買了一束花。","p33/examples.2.ko":"加一小撮鹽。","p33/examples.3.ko":"派對上有很多人。","p33/compare":"a cup of coffee 是裝了咖啡的杯子,a coffee cup 是咖啡用的杯子(可能是空的)。有 of 就表示裡面有內容物。","p33/quiz.0.ko":"請給我一杯水。","p33/quiz.0.why":"杯子裡裝的內容物,所以用 of。","p33/quiz.1.ko":"她喝了兩瓶果汁。","p33/quiz.1.why":"瓶子裡裝的內容物,所以用 of。","p33/quiz.2.ko":"把杯子裝滿水。","p33/quiz.2.why":"用什麼裝滿是 fill A with B(with ②)。","p34/title":"原因 · 對象","p34/why":"心情或事情「從什麼而來、附屬於什麼」。afraid of dogs(怕狗)、proud of you(以你為榮)、think of(想到~)、die of cancer(死於癌症)。常接在情緒形容詞後面,說出那種情緒的對象。","p34/examples.0.ko":"我怕蜘蛛。","p34/examples.1.ko":"我真以你為榮!","p34/examples.2.ko":"我受夠等待了。","p34/examples.3.ko":"你覺得我的新髮型怎麼樣?","p34/compare":"think of 是想起、表達看法,think about 是仔細思考。What do you think of it?(你覺得如何?)/ I'm thinking about it.(我正在考慮)","p34/quiz.0.ko":"她怕黑。","p34/quiz.0.why":"害怕的對象用 afraid of。","p34/quiz.1.ko":"我真為我們的團隊感到驕傲。","p34/quiz.1.why":"引以為傲的對象用 proud of。","p34/quiz.2.ko":"我再想想。明天告訴你。","p34/quiz.2.why":"仔細思考用 think about。","p35/title":"一起","p35/why":"兩個人或兩樣東西並排靠在一起的畫面。go with friends(和朋友一起去)、live with my parents(和父母同住)、coffee with milk(加牛奶的咖啡)。相反的是 without(沒有~)(會在 within · without 再看到)。","p35/examples.0.ko":"我和 Jake 去看電影了。","p35/examples.1.ko":"她和父母住在一起。","p35/examples.2.ko":"可以給我一杯加牛奶的咖啡嗎?","p35/examples.3.ko":"跟我一起來吧。我帶你看。","p35/compare":"talk with 和 talk to 都可以用。with 是「互相交流」,to 是「話傳到那個人那裡」的感覺。","p35/quiz.0.ko":"要不要和我們一起去?","p35/quiz.0.why":"是一起去,所以用 with。","p35/quiz.1.ko":"我和兩個室友住在一起。","p35/quiz.1.why":"是一起住,所以用 with。","p35/quiz.2.ko":"我搭公車上班。","p35/quiz.2.why":"交通方式用 by(by ②)。","p36/title":"工具","p36/why":"手上「握著」工具一起動作的畫面。cut with a knife(用刀切)、write with a pen(用筆寫)、eat with chopsticks(用筷子吃)、fill with water(用水裝滿)。手裡拿著用的東西就用 with。","p36/examples.0.ko":"用這把刀切麵包。","p36/examples.1.ko":"你用筷子吃嗎?","p36/examples.2.ko":"她用鑰匙開了門。","p36/examples.3.ko":"把瓶子裝滿水。","p36/compare":"with 是手上拿的工具(with a pen),by 是方法 · 交通方式(by email, by bus),in 是表達的方式(in pen, in English)。Day 47 會把 with 和 by 放在一起比較。","p36/quiz.0.ko":"他用鎚子把它修好了。","p36/quiz.0.why":"手上拿的工具,所以用 with。","p36/quiz.1.ko":"請用英文寫下你的名字。","p36/quiz.1.why":"用哪種語言寫是 in(in ⑤)。","p36/quiz.2.ko":"我會用電子郵件寄給你。","p36/quiz.2.why":"通訊方式用 by(by ②)。","p37/title":"具有","p37/why":"人或東西「帶著」某個特徵「一起」存在的畫面。a girl with long hair(長頭髮的女孩)、a room with a view(有景觀的房間)、a man with a beard(留鬍子的男人)。中文也是放在名詞前面修飾(「長頭髮的女孩」),英文則是把 with 放在名詞後面。","p37/examples.0.ko":"那個灰頭髮的男人是誰?","p37/examples.1.ko":"請給我一間景觀好的房間。","p37/examples.2.ko":"拿著紅色包包的人就是她。","p37/examples.3.ko":"這是一個充滿人情味的小社區。","p37/compare":"a girl with long hair 是身上帶有的特徵,a girl in a red dress 是穿在身上的衣服(in ⑤)。身上帶有的用 with,穿著的衣服用 in。","p37/quiz.0.ko":"我在找有花園的房子。","p37/quiz.0.why":"是擁有花園的房子,所以用 with。","p37/quiz.1.ko":"戴眼鏡的那個男人是我們的老師。","p37/quiz.1.why":"身上帶有的特徵(眼鏡)用 with。","p37/quiz.2.ko":"穿黑色外套的人是 Dana。","p37/quiz.2.why":"穿著的衣服用 in。","p38/title":"原因 · 狀態","p38/why":"某種感覺或狀態「跟著」身體一起出現的畫面。shaking with cold(冷得發抖)、red with anger(氣得臉紅)、with tears in her eyes(眼裡含著淚)、with the door open(開著門)。和什麼一起出現,就成了原因或樣子。","p38/examples.0.ko":"她冷得發抖。","p38/examples.1.ko":"他氣得滿臉通紅。","p38/examples.2.ko":"不要開著窗戶睡覺。","p38/examples.3.ko":"她眼裡含著淚道別。","p38/compare":"with + 名詞 + 狀態(with the door open, with the TV on)表示「保持著~的狀態」,和中文「開著門」「開著電視」的說法相近。","p38/quiz.0.ko":"他高興得又蹦又跳。","p38/quiz.0.why":"是和喜悅一起出現的狀態,所以用 with。","p38/quiz.1.ko":"不要嘴裡含著食物說話。","p38/quiz.1.why":"「保持著~的狀態」是 with + 名詞 + 狀態。","p38/quiz.2.ko":"她因癌症而過世。","p38/quiz.2.why":"死於疾病是 die of(of ④)。","p39/title":"就在旁邊","p39/why":"緊貼著某物「身旁」的畫面。by the window(在窗邊)、by the door(在門邊)、a house by the sea(海邊的房子)。walk by(從旁邊走過)也是同一個畫面。","p39/examples.0.ko":"我們坐窗邊吧。","p39/examples.1.ko":"在門邊等我。","p39/examples.2.ko":"他們住在海邊的房子。","p39/examples.3.ko":"今天早上我經過你們的辦公室。","p39/compare":"by the window 是窗戶附近,next to the window 是窗戶正旁邊,at the window 是站在窗前往外看。","p39/quiz.0.ko":"河邊有一間小咖啡店。","p39/quiz.0.why":"就在河的旁邊,所以用 by。","p39/quiz.1.ko":"她坐在火堆旁取暖。","p39/quiz.1.why":"就在火的旁邊,所以用 by。","p39/quiz.2.ko":"鑰匙在包包裡面。","p39/quiz.2.why":"放在包包裡面,所以用 in。","p40/title":"方式","p40/why":"「經由」旁邊前往目的地的畫面。by bus(經由公車)、by email(經由電子郵件)、by card、by hand(用手親自)。交通 · 通訊 · 付款方式,不加冠詞,用 by + 名詞。","p40/examples.0.ko":"我搭地鐵上班。","p40/examples.1.ko":"請用電子郵件寄給我。","p40/examples.2.ko":"可以刷卡嗎?","p40/examples.3.ko":"這件毛衣是手工做的。","p40/compare":"by car(搭車)· in my car(坐我的車),by bus(搭公車)· on the bus(在公車上)。加上 my · the 時,就用 in · on 取代 by。走路是 on foot。","p40/quiz.0.ko":"我們搭火車旅行。","p40/quiz.0.why":"交通方式用 by + 不加冠詞的名詞。","p40/quiz.1.ko":"我是走路來這裡的。","p40/quiz.1.why":"走路是 on foot。","p40/quiz.2.ko":"她坐我的車去機場。","p40/quiz.2.why":"加了 my 就用 in,不用 by。","p41/title":"做的人","p41/why":"被動語態裡,「做這件事的人」站在那件事旁邊的畫面。The logo was designed by Mina.(這個標誌是 Mina 設計的)。就像在作品旁簽上名字一樣,把名字接在後面。作品 · 歌曲 · 發明 · 天氣等原因也可以用。","p41/examples.0.ko":"這個標誌是 Mina 設計的。","p41/examples.1.ko":"窗戶被風吹破了。","p41/examples.2.ko":"這首歌是我最喜歡的歌手寫的。","p41/examples.3.ko":"我們被那個消息嚇到了。","p41/compare":"by + 做的人(by Mina),with + 用的工具(with a pen)。The letter was written by Mina with a red pen. Day 47 會把它們放在一起比較。","p41/quiz.0.ko":"這幅畫是我爺爺畫的。","p41/quiz.0.why":"畫的人用 by。","p41/quiz.1.ko":"那個蛋糕是 Noah 做的。","p41/quiz.1.why":"做的人用 by。","p41/quiz.2.ko":"他用鉛筆寫了信。","p41/quiz.2.why":"手上拿的工具用 with。","p42/title":"期限","p42/why":"沿著時間走,走到某個「時間點」旁邊的畫面。by Friday 是「走到星期五旁邊」= 最晚到星期五。在那之前任何時候都可以。容易和 until(一直持續到那時)搞混。","p42/examples.0.ko":"請最晚星期五前寄給我。","p42/examples.1.ko":"我 7 點前會到家。","p42/examples.2.ko":"我們到的時候,電影已經開始了。","p42/examples.3.ko":"我需要你明天之前回覆。","p42/compare":"by Friday 是「最晚星期五前做一次」(截止),until Friday 是「一直持續到星期五」。I'll finish it by Friday. / I'll stay here until Friday.(97 課會再看到)","p42/quiz.0.ko":"這本書最晚星期一要還。","p42/quiz.0.why":"是截止期限,所以用 by。","p42/quiz.1.ko":"我會在這裡等到你回來。","p42/quiz.1.why":"是一直等到那時候,所以用 until。","p42/quiz.2.ko":"請在下午 5 點前完成報告。","p42/quiz.2.why":"是截止時間,所以用 by。","p43/title":"差距 · 單位","p43/why":"把兩個東西並排放在身旁,量出「差了多少」的畫面。up by 10%(上漲了 10%)、win by two points(以 2 分之差獲勝)。一個一個挨著算,就成了單位:by the hour(按小時)、one by one(一個一個)、day by day(一天一天)。","p43/examples.0.ko":"價格上漲了 10%。","p43/examples.1.ko":"我們以 2 分之差獲勝。","p43/examples.2.ko":"我是領時薪的。","p43/examples.3.ko":"他們一個一個走進來。","p43/compare":"「貴 2 美元」可以說 2 dollars more expensive,也可以說 more expensive by 2 dollars。把差距單獨拿出來說時,就加 by。","p43/quiz.0.ko":"價格下跌了 20%。","p43/quiz.0.why":"差距的大小用 by。","p43/quiz.1.ko":"她差一分鐘沒趕上公車。","p43/quiz.1.why":"差多少用 by。","p43/quiz.2.ko":"我用 20 美元買了那個。","p43/quiz.2.why":"交換的價錢用 for(for ④)。","p44/title":"主題","p44/why":"話題繞著某件事打轉的畫面。talk about work(聊工作)、a movie about love(關於愛情的電影)、worry about(擔心~)。比 on(on ④)更輕鬆、更廣泛,有「東聊西聊」的感覺。","p44/examples.0.ko":"你在說什麼?","p44/examples.1.ko":"這是一部關於兩姊妹的電影。","p44/examples.2.ko":"不用擔心我。","p44/examples.3.ko":"喝杯咖啡怎麼樣?","p44/compare":"How about…?(~如何?)和 What about…?(那~呢?)後面接名詞或 -ing。How about going out?","p44/quiz.0.ko":"我們得談談我們的計畫。","p44/quiz.0.why":"話題的主題用 about。","p44/quiz.1.ko":"我很擔心考試。","p44/quiz.1.why":"擔心的對象用 worried about。","p44/quiz.2.ko":"我在等公車。","p44/quiz.2.why":"期盼它來而等待,用 wait for(for ①)。","p45/title":"周圍 · 關於","p45/why":"圍繞在人或東西「周圍」的某種東西。There's something about her.(她身上有種特別的東西)、What I like about him is…(我喜歡他的地方是…)。英式英語裡「到處」(walk about)也用 about,但美式英語這個意思用 around(會在 around ② 再看到)。","p45/examples.0.ko":"這座城市有種特別的味道。","p45/examples.1.ko":"我喜歡她的地方是她的笑聲。","p45/examples.2.ko":"他有點奇怪。","p45/examples.3.ko":"我工作最棒的地方是那些人。","p45/compare":"There's something about him. 的意思是「他身上有種說不上來的東西」,常用來形容魅力或可疑之處。","p45/quiz.0.ko":"你最喜歡紐約的哪一點?","p45/quiz.0.why":"它身上的優點用 about。","p45/quiz.1.ko":"你今天看起來有點不一樣。","p45/quiz.1.why":"圍繞在人身上的某種東西,用 about。","p45/quiz.2.ko":"我的手機怎麼了?打不開。","p45/quiz.2.why":"出問題的對象用 What's wrong with…?。","p46/title":"大約 · 正要","p46/why":"繞著數字「周圍」打轉的畫面。about 10 people(大約 10 個人)、about 3 o'clock(3 點左右)。站在事情開始點的正周圍,就是 be about to(正要~)。","p46/examples.0.ko":"那裡大約有 50 個人。","p46/examples.1.ko":"大約要 10 分鐘。","p46/examples.2.ko":"我正要打給你!","p46/examples.3.ko":"電影快要開始了。","p46/compare":"表示「大約」的 about,美式口語也常用 around。be about to + 原形是「正要~」,指非常近的未來。","p46/quiz.0.ko":"大約 30 美元。","p46/quiz.0.why":"繞著數字的「大約」用 about。","p46/quiz.1.ko":"快點!火車快開了。","p46/quiz.1.why":"正要~是 be about to。","p46/quiz.2.ko":"會議下午 3 點整開始。","p46/quiz.2.why":"「剛好」那個時刻用 at(at ②)。","p47/why":"with 是手裡握著的「工具」,by 是經由的「方法 · 方式」,以及做事的「人」。cut it with a knife(用刀)/ send it by email(用電子郵件)/ drawn by Mina(Mina 畫的)/ drawn with a pencil(用鉛筆畫的)。搞不清楚時,問自己「是手裡握著的嗎?」(with)、「是方法或做事的人嗎?」(by)。","p47/examples.0.ko":"那張素描是 Mina 用鉛筆畫的。","p47/examples.1.ko":"我刷卡付了錢。","p47/examples.2.ko":"他用硬幣把它打開了。","p47/examples.3.ko":"她用電子郵件寄了檔案,還附上一則簡短的留言。","p47/compare":"by hand(用手親自 = 不用機器)是方法,所以用 by;with my hands(用我的雙手)像工具一樣,所以用 with。","p47/quiz.0.ko":"這本書是一位知名作家寫的。","p47/quiz.0.why":"寫的人用 by。","p47/quiz.1.ko":"他用鎚子把椅子修好了。","p47/quiz.1.why":"手裡握著的工具用 with。","p47/quiz.2.ko":"我們搭計程車去吧。","p47/quiz.2.why":"交通方式用 by。","p48/title":"覆蓋 · 越過","p48/why":"在某物上方覆蓋或越過的弧線。a bridge over the river(橫跨河上的橋)、jump over the fence(跳過圍欄)、put a blanket over her(把毯子蓋在她身上)、trip over(絆倒)。和 on 不同,不必接觸,是從上面「覆蓋著、越過去」的感覺。","p48/examples.0.ko":"河上有一座橋。","p48/examples.1.ko":"貓跳過了圍欄。","p48/examples.2.ko":"她把毯子蓋在寶寶身上。","p48/examples.3.ko":"飛機飛過了我家上空。","p48/compare":"over 是覆蓋或越過上方,above 只是在更高、有一段距離的地方(會在 above · below 再看到)。","p48/quiz.0.ko":"他跳過了水坑。","p48/quiz.0.why":"從上方越過去,所以用 over。","p48/quiz.1.ko":"餐桌上方掛著一盞燈。","p48/quiz.1.why":"沒有接觸,像覆蓋在上方般懸掛,所以用 over。","p48/quiz.2.ko":"狗躲在床底下。","p48/quiz.2.why":"下面用 under。","p49/title":"超過的數量","p49/why":"在基準線上方畫出弧線「越過去」的畫面。over 100 people(超過 100 人)、over 18(18 歲以上)、over budget(超出預算)。意思和 more than 相同,口語中很常用。","p49/examples.0.ko":"有 200 多人來參加派對。","p49/examples.1.ko":"這部電影是給 18 歲以上的人看的。","p49/examples.2.ko":"那支影片的觀看次數超過 100 萬。","p49/examples.3.ko":"我等了一個多小時。","p49/compare":"相反的是 under(under 18,under ②)。about 是「大約」,可能超過也可能不足。","p49/quiz.0.ko":"有超過 1,000 人報名。","p49/quiz.0.why":"超過的數量用 over。","p49/quiz.1.ko":"12 歲以下的兒童不能看這個。","p49/quiz.1.why":"未滿用 under。","p49/quiz.2.ko":"花了三個多小時。","p49/quiz.2.why":"超過的數量用 over。","p50/title":"結束 · 重來","p50/why":"弧線一路越到最後、「碰到另一邊」的畫面。The game is over.(比賽結束了)— 從頭到尾都越過去了。走到盡頭後再越回來從頭開始,就是「重來」:do it over(重做)、start over(從頭開始)。","p50/examples.0.ko":"派對結束了。","p50/examples.1.ko":"會議已經結束了嗎?","p50/examples.2.ko":"我搞砸了,只好從頭再來。","p50/examples.3.ko":"我們之間結束了。","p50/compare":"over and over (again) 是「一再重複」。I watched it over and over.","p50/quiz.0.ko":"暑假結束了。要回學校囉!","p50/quiz.0.why":"一路越到最後,所以用 over。","p50/quiz.1.ko":"這篇文章一團糟。我得重新寫一遍。","p50/quiz.1.why":"從頭重來是 start over。","p50/quiz.2.ko":"暴風雨時燈熄了。","p50/quiz.2.why":"燈熄滅消失是 go out(out ②)。","p51/title":"在…期間","p51/why":"「橫跨」在時間或某件事上方覆蓋著的畫面。over dinner(吃晚餐時)、over the weekend(整個週末)、over the past year(過去一年間)。談話或變化覆蓋整段時間持續下去。","p51/examples.0.ko":"我們吃晚餐時聊這件事吧。","p51/examples.1.ko":"週末你做了什麼?","p51/examples.2.ko":"過去一年物價上漲了。","p51/examples.3.ko":"我們一邊喝咖啡一邊討論計畫。","p51/compare":"over dinner 是「邊吃晚餐邊」聊天的感覺,during dinner 是「晚餐時間當中的某個時候」的感覺。","p51/quiz.0.ko":"我們吃午餐時聊那件事吧。","p51/quiz.0.why":"邊用餐邊做某事,用 over。","p51/quiz.1.ko":"過去三個月銷售額增加了。","p51/quiz.1.why":"是橫跨整段期間的變化,所以用 over。","p51/quiz.2.ko":"我從 2020 年起就住在這裡。","p51/quiz.2.why":"起點用 since。","p52/title":"掌控","p52/why":"從上方「覆蓋、俯視」某物的畫面。control over(對~的掌控)、power over(支配~的力量)、the final say over(對~的最終決定權)。從上面覆蓋住,就能操控底下的東西。","p52/examples.0.ko":"預算全由她掌控。","p52/examples.1.ko":"國王擁有統治整個國家的權力。","p52/examples.2.ko":"天氣不是我們能控制的。","p52/examples.3.ko":"她的笑容擄獲了每個人的心。","p52/compare":"control over 和 control of 都可以用。take over(接管,片語動詞第 36 個)也是同一個畫面。","p52/quiz.0.ko":"父母管理孩子的螢幕時間。","p52/quiz.0.why":"從上方俯視、握在手裡,所以是 control over。","p52/quiz.1.ko":"新經理擁有聘用的決定權。","p52/quiz.1.why":"統治某事物的力量是 power over。","p52/quiz.2.ko":"別擔心。專案現在已經在掌控中了。","p52/quiz.2.why":"在控制「之下」,所以是 under control(under ③)。","p53/title":"下面","p53/why":"就在某物正下方、被它覆蓋著的地方。under the table(桌子底下)、under the bed(床底下)、under the bridge(橋下)。帶有上方有東西覆蓋著的感覺。","p53/examples.0.ko":"貓躲在床底下。","p53/examples.1.ko":"我在沙發底下找到一些舊照片。","p53/examples.2.ko":"我們在這棵樹下等到雨停吧。","p53/examples.3.ko":"她在外套裡面穿了一件毛衣。","p53/compare":"under 是就在正下方、被覆蓋著,below 是有一段距離的下方(Day 56 的 above · below 會再看到)。","p53/quiz.0.ko":"我的鞋子在床底下。","p53/quiz.0.why":"就在床的正下方,所以用 under。","p53/quiz.1.ko":"飛機飛過城市上空。","p53/quiz.1.why":"從上方越過去,所以用 over。","p53/quiz.2.ko":"請把花瓶放在桌上。","p53/quiz.2.why":"放在桌面上、碰到桌面,所以用 on。","p54/title":"未滿","p54/why":"在基準線「下面」的畫面。under 18(未滿 18 歲)、under $10(不到 10 美元)、under an hour(不到一小時)。是 over ② 的相反。","p54/examples.0.ko":"12 歲以下的兒童免費。","p54/examples.1.ko":"我找到一間月租不到 2 千美元的房子。","p54/examples.2.ko":"走到那裡不用 10 分鐘。","p54/examples.3.ko":"這家店的東西全都不到 5 美元。","p54/compare":"講年齡時,under 18 是「未滿 18 歲」。講價格 · 時間時,是「在~以內、不到~」的用法。相反的是 over(over ②)。","p54/quiz.0.ko":"在美國,未滿 21 歲不能買酒。","p54/quiz.0.why":"未滿用 under。","p54/quiz.1.ko":"這趟旅程花了兩個多小時。","p54/quiz.1.why":"超過的數量用 over。","p54/quiz.2.ko":"有沒有一晚不到 100 美元的好旅館?","p54/quiz.2.why":"低於那個金額用 under。","p55/title":"受影響 · 進行中","p55/why":"被沉重的力量或事情壓在「下面」的畫面。under pressure(承受壓力)、under stress、under construction(施工中)、under control(在掌控中)。是那股力量從上方覆蓋著。","p55/examples.0.ko":"我在有壓力的時候工作表現很好。","p55/examples.1.ko":"新橋正在施工。","p55/examples.2.ko":"別擔心。一切都在掌控中。","p55/examples.3.ko":"她最近壓力很大。","p55/compare":"under construction(施工中)· under repair(維修中)· under discussion(討論中)這類用法,表示「正在~中」。","p55/quiz.0.ko":"那條路在維修。走別條路吧。","p55/quiz.0.why":"維修中是 under repair。","p55/quiz.1.ko":"他在公司承受很大的壓力。","p55/quiz.1.why":"被壓力壓在下面,所以用 under。","p55/quiz.2.ko":"我們有麻煩了!","p55/quiz.2.why":"陷入困境的狀態是 in trouble(in ④)。","p56/why":"above 是沒有接觸、有一段距離的「上方」,below 是有一段距離的「下方」。over · under 是正上方 · 正下方覆蓋或經過的畫面,above · below 則只說高度的差別。the apartment above mine(我家樓上那戶)、ten degrees below zero(零下 10 度)、above average(高於平均)。","p56/examples.0.ko":"Jake 和 Rosa 住在我家樓下。","p56/examples.1.ko":"畫掛在沙發上方。","p56/examples.2.ko":"今天零下 10 度。","p56/examples.3.ko":"她的成績高於平均。","p56/compare":"像溫度 · 平均 · 樓層 · 海拔這種在「刻度」上說高低時,用 above · below。above sea level(海拔)。","p56/quiz.0.ko":"昨晚氣溫降到零度以下。","p56/quiz.0.why":"刻度上 0 以下用 below。","p56/quiz.1.ko":"我的辦公室在咖啡廳樓上。","p56/quiz.1.why":"有一段距離的樓上用 above。","p56/quiz.2.ko":"她翻過了圍牆。","p56/quiz.2.why":"從上方越過的動作用 over。","p57/title":"穿過","p57/why":"進到裡面、再從另一邊穿出去的畫面。walk through the park(穿過公園)、drive through a tunnel(開車穿過隧道)、look through the window(透過窗戶看)。和 across(橫越表面)不同,through 是從「裡面」穿過去。","p57/examples.0.ko":"我們走過公園。","p57/examples.1.ko":"火車穿過了一條長長的隧道。","p57/examples.2.ko":"你能把這個箱子搬過門嗎?","p57/examples.3.ko":"我從窗戶往外看。","p57/compare":"through 是從裡面穿過(through the forest),across 是橫越表面(across the street)。","p57/quiz.0.ko":"河流穿過整座城市。","p57/quiz.0.why":"從城市裡面穿過,所以用 through。","p57/quiz.1.ko":"我們過馬路吧。","p57/quiz.1.why":"橫越路面,所以用 across。","p57/quiz.2.ko":"光從窗戶照進來。","p57/quiz.2.why":"穿透窗戶進來,所以用 through。","p58/title":"從頭到尾","p58/why":"把時間當成隧道,從頭到尾穿過去的畫面。all through the night(整夜)、through the winter(整個冬天)。美式英語的 Monday through Friday 是「星期一到星期五(含星期五)」。","p58/examples.0.ko":"寶寶整晚都在哭。","p58/examples.1.ko":"那家店星期一到星期五營業。","p58/examples.2.ko":"我整部電影都在睡覺。","p58/examples.3.ko":"她連午餐都沒吃,一直工作。","p58/compare":"Monday through Friday(含星期五,美式)· from Monday to Friday(to ③)。在美國,through 明確包含最後一天。","p58/quiz.0.ko":"博物館星期二到星期日開放。","p58/quiz.0.why":"從頭到尾(含結尾)用 through。","p58/quiz.1.ko":"他整部電影都在睡覺。","p58/quiz.1.why":"是電影從頭到尾,所以用 through。","p58/quiz.2.ko":"我星期一到星期五都會在這裡。","p58/quiz.2.why":"是 from A to B(to ③)。","p59/title":"經由","p59/why":"把某樣東西當成「通道」穿過去的畫面。I got the job through a friend(我透過朋友找到工作)、learn through practice(透過練習學習)。經由人 · 方法 · 經驗而得到結果。","p59/examples.0.ko":"我透過朋友認識了那隻小貓。","p59/examples.1.ko":"我們是因為工作而認識的。","p59/examples.2.ko":"語言要透過練習來學。","p59/examples.3.ko":"我是從 Jake 那裡聽到那個消息的。","p59/compare":"through a friend 是經過朋友這個人 · 這個過程,by email 是電子郵件這個手段。經過人 · 過程用 through,像工具一樣的手段用 by。","p59/quiz.0.ko":"我是透過表哥找到這份工作的。","p59/quiz.0.why":"經由某個人,用 through。","p59/quiz.1.ko":"請用電子郵件寄給我。","p59/quiz.1.why":"通訊方式用 by。","p59/quiz.2.ko":"她用刀子打開了箱子。","p59/quiz.2.why":"手上拿的工具用 with。","p60/title":"橫越","p60/why":"像道路 · 河流 · 橋這類平面,從這一側橫越到另一側的畫面。walk across the street(走過馬路)、swim across the river(游過河)、walk across the bridge(走過橋)。和 through(從裡面穿過)不同,across 是穿越「表面上」。","p60/examples.0.ko":"我們走過橋吧。","p60/examples.1.ko":"過馬路要小心。","p60/examples.2.ko":"他游過了河。","p60/examples.3.ko":"一隻貓跑過馬路。","p60/compare":"across 是橫越表面(across the field),through 是從裡面穿過(through the forest),over 是從上方越過(over the wall)。","p60/quiz.0.ko":"我們過馬路吧。","p60/quiz.0.why":"橫越路面,所以用 across。","p60/quiz.1.ko":"火車穿過了隧道。","p60/quiz.1.why":"從隧道裡面穿過,所以用 through。","p60/quiz.2.ko":"馬跳過了圍欄。","p60/quiz.2.why":"從上方越過,所以用 over。","p61/title":"對面 · 到處","p61/why":"在橫越之後的「另一端」就是對面。the café across the street(對街的咖啡廳)、live across the hall(住在走廊對面)。橫越擴大到整個寬闊的面,就是「到處」:across the country(全國各地)、across the world(全世界)。","p61/examples.0.ko":"對街有一家寵物店。","p61/examples.1.ko":"走廊對面的鄰居是飛行員。","p61/examples.2.ko":"那家公司在全國各地都有辦公室。","p61/examples.3.ko":"全世界的人都喜歡這首歌。","p61/compare":"美式英語也常用 across from(在~的對面)。The bank is across from the park.","p61/quiz.0.ko":"銀行在對街。","p61/quiz.0.why":"是橫越馬路後的對面,所以用 across。","p61/quiz.1.ko":"那個消息傳遍了全國。","p61/quiz.1.why":"擴散到整個寬闊的面,所以用 across。","p61/quiz.2.ko":"我們沿著海灘散步。","p61/quiz.2.why":"順著長長的海灘走,所以用 along。","p62/title":"沿著","p62/why":"順著道路 · 河流 · 海灘這類長長的東西,並排前進的畫面。walk along the river(沿著河邊走)、trees along the street(沿街的樹)。方向和 across 不同:across 是橫著越過去,along 是順著長度走。","p62/examples.0.ko":"我們沿著河邊走吧。","p62/examples.1.ko":"沿著街道有一排樹。","p62/examples.2.ko":"沿著這條路走兩個街區。","p62/examples.3.ko":"我們沿著海灘騎腳踏車。","p62/compare":"across the river 是渡河(橫向),along the river 是沿著河走(順著長度的方向)。","p62/quiz.0.ko":"黃昏時我沿著海灘散步。","p62/quiz.0.why":"順著海灘走,所以用 along。","p62/quiz.1.ko":"我們游到河的對岸吧。","p62/quiz.1.why":"橫向渡過河,所以用 across。","p62/quiz.2.ko":"那條路穿過森林。","p62/quiz.2.why":"從森林裡面穿過,所以用 through。","p63/title":"一起 · 進展","p63/why":"在某人「身旁並肩」一起前進的畫面。come along(一起去)、bring along(帶著去)、get along(相處融洽,片語動詞第 40 個)、sing along(跟著唱)。事情往前進展也是 along:How's it coming along?(進展得怎麼樣?)","p63/examples.0.ko":"我們要去公園,你要一起來嗎?","p63/examples.1.ko":"也把你妹妹帶來吧!","p63/examples.2.ko":"大家都跟著一起唱。","p63/examples.3.ko":"專案進展得如何?","p63/compare":"along with(和~一起)也很常用。She came along with her mom.","p63/quiz.0.ko":"我也可以一起去嗎?","p63/quiz.0.why":"在身旁一起去,所以用 along。","p63/quiz.1.ko":"你的韓語學得怎麼樣了?","p63/quiz.1.why":"事情在往前進展,所以是 coming along。","p63/quiz.2.ko":"我們在附近繞一圈吧。","p63/quiz.2.why":"轉一整圈,所以用 around。","p64/title":"周圍","p64/why":"以某物為中心,「圍成一圈」的畫面。sit around the table(圍著桌子坐)、a fence around the garden(圍著花園的籬笆)、around the corner(轉個彎就到)。地球繞著太陽轉也是 around。","p64/examples.0.ko":"我們圍著桌子聊天。","p64/examples.1.ko":"花園四周圍著籬笆。","p64/examples.2.ko":"咖啡廳轉個彎就到。","p64/examples.3.ko":"地球繞著太陽轉。","p64/compare":"around the corner 既是「轉個彎就到」的位置,也可以表示「(時間)就在眼前」。Summer is just around the corner.","p64/quiz.0.ko":"孩子們繞著樹跳舞。","p64/quiz.0.why":"圍著周圍轉一圈,所以用 around。","p64/quiz.1.ko":"轉個彎就有一間藥局。","p64/quiz.1.why":"轉個彎就到是 around the corner。","p64/quiz.2.ko":"沿著河走,直到看見橋。","p64/quiz.2.why":"順著河走,所以用 along。","p65/title":"到處","p65/why":"在各處「繞來繞去」的畫面。travel around Europe(在歐洲各地旅行)、show someone around(帶人四處參觀)、look around(四處看看,片語動詞第 54 個)。美式英語裡「到處」用 around 而不是 about(與 about ② 比較)。","p65/examples.0.ko":"我想到歐洲各地旅行。","p65/examples.1.ko":"我帶你逛逛這座城市。","p65/examples.2.ko":"孩子們在公園裡到處跑。","p65/examples.3.ko":"這附近有不錯的麵包店嗎?","p65/compare":"around here 是「這附近」。Is there a bank around here?(這附近有銀行嗎?)","p65/quiz.0.ko":"我帶你參觀辦公室。","p65/quiz.0.why":"帶人四處參觀是 show around。","p65/quiz.1.ko":"這附近有加油站嗎?","p65/quiz.1.why":"這附近是 around here。","p65/quiz.2.ko":"我們開車過了橋。","p65/quiz.2.why":"橫越橋面過去,所以用 across。","p66/title":"大約","p66/why":"在數字「附近繞來繞去」的畫面。around 10 o'clock(10 點左右)、around 30 people(約 30 個人)。美式口語中,和 about ③ 的意思相同,非常常用。","p66/examples.0.ko":"她的班機晚上 10 點左右抵達。","p66/examples.1.ko":"大約 50 美元。","p66/examples.2.ko":"婚禮上來了大約 100 個人。","p66/examples.3.ko":"我中午左右到。","p66/compare":"around 7 = about 7(7 點左右)。at 7 是「剛好 7 點」(at ②)。","p66/quiz.0.ko":"6 點左右見吧,我可能會晚一點。","p66/quiz.0.why":"不精確的「左右」用 around。","p66/quiz.1.ko":"電影 7 點 30 分整開始。","p66/quiz.1.why":"剛好那個時刻用 at。","p66/quiz.2.ko":"這趟旅行要花大約 500 美元。","p66/quiz.2.why":"大約的金額用 around。","p67/title":"向上","p67/why":"由下往上的箭頭。stand up(站起來)、go up the stairs(上樓梯)、look up(往上看)、pick up(拿起來,片語動詞第 1 個)。身體或東西往高處移動。","p67/examples.0.ko":"請站起來。","p67/examples.1.ko":"你能幫我把這個行李箱拿上樓嗎?","p67/examples.2.ko":"看上面!是流星!","p67/examples.3.ko":"她把小貓抱了起來。","p67/compare":"up the stairs(上樓梯)↔ down the stairs(下樓梯)。up 和 down 要一起成對記(會在 down ① 再看到)。","p67/quiz.0.ko":"老師一進來,大家都站了起來。","p67/quiz.0.why":"身體往上起來,所以用 up。","p67/quiz.1.ko":"上樓梯後往左走。","p67/quiz.1.why":"往樓梯上方走,所以用 up。","p67/quiz.2.ko":"請坐。","p67/quiz.2.why":"身體往下放,所以用 down。","p68/title":"增加","p68/why":"刻度往上「升高」的畫面。聲音 · 價格 · 溫度升高就是增加。turn up the music(把音樂調大聲)、prices go up(物價上漲)、speak up(說大聲一點)、hurry up(快點 = 把速度提上去)、cheer up(打起精神,片語動詞第 22 個)。","p68/examples.0.ko":"可以把暖氣調高嗎?我好冷。","p68/examples.1.ko":"今年房租又漲了。","p68/examples.2.ko":"請說大聲一點。我聽不到。","p68/examples.3.ko":"快點!你要遲到了。","p68/compare":"go up(上升)↔ go down(下降),turn up(調大)↔ turn down(調小)。","p68/quiz.0.ko":"夏天物價總是會上漲。","p68/quiz.0.why":"價格升高,所以用 up。","p68/quiz.1.ko":"太吵了。把音量調小。","p68/quiz.1.why":"把聲音降低是 down。","p68/quiz.2.ko":"請大聲說。後面的人說聽不到。","p68/quiz.2.why":"把聲音提高是 speak up。","p69/title":"徹底做完","p69/why":"容器「滿到頂端」的畫面。一直滿到最上面就是完成了。eat up(吃光)、drink up(喝光)、use up(用完)、fill up(裝滿)、clean up(打掃乾淨)、give up(放棄,片語動詞第 13 個)。","p69/examples.0.ko":"吃光它!還有呢。","p69/examples.1.ko":"貓飼料用完了。","p69/examples.2.ko":"我們把廚房打掃乾淨吧。","p69/examples.3.ko":"請幫我加滿。","p69/compare":"eat(吃)和 eat up(一點不剩全吃完),use(用)和 use up(全部用光)。加上 up 就多了「徹底」的感覺。","p69/quiz.0.ko":"喝完它。我們該走了。","p69/quiz.0.why":"一路喝到底,所以用 up。","p69/quiz.1.ko":"我把紙用完了。","p69/quiz.1.why":"全部用光是 use up。","p69/quiz.2.ko":"牛奶喝完了。","p69/quiz.2.why":"用完、沒有了是 run out of(out ②)。","p70/title":"靠近 · 出現","p70/why":"從視野下方「浮上來、出現」的畫面。show up(出現,片語動詞第 6 個)、come up(冒出來 · 想到)、turn up(突然出現)、pop up(突然彈出)。原本看不見的東西靠近,出現在眼前。","p70/examples.0.ko":"她遲到了一個小時才出現。","p70/examples.1.ko":"螢幕上突然跳出一則訊息。","p70/examples.2.ko":"弄丟的鑰匙在外套口袋裡冒出來了。","p70/examples.3.ko":"一隻狗走過來,然後坐下。","p70/compare":"像 come up to(走向~)這樣向人靠近時,也是 up。catch up(趕上)也是同一個畫面。","p70/quiz.0.ko":"開會時沒有半個人出現。","p70/quiz.0.why":"出現是 show up。","p70/quiz.1.ko":"手機上突然跳出一則廣告。","p70/quiz.1.why":"突然彈出來看見,所以用 pop up。","p70/quiz.2.ko":"你能查一下那家店幾點開門嗎?","p70/quiz.2.why":"查出來是 find out(out ④)。","p71/title":"向下","p71/why":"由上往下的箭頭。sit down(坐下,片語動詞第 67 個)、go down the stairs(下樓梯)、look down(往下看)、put it down(放下)。和 up ① 方向正好相反。","p71/examples.0.ko":"看下面!城市看起來好小。","p71/examples.1.ko":"把手機放下吧。","p71/examples.2.ko":"她走下樓梯。","p71/examples.3.ko":"太陽 7 點下山了。","p71/compare":"up the hill(上山坡)↔ down the hill(下山坡)。down the street 也可以表示「沿著街走過去」:The café is just down the street.(咖啡廳沿著這條街走一小段就到了)","p71/quiz.0.ko":"不要往下看!繼續往上爬。","p71/quiz.0.why":"往下俯視,所以用 down。","p71/quiz.1.ko":"他把箱子放在地上。","p71/quiz.1.why":"往下放,所以用 down。","p71/quiz.2.ko":"這部電梯是往上嗎?我們要去 10 樓。","p71/quiz.2.why":"往上層走,所以用 up(up ①)。","p72/title":"減少 · 減弱","p72/why":"刻度往下降的畫面。數量 · 聲音 · 速度 · 情緒往下降,就是「減少 · 減弱」。turn down(調小聲,片語動詞第 30 個)、slow down(減速,第 62 個)、calm down(冷靜下來,第 8 個)。","p72/examples.0.ko":"用戶減少了 40%。","p72/examples.1.ko":"可以把音樂調小聲一點嗎?","p72/examples.2.ko":"小聲一點。寶寶在睡覺。","p72/examples.3.ko":"雨終於漸漸小了。","p72/compare":"turn up(增加,up ②)↔ turn down(減少)。Prices went up.(物價上漲了)/ Prices went down.(物價下跌了)","p72/quiz.0.ko":"這個月的銷售額減少了 10%。","p72/quiz.0.why":"數字減少了,所以用 down。","p72/quiz.1.ko":"把電視聲音調小一點。太吵了。","p72/quiz.1.why":"把聲音降低,所以用 down。","p72/quiz.2.ko":"物價又漲了。什麼都太貴了!","p72/quiz.2.why":"價格上漲,所以用 up(up ②)。","p73/title":"寫下 · 定案","p73/why":"往下壓住、讓它不能動的畫面。把話記在紙上固定下來就是 write down(寫下來),把計畫牢牢釘住就是 nail down(敲定),四處漂泊的人安頓下來就是 settle down(定居,片語動詞第 50 個)。是不讓東西飄走、把它抓牢的 down。","p73/examples.0.ko":"我可以把這個寫下來嗎?","p73/examples.1.ko":"我來記一下你的電話號碼。","p73/examples.2.ko":"我們今天把細節敲定吧。","p73/examples.3.ko":"把帳篷綁緊。風很大。","p73/compare":"write down(寫在紙上定下來)↔ write up(把報告整份寫完,up ③ 徹底做完)。開會中用 write down,開會後用 write up。","p73/quiz.0.ko":"請在這裡寫下你的名字。","p73/quiz.0.why":"寫在紙上記下來,所以用 down。","p73/quiz.1.ko":"我們得把開會日期定下來。","p73/quiz.1.why":"把日期釘住固定,所以是 pin down。","p73/quiz.2.ko":"他終於在一個小鎮定居了。","p73/quiz.2.why":"安頓下來,所以是 settle down。","p74/title":"向外","p74/why":"從框框裡面往外走出去的箭頭。go out(出門,片語動詞第 68 個)、get out(出去)、take out the trash(把垃圾拿出去)、look out the window(看窗外)。是 in ① 的相反。","p74/examples.0.ko":"我每天早上都出去散步。","p74/examples.1.ko":"你可以把垃圾拿出去嗎?","p74/examples.2.ko":"她往窗外看。","p74/examples.3.ko":"今天晚餐我們去外面吃吧。","p74/compare":"come in(進來)↔ go out(出去)。eat in(在家吃)↔ eat out(外食)。接上地點時用 out of:Get out of the car.(下車)","p74/quiz.0.ko":"今晚我們出去吃吧。我累得不想煮。","p74/quiz.0.why":"在外面吃,所以是 eat out。","p74/quiz.1.ko":"帶狗出去散步。","p74/quiz.1.why":"帶到屋外去,所以用 out。","p74/quiz.2.ko":"進來!門開著。","p74/quiz.2.why":"往裡面進來,所以用 in(in ①)。","p75/title":"消失 · 用完","p75/why":"裡面的東西全都跑出去、變得空空的畫面。run out of(用完,片語動詞第 61 個)、sold out(賣完)、The lights went out(燈熄了)、pass out(昏倒,第 49 個)。原本有的東西不見了。","p75/examples.0.ko":"印表機的墨水用完了。","p75/examples.1.ko":"抱歉,蛋糕賣完了。","p75/examples.2.ko":"剛剛燈熄了!","p75/examples.3.ko":"把蠟燭吹熄!","p75/compare":"The lights went out.(燈自己熄滅消失,out ②)/ Turn off the lights.(切斷開關,off ③)。自己熄滅多用 out,人去關則多用 off。","p75/quiz.0.ko":"牛奶喝完了。","p75/quiz.0.why":"全都跑光、用完了,所以是 run out of。","p75/quiz.1.ko":"演唱會門票 5 分鐘就賣完了。","p75/quiz.1.why":"全部賣光、沒有了,所以是 sold out。","p75/quiz.2.ko":"許個願,然後吹蠟燭。","p75/quiz.2.why":"一吹火焰就消失,所以是 blow out。","p76/title":"徹底 · 到底","p76/why":"把裡面的東西一點不剩、一路拿到底的畫面。work out(解決,片語動詞第 7 個)、figure out(弄清楚,第 12 個)、sort out(整理好,第 47 個)、hear me out(聽我說完)、worn out(累壞了)。從頭到尾一點都不漏掉。","p76/examples.0.ko":"請聽我把話說完。","p76/examples.1.ko":"我把十種方法全都試過了。","p76/examples.2.ko":"我累壞了。","p76/examples.3.ko":"請把這些文件填寫完整。","p76/compare":"fill in(在一個空格裡填上)↔ fill out(把整份表格全部填完)。美式英語填表格比較常用 fill out。","p76/quiz.0.ko":"不要打斷,把我的話聽完。","p76/quiz.0.why":"一路聽到底,所以是 hear out。","p76/quiz.1.ko":"長途旅行之後我累壞了。","p76/quiz.1.why":"力氣全部用光了,所以是 worn out。","p76/quiz.2.ko":"請填寫這份文件。","p76/quiz.2.why":"把整份文件全部填完,所以是 fill out。","p77/title":"顯露","p77/why":"原本被遮住的東西跑出來、被看見的畫面。find out(查出來,片語動詞第 3 個)、turn out(結果是~,第 27 個)、point out(指出,第 31 個)、The sun came out(太陽出來了)、The results came out(結果出來了)。","p77/examples.0.ko":"今天早上結果出來了。","p77/examples.1.ko":"雨停後太陽出來了。","p77/examples.2.ko":"消息一傳開,大家就都會知道。","p77/examples.3.ko":"她的新專輯下週發行。","p77/compare":"The sun came out.(從雲後露出來,out ④)/ The sun came up.(往上升起,up ④)/ The sun went down.(往下落,down ①)","p77/quiz.0.ko":"真相總會水落石出。","p77/quiz.0.why":"藏起來的東西跑出來被看見,所以是 come out。","p77/quiz.1.ko":"她的新書 5 月出版。","p77/quiz.1.why":"問世、被大家看到,所以是 come out。","p77/quiz.2.ko":"太陽下山了。天色漸漸變暗。","p77/quiz.2.why":"太陽往下落,所以用 down(down ①)。","p78/title":"脫離","p78/why":"原本貼在表面上的東西掉下來的畫面。take off(脫掉,片語動詞第 65 個)、get off(下車,第 66 個)、fall off(掉下來)、Keep off the grass(請勿踐踏草坪)。是 on ①(貼著)的相反。","p78/examples.0.ko":"請把鞋子脫掉。","p78/examples.1.ko":"外套的釦子掉了。","p78/examples.2.ko":"把手從我的年糕上拿開!","p78/examples.3.ko":"請勿踏入草坪。","p78/compare":"put on(穿上,on ①)↔ take off(脫掉)。get on the bus(上車)↔ get off the bus(下車)。on 和 off 要成對記。","p78/quiz.0.ko":"室內請把帽子脫掉。","p78/quiz.0.why":"從身上拿下來,所以用 off。","p78/quiz.1.ko":"貓從桌子上跳下來。","p78/quiz.1.why":"離開桌面,所以用 off。","p78/quiz.2.ko":"穿上外套。很冷。","p78/quiz.2.why":"穿在身上、貼著身體,所以用 on(on ①)。","p79/title":"離開","p79/why":"離開原本的位置、出發的畫面。I'm off(我走了)、set off(出發)、see someone off(送行)、run off(跑掉)、kick off(開始,片語動詞第 52 個)。身體離開了出發點。","p79/examples.0.ko":"我馬上要去咖啡廳。","p79/examples.1.ko":"我們一大早就出發了。","p79/examples.2.ko":"Kimchi 叼著我的襪子跑掉了!","p79/examples.3.ko":"媽媽來機場送我。","p79/compare":"see off(送要離開的人)↔ pick up(去接要來的人,片語動詞第 1 個)。在機場這兩個都很常用。","p79/quiz.0.ko":"好了,我走了。明天見!","p79/quiz.0.why":"離開這個地方,所以是 I'm off。","p79/quiz.1.ko":"他們一大早出發前往釜山。","p79/quiz.1.why":"踏上旅程,所以是 set off。","p79/quiz.2.ko":"朋友們到車站來送我。","p79/quiz.2.why":"為要離開的人送行,所以是 see off。","p80/title":"關掉 · 停止","p80/why":"電線從開關上脫開、電流中斷的畫面。turn off(關掉,片語動詞第 10 個)、The TV is off(電視是關的)、call off(取消)、The game is off(比賽取消了)。連結斷了就會停下來。是 on ⑤(運作 · 進行中)的相反。","p80/examples.0.ko":"他把螢幕關掉了。","p80/examples.1.ko":"烤箱關了嗎?","p80/examples.2.ko":"因為下雨,比賽取消了。","p80/examples.3.ko":"把手機關掉,好好想一想。","p80/compare":"The light is on.(亮著,on ⑤)↔ The light is off.(關著)。活動是 off,就表示「取消了」:The party is off.","p80/quiz.0.ko":"別忘了關燈。","p80/quiz.0.why":"切斷開關、關掉,所以用 off。","p80/quiz.1.ko":"因為下雨,野餐取消了。","p80/quiz.1.why":"活動中止、取消,所以用 off。","p80/quiz.2.ko":"電視開著嗎?我聽到有聲音。","p80/quiz.2.why":"在運作中,所以用 on(on ⑤)。","p81/title":"休息 · 減去","p81/why":"從工作或價格中被拿掉一部分的畫面。從工作中拿掉一天就是 a day off(休假日)· take tomorrow off(明天休息),從價格中拿掉就是 20% off(打八折),把債務全部卸掉就是 pay off(還清)。","p81/examples.0.ko":"明天休息吧。你需要休息。","p81/examples.1.ko":"我星期天休息。","p81/examples.2.ko":"今天全部商品七折。","p81/examples.3.ko":"可以便宜 10 美元嗎?","p81/compare":"off duty(不當班)↔ on duty(當班中)。護理師 Rosa 說「I'm off tonight.」,就是今晚休息的意思。","p81/quiz.0.ko":"我星期五休假。我們去爬山吧!","p81/quiz.0.why":"從工作中拿掉一天來休息,所以用 off。","p81/quiz.1.ko":"這雙鞋打五折。","p81/quiz.1.why":"從價格中扣掉,所以用 off。","p81/quiz.2.ko":"Rosa 今晚當班嗎?聽說她在醫院。","p81/quiz.2.why":"在上班中,所以是 on duty(on ⑤)。","p82/title":"進入","p82/why":"從外面越過界線、咻地進到裡面的箭頭。in 是「待在」裡面的狀態,into 是「進入」裡面的動作。walk into the kitchen(走進廚房)、pour into a bowl(倒進碗裡)、get into a car(上車)。","p82/examples.0.ko":"進廚房來。晚餐好了。","p82/examples.1.ko":"把湯倒進兩個碗裡。","p82/examples.2.ko":"Kimchi 跳進了箱子裡。","p82/examples.3.ko":"她上了計程車。","p82/compare":"The cat is in the box.(在裡面,in ①)/ The cat jumped into the box.(進到裡面)。看得到動作就用 into(99 課會再看到)。","p82/quiz.0.ko":"他走進房間坐下。","p82/quiz.0.why":"是走進房間裡的動作,所以用 into。","p82/quiz.1.ko":"把牛奶放回冰箱。","p82/quiz.1.why":"放進冰箱裡面,所以用 into。","p82/quiz.2.ko":"鑰匙在包包裡面。","p82/quiz.2.why":"沒有動作、只是在裡面的狀態,所以用 in(in ①)。","p83/title":"變成 · 迷上","p83/why":"進入另一種樣貌 · 狀態裡的畫面。進入新的樣貌就是「變成」:turn into(變成~,片語動詞第 33 個)、translate into English(翻成英文)。深深進入某件事就是「迷上」:be into(迷上~)、run into(撞上 · 偶然遇到,第 11 個)。","p83/examples.0.ko":"Noah 迷上了韓國料理。","p83/examples.1.ko":"雨變成了雪。","p83/examples.2.ko":"你可以把這個翻成英文嗎?","p83/examples.3.ko":"我在車站巧遇 Daniel。","p83/compare":"I like jazz.(喜歡)< I'm into jazz.(迷上了)。be into 很常用來說最近著迷的東西。","p83/quiz.0.ko":"我最近迷上了瑜伽。","p83/quiz.0.why":"深深迷上某件事,所以是 be into。","p83/quiz.1.ko":"毛毛蟲變成了蝴蝶。","p83/quiz.1.why":"變成另一種樣貌,所以是 turn into。","p83/quiz.2.ko":"孩子們在游泳池裡玩。","p83/quiz.2.why":"已經在裡面玩的狀態,所以用 in(in ①)。","p84/title":"遠離","p84/why":"從基準點漸漸遠離的箭頭。go away(走開)、run away(逃跑)、throw away(丟掉,片語動詞第 53 個)、far away(很遠)。和數字一起,也能表示「相距~」:two blocks away(相距兩個街區)。","p84/examples.0.ko":"首爾離這裡有 7 千英里遠。","p84/examples.1.ko":"把手機收起來。","p84/examples.2.ko":"不要走開!我還在說話。","p84/examples.3.ko":"咖啡廳只要走兩個街區。","p84/compare":"go away(走遠、離開)↔ come back(回到原來的位置,back ①)。put away(收起來)也是把東西從眼前移開的畫面。","p84/quiz.0.ko":"車站離這裡 10 分鐘路程。","p84/quiz.0.why":"是離這裡的距離,所以用 away。","p84/quiz.1.ko":"把玩具收起來。該睡覺了。","p84/quiz.1.why":"從眼前收走放好,所以是 put away。","p84/quiz.2.ko":"快回來!","p84/quiz.2.why":"回到原來的位置,所以用 back(back ①)。","p85/title":"消失","p85/why":"離得太遠、越變越小、最後看不見的畫面。The pain went away(疼痛消失了)、fade away(漸漸消逝)、melt away(融化消失)、give away(送給別人)。原本有的東西慢慢變得沒有了。","p85/examples.0.ko":"我的煩惱在這裡煙消雲散了。","p85/examples.1.ko":"太陽漸漸消失在樹後。","p85/examples.2.ko":"音樂漸漸變小,直到消失。","p85/examples.3.ko":"她把舊衣服全都送人了。","p85/compare":"go away 可以是人「走開」(away ①),也可以是疼痛 · 煩惱「消失」(away ②)。要看上下文來分辨。","p85/quiz.0.ko":"吃了這個藥,疼痛就會消失。","p85/quiz.0.why":"疼痛不見了,所以是 go away。","p85/quiz.1.ko":"他臉上的笑容漸漸消失了。","p85/quiz.1.why":"慢慢消失,所以是 fade away。","p85/quiz.2.ko":"咖啡廳免費送餅乾。","p85/quiz.2.why":"從我手上送給別人,所以是 give away。","p86/title":"回到原處","p86/why":"這個箭頭是沿著來時的路倒著走回去。come back(回來，第35個片語動詞)、get back(回來 · 拿回)、put it back(放回原位)、go back to sleep(再次入睡)。都是回到原本的地方 · 狀態。","p86/examples.0.ko":"如果我走了，我還能回來嗎？","p86/examples.1.ko":"把書放回書架上。","p86/examples.2.ko":"我再也睡不著了。","p86/examples.3.ko":"一切都恢復原樣了。","p86/compare":"go back(回到去過的地方) ↔ come back(回到這邊來)。回到說話者所在的地方，就用 come back。","p86/quiz.0.ko":"我十分鐘後回來。","p86/quiz.0.why":"是回到原本的地方，所以用 back。","p86/quiz.1.ko":"把牛奶放回冰箱。","p86/quiz.1.why":"是放回原本的位置，所以用 back。","p86/quiz.2.ko":"首爾離這裡很遠。","p86/quiz.2.why":"是離得很遠，所以用 away (away ①)。","p87/title":"回應對方","p87/why":"這個畫面是把收到的東西回送給對方。call back(回電話，第18個片語動詞)、write back(回信)、smile back(回以微笑)、pay back(還錢)、talk back(頂嘴)。就像傳球一樣，朝對方那邊回去。","p87/examples.0.ko":"我傳了訊息，但沒有回音。","p87/examples.1.ko":"她對我笑，所以我也對她笑了。","p87/examples.2.ko":"我明天還你。","p87/examples.3.ko":"不要頂嘴！","p87/compare":"我回到原處是 back ①(come back)，把東西還給對方則是 back ②(give back · write back)。","p87/quiz.0.ko":"我五分鐘後再打給你。","p87/quiz.0.why":"是回撥電話，所以用 call back。","p87/quiz.1.ko":"可以借我 20 美元嗎？我星期五還你。","p87/quiz.1.why":"是把借來的錢還給對方，所以用 pay back。","p87/quiz.2.ko":"他向我揮手，我也向他揮手。","p87/quiz.2.why":"是把收到的招呼回敬對方，所以用 back。","p88/title":"對抗","p88/why":"這個畫面是兩股力量從相反的方向對抗。be against(反對～)、fight against(對抗～而戰)、against the rules(違反規則)、play against(和～對戰)。反義詞是 for(贊成，for ⑤)。","p88/examples.0.ko":"Noah 反對我去首爾嗎？","p88/examples.1.ko":"你是贊成還是反對？","p88/examples.2.ko":"在這裡跑步違反規則。","p88/examples.3.ko":"今晚韓國對上日本。","p88/compare":"for(贊成，for ⑤) ↔ against(反對)。I'm for the plan. / I'm against the plan. 投票時的「贊成 · 反對」也是 for · against。","p88/quiz.0.ko":"很多人反對新法律。","p88/quiz.0.why":"是反對，所以用 against。","p88/quiz.1.ko":"在這裡抽菸違反規則。","p88/quiz.1.why":"是和規則相抵觸，所以用 against。","p88/quiz.2.ko":"我贊成那個計畫。我們開始吧！","p88/quiz.2.why":"贊成要用 for (for ⑤)。","p89/title":"靠著 · 撞上","p89/why":"這個畫面是身體或物品貼著某個面並施力。輕輕施力就是「靠著」：lean against the wall(靠著牆)。用力撞上就是「撞擊」：The rain beat against the window(雨打在窗戶上)。比起 on(接觸著)，更能感受到「力道」。","p89/examples.0.ko":"Noah 靠著牆站著。","p89/examples.1.ko":"雨滴猛烈地打在窗戶上。","p89/examples.2.ko":"把梯子靠在樹上。","p89/examples.3.ko":"我的頭撞到門了。","p89/compare":"a picture on the wall(掛在牆上的畫，on ①) / a bike against the wall(靠牆立著的腳踏車)。掛著用 on，靠著施力用 against。","p89/quiz.0.ko":"她靠著門哭了。","p89/quiz.0.why":"是靠在門上施力，所以用 against。","p89/quiz.1.ko":"海浪拍打在岩石上。","p89/quiz.1.why":"是猛烈地撞上，所以用 against。","p89/quiz.2.ko":"牆上掛著一個時鐘。","p89/quiz.2.why":"是掛在牆面上，所以用 on (on ①)。","p90/title":"預防 · 襯托","p90/why":"這個畫面是擋在危險前面，或是貼著背景而變得鮮明。針對危險事先防範就是「預防」：protect against the sun(防曬)、a shot against the flu(流感疫苗)。貼著背景而突顯就是「襯托」：dark against the blue sky(在藍天襯托下顯得黑)。","p90/examples.0.ko":"這款乳霜能保護你的皮膚不被陽光傷害。","p90/examples.1.ko":"你打流感疫苗了嗎？","p90/examples.2.ko":"橋在晴朗的藍天襯托下顯得很清楚。","p90/examples.3.ko":"紅色的燈在雪地上顯得特別醒目。","p90/compare":"save money for a rainy day(存錢以備不時之需)這類預防也可以用 for，但 against 更有「擋在前面」的感覺：insurance against fire(火災保險)。","p90/quiz.0.ko":"要防曬就戴帽子。","p90/quiz.0.why":"是擋住陽光，所以用 against。","p90/quiz.1.ko":"塔在夕陽的襯托下呈現黑色剪影。","p90/quiz.1.why":"是貼著背景而突顯，所以用 against。","p90/quiz.2.ko":"你贊成還是反對那個想法？","p90/quiz.2.why":"贊成要用 for (for ⑤)。","p91/title":"兩者之間","p91/why":"這個畫面是夾在兩者中間。between A and B(A 和 B 之間)、between nine and ten(九點到十點之間)、a bridge between two cities(連接兩座城市的橋)、between you and me(只有你知我知)。","p91/examples.0.ko":"我想成為連接首爾和紐約的橋梁。","p91/examples.1.ko":"九點到十點之間打給我。","p91/examples.2.ko":"咖啡店在銀行和麵包店中間。","p91/examples.3.ko":"這只有你知我知，Jake 超級緊張。","p91/compare":"between(清楚的兩者之間) ↔ among(混在一群中，第92課)。Choose between tea and coffee.(在茶和咖啡之間選一個) / She's popular among students.(她在學生之間很受歡迎)","p91/quiz.0.ko":"商店下午一點到兩點之間休息。","p91/quiz.0.why":"是兩個時間點之間，所以用 between。from 要和 to 搭配。","p91/quiz.1.ko":"坐在 Mina 和 Noah 中間。","p91/quiz.1.why":"是兩個人之間，所以用 between。","p91/quiz.2.ko":"我們當中有間諜！","p91/quiz.2.why":"是混在一群人之中，所以用 among (第92課)。","p92/title":"眾人之間","p92/why":"這個畫面是置身於一群混雜的人或物之中。among friends(在朋友之間)、among the trees(在樹林之間)、popular among teenagers(在青少年之間很受歡迎)。是不逐一細數的一群「當中」。","p92/examples.0.ko":"我的設計師當中，沒有人會這樣想。","p92/examples.1.ko":"我們當中有很多有才華的人。","p92/examples.2.ko":"那棟房子藏在樹林之間。","p92/examples.3.ko":"這首歌在青少年之間很受歡迎。","p92/compare":"between 用在可以像「A 和 B」這樣逐一指出的時候，among 則是用在「一群之中」。即使是三個以上，只要逐一指出就用 between：a deal between three companies(三家公司之間的合約)","p92/quiz.0.ko":"她和朋友們在一起很自在。","p92/quiz.0.why":"是在一群朋友之中，所以用 among。","p92/quiz.1.ko":"我在落葉堆中找到了戒指。","p92/quiz.1.why":"是在許多落葉之中，所以用 among。","p92/quiz.2.ko":"在紅色和藍色之間選一個。","p92/quiz.2.why":"是清楚的兩者之間，所以用 between (第91課)。","p93/title":"後面 · 落後","p93/why":"這個畫面是在某物的後方。在空間上躲在後面是 behind the door(在門後)，在時間 · 進度上落後是 behind schedule(進度落後) · fall behind(落後)。和 in front of(在前面)相反。","p93/examples.0.ko":"大家躲到花盆後面！","p93/examples.1.ko":"進度落後了！","p93/examples.2.ko":"你後面那個人是誰？","p93/examples.3.ko":"我的數學課落後了。","p93/compare":"behind the car(車子後面) ↔ in front of the car(車子前面)。behind 是「後面的位置」，back 是「往後 · 回到原處」的動作 (back ①)。","p93/quiz.0.ko":"貓躲在沙發後面。","p93/quiz.0.why":"是沙發的後方，所以用 behind。","p93/quiz.1.ko":"專案比預定進度晚了兩週。","p93/quiz.1.why":"是比進度落後，所以用 behind schedule。","p93/quiz.2.ko":"我家前面有一棵大樹。","p93/quiz.2.why":"前面是 in front of。和 behind 相反。","p94/title":"在背後支持","p94/why":"這個畫面是站在後面撐住你的背。I'm behind you.(我在你後面 = 我站在你這邊)、be behind a plan(支持計畫)。也可以指某件事「背後的人 · 原因」：Who's behind this?(這是誰策劃的？)","p94/examples.0.ko":"Rosa，我們都站在你們兩個這邊。","p94/examples.1.ko":"我永遠都會在背後支持你。","p94/examples.2.ko":"整個團隊都支持那個計畫。","p94/examples.3.ko":"這個驚喜是誰策劃的？","p94/compare":"I'm behind you.(我站在你這邊) = I support you. I'm with you.(我會陪著你，with ①)在替人加油時也有類似的用法。","p94/quiz.0.ko":"不管你做什麼決定，我都站在你這邊。","p94/quiz.0.why":"是在背後撐著你，所以用 behind。","p94/quiz.1.ko":"那個點子是誰想的？","p94/quiz.1.why":"是事情背後的人，所以用 behind。","p94/quiz.2.ko":"你先走。我馬上跟上。","p94/quiz.2.why":"是空間上緊跟在後面，所以用 behind (behind ①)。","p95/title":"那一邊 · 超出","p95/why":"這個畫面是越過線或界線，位在它的另一邊。beyond the hills(山丘的另一邊)、beyond this café(這間咖啡店之外)、beyond words(無法言喻)、beyond my control(我無法掌控)。是越過看得見的盡頭，再往更遠處去。","p95/examples.0.ko":"去這間咖啡店之外的地方看看吧，兒子。","p95/examples.1.ko":"山丘的另一邊有一個小村莊。","p95/examples.2.ko":"美得無法用言語形容。","p95/examples.3.ko":"天氣不是我們能掌控的。","p95/compare":"over the hill(翻越山丘的動作，over ①) / beyond the hill(在山丘另一邊的位置)。beyond 指的是越過之後的「那邊的世界」。","p95/quiz.0.ko":"那個村莊就在河的另一邊。","p95/quiz.0.why":"是越過河的那一邊，所以用 beyond。","p95/quiz.1.ko":"抱歉。這不是我能控制的。","p95/quiz.1.why":"是超出我能力界線的事，所以用 beyond。","p95/quiz.2.ko":"她上課時坐在我後面。","p95/quiz.2.why":"是正後方，所以用 behind (behind ①)。","p96/title":"範圍之內","p96/why":"這個畫面是待在劃定的界線內側。within a week(一週內)、within walking distance(在步行可到的距離內)、within budget(在預算內)。比起 in，更有「不超出界線」的感覺。","p96/examples.0.ko":"第一版設計必須在兩週內完成。","p96/examples.1.ko":"必須在預算內完成。","p96/examples.2.ko":"一週就去了三座城市呢！","p96/examples.3.ko":"咖啡店就在步行可到的距離內。","p96/compare":"in a week(剛好一週後，in ③) ↔ within a week(一週內的任何時候)。I'll be back in a week. / I'll be back within a week.","p96/quiz.0.ko":"您會在三天內收到包裹。","p96/quiz.0.why":"是三天這個範圍之內，所以用 within。","p96/quiz.1.ko":"請待在線的裡面。","p96/quiz.1.why":"是不超出線的內側，所以用 within。","p96/quiz.2.ko":"沒有咖啡我活不下去。","p96/quiz.2.why":"「沒有」是 without (第97課)。","p97/title":"沒有","p97/why":"和 with(一起)相反。這個畫面是該在身邊的東西不在。without you(沒有你)、without sugar(不加糖)、without saying goodbye(不說再見)。後面接動詞時要用 -ing。","p97/examples.0.ko":"沒有你，這間咖啡店就不一樣了。","p97/examples.1.ko":"不要不打招呼就走。","p97/examples.2.ko":"十年來第一次沒穿制服就來了。","p97/examples.3.ko":"請給我不加糖的咖啡。","p97/compare":"with you(和你一起，with ①) ↔ without you(沒有你)。without 後面的動詞用 -ing：without asking(沒問就)","p97/quiz.0.ko":"他一句話都沒說就走了。","p97/quiz.0.why":"「沒有」是 without。","p97/quiz.1.ko":"不要不穿外套就出門。","p97/quiz.1.why":"是沒有外套的狀態，所以用 without。","p97/quiz.2.ko":"我可以跟你一起去嗎？","p97/quiz.2.why":"「一起」是 with (with ①)。","p98/why":"before 是比基準點「前面 · 先」，after 是比基準點「後面 · 接著」。在時間上是 before work(上班前) · after work(下班後)，在順序上是 After you.(您先請)，跟在某人後面則是 run after(追趕) · look after(照顧，第59個片語動詞)。","p98/examples.0.ko":"過安檢之前先喝杯咖啡吧。","p98/examples.1.ko":"每天晚上下班後打給我。","p98/examples.2.ko":"您先請。——不，您先請！","p98/examples.3.ko":"幫我照顧一下我兒子，好嗎？","p98/compare":"before 3 p.m.(三點前) ↔ after 3 p.m.(三點後)。像「從現在起三個月後」這種從現在開始算的時候，比起 after，用 in three months 更自然 (in ③)。","p98/quiz.0.ko":"睡前要刷牙。","p98/quiz.0.why":"是比睡覺更早，所以用 before。","p98/quiz.1.ko":"我們吃完晚餐後去散步了。","p98/quiz.1.why":"是晚餐之後，所以用 after。","p98/quiz.2.ko":"誰會照顧你的貓？","p98/quiz.2.why":"是跟在後面照顧，所以用 look after。","p99/why":"in · on 是已經「在」那個位置的狀態，into · onto 是「進入 · 爬上」那個位置的動作。The cat is in the box.(在裡面) / The cat jumped into the box.(跳進了裡面) · The cat is on the table.(在上面) / The cat jumped onto the table.(跳到了上面)","p99/examples.0.ko":"媽媽兩次都走錯房間。","p99/examples.1.ko":"現在大家都在會議室裡了。","p99/examples.2.ko":"Jake 把咖啡灑到襯衫上了。","p99/examples.3.ko":"紫菜飯捲在桌上。","p99/compare":"搭配 go · walk · jump · climb · fall · spill 這類表示移動的動詞時，用 into · onto 比較自然。不過 put · sit 用 in · on 就夠了：Put it in the box. / Sit on the chair.","p99/quiz.0.ko":"他掉進游泳池了！","p99/quiz.0.why":"是進入水中的動作，所以用 into。","p99/quiz.1.ko":"貓爬上了屋頂。","p99/quiz.1.why":"是爬上某個面的動作，所以用 onto。","p99/quiz.2.ko":"你的手機在桌上。","p99/quiz.2.why":"是沒有移動、在上面的狀態，所以用 on。","p100/title":"介系詞 100 天總整理","p100/why":"100 天來學的介系詞，說到底就是幾個「畫面」。in 是箱子裡，on 是貼著面，at 是一個點，to 是抵達點，for 是朝向的地方，from 是出發點，of 是整體的一部分，with 是一起，by 是緊鄰，over 是覆蓋跨越，through 是穿過，up · down 是上下，out 是向外，off 是脫離，back 是回去。遇到不懂的意思時，不要死背，先想想畫面。","p100/examples.0.ko":"我提著兩個大行李箱，在雨中抵達了紐約。","p100/examples.1.ko":"我們過橋時聊著未來。","p100/examples.2.ko":"我為了新團隊從紐約飛到了首爾。","p100/examples.3.ko":"現在我是連接兩座城市的橋梁，朋友們在背後支持我。","p100/compare":"同一個介系詞有多種意思時，先想核心畫面 → 再想意思。例：on = 貼著面 → on the wall(牆上) · on Monday(日曆格子) · on TV(媒體) · The light is on(運作中)。今天是第 100 天了。辛苦了！","p100/quiz.0.ko":"鑰匙在抽屜裡。","p100/quiz.0.why":"是抽屜這個箱子的裡面，所以用 in (in ①)。","p100/quiz.1.ko":"我們在公車站碰面吧。","p100/quiz.1.why":"是地圖上的一個點，所以用 at (at ①)。","p100/quiz.2.ko":"我們邊吃晚餐邊聊了好幾個小時。","p100/quiz.2.why":"像覆蓋在晚餐之上，涵蓋那段時間，所以用 over (over ④)。","v1/meanings.0":"去接人","v1/meanings.1":"無師自通地學到","v1/meanings.2":"接電話","v1/why":"pick(挑起) + up(向上) → 把地上的東西撿起來。把站在路邊的人「接上車」就是去接人，把耳朵聽到的話「撿起來」就是無師自通地學到，拿起話筒就是接電話。","v1/object":"pick you up ○ · pick up you ✕ (代名詞放中間) · pick up the kids ○ · pick the kids up ○","v1/examples.0.scene":"去機場接朋友時","v1/examples.0.ko":"我六點去接你。","v1/examples.1.scene":"旅行回來的同事說","v1/examples.1.ko":"我在馬德里學到了一點西班牙語。","v1/examples.2.scene":"對沒接電話的朋友說","v1/examples.2.ko":"你為什麼沒接電話？","v1/similar":"get (帶來) · learn (學習) · answer (接電話)","v1/opposite":"drop off (開車送到)","v1/quiz.0.options.0":"你下班後可以來接我嗎？","v1/quiz.0.options.1":"你下班後可以把我舉起來嗎？","v1/quiz.0.options.2":"你下班後可以打電話給我嗎？","v1/quiz.0.options.3":"你下班後可以幫我挑一個嗎？","v1/quiz.0.why":"pick up 用在人身上是去接 · 來接。","v1/quiz.1.ko":"你為什麼沒接？我打了三次耶！","v1/quiz.1.why":"是拿起話筒的畫面，所以接電話是 pick up。","v1/quiz.2.q":"「我六點去接你。」用英文怎麼說？","v1/quiz.2.why":"受詞是 you 這類代名詞時，要放在 pick 和 up 中間。","v2/meanings.0":"快點","v2/meanings.1":"拜託 · 少來了","v2/meanings.2":"加油 · 你可以的","v2/why":"come(來) + on(不停地持續) → 「別停，繼續往這邊來」。所以催人時是「快點！」，替人加油時是「加油，繼續！」，聽到離譜的話時是「拜託，別鬧了」。燈亮起來時也能用 (The lights came on)。","v2/object":"像 Come on! 這樣不接受詞，單獨使用。","v2/tip":"語調不同，意思也不同。催促時又短又快，「拜託 · 少來了」則拉長音 (Come o~n)。","v2/examples.0.scene":"對動作慢吞吞的朋友說","v2/examples.0.ko":"快點，我們遲到了！","v2/examples.1.scene":"同事聽到一個明顯的謠言時說","v2/examples.1.ko":"少來了。你不會真的相信吧。","v2/examples.2.scene":"對馬拉松終點線前的朋友說","v2/examples.2.ko":"加油！你可以的！","v2/similar":"hurry up (快點) · no way (不會吧) · you can do it (加油)","v2/quiz.0.q":"(朋友說「我昨天和一位有名的演員吃晚餐」時) Oh, come on!","v2/quiz.0.options.0":"拜託，不會吧！","v2/quiz.0.options.1":"快過來！","v2/quiz.0.options.2":"把燈打開！","v2/quiz.0.options.3":"加油！","v2/quiz.0.why":"聽到難以置信的話而拉長音的 come on 是「拜託，不會吧」。","v2/quiz.1.ko":"快點！公車要開走了！","v2/quiz.1.why":"催促的話用 Come on!","v2/quiz.2.q":"(對考試前一天哭泣的朋友說) ___, you studied so hard. You'll be fine.","v2/quiz.2.ko":"加油，你真的很努力了。會沒事的。","v2/quiz.2.why":"替人加油時也用 Come on。","v3/meanings.0":"查出來 · 得知","v3/meanings.1":"(祕密 · 謊言)被發現","v3/why":"find(找) + out(向外顯露) → 把藏起來的事實找出來，攤在外面 = 查出來。和 know(已經知道的狀態)不同，是「原本不知道，後來才得知的瞬間」。","v3/object":"find out the truth ○ · find out where he lives ○ · 代名詞通常說成 find out about it。也常不接受詞，說 How did you find out?","v3/examples.0.scene":"對被發現驚喜派對的朋友說","v3/examples.0.ko":"你怎麼知道的？","v3/examples.1.scene":"打開地圖 App 時","v3/examples.1.ko":"我來查一下店什麼時候開。","v3/examples.2.scene":"對說謊的弟弟說","v3/examples.2.ko":"媽媽如果知道了，你就慘了。","v3/similar":"learn (得知) · discover (發現) · figure out (動腦筋想出來，第12個)","v3/quiz.0.ko":"我剛剛得知 Jake 要辭職了！","v3/quiz.0.why":"是得知原本不知道的事實的瞬間，所以用 found out。","v3/quiz.1.options.0":"你怎麼知道的？","v3/quiz.1.options.1":"你怎麼找到這裡的？","v3/quiz.1.options.2":"你怎麼出去的？","v3/quiz.1.options.3":"你怎麼選的？","v3/quiz.1.why":"find out 是得知事實。","v3/quiz.2.ko":"我去查一下店幾點關門。","v3/quiz.2.why":"查詢不知道的資訊是 find out。只用 find 的話是「找東西」。","v4/meanings.0":"等一下","v4/meanings.1":"抓緊","v4/meanings.2":"撐住","v4/why":"hold(握住) + on(貼著) → 手不放開，緊緊抓著。所以是「抓緊！」，面對困難不放棄是「撐住！」，要對方別掛電話、繼續拿著話筒則是「請稍等」。","v4/object":"像 Hold on! 這樣單獨使用。要抓住的對象用 hold on to 來說 (Hold on to my hand)。","v4/examples.0.scene":"通話中門鈴響了","v4/examples.0.ko":"等一下，有人來了。","v4/examples.1.scene":"雲霄飛車出發時","v4/examples.1.ko":"抓緊！","v4/examples.2.scene":"在受傷的朋友身邊","v4/examples.2.ko":"再撐一下。醫生正在趕來。","v4/similar":"wait a minute (等一下) · hang on (等一下，更輕鬆的說法)","v4/quiz.0.options.0":"等一下，有電話進來。","v4/quiz.0.options.1":"抓緊，有電話進來。","v4/quiz.0.options.2":"繼續，有電話進來。","v4/quiz.0.options.3":"掛掉，有電話進來。","v4/quiz.0.why":"是請對方停下手邊的事等一下，所以是 Hold on。","v4/quiz.1.ko":"路很顛簸。抓緊！","v4/quiz.1.why":"是叫人手不要放開、抓緊，所以用 Hold on。","v4/quiz.2.ko":"抓緊繩子，不要放手！","v4/quiz.2.why":"要抓住的對象用 hold on to 來說。","v5/meanings.0":"(和朋友)一起玩 · 混在一起","v5/meanings.1":"打發時間","v5/why":"hang(掛著 · 垂著) + out(在外面) → 在外面沒事做、閒閒待著 = 和朋友一起玩 · 打發時間。就算沒做什麼特別的事，也有「在一起」的感覺。","v5/object":"不接受詞。和誰一起用 hang out with，在哪裡用 hang out at。","v5/examples.0.scene":"星期五下午對同事說","v5/examples.0.ko":"下班後要一起去玩嗎？","v5/examples.1.scene":"媽媽對兒子說","v5/examples.1.ko":"你最近都和誰一起玩？","v5/examples.2.scene":"朋友問週末的計畫","v5/examples.2.ko":"沒什麼。就在家閒晃。","v5/similar":"spend time (度過時間) · get together (聚在一起)","v5/quiz.0.options.0":"我們整天都在購物中心閒逛。","v5/quiz.0.options.1":"我們整天都掛在購物中心上。","v5/quiz.0.options.2":"我們整天都在購物中心工作。","v5/quiz.0.options.3":"我們整天都在找購物中心。","v5/quiz.0.why":"hang out 的過去式是 hung out，意思是一起玩過了。","v5/quiz.1.ko":"這個週末要一起玩嗎？","v5/quiz.1.why":"一起玩是 hang out。hang up 是「掛電話」。","v5/quiz.2.ko":"我通常每週五都和朋友們一起玩。","v5/quiz.2.why":"和誰一起玩要用 hang out with。","v6/meanings.0":"(在約好的地方)出現 · 到場","v6/meanings.1":"看得出來 · 看得見","v6/why":"show(顯示) + up(靠近而出現) → 「噌」地進入視線內而被看見 = 出現。就像把到約定場合說成「露面」一樣。","v6/object":"不接受詞。地點像 show up at the party 這樣接在後面。","v6/examples.0.scene":"對又開會遲到的同事說","v6/examples.0.ko":"你又遲到了！","v6/examples.1.scene":"在空蕩蕩的派對會場","v6/examples.1.ko":"沒有人來。","v6/examples.2.scene":"看著照片時","v6/examples.2.ko":"那道刮痕在照片裡看不出來。","v6/similar":"come (來) · appear (出現) · turn up (出現)","v6/quiz.0.options.0":"他沒有出現在會議上。","v6/quiz.0.options.1":"他沒有給別人看會議。","v6/quiz.0.options.2":"他沒有結束會議。","v6/quiz.0.options.3":"他沒有找會議。","v6/quiz.0.why":"show up 是在約好的地方出現。","v6/quiz.1.ko":"我等了一個小時，她始終沒有出現。","v6/quiz.1.why":"出現是 show up，是過去的事，所以用 showed up。","v6/quiz.2.ko":"派對上只來了五個人。","v6/quiz.2.why":"是過去的事，所以用過去式 showed up。","v7/meanings.0":"運動","v7/meanings.1":"(事情)順利解決","v7/meanings.2":"(辦法)想出來","v7/why":"work(努力) + out(到最後 · 完全) → 努力到最後把它解決。把問題解到最後就是「想出辦法」，事情順利進行到最後就是「順利解決」，把身體用到最後就是「運動」。","v7/object":"運動 · 順利解決不接受詞。想出辦法用 work out a plan ○ · work it out ○ (代名詞放中間)。","v7/examples.0.scene":"在健身房門口","v7/examples.0.ko":"我一週運動三次。","v7/examples.1.scene":"對擔心的朋友說","v7/examples.1.ko":"別擔心。一切都會順利的。","v7/examples.2.scene":"看著複雜的行程表時","v7/examples.2.ko":"我們一起想辦法吧。","v7/similar":"exercise (運動) · go well (順利) · solve (解決)","v7/quiz.0.options.0":"希望一切順利。","v7/quiz.0.options.1":"希望大家都去運動。","v7/quiz.0.options.2":"希望大家都出去。","v7/quiz.0.options.3":"希望大家都結束。","v7/quiz.0.why":"是事情順利進行到最後的 work out。","v7/quiz.1.ko":"她每天早上都在健身房運動。","v7/quiz.1.why":"運動是 work out，主詞是 she，所以用 works out。","v7/quiz.2.q":"「我們一起想辦法吧。」用英文怎麼說？","v7/quiz.2.why":"代名詞 it 要放在 work 和 out 中間。","v8/meanings.0":"冷靜下來","v8/meanings.1":"讓(人)冷靜下來","v8/why":"calm(平靜的) + down(減少 · 變弱) → 沸騰的情緒往下沉澱 = 冷靜下來。風 · 浪平息時也能用。","v8/object":"單獨用是冷靜下來 (Calm down!)，有受詞則是讓人冷靜下來：calm her down ○ · calm down the baby ○ · calm down her ✕","v8/tip":"對生氣的人大聲說 Calm down! 可能讓對方更生氣。也可以像 Take a deep breath. 這樣溫和地說。","v8/examples.0.scene":"對生氣的朋友說","v8/examples.0.ko":"冷靜點。我們談一談。","v8/examples.1.scene":"抱著哭泣的孩子時","v8/examples.1.ko":"我試著安撫孩子。","v8/examples.2.scene":"暴風雨過後","v8/examples.2.ko":"風終於平息了。","v8/similar":"relax (放鬆) · chill out (冷靜點，更輕鬆的說法)","v8/quiz.0.options.0":"我花了一個小時才把寶寶哄好。","v8/quiz.0.options.1":"我花了一個小時才把寶寶放下。","v8/quiz.0.options.2":"我花了一個小時才把寶寶叫醒。","v8/quiz.0.options.3":"我花了一個小時才找到寶寶。","v8/quiz.0.why":"有受詞的 calm down 是讓人冷靜下來。","v8/quiz.1.ko":"冷靜點！只是個小失誤。","v8/quiz.1.why":"對情緒激動的人說的話是 Calm down。","v8/quiz.2.q":"「我試著讓她冷靜下來。」用英文怎麼說？","v8/quiz.2.why":"代名詞 her 要放在 calm 和 down 中間。","v9/meanings.0":"繼續","v9/meanings.1":"(事情)發生 · 進行中","v9/why":"go(去) + on(不停地持續) → 不停地一直走下去 = 繼續。有事情一直「進行著」就是發生 · 進行中。What's going on? 是「現在什麼正在進行？」= 怎麼回事？","v9/object":"不接受詞。持續做的事用 go on -ing (Go on reading) 或 go on with it 來說。","v9/examples.0.scene":"對停下話來的朋友說","v9/examples.0.ko":"繼續說。","v9/examples.1.scene":"走進吵鬧的客廳時","v9/examples.1.ko":"這裡是怎麼回事？","v9/examples.2.scene":"下雨天在球場","v9/examples.2.ko":"比賽在雨中仍繼續進行。","v9/similar":"continue (繼續) · happen (發生)","v9/quiz.0.options.0":"怎麼回事？","v9/quiz.0.options.1":"你要去哪裡？","v9/quiz.0.options.2":"什麼開著？","v9/quiz.0.options.3":"你什麼時候去？","v9/quiz.0.why":"是在問現在正發生的事。","v9/quiz.1.ko":"不好意思打斷你。請繼續。","v9/quiz.1.why":"是叫人繼續說停下來的話，所以用 go on。","v9/quiz.2.ko":"派對持續到凌晨兩點。","v9/quiz.2.why":"是不停地持續下去，所以用 went on。","v10/meanings.0":"關掉(電器 · 機器)","v10/meanings.1":"(從大馬路)駛離","v10/why":"turn(轉動) + off(分離 · 切斷) → 轉動開關切斷電源 = 關掉。從大馬路轉方向盤脫離出去就是「駛離」。","v10/examples.0.scene":"對要出門的室友說","v10/examples.0.ko":"別忘了關燈。","v10/examples.1.scene":"對吵人的鬧鐘說","v10/examples.1.ko":"可以把它關掉嗎？","v10/examples.2.scene":"導航提示","v10/examples.2.ko":"請在下一個出口駛離。","v10/similar":"switch off (關掉) · shut off (關掉)","v10/opposite":"turn on (打開)","v10/quiz.0.options.0":"看電影時請關掉手機。","v10/quiz.0.options.1":"看電影時請把手機轉給我。","v10/quiz.0.options.2":"看電影時請打開手機。","v10/quiz.0.options.3":"看電影時請幫我找手機。","v10/quiz.0.why":"是關掉機器的 turn off。","v10/quiz.1.ko":"太熱了。可以把暖氣關掉嗎？","v10/quiz.1.why":"因為熱所以要關掉，用 turn off。turn up 是「調大」。","v10/quiz.2.q":"「把它關掉。」用英文怎麼說？","v10/quiz.2.why":"代名詞 it 要放在 turn 和 off 中間。","v11/meanings.0":"(偶然)碰到","v11/meanings.1":"(遇到)問題","v11/meanings.2":"(跑著)撞上","v11/why":"run(跑) + into(進到裡面碰上) → 跑著跑著「砰」地撞上某物。「撞上」人就是偶然遇到，撞上問題就是遇到困難。","v11/object":"run into + 人 · 問題。不能拆開用：run into him ○ · run him into ✕","v11/examples.0.scene":"在超市看到老同事後回來說","v11/examples.0.ko":"你猜我在超市遇到誰！","v11/examples.1.scene":"在專案會議上","v11/examples.1.ko":"我們遇到了一些問題。","v11/examples.2.scene":"邊走邊看手機時","v11/examples.2.ko":"我撞到柱子了。","v11/similar":"bump into (偶然遇到) · meet by chance (偶然碰面)","v11/quiz.0.options.0":"我昨天偶然遇到以前的老師。","v11/quiz.0.options.1":"我昨天跑向以前的老師。","v11/quiz.0.options.2":"我昨天找到了以前的老師。","v11/quiz.0.options.3":"我昨天和以前的老師一起玩。","v11/quiz.0.why":"對人用 run into 是偶然遇到。","v11/quiz.1.ko":"我在來的路上遇到了一些問題。","v11/quiz.1.why":"遇到問題也是用 run into。","v11/quiz.2.q":"「我昨天在機場偶然遇到他。」用英文怎麼說？","v11/quiz.2.why":"run into 不能拆開用，所以 him 要放在 into 後面。","v12/meanings.0":"(動腦)想出來 · 解開","v12/meanings.1":"(人)搞懂","v12/why":"figure(計算 · 在腦中描繪) + out(到最後 · 完全) → 用腦袋算到最後，把答案拿出來。find out 是「得知資訊」，figure out 則是「動腦筋解開」。","v12/examples.0.scene":"站在複雜的地鐵路線圖前","v12/examples.0.ko":"我搞不清楚該搭哪一班車。","v12/examples.1.scene":"修好壞掉的印表機的同事說","v12/examples.1.ko":"我終於搞定了！","v12/examples.2.scene":"談到一個捉摸不透的朋友","v12/examples.2.ko":"我完全搞不懂他。","v12/similar":"work out (想出辦法) · understand (理解) · solve (解決)","v12/quiz.0.options.0":"你能解開這道數學題嗎？","v12/quiz.0.options.1":"你能找到這道數學題嗎？","v12/quiz.0.options.2":"你能丟掉這道數學題嗎？","v12/quiz.0.options.3":"你能給我看這道數學題嗎？","v12/quiz.0.why":"是動腦筋解開的 figure out。","v12/quiz.1.ko":"我讀了說明書，但還是搞不懂怎麼用。","v12/quiz.1.why":"用腦袋想出方法是 figure out。","v12/quiz.2.q":"「我終於搞懂了！」用英文怎麼說？","v12/quiz.2.why":"代名詞 it 要放在 figure 和 out 中間。","v13/meanings.0":"放棄","v13/meanings.1":"戒掉(習慣)","v13/meanings.2":"讓出(位子 · 東西)","v13/why":"give(給) + up(全部到底) → 把擁有的東西全部讓出去。把目標全部讓出去就是「放棄」，把習慣讓出去就是「戒掉」，把位子讓出去就是「讓座」。","v13/object":"像 Don't give up! 這樣單獨使用。give up smoking ○ · give it up ○ · give up it ✕。放棄某人 · 某事時用 give up on (Don't give up on me)。","v13/examples.0.scene":"在馬拉松 30 公里處","v13/examples.0.ko":"不要放棄！快到了！","v13/examples.1.scene":"說起新年新希望時","v13/examples.1.ko":"我上個月戒掉咖啡了。","v13/examples.2.scene":"在地鐵上","v13/examples.2.ko":"他把座位讓給了一位老奶奶。","v13/similar":"quit (退出) · stop (停止)","v13/quiz.0.options.0":"爸爸十年前戒菸了。","v13/quiz.0.options.1":"爸爸十年前送了香菸。","v13/quiz.0.options.2":"爸爸十年前開始抽菸。","v13/quiz.0.options.3":"爸爸十年前找到了香菸。","v13/quiz.0.why":"對習慣用 give up 是戒掉。","v13/quiz.1.ko":"這個拼圖太難了。我放棄。","v13/quiz.1.why":"放棄是 give up。","v13/quiz.2.ko":"不要放棄你的夢想。","v13/quiz.2.why":"放棄某人 · 某事要用 give up on 來說。","v14/meanings.0":"期待 · 盼望(開心的事)","v14/why":"look forward(向前看) + to(朝著那件事) → 朝著即將到來的事，伸長脖子張望 = 期待。帶有雀躍的心情。","v14/object":"to 後面接名詞或 -ing。looking forward to the trip ○ · to seeing you ○ · to see you ✕","v14/tip":"電子郵件結尾的 I look forward to hearing from you. 是「期待您的回覆」的禮貌用語。","v14/examples.0.scene":"暑假快到時","v14/examples.0.ko":"我真的很期待這趟旅行。","v14/examples.1.scene":"對久違要見面的朋友說","v14/examples.1.ko":"我很期待見到你！","v14/examples.2.scene":"在工作郵件的結尾","v14/examples.2.ko":"期待您的回覆。","v14/similar":"can't wait (等不及) · be excited about (對～感到興奮)","v14/quiz.0.options.0":"我很期待週末。","v14/quiz.0.options.1":"我在找週末。","v14/quiz.0.options.2":"我把週末往前推了。","v14/quiz.0.options.3":"我在週末往前看。","v14/quiz.0.why":"是望著即將到來的事而等待的 look forward to。","v14/quiz.1.ko":"我很期待見到您。","v14/quiz.1.why":"look forward to 後面接 -ing。","v14/quiz.2.ko":"我等不及了！我真的很期待演唱會。","v14/quiz.2.why":"期待是 look forward to。","v15/meanings.0":"嚇壞 · 崩潰","v15/meanings.1":"把(別人)嚇壞","v15/why":"freak(怪異的 · 嚇一跳的) + out(向外爆發) → 驚嚇 · 不安一下子向外爆發 = 嚇壞。口語中非常常用。","v15/object":"單獨用是嚇壞(Don't freak out!)，有受詞則是把人嚇壞：You freaked me out! ○ · freaked out me ✕","v15/examples.0.scene":"對受到驚嚇的朋友說","v15/examples.0.ko":"別慌。只是一隻蜘蛛。","v15/examples.1.scene":"看完恐怖片後","v15/examples.1.ko":"那部電影真的讓我毛骨悚然。","v15/examples.2.scene":"等待考試結果時","v15/examples.2.ko":"我為了成績快崩潰了。","v15/similar":"panic (恐慌) · lose it (失控)","v15/opposite":"calm down (冷靜下來)","v15/quiz.0.options.0":"她看到老鼠嚇壞了。","v15/quiz.0.options.1":"她看到老鼠就走出去了。","v15/quiz.0.options.2":"她看到老鼠就笑了。","v15/quiz.0.options.3":"她看到老鼠就冷靜下來了。","v15/quiz.0.why":"是驚嚇一下子爆發出來的 freak out。","v15/quiz.1.ko":"別慌！只是擦傷一點點而已。","v15/quiz.1.why":"對受到驚嚇的人說的話是 Don't freak out。","v15/quiz.2.q":"「你嚇了我一大跳！」用英文怎麼說？","v15/quiz.2.why":"代名詞 me 要放在 freaked 和 out 中間。","v16/meanings.0":"(情侶)分手","v16/meanings.1":"分開 · 解散(一群人)","v16/meanings.2":"(通話聲音)斷斷續續","v16/why":"break(打破) + up(到最後全部 · 完全) → 碎成一片片。關係破裂就是「分手」，一整團被打散就是「分開 · 解散」，電話的聲音碎成一段一段就是「斷斷續續」。","v16/object":"分手是 break up with + 人。分開是 break up the class ○ · break it up ○。通話時用 You're breaking up.(你的聲音斷斷續續)","v16/examples.0.scene":"聽到朋友的感情消息時","v16/examples.0.ko":"他們上個月分手了。","v16/examples.1.scene":"老師在教室裡說","v16/examples.1.ko":"我們四個人一組分開吧。","v16/examples.2.scene":"在隧道裡通話時","v16/examples.2.ko":"抱歉，你的聲音斷斷續續的！","v16/similar":"split up (分手) · divide (分開)","v16/quiz.0.options.0":"喂？你的聲音斷斷續續的。","v16/quiz.0.options.1":"喂？我們分手吧。","v16/quiz.0.options.2":"喂？門壞掉了。","v16/quiz.0.options.3":"喂？請起床。","v16/quiz.0.why":"通話時說的 You're breaking up 是聲音斷斷續續的意思。","v16/quiz.1.ko":"Jake 和他女朋友去年分手了。","v16/quiz.1.why":"情侶分手是 break up。","v16/quiz.2.ko":"她和男朋友分手了。","v16/quiz.2.why":"和誰分手要用 break up with。","v17/meanings.0":"(把過去的事)放下，往前走","v17/meanings.1":"進入下一項","v17/why":"move(移動) + on(不停地持續) → 不停留在原地，一直往前移動。從傷心事中不停下來繼續向前就是「放下往前走」，在會議上前往下一個議題就是「進入下一項」。","v17/object":"單獨使用，或用 move on to + 下一件事 (Let's move on to the next topic)。過去的事用 move on from。","v17/examples.0.scene":"對剛分手的朋友說","v17/examples.0.ko":"該放下了。","v17/examples.1.scene":"主持會議時","v17/examples.1.ko":"我們進入下一個主題吧。","v17/examples.2.scene":"對犯錯的同事說","v17/examples.2.ko":"每個人都會犯錯。別提了，往前走吧。","v17/similar":"get over (克服) · let go (放手)","v17/quiz.0.options.0":"分手後她很快就走出來了。","v17/quiz.0.options.1":"分手後她很快就搬家了。","v17/quiz.0.options.2":"分手後她很快就復合了。","v17/quiz.0.options.3":"分手後她一直在哭。","v17/quiz.0.why":"是不停留在過去、繼續往前的 move on。搬家是 move。","v17/quiz.1.ko":"好的，我們進入第 5 題。","v17/quiz.1.why":"進入下一項是 move on。","v17/quiz.2.ko":"已經一年了。你該放下了。","v17/quiz.2.why":"放下過去往前走是 move on。","v18/meanings.0":"再打電話","v18/meanings.1":"回電(給打來的人)","v18/why":"call(打電話) + back(回應 · 再回去) → 是接到電話的一方回撥過去的畫面。回撥沒接到的電話，或通話中說「等一下再打給你」時都會用。","v18/object":"call you back ○ · call back you ✕ (代名詞放中間) · call back the client ○ · call the client back ○","v18/examples.0.scene":"開會時電話響了","v18/examples.0.ko":"我在開會。我等一下再打給你可以嗎？","v18/examples.1.scene":"看到未接來電時","v18/examples.1.ko":"抱歉沒接到電話。我現在回電給你。","v18/examples.2.scene":"同事轉達留言時","v18/examples.2.ko":"Kim 老師希望你回電給他。","v18/similar":"return a call (回電) · get back to (之後再聯絡)","v18/quiz.0.options.0":"我十分鐘後再打給你。","v18/quiz.0.options.1":"我十分鐘後叫你。","v18/quiz.0.options.2":"我十分鐘後回去。","v18/quiz.0.options.3":"我十分鐘後掛電話。","v18/quiz.0.why":"是回撥電話的 call back。","v18/quiz.1.ko":"他現在不在座位上。我可以等一下再打給您嗎？","v18/quiz.1.why":"代名詞 you 要放在 call 和 back 中間。","v18/quiz.2.q":"「我得回電話給他。」用英文怎麼說？","v18/quiz.2.why":"代名詞 him 要放在 call 和 back 中間。","v19/meanings.0":"(有趣的東西)看一看 · 參觀","v19/meanings.1":"(飯店)退房","v19/why":"check(確認) + out(到最後 · 完全) → 仔仔細細確認到最後 = 看一看 · 參觀。在飯店是辦完確認手續後走「出去」，所以是退房 (out ①)。","v19/object":"Check this out! ○ · check out the new café ○ · check it out ○ · check out it ✕。飯店用 check out of the hotel。","v19/examples.0.scene":"播新歌給朋友聽時","v19/examples.0.ko":"聽聽這個！太棒了。","v19/examples.1.scene":"在飯店櫃檯","v19/examples.1.ko":"我必須幾點前退房？","v19/examples.2.scene":"在社區散步時","v19/examples.2.ko":"我們去逛逛那家新開的書店吧。","v19/similar":"take a look (看一眼) · visit (拜訪)","v19/opposite":"check in (登記入住)","v19/quiz.0.options.0":"看一下這個網站。","v19/quiz.0.options.1":"離開這個網站。","v19/quiz.0.options.2":"關掉這個網站。","v19/quiz.0.options.3":"修好這個網站。","v19/quiz.0.why":"是叫人看看有趣東西的 check out。","v19/quiz.1.ko":"我必須在十一點前從飯店退房。","v19/quiz.1.why":"離開飯店是 check out。","v19/quiz.2.q":"「看看這個！」用英文怎麼說？","v19/quiz.2.why":"代名詞 it 要放在 check 和 out 中間。","v20/meanings.0":"想出(點子 · 辦法)","v20/meanings.1":"籌措(錢等)","v20/why":"come up(往上浮現) + with(帶著) → 從腦海深處「帶著」想法浮上來 = 想出來。帶著需要的錢出現，就是「籌措」。","v20/object":"come up with + 點子 · 計畫 · 名稱。不能拆開用：come up with it ○ · come it up with ✕","v20/examples.0.scene":"開會時","v20/examples.0.ko":"這個點子是誰想出來的？","v20/examples.1.scene":"煩惱店名時","v20/examples.1.ko":"我們得想一個更好的名字。","v20/examples.2.scene":"房租拖欠的朋友說","v20/examples.2.ko":"我得在週五前湊到 500 美元。","v20/similar":"think of (想到) · invent (發明)","v20/quiz.0.options.0":"她想出了一個很棒的計畫。","v20/quiz.0.options.1":"她帶著一個很棒的計畫走上來。","v20/quiz.0.options.2":"她放棄了一個很棒的計畫。","v20/quiz.0.options.3":"她確認了一個很棒的計畫。","v20/quiz.0.why":"是想出點子並提出來的 come up with。","v20/quiz.1.ko":"你可以幫忙想一下文章標題嗎？","v20/quiz.1.why":"想出來是 come up with。","v20/quiz.2.ko":"我們得想出解決辦法。","v20/quiz.2.why":"come up with 是一個整體。","v21/meanings.0":"最後變成～","v21/meanings.1":"最後到了～","v21/why":"end(結束) + up(到最後全部) → 東走西走，最後抵達的地方 = 最後變成～。常用在和原本計畫不同的結果上。","v21/object":"end up + -ing (end up working)，end up + 地點 (end up in Paris)，end up with + 名詞。","v21/examples.0.scene":"聊起週末時","v21/examples.0.ko":"我最後整個週末都在工作。","v21/examples.1.scene":"迷路的旅行故事","v21/examples.1.ko":"我們迷了路，最後來到一個小村莊。","v21/examples.2.scene":"看著購物收據時","v21/examples.2.ko":"我去買牛奶，結果還買了一包餅乾。","v21/similar":"finally (終於) · wind up (最後變成～)","v21/quiz.0.options.0":"我們最後待在家裡。","v21/quiz.0.options.1":"我們在家裡結束了。","v21/quiz.0.options.2":"我們走上了家裡。","v21/quiz.0.options.3":"我們放棄了家。","v21/quiz.0.why":"是一路演變到最後變成那樣的 end up。","v21/quiz.1.ko":"我本來沒打算買，結果還是買了。","v21/quiz.1.why":"最後變成～是 end up + -ing。","v21/quiz.2.ko":"如果你不小心，最後會迷路的。","v21/quiz.2.why":"end up 後面接 -ing。","v22/meanings.0":"打起精神","v22/meanings.1":"讓(別人)打起精神","v22/why":"cheer(加油 · 精神) + up(向上提升) → 把低落的心情往上提 = 打起精神 · 讓人打起精神。","v22/object":"單獨用是打起精神(Cheer up!)，有受詞則是讓人打起精神：cheer her up ○ · cheer up her ✕","v22/examples.0.scene":"對考砸的朋友說","v22/examples.0.ko":"打起精神來！只是一次考試而已。","v22/examples.1.scene":"送花給生病的同事時","v22/examples.1.ko":"看看這些花，打起精神吧。","v22/examples.2.scene":"心情低落的日子","v22/examples.2.ko":"搞笑影片總是能讓我振作起來。","v22/similar":"feel better (心情變好) · lift someone's spirits (提振某人的精神)","v22/quiz.0.options.0":"她試著讓他打起精神。","v22/quiz.0.options.1":"她試著把他舉起來。","v22/quiz.0.options.2":"她試著讓他加入啦啦隊。","v22/quiz.0.options.3":"她試著讓他冷靜下來。","v22/quiz.0.why":"是把低落的心情往上提的 cheer up。","v22/quiz.1.ko":"打起精神來！一切都會好起來的。","v22/quiz.1.why":"叫人打起精神的話是 Cheer up。","v22/quiz.2.q":"「我想讓她打起精神。」用英文怎麼說？","v22/quiz.2.why":"代名詞 her 要放在 cheer 和 up 中間。","v23/meanings.0":"搞砸 · 弄得一團亂","v23/meanings.1":"犯錯","v23/why":"mess(一團亂) + up(到最後 · 完全) → 完全弄得一團亂 = 搞砸。不接受詞時是「犯錯 · 把事情搞砸」。","v23/object":"mess up the file ○ · mess it up ○ · mess up it ✕。單獨用是 I messed up.(我搞砸了)","v23/examples.0.scene":"簡報搞砸後","v23/examples.0.ko":"我的簡報徹底搞砸了。","v23/examples.1.scene":"孩子把客廳弄亂時","v23/examples.1.ko":"誰把客廳弄得一團亂？","v23/examples.2.scene":"道歉時","v23/examples.2.ko":"對不起。是我搞砸了。","v23/similar":"ruin (毀掉) · screw up (搞砸，更粗魯的說法)","v23/quiz.0.options.0":"不要弄亂我的頭髮！","v23/quiz.0.options.1":"不要洗我的頭髮！","v23/quiz.0.options.2":"不要剪我的頭髮！","v23/quiz.0.options.3":"不要綁我的頭髮！","v23/quiz.0.why":"弄得一團亂是 mess up。","v23/quiz.1.ko":"真的很抱歉。我真的搞砸了。","v23/quiz.1.why":"單獨使用的 mess up 是犯錯。","v23/quiz.2.q":"「別把它搞砸。」用英文怎麼說？","v23/quiz.2.why":"代名詞 it 要放在 mess 和 up 中間。","v24/meanings.0":"編造(故事)","v24/meanings.1":"和好","v24/meanings.2":"彌補 (make up for)","v24/why":"make(做) + up(把空缺補到滿) → 把不存在的故事編出來補上就是「編造」，填補關係的縫隙就是「和好」，把失去的補回來就是「彌補(make up for)」。","v24/object":"編造是 make up a story ○ · make it up ○。和好是 make up (with someone)。彌補是 make up for + 名詞。","v24/examples.0.scene":"聽到明顯藉口的媽媽說","v24/examples.0.ko":"別編藉口了。","v24/examples.1.scene":"吵過架的情侶說","v24/examples.1.ko":"我們吵架了，但後來和好了。","v24/examples.2.scene":"約會遲到的朋友說","v24/examples.2.ko":"為了彌補我的過錯，晚餐我請客。","v24/similar":"invent (編造) · reconcile (和解)","v24/quiz.0.options.0":"他把整個故事都編出來了。","v24/quiz.0.options.1":"他把整個故事都整理好了。","v24/quiz.0.options.2":"他把整個故事都聽完了。","v24/quiz.0.options.3":"他把整個故事都忘了。","v24/quiz.0.why":"是把不存在的故事編出來補上的 make up。","v24/quiz.1.ko":"我們昨天吵架了，但今天早上和好了。","v24/quiz.1.why":"是填補關係縫隙的 make up。","v24/quiz.2.ko":"為了彌補失去的時間，我們得努力。","v24/quiz.2.why":"彌補是 make up for。","v25/meanings.0":"延後 · 推遲","v25/meanings.1":"讓(別人)倒胃口","v25/why":"put(放) + off(離開) → 把事情從現在移開、放到遠處 = 延後。讓人的心離開就是「倒胃口」。","v25/examples.0.scene":"對又推遲看牙醫的朋友說","v25/examples.0.ko":"別再拖了！","v25/examples.1.scene":"因為雨下得很大","v25/examples.1.ko":"我們把比賽延到下週了。","v25/examples.2.scene":"對面臨作業的弟弟說","v25/examples.2.ko":"今天能做的事不要拖到明天。","v25/similar":"postpone (延期) · delay (延遲)。call off 是完全取消，意思不同。","v25/quiz.0.options.0":"我們把會議延到星期五吧。","v25/quiz.0.options.1":"我們在星期五結束會議吧。","v25/quiz.0.options.2":"我們在星期五取消會議吧。","v25/quiz.0.options.3":"我們在星期五開始會議吧。","v25/quiz.0.why":"是把事情從現在移開、往後放的 put off。","v25/quiz.1.ko":"我一直在拖延作業。","v25/quiz.1.why":"keep 後面接 -ing，延後是 put off。","v25/quiz.2.q":"「別拖著不做。」用英文怎麼說？","v25/quiz.2.why":"代名詞 it 要放在 put 和 off 中間。","v26/meanings.0":"架設 · 安裝","v26/meanings.1":"安排(行程) · 成立(公司)","v26/meanings.2":"介紹(人)認識 (set A up with B)","v26/why":"set(放) + up(向上) → 向上立起來放好 = 安裝。把會議或公司「立起來」就是「安排 · 成立」，替兩個人牽線讓他們見面就是「介紹認識」。","v26/object":"set up a tent ○ · set it up ○ · set up it ✕。介紹用 set you up with my friend。","v26/examples.0.scene":"在露營地","v26/examples.0.ko":"我們在天黑前搭好帳篷吧。","v26/examples.1.scene":"對同事說","v26/examples.1.ko":"你可以幫我和客戶安排一場會議嗎？","v26/examples.2.scene":"朋友笑著說","v26/examples.2.ko":"我想介紹你和我表弟認識。","v26/similar":"install (安裝) · arrange (安排)","v26/quiz.0.options.0":"Jake 介紹我認識他的朋友。","v26/quiz.0.options.1":"Jake 把我立在他朋友旁邊。","v26/quiz.0.options.2":"Jake 讓我和他朋友吵架。","v26/quiz.0.options.3":"Jake 送我到他朋友家。","v26/quiz.0.why":"set A up with B 是把 A 介紹給 B 認識。","v26/quiz.1.ko":"你可以幫我裝新電腦嗎？","v26/quiz.1.why":"是立起來並準備好的 set up。","v26/quiz.2.q":"「我會介紹她和我弟弟認識。」用英文怎麼說？","v26/quiz.2.why":"代名詞 her 要放在 set 和 up 中間。","v27/meanings.0":"結果發現是～","v27/meanings.1":"(結果)變成～","v27/why":"turn(轉 · 翻) + out(向外顯露) → 翻過來一看，裡面露出來了 = 結果發現是～。事情全部進行完後顯露出的結果就是「變成～」。","v27/object":"不接受詞。It turned out (that) + 句子，turn out to be + 名詞，turn out well · fine。","v27/examples.0.scene":"查證謠言之後","v27/examples.0.ko":"結果那個謠言是假的。","v27/examples.1.scene":"談到剛認識的人","v27/examples.1.ko":"結果他人真的很好。","v27/examples.2.scene":"擔心的簡報結束後","v27/examples.2.ko":"結果一切都很順利。","v27/similar":"prove (證明是～) · end up (最後變成～)","v27/quiz.0.options.0":"結果那是非常美好的一天。","v27/quiz.0.options.1":"把非常美好的一天還給了我。","v27/quiz.0.options.2":"非常美好的一天被關掉了。","v27/quiz.0.options.3":"在外面度過了非常美好的一天。","v27/quiz.0.why":"是說出事情過後顯露出的結果的 turn out。","v27/quiz.1.ko":"考試比我想的還要簡單。","v27/quiz.1.why":"結果發現是～要用 turn out to be。","v27/quiz.2.ko":"結果他是 Leo 的兒子。","v27/quiz.2.why":"是 It turned out that + 句子。","v28/meanings.0":"長大 · 成年","v28/meanings.1":"成熟懂事","v28/why":"grow(成長) + up(向上) → 個子往上長高 = 長大成人。也可以用來叫人「成熟一點」，意思是要像大人一樣行事。","v28/object":"不接受詞。在哪裡長大用 grow up in + 地點。","v28/examples.0.scene":"聊起家鄉時","v28/examples.0.ko":"我在一個小鎮長大。","v28/examples.1.scene":"對孩子說","v28/examples.1.ko":"你長大後想做什麼？","v28/examples.2.scene":"對舉止幼稚的朋友說","v28/examples.2.ko":"成熟一點！","v28/similar":"be raised (被養大) · mature (成熟)","v28/quiz.0.options.0":"你在哪裡長大的？","v28/quiz.0.options.1":"你往哪裡上去了？","v28/quiz.0.options.2":"你在哪裡起床的？","v28/quiz.0.options.3":"你在哪裡養大的？","v28/quiz.0.why":"長大 · 成年是 grow up。","v28/quiz.1.ko":"我的孩子們長得太快了。","v28/quiz.1.why":"長大是 grow up。","v28/quiz.2.ko":"她在芝加哥長大。","v28/quiz.2.why":"城市像容器一樣，所以用 grow up in。","v29/meanings.0":"(仔細)檢查 · 看過一遍","v29/meanings.1":"(到某人家)過去坐坐","v29/why":"go(去) + over(覆蓋在上面越過) → 從頭到尾在上面掃過一遍 = 檢查。過馬路到某人家去就是「過去坐坐」(go over to Jake's)。","v29/object":"go over the notes ○ · go over it ○ (it 放在後面，go it over ✕)","v29/examples.0.scene":"考試前一天對朋友說","v29/examples.0.ko":"我們一起把筆記看一遍吧。","v29/examples.1.scene":"拿到合約時","v29/examples.1.ko":"我們得先仔細看一下這份合約。","v29/examples.2.scene":"練習完簡報後","v29/examples.2.ko":"我可以再檢查一次嗎？","v29/similar":"review (審閱) · check (確認)","v29/quiz.0.options.0":"可以請您幫我檢查報告嗎？","v29/quiz.0.options.1":"可以請您幫我跨過報告嗎？","v29/quiz.0.options.2":"可以請您幫我丟掉報告嗎？","v29/quiz.0.options.3":"可以請您幫我寫報告嗎？","v29/quiz.0.why":"是從頭到尾看過一遍的 go over。","v29/quiz.1.ko":"開會前我們再檢查一次計畫吧。","v29/quiz.1.why":"檢查是 go over。","v29/quiz.2.q":"「我們再看一遍吧。」用英文怎麼說？","v29/quiz.2.why":"go over 不能拆開用，所以 it 要放在 over 後面。","v30/meanings.0":"拒絕(提議)","v30/meanings.1":"調小(音量 · 溫度)","v30/why":"turn(轉) + down(減少 · 變弱) → 把旋鈕往下轉來調小。把提議往下壓就是「拒絕」。","v30/examples.0.scene":"鄰居在深夜說","v30/examples.0.ko":"可以請您把音樂調小聲一點嗎？","v30/examples.1.scene":"對拒絕了好提議的朋友說","v30/examples.1.ko":"你為什麼拒絕那份工作？","v30/examples.2.scene":"被邀約約會時","v30/examples.2.ko":"她禮貌地拒絕了他。","v30/similar":"refuse (拒絕) · lower (降低)","v30/opposite":"turn up (調大音量) · accept (接受)","v30/quiz.0.options.0":"他拒絕了那個提議。","v30/quiz.0.options.1":"他把那個提議調小了。","v30/quiz.0.options.2":"他接受了那個提議。","v30/quiz.0.options.3":"他推翻了那個提議。","v30/quiz.0.why":"是把提議往下壓的 turn down。","v30/quiz.1.ko":"太吵了。可以把 TV 的聲音調小嗎？","v30/quiz.1.why":"調小音量是 turn down。","v30/quiz.2.q":"「她拒絕了他。」用英文怎麼說？","v30/quiz.2.why":"代名詞 him 要放在 turned 和 down 中間。","v31/meanings.0":"指出(別人沒看到的事)","v31/why":"point(用手指指) + out(向外顯露) → 把別人沒看到的東西指出來、攤開 = 指出。","v31/object":"point out the mistake ○ · point it out ○ · point out it ✕ · point out that + 句子","v31/examples.0.scene":"開會時","v31/examples.0.ko":"我可以指出一個問題嗎？","v31/examples.1.scene":"導遊說","v31/examples.1.ko":"她指給我們看那座古老的教堂。","v31/examples.2.scene":"對指出錯誤的同事說","v31/examples.2.ko":"謝謝你指出來。","v31/similar":"mention (提到) · show (給看)","v31/quiz.0.options.0":"她指出了我的錯誤。","v31/quiz.0.options.1":"她隱藏了我的錯誤。","v31/quiz.0.options.2":"她改正了我的錯誤。","v31/quiz.0.options.3":"她模仿了我的錯誤。","v31/quiz.0.why":"是把沒看到的東西指出來的 point out。","v31/quiz.1.ko":"我想指出只剩兩天了。","v31/quiz.1.why":"指出來說是 point out。","v31/quiz.2.q":"「謝謝你指出來。」用英文怎麼說？","v31/quiz.2.why":"代名詞 it 要放在 pointing 和 out 中間。","v32/meanings.0":"迷上 · 愛上(某人)","v32/meanings.1":"被(花招)騙到","v32/why":"fall(掉落 · 倒下) + for(朝著那邊) → 整個人朝某人那邊倒下去 = 迷上。倒向謊言那邊就是「被騙到」。","v32/object":"fall for + 人 · 花招。不能拆開用：fall for him ○ · fall him for ✕","v32/examples.0.scene":"聽朋友說戀愛故事時","v32/examples.0.ko":"她第一次約會就迷上了他。","v32/examples.1.scene":"對上了愚人節惡作劇的朋友說","v32/examples.1.ko":"你居然被那個騙了！","v32/examples.2.scene":"看著廣告時","v32/examples.2.ko":"別被那種假廣告騙了。","v32/similar":"fall in love with (愛上) · be fooled by (被愚弄)","v32/quiz.0.options.0":"我好像迷上他了。","v32/quiz.0.options.1":"我好像會因為他而摔倒。","v32/quiz.0.options.2":"我好像會把他摔下去。","v32/quiz.0.options.3":"我好像會和他吵架。","v32/quiz.0.why":"是朝某人倒下去的 fall for，意思是迷上。","v32/quiz.1.ko":"別再被他的謊言騙了。","v32/quiz.1.why":"被騙是 fall for。","v32/quiz.2.ko":"她被他的魅力迷住了。","v32/quiz.2.why":"fall for 是一個整體。","v33/meanings.0":"變成～","v33/meanings.1":"(把 A)變成 B","v33/why":"turn(轉 · 變) + into(進到裡面) → 轉了一圈，進入另一種樣子 = 變成～。","v33/object":"A turn into B (A 變成 B)，turn A into B (把 A 變成 B)。turn into a frog ○","v33/examples.0.scene":"讀童話書給孩子聽時","v33/examples.0.ko":"青蛙變成了王子。","v33/examples.1.scene":"聊起週末時","v33/examples.1.ko":"簡單的晚餐變成了一場大派對。","v33/examples.2.scene":"整修房子的朋友說","v33/examples.2.ko":"他把車庫改成了工作室。","v33/similar":"become (成為) · change into (變成)","v33/quiz.0.options.0":"雨變成了雪。","v33/quiz.0.options.1":"雨走進了雪裡。","v33/quiz.0.options.2":"雨把雪關掉了。","v33/quiz.0.options.3":"雨把雪轉過去了。","v33/quiz.0.why":"是變成另一種樣子的 turn into。","v33/quiz.1.ko":"水在零度時會變成冰。","v33/quiz.1.why":"變成～是 turn into。","v33/quiz.2.ko":"他們把舊工廠改建成博物館。","v33/quiz.2.why":"是 turn A into B。","v34/meanings.0":"信賴 · 依靠","v34/meanings.1":"指望會～","v34/why":"count(算 · 算進去) + on(靠著並加上重量) → 把某人算進去，把重量壓在他身上 = 信賴 · 依靠。","v34/object":"count on + 人 · 事。不能拆開用：count on me ○ · count me on ✕。也可以用 count on + 人 + to do。","v34/examples.0.scene":"對請你幫忙搬家的朋友說","v34/examples.0.ko":"包在我身上。","v34/examples.1.scene":"組長在會議上說","v34/examples.1.ko":"我指望你把這件事完成。","v34/examples.2.scene":"野餐那天看著天空時","v34/examples.2.ko":"別指望天氣會好。","v34/similar":"rely on · depend on (依賴)","v34/quiz.0.options.0":"我就靠你了。","v34/quiz.0.options.1":"我在數你。","v34/quiz.0.options.2":"我在等你。","v34/quiz.0.options.3":"我在計算你。","v34/quiz.0.why":"是把重量壓在某人身上的 count on。","v34/quiz.1.ko":"家人是你隨時都可以信賴和依靠的。","v34/quiz.1.why":"信賴 · 依靠是 count on。","v34/quiz.2.q":"「你可以信賴我。」用英文怎麼說？","v34/quiz.2.why":"count on 不能拆開用，所以 me 要放在 on 後面。","v35/meanings.0":"回來","v35/meanings.1":"(記憶)重新浮現","v35/meanings.2":"再度流行","v35/why":"come(來) + back(回到原處) → 回到離開過的地方 = 回來。忘掉的記憶回來了就是「重新浮現」，過去的流行回來了就是「再度流行」。","v35/object":"不接受詞。回到哪裡用 come back to + 地點，回家是 come back home。","v35/examples.0.scene":"對要出差的家人說","v35/examples.0.ko":"你什麼時候回來？","v35/examples.1.scene":"看著老照片時","v35/examples.1.ko":"現在我全都想起來了。","v35/examples.2.scene":"在服飾店","v35/examples.2.ko":"寬褲管牛仔褲又流行起來了。","v35/similar":"return (返回) · go back (回去)","v35/quiz.0.options.0":"他上週從日本回來了。","v35/quiz.0.options.1":"他上週前往日本了。","v35/quiz.0.options.2":"他上週背棄了日本。","v35/quiz.0.options.3":"他上週打電話給日本了。","v35/quiz.0.why":"是回到原本地方的 come back。","v35/quiz.1.ko":"快點回來。我會想你的。","v35/quiz.1.why":"回來是 come back。","v35/quiz.2.ko":"我吃完午餐後就回辦公室。","v35/quiz.2.why":"回來的抵達點用 to。","v36/meanings.0":"(公司)收購 · 掌控","v36/meanings.1":"(工作)接手 · 代為負責","v36/why":"take(拿走) + over(從上方蓋住、掌控) → 從上面蓋住並拿到手 = 收購。把別人做到一半的事接過來蓋上自己的，就是「代為負責」。","v36/object":"take over the company ○ · take it over ○ · take over it ✕。單獨使用時是「接手」 (I'll take over.)","v36/examples.0.scene":"新聞主播說","v36/examples.0.ko":"大型科技公司收購了那家新創公司。","v36/examples.1.scene":"對開車開累的朋友說","v36/examples.1.ko":"你看起來很累。我來開吧。","v36/examples.2.scene":"要去度假的同事說","v36/examples.2.ko":"下週可以幫我接手我的專案嗎？","v36/similar":"buy (買下) · replace (取代)","v36/quiz.0.options.0":"Dana 去度假的話，誰來接手？","v36/quiz.0.options.1":"Dana 去度假的話，誰會翻過去？","v36/quiz.0.options.2":"Dana 去度假的話，誰會拿走？","v36/quiz.0.options.3":"Dana 去度假的話，誰來收尾？","v36/quiz.0.why":"這是接手別人做到一半的事的 take over。","v36/quiz.1.ko":"聽說一間韓國公司要收購我們工作室。","v36/quiz.1.why":"收購公司就是 take over。","v36/quiz.2.q":"「我來接手。」用英文怎麼說？","v36/quiz.2.why":"代名詞 it 要放在 take 和 over 之間。","v37/meanings.0":"(在字典 · 網路上)查詢","v37/meanings.1":"(抬頭)往上看","v37/meanings.2":"(情況)好轉","v37/why":"look(看) + up(向上) → 抬頭往上看。在字典 · 網路上找資料，像把資訊「拉到眼前」，就是查詢；情況朝上走就是「好轉」。","v37/examples.0.scene":"遇到不認識的單字時","v37/examples.0.ko":"我來查一下。","v37/examples.1.scene":"在星光閃爍的夜晚","v37/examples.1.ko":"往上看！看得到星星耶。","v37/examples.2.scene":"度過一段辛苦時光的朋友說","v37/examples.2.ko":"情況終於好轉了。","v37/similar":"search (搜尋) · check (確認)","v37/quiz.0.options.0":"我在字典裡查了那個單字。","v37/quiz.0.options.1":"我把那個單字放到字典上面。","v37/quiz.0.options.2":"我把那個單字從字典裡刪掉了。","v37/quiz.0.options.3":"我把那個單字寫進字典裡。","v37/quiz.0.why":"這是查詢資料的 look up。","v37/quiz.1.ko":"不知道地址的話就上網查。","v37/quiz.1.why":"代名詞 it 要放在 look 和 up 之間。","v37/quiz.2.ko":"辛苦的一年過去，情況終於好轉了。","v37/quiz.2.why":"這是情況朝上走的 look up。","v38/meanings.0":"(撐過困難的事)熬過去 · 做到最後","v38/meanings.1":"(電話)接通","v38/why":"get(去 · 到達) + through(從頭到尾穿過) → 把隧道一路穿到底 = 熬過艱難的時期。電話一路穿過去、連到對方，就是「接通」。","v38/object":"get through + 困難的事 (get through the week)。電話則是 get through to + 人。","v38/examples.0.scene":"對分手的朋友說","v38/examples.0.ko":"你一定能撐過這個的。","v38/examples.1.scene":"在趕工的那一週","v38/examples.1.ko":"只要撐過這一週就好。","v38/examples.2.scene":"打電話到客服中心時","v38/examples.2.ko":"終於接通客服中心了。","v38/similar":"survive (存活) · make it through (撐過去)","v38/quiz.0.options.0":"我們會一起撐過去的。","v38/quiz.0.options.1":"我們會一起走過這裡的。","v38/quiz.0.options.2":"我們會一起拿到這個的。","v38/quiz.0.options.3":"我們會一起選這個的。","v38/quiz.0.why":"這是把困難的事一路穿過去的 get through。","v38/quiz.1.ko":"我打了電話，但沒有打通她的。","v38/quiz.1.why":"電話接通就是 get through (to)。","v38/quiz.2.ko":"多虧咖啡，我才撐過一天。","v38/quiz.2.why":"這是撐完一整天的 get through。","v39/meanings.0":"(衣服 · 鞋子)穿上 · 戴上","v39/meanings.1":"(化妝品)塗抹","v39/meanings.2":"(體重)增加 (put on weight)","v39/why":"put(放) + on(貼在表面) → 放到身上貼住 = 穿上 · 戴上 · 塗抹。讓肉長在身上，就是「變胖」。","v39/object":"put on your coat ○ · put your coat on ○ · put it on ○ · put on it ✕。穿上的「動作」用 put on，穿著的「狀態」用 wear。","v39/examples.0.scene":"對要出門的孩子說","v39/examples.0.ko":"穿上外套。外面很冷。","v39/examples.1.scene":"在海邊","v39/examples.1.ko":"別忘了擦防曬乳。","v39/examples.2.scene":"連假結束後","v39/examples.2.ko":"連假期間我胖了三公斤。","v39/similar":"wear (穿著) · get dressed (穿好衣服)","v39/opposite":"take off (脫掉)","v39/quiz.0.options.0":"穿上鞋子。我們要出門了。","v39/quiz.0.options.1":"脫掉鞋子。我們要出門了。","v39/quiz.0.options.2":"把鞋子放下。我們要出門了。","v39/quiz.0.options.3":"去買鞋子。我們要出門了。","v39/quiz.0.why":"這是穿到身上的 put on。","v39/quiz.1.q":"She ___ a red dress today. (現在穿著的狀態)","v39/quiz.1.ko":"她今天穿著一件紅色洋裝。","v39/quiz.1.why":"穿著的狀態用 wear。put on 是穿上的動作。","v39/quiz.2.q":"「穿穿看那個！」用英文怎麼說？","v39/quiz.2.why":"代名詞 it 要放在 put 和 on 之間。","v40/meanings.0":"(和睦地)相處融洽","v40/meanings.1":"勉強過得去","v40/why":"get(變成 · 前進) + along(並肩跟著一起) → 沿著同一條路並肩同行 = 和睦相處。","v40/object":"不接受詞，要說跟誰就用 get along with + 人。英式英語也會用 get on。","v40/examples.0.scene":"談到新室友時","v40/examples.0.ko":"我們真的處得很好。","v40/examples.1.scene":"問朋友兄弟感情如何時","v40/examples.1.ko":"你和你弟弟感情好嗎？","v40/examples.2.scene":"孩子們吵架時","v40/examples.2.ko":"你們兩個就不能好好相處嗎？","v40/similar":"be friends (成為朋友) · get on (英式：相處融洽)","v40/quiz.0.options.0":"我和我的老闆處得不好。","v40/quiz.0.options.1":"我不跟著我的老闆走。","v40/quiz.0.options.2":"我不跟我的老闆見面。","v40/quiz.0.options.3":"我不去老闆那裡。","v40/quiz.0.why":"這是和睦相處的 get along。","v40/quiz.1.ko":"Jake 和 Rosa 處得很好。","v40/quiz.1.why":"相處融洽就是 get along。","v40/quiz.2.ko":"你和鄰居處得好嗎？","v40/quiz.2.why":"跟誰相處要用 get along with。","v41/meanings.0":"(做決定前)仔細考慮","v41/why":"think(想) + over(從頭到尾覆蓋過一遍) → 把問題從頭到尾來回掃過，仔細思考。做決定之前花時間想的時候會用。","v41/examples.0.scene":"收到提議時","v41/examples.0.ko":"我可以考慮一下嗎？","v41/examples.1.scene":"對面臨重要決定的朋友說","v41/examples.1.ko":"慢慢想吧。","v41/examples.2.scene":"面試結束後，面試官說","v41/examples.2.ko":"我們會好好審閱你的履歷。","v41/similar":"consider (考慮) · sleep on it (睡一晚再想)","v41/quiz.0.options.0":"我得仔細考慮一下。","v41/quiz.0.options.1":"我得把它跳過去。","v41/quiz.0.options.2":"我得把它忘掉。","v41/quiz.0.options.3":"我得把它做完。","v41/quiz.0.why":"這是仔細把問題想過一遍的 think over。","v41/quiz.1.ko":"這是個重大決定。回答之前先仔細想想。","v41/quiz.1.why":"代名詞 it 要放在 think 和 over 之間。","v41/quiz.2.ko":"她要求一星期的時間來考慮這個提議。","v41/quiz.2.why":"仔細考慮就是 think over。","v42/meanings.0":"(話題)提起","v42/meanings.1":"(孩子)養大","v42/why":"bring(帶來) + up(向上 · 出現在眼前) → 把埋著的話題拉上來提出。把孩子往上一路養大，就是「撫養」(與 grow up 成對)。","v42/object":"bring up the topic ○ · bring it up ○ · bring up it ✕。「養大」常像 She was brought up in Busan. 這樣用被動語態。","v42/examples.0.scene":"會議快結束時","v42/examples.0.ko":"我還想再提一件事。","v42/examples.1.scene":"氣氛變得尷尬時","v42/examples.1.ko":"你為什麼要提那件事？","v42/examples.2.scene":"談到奶奶時","v42/examples.2.ko":"我是被奶奶帶大的。","v42/similar":"mention (提到) · raise (提出 · 養大)","v42/quiz.0.options.0":"別提他的前女友。","v42/quiz.0.options.1":"別把他的前女友帶來。","v42/quiz.0.options.2":"別養他的前女友。","v42/quiz.0.options.3":"別去找他的前女友。","v42/quiz.0.why":"這是把話題拉上來提出的 bring up。","v42/quiz.1.ko":"她在一個小鎮長大。","v42/quiz.1.why":"被養大就是 be brought up。","v42/quiz.2.q":"「別提那件事。」用英文怎麼說？","v42/quiz.2.why":"代名詞 it 要放在 bring 和 up 之間。","v43/meanings.0":"(順道)拜訪一下","v43/why":"drop(輕輕落下) + by(就在旁邊) → 順路像輕輕落在某人身旁一樣去一下 = 順道拜訪。給人沒有事先約好、輕鬆造訪的感覺。","v43/object":"不接受詞，或用 drop by + 地點 (drop by the office)。","v43/examples.0.scene":"對下班路上的朋友說","v43/examples.0.ko":"下班後來咖啡廳坐一下吧！","v43/examples.1.scene":"鄰居在門口說","v43/examples.1.ko":"我只是來打聲招呼。","v43/examples.2.scene":"教授在下課時說","v43/examples.2.ko":"你隨時都可以來研究室找我。","v43/similar":"stop by (順道拜訪) · drop in (臨時登門) · visit (拜訪)","v43/quiz.0.options.0":"我今晚可以順道過去一下嗎？","v43/quiz.0.options.1":"我今晚可以把它掉下去嗎？","v43/quiz.0.options.2":"我今晚可以讓你下車嗎？","v43/quiz.0.options.3":"我今晚可以待在旁邊嗎？","v43/quiz.0.why":"這是輕鬆順道拜訪的 drop by。","v43/quiz.1.ko":"我回家路上會順道去你家。","v43/quiz.1.why":"順道拜訪就是 drop by。","v43/quiz.2.ko":"她來是為了送湯給我。","v43/quiz.2.why":"drop by 要當成一個整體。","v44/meanings.0":"(放手)試試看 · 挑戰","v44/meanings.1":"(從好幾個選項中)選","v44/why":"go(去) + for(朝著想要的東西) → 朝著想要的東西毫不猶豫地走去 = 挑戰。在菜單上朝想要的那一項走去，就是「選」。","v44/object":"像 Go for it! 這樣單獨使用，或用 go for + 名詞 (go for the steak, go for the job)。","v44/examples.0.scene":"對猶豫要不要去試鏡的朋友說","v44/examples.0.ko":"去試試看吧！","v44/examples.1.scene":"在餐廳點餐時","v44/examples.1.ko":"我要點義大利麵。","v44/examples.2.scene":"面對升遷的機會時","v44/examples.2.ko":"她決定爭取經理的職位。","v44/similar":"try (試試) · choose (選擇)","v44/quiz.0.options.0":"如果你想做那份工作，就放手去試吧！","v44/quiz.0.options.1":"如果你想做那份工作，就去那裡吧！","v44/quiz.0.options.2":"如果你想做那份工作，就為它等待吧！","v44/quiz.0.options.3":"如果你想做那份工作，就放棄吧！","v44/quiz.0.why":"這是朝著想要的東西前進的 go for。","v44/quiz.1.ko":"咖啡？茶？ — 我要茶，謝謝。","v44/quiz.1.why":"選擇就是 go for。","v44/quiz.2.ko":"人生只有一次。去挑戰吧！","v44/quiz.2.why":"Go for it! 是固定說法。","v45/meanings.0":"(追上前面的人)趕上","v45/meanings.1":"(落後的進度)趕上","v45/meanings.2":"(聊聊近況)敘舊","v45/why":"catch(抓住) + up(緊貼靠近) → 緊貼著跑在前面的人並抓住他 = 追上。追上累積的工作 · 消息，就是「趕進度 · 敘舊」。","v45/object":"單獨使用，或用 catch up with + 人、catch up on + 事情 · 消息。","v45/examples.0.scene":"落在後面的朋友說","v45/examples.0.ko":"等一下！我馬上跟上！","v45/examples.1.scene":"對好久不見的朋友說","v45/examples.1.ko":"我們邊喝咖啡邊聊聊近況吧。","v45/examples.2.scene":"休假回來後","v45/examples.2.ko":"我得先把積壓的電子郵件處理掉。","v45/similar":"keep up (跟上) · reconnect (重新聯絡)","v45/quiz.0.options.0":"好久不見啊！我們改天聊聊近況吧。","v45/quiz.0.options.1":"好久不見啊！我們改天去抓它吧。","v45/quiz.0.options.2":"好久不見啊！我們改天起床吧。","v45/quiz.0.options.3":"好久不見啊！我們改天放棄吧。","v45/quiz.0.why":"這是趕上累積消息的 catch up。","v45/quiz.1.ko":"你走太快了！我跟不上。","v45/quiz.1.why":"追上就是 catch up (with)。","v45/quiz.2.ko":"星期天我把欠的覺補回來了。","v45/quiz.2.why":"積壓的事 · 睡眠要用 catch up on。","v46/meanings.0":"閉嘴 · 住口 (無禮的說法)","v46/meanings.1":"(驚訝地)不會吧！ (熟人之間的口語)","v46/why":"shut(關上) + up(到底 · 完全) → 把嘴巴緊緊閉上 = 閉嘴。朋友之間聽到驚人的消息，笑著說 Shut up!，就是「不會吧！」這種開心的驚訝。","v46/object":"單獨使用，或用 shut someone up。大多像 Shut up! 這樣當命令用。","v46/tip":"Shut up! 可能是「閉嘴」這種非常無禮的話。表示驚訝的用法只在熟人之間、笑著說。要禮貌地請人安靜時，要說 Please be quiet.。","v46/examples.0.scene":"聽到難以置信的消息，朋友笑著說","v46/examples.0.ko":"不會吧！你錄取了？","v46/examples.1.scene":"電影裡的反派大吼","v46/examples.1.ko":"閉嘴聽著！","v46/examples.2.scene":"面對一直吠叫的小狗","v46/examples.2.ko":"那隻狗誰都拿它沒辦法。","v46/similar":"be quiet (安靜) · no way (不可能)","v46/quiz.0.q":"(朋友笑著說) Shut up! Are you serious?","v46/quiz.0.options.0":"不會吧！真的嗎？","v46/quiz.0.options.1":"把門關上！真的嗎？","v46/quiz.0.options.2":"起來！真的嗎？","v46/quiz.0.options.3":"安靜念書！真的嗎？","v46/quiz.0.why":"笑著說的 Shut up! 是開心的驚訝。","v46/quiz.1.q":"(在圖書館禮貌地說) ___, please.","v46/quiz.1.why":"禮貌的說法是 Be quiet。Shut up 聽起來很無禮。","v46/quiz.2.ko":"他一直說個不停，所以我叫他閉嘴。","v46/quiz.2.why":"閉嘴就是 shut up。","v47/meanings.0":"(問題)解決","v47/meanings.1":"(東西 · 事情)整理","v47/why":"sort(按種類分開) + out(到底 · 完全) → 把混在一起的東西徹底分開整理 = 整理 · 解決。","v47/examples.0.scene":"對吵架的兩位同事說","v47/examples.0.ko":"你們兩位得把這件事解決。","v47/examples.1.scene":"在搬家的箱子前","v47/examples.1.ko":"我們來整理這些箱子吧。","v47/examples.2.scene":"發現算錯了時","v47/examples.2.ko":"別擔心，我來處理。","v47/similar":"solve (解決) · organize (整理) · figure out (弄清楚)","v47/quiz.0.options.0":"我得把行程整理好。","v47/quiz.0.options.1":"我得把行程丟到外面。","v47/quiz.0.options.2":"我得把行程延後。","v47/quiz.0.options.3":"我得找行程。","v47/quiz.0.why":"這是徹底分開整理的 sort out。","v47/quiz.1.ko":"訂單有問題，我們會處理。","v47/quiz.1.why":"代名詞 it 要放在 sort 和 out 之間。","v47/quiz.2.q":"「我來處理。」用英文怎麼說？","v47/quiz.2.why":"代名詞 it 要放在 sort 和 out 之間。","v48/meanings.0":"(聲音 · 溫度)調大 · 調高","v48/meanings.1":"(突然)出現","v48/why":"turn(轉) + up(向上 · 增加) → 把旋鈕往上轉而調大。從意想不到的地方冒出來，就是「突然出現」。","v48/object":"turn up the music ○ · turn it up ○ · turn up it ✕。「出現」不接受詞 (He turned up late)。","v48/examples.0.scene":"聽到喜歡的歌時","v48/examples.0.ko":"音量調大！我喜歡這首歌！","v48/examples.1.scene":"在很冷的辦公室裡","v48/examples.1.ko":"可以把暖氣調高一點嗎？","v48/examples.2.scene":"找到弄丟的鑰匙後","v48/examples.2.ko":"鑰匙居然在冰箱裡冒出來了！","v48/similar":"raise (提高) · show up (出現)","v48/opposite":"turn down (調小)","v48/quiz.0.options.0":"把音量調大。","v48/quiz.0.options.1":"把音量調小。","v48/quiz.0.options.2":"把音量關掉。","v48/quiz.0.options.3":"把音量換掉。","v48/quiz.0.why":"這是把旋鈕往上轉的 turn up。","v48/quiz.1.ko":"太冷了。可以把暖氣調高一點嗎？","v48/quiz.1.why":"把溫度調高就是 turn up。","v48/quiz.2.q":"「把它的音量調大一點。」用英文怎麼說？","v48/quiz.2.why":"代名詞 it 要放在 turn 和 up 之間。","v49/meanings.0":"昏倒 · 失去意識","v49/meanings.1":"(分給大家)發放","v49/why":"pass(經過) + out(出去 · 消失) → 意識從身體裡溜走消失 = 昏倒。把東西一個個送到大家手上，就是「發放」。","v49/object":"昏倒不接受詞。發放則是 pass out the papers ○ · pass them out ○","v49/examples.0.scene":"在大熱天排隊時","v49/examples.0.ko":"我熱得差點昏倒。","v49/examples.1.scene":"在捐血處，護理師說","v49/examples.1.ko":"也有人一看到血就會昏倒。","v49/examples.2.scene":"老師在考試前說","v49/examples.2.ko":"現在我要發考卷了。","v49/similar":"faint (昏倒) · hand out (發放)","v49/quiz.0.options.0":"他中暑昏倒了。","v49/quiz.0.options.1":"他走過了暑熱。","v49/quiz.0.options.2":"他把暑熱分給了大家。","v49/quiz.0.options.3":"他躲開暑熱走了出去。","v49/quiz.0.why":"這是意識溜走的 pass out。","v49/quiz.1.ko":"請把這些傳單發給每個人。","v49/quiz.1.why":"發放就是 pass out。pass away 是「過世」。","v49/quiz.2.ko":"我太累了，在沙發上睡死了。","v49/quiz.2.why":"像失去意識般睡著，也是 pass out。","v50/meanings.0":"(在某地)定居 · 安頓下來","v50/meanings.1":"冷靜下來 · 平靜下來","v50/why":"settle(安頓) + down(往下沉、固定) → 四處漂泊的東西往下沉、安頓下來 = 定居。浮躁的心沉澱下來，就是「冷靜下來」。","v50/object":"不接受詞。要說在哪裡，用 settle down in + 地點。","v50/examples.0.scene":"對很常旅行的朋友說","v50/examples.0.ko":"我想現在該定下來了。","v50/examples.1.scene":"在吵鬧的教室裡","v50/examples.1.ko":"好了，各位同學，安靜下來。","v50/examples.2.scene":"搬家後被問近況時","v50/examples.2.ko":"我已經在新家安頓下來了。","v50/similar":"calm down (冷靜下來) · put down roots (扎根)","v50/quiz.0.options.0":"他們在一個小鎮定居了。","v50/quiz.0.options.1":"他們在一個小鎮坐了下來。","v50/quiz.0.options.2":"他們離開了一個小鎮。","v50/quiz.0.options.3":"他們整理了一個小鎮。","v50/quiz.0.why":"這是沉下來安頓的 settle down。","v50/quiz.1.ko":"孩子們原本很興奮，但終於平靜下來了。","v50/quiz.1.why":"這是浮躁的心沉澱下來的 settle down。","v50/quiz.2.ko":"旅行了好幾年後，他在首爾定居了。","v50/quiz.2.why":"城市像個容器，所以用 settle down in。","v51/meanings.0":"(到某人家)來玩 · 過來","v51/why":"come(來) + over(越過) → 越過路 · 距離，來到這一邊 = 來我家玩。","v51/object":"不接受詞。像 come over to my place、come over for dinner 這樣說。","v51/examples.0.scene":"傳訊息給朋友說","v51/examples.0.ko":"今晚要不要來我家？","v51/examples.1.scene":"剛搬新家的朋友說","v51/examples.1.ko":"星期五來吃晚餐吧！","v51/examples.2.scene":"對沒赴約的朋友說","v51/examples.2.ko":"你昨天為什麼沒來？","v51/similar":"drop by (順道拜訪) · visit (拜訪)","v51/quiz.0.options.0":"下班後你可以來我家嗎？","v51/quiz.0.options.1":"下班後你可以跌倒嗎？","v51/quiz.0.options.2":"下班後你可以結束嗎？","v51/quiz.0.options.3":"下班後你可以離開嗎？","v51/quiz.0.why":"這是越過來這一邊的 come over。","v51/quiz.1.ko":"今晚朋友們要來吃晚餐。","v51/quiz.1.why":"來玩就是 come over。","v51/quiz.2.ko":"這個週末來我家玩吧。","v51/quiz.2.why":"來到的目的地用 to。","v52/meanings.0":"(活動 · 事情)開始","v52/meanings.1":"(足球)開球","v52/why":"kick(踢) + off(離開 · 出發) → 把球踢出去，讓比賽出發 = 開始。源自足球，開會 · 專案 · 活動開始時也能用。","v52/object":"kick off the meeting ○ · kick it off ○。單獨使用是「開始」 (The game kicks off at 7).","v52/examples.0.scene":"組長開始開會時說","v52/examples.0.ko":"我們開始開會吧。","v52/examples.1.scene":"在足球轉播中","v52/examples.1.ko":"比賽晚上七點開始。","v52/examples.2.scene":"新專案的第一天","v52/examples.2.ko":"我們要用團隊午餐為專案揭開序幕。","v52/similar":"start (開始) · launch (推出 · 開始)","v52/quiz.0.options.0":"慶典下週五開始。","v52/quiz.0.options.1":"慶典下週五結束。","v52/quiz.0.options.2":"慶典下週五取消。","v52/quiz.0.options.3":"慶典延到下週五。","v52/quiz.0.why":"讓事情出發的 kick off 就是開始。","v52/quiz.1.ko":"我們用好消息來開始會議吧。","v52/quiz.1.why":"開始就是 kick off。call off 是「取消」。","v52/quiz.2.ko":"比賽八點開始。","v52/quiz.2.why":"kick off 要當成一個整體。","v53/meanings.0":"丟掉","v53/meanings.1":"(機會)白白浪費","v53/why":"throw(丟) + away(遠遠地) → 丟得遠遠的 = 丟掉。把機會丟得遠遠的，就是「白白浪費」。","v53/examples.0.scene":"在打包搬家行李時","v53/examples.0.ko":"這些舊雜誌要丟掉嗎？","v53/examples.1.scene":"媽媽對孩子說","v53/examples.1.ko":"不要把垃圾丟在路上。","v53/examples.2.scene":"對拒絕了好提議的朋友說","v53/examples.2.ko":"你正在浪費一個好機會。","v53/similar":"throw out (丟掉) · get rid of (擺脫)","v53/opposite":"keep (留著)","v53/quiz.0.options.0":"不要丟掉收據。","v53/quiz.0.options.1":"不要丟收據。","v53/quiz.0.options.2":"不要弄丟收據。","v53/quiz.0.options.3":"不要寄收據。","v53/quiz.0.why":"這是遠遠丟掉的 throw away。","v53/quiz.1.ko":"這牛奶過期了。丟掉吧。","v53/quiz.1.why":"代名詞 it 要放在 throw 和 away 之間。","v53/quiz.2.ko":"他白白浪費了獲勝的機會。","v53/quiz.2.why":"白白浪費機會就是 throw away。","v54/meanings.0":"四處看看 · 逛逛","v54/meanings.1":"(往後)回頭看","v54/why":"look(看) + around(繞一圈 · 到處) → 頭轉一圈到處看 = 四處看看。轉身往後看，就是「回頭看」。","v54/object":"單獨使用，或用 look around + 地點 (look around the apartment)。","v54/examples.0.scene":"服飾店店員問要不要幫忙時","v54/examples.0.ko":"謝謝，我只是隨便看看。","v54/examples.1.scene":"去看房子時","v54/examples.1.ko":"我可以到處看看這間房子嗎？","v54/examples.2.scene":"聽到有人叫名字時","v54/examples.2.ko":"她回頭看了，但一個人也沒有。","v54/similar":"browse (隨意瀏覽) · look back (回頭看)","v54/quiz.0.options.0":"需要幫忙嗎？ — 不用，我只是隨便看看。","v54/quiz.0.options.1":"需要幫忙嗎？ — 不用，我只是在找東西。","v54/quiz.0.options.2":"需要幫忙嗎？ — 不用，我只是要回去。","v54/quiz.0.options.3":"需要幫忙嗎？ — 不用，我只是在等。","v54/quiz.0.why":"到處看看的 look around 就是隨便逛逛。","v54/quiz.1.ko":"決定之前，我們先逛逛這一帶吧。","v54/quiz.1.why":"四處看看就是 look around。","v54/quiz.2.ko":"我有一個小時。我們去逛逛市場吧。","v54/quiz.2.why":"這是到處逛逛的 look around。","v55/meanings.0":"(機器)故障","v55/meanings.1":"(情緒)崩潰大哭","v55/meanings.2":"(細細地)拆解","v55/why":"break(破裂) + down(往下) → 破裂後往下垮掉。機器垮了就是「故障」，心垮了就是「崩潰大哭」，把大塊頭往下一層層拆開，就是「拆解」。","v55/object":"故障 · 哭泣不接受詞。拆解則是 break down the problem ○ · break it down ○","v55/examples.0.scene":"在高速公路上","v55/examples.0.ko":"我的車在高速公路上拋錨了。","v55/examples.1.scene":"聽到壞消息後","v55/examples.1.ko":"她崩潰大哭了。","v55/examples.2.scene":"看著很難的數學題時","v55/examples.2.ko":"我們把它拆成小步驟吧。","v55/similar":"stop working (停止運作) · burst into tears (放聲大哭)","v55/quiz.0.options.0":"電梯又故障了。","v55/quiz.0.options.1":"電梯又下去了。","v55/quiz.0.options.2":"電梯又變乾淨了。","v55/quiz.0.options.3":"電梯又客滿了。","v55/quiz.0.why":"機器垮掉的 break down 就是故障。","v55/quiz.1.ko":"聽到那個消息，他崩潰大哭了。","v55/quiz.1.why":"情緒垮掉就是 break down。","v55/quiz.2.q":"「我們把它拆成小步驟吧。」用英文怎麼說？","v55/quiz.2.why":"代名詞 it 要放在 break 和 down 之間。","v56/meanings.0":"(融入群體)合群 · 融入","v56/meanings.1":"(空間 · 行程)放得進去 · 排進去","v56/why":"fit(剛好合適) + in(裡面) → 剛好放進裡面。合乎空間地放進去，就是「放得進去」；剛好適合待在一群人當中，就是「合群」。","v56/object":"合群不接受詞 (fit in with + 人)。排進去則是 fit you in ○ · fit in a meeting ○","v56/examples.0.scene":"轉學來的孩子說","v56/examples.0.ko":"我擔心在新學校融入不了。","v56/examples.1.scene":"在搬運搬家行李時","v56/examples.1.ko":"這張沙發放得進電梯嗎？","v56/examples.2.scene":"在忙碌的醫院櫃檯","v56/examples.2.ko":"我可以幫您排在下午三點。","v56/similar":"belong (屬於 · 合群) · get along (相處融洽)","v56/quiz.0.options.0":"她馬上就融入了團隊。","v56/quiz.0.options.1":"她馬上就換了團隊。","v56/quiz.0.options.2":"她馬上就離開了團隊。","v56/quiz.0.options.3":"她馬上就對團隊發了脾氣。","v56/quiz.0.why":"這是剛好放進群體裡的 fit in。","v56/quiz.1.ko":"這張桌子放得進車子裡嗎？","v56/quiz.1.why":"放進空間就是 fit in。","v56/quiz.2.ko":"醫生雖然很忙，但明天可以排時間給你。","v56/quiz.2.why":"幫人排進行程就是 fit someone in。","v57/meanings.0":"小心 · 留意","v57/why":"watch(注視) + out(向外) → 眼睛睜大往外四處察看 = 小心！危險逼近時會喊的話。","v57/object":"像 Watch out! 這樣單獨使用，要小心的對象則用 watch out for + 名詞。","v57/examples.0.scene":"腳踏車靠近時","v57/examples.0.ko":"小心！腳踏車來了！","v57/examples.1.scene":"冬天早晨的上班路上","v57/examples.1.ko":"小心路上的冰。","v57/examples.2.scene":"在搬運搬家行李時","v57/examples.2.ko":"小心。這個箱子很重。","v57/similar":"look out (小心) · be careful (小心)","v57/quiz.0.options.0":"小心！地板是濕的。","v57/quiz.0.options.1":"往外看！地板是濕的。","v57/quiz.0.options.2":"出去！地板是濕的。","v57/quiz.0.options.3":"看著！地板是濕的。","v57/quiz.0.why":"這是提醒危險的 Watch out!。","v57/quiz.1.ko":"在人多的地方要小心扒手。","v57/quiz.1.why":"小心就是 watch out。","v57/quiz.2.ko":"過馬路時要小心車子。","v57/quiz.2.why":"要小心的對象要用 watch out for。","v58/meanings.0":"(從睡夢中)醒來","v58/meanings.1":"(把別人)叫醒","v58/why":"wake(醒) + up(向上) → 意識從睡眠的底部往上浮起 = 醒來。把別人往上拉起，就是「叫醒」。","v58/object":"單獨使用是醒來，有受詞就是叫醒：wake me up ○ · wake up me ✕。過去式是 woke up。","v58/tip":"wake up 是從睡夢中醒來，get up 是離開床起身。I woke up at 6 but got up at 7.","v58/examples.0.scene":"對睡過頭的朋友說","v58/examples.0.ko":"你幾點醒的？","v58/examples.1.scene":"拜託室友時","v58/examples.1.ko":"七點可以叫我起床嗎？","v58/examples.2.scene":"半夜聽到聲音時","v58/examples.2.ko":"我被很大的聲音吵醒了。","v58/similar":"get up (起床 · 離開床)","v58/quiz.0.options.0":"寶寶半夜醒來了。","v58/quiz.0.options.1":"寶寶半夜站起來了。","v58/quiz.0.options.2":"寶寶半夜哭了。","v58/quiz.0.options.3":"寶寶半夜睡著了。","v58/quiz.0.why":"這是從睡夢中醒來的 wake up。","v58/quiz.1.q":"「九點前別叫醒我。」用英文怎麼說？","v58/quiz.1.why":"代名詞 me 要放在 wake 和 up 之間。","v58/quiz.2.ko":"我六點醒了，但到七點才起床。","v58/quiz.2.why":"從睡夢中醒來是 woke up。get up 是離開床。","v59/meanings.0":"照顧 · 看顧","v59/why":"look(看) + after(跟在後面) → 跟在某人後面一直看著 = 照顧。照料孩子 · 動物 · 生病的人 · 東西時會用。","v59/object":"look after + 人 · 動物。不拆開用：look after her ○ · look her after ✕","v59/examples.0.scene":"對要去旅行的鄰居說","v59/examples.0.ko":"你不在的時候，我會幫你照顧貓。","v59/examples.1.scene":"對感冒的朋友說","v59/examples.1.ko":"好好照顧自己。","v59/examples.2.scene":"託人帶孩子後來接孩子時","v59/examples.2.ko":"謝謝你幫我看孩子。","v59/similar":"take care of (照顧) · care for (照料)","v59/quiz.0.options.0":"誰來照顧小狗？","v59/quiz.0.options.1":"誰來找小狗？","v59/quiz.0.options.2":"誰跟著小狗？","v59/quiz.0.options.3":"誰來買小狗？","v59/quiz.0.why":"跟在後面看著的 look after 就是照顧。","v59/quiz.1.ko":"我小時候是奶奶照顧我的。","v59/quiz.1.why":"照顧就是 look after。","v59/quiz.2.q":"「好好照顧自己。」用英文怎麼說？","v59/quiz.2.why":"look after 不拆開用。","v60/meanings.0":"偶然發現 · 碰見","v60/meanings.1":"給人(~的)印象 (come across as)","v60/why":"come(來) + across(橫越) → 走在路上橫越時剛好撞見某樣東西 = 偶然發現。自己的樣子橫越過去傳到對方那裡，就是「給人~的印象」。","v60/object":"come across + 東西 · 人。不拆開用：come across it ○ · come it across ✕。印象則用 come across as + 名詞 · 形容詞。","v60/examples.0.scene":"整理搬家行李時","v60/examples.0.ko":"我們翻到了以前的舊照片。","v60/examples.1.scene":"在二手書店","v60/examples.1.ko":"我偶然發現了這本書。","v60/examples.2.scene":"談到面試時","v60/examples.2.ko":"他看起來非常有自信。","v60/similar":"find by chance (偶然找到) · run into (偶遇)","v60/quiz.0.options.0":"我在舊筆記本裡發現了你的名字。","v60/quiz.0.options.1":"我在舊筆記本上橫著寫了你的名字。","v60/quiz.0.options.2":"我把你的名字從舊筆記本裡擦掉了。","v60/quiz.0.options.3":"我到處找你在舊筆記本裡的名字。","v60/quiz.0.why":"橫越而碰見的 come across 就是偶然發現。","v60/quiz.1.ko":"如果你碰巧看到我的鑰匙，請告訴我。","v60/quiz.1.why":"偶然發現就是 come across。","v60/quiz.2.ko":"她給人一種親切的印象。","v60/quiz.2.why":"給人印象就是 come across as。","v61/meanings.0":"(~)用完了 · 耗盡","v61/why":"run(流動) + out(流到外面、見底) → 擁有的東西流光、見底 = 用完。of 後面接用完的東西。","v61/object":"run out of + 名詞。單獨使用則像 Time is running out.(時間不多了)","v61/examples.0.scene":"打開冰箱時","v61/examples.0.ko":"牛奶喝完了。","v61/examples.1.scene":"加油警示燈亮起時","v61/examples.1.ko":"油快用完了。","v61/examples.2.scene":"考完試走出來後","v61/examples.2.ko":"最後一題時間不夠了。","v61/similar":"be out of (用完了) · use up (用光)","v61/quiz.0.options.0":"咖啡喝完了。","v61/quiz.0.options.1":"我在外面喝了咖啡。","v61/quiz.0.options.2":"我把咖啡灑了。","v61/quiz.0.options.3":"我跑去買咖啡。","v61/quiz.0.why":"流光見底的 run out of。","v61/quiz.1.ko":"快點！時間不多了。","v61/quiz.1.why":"什麼東西用完，要用 run out of。","v61/quiz.2.ko":"手機電量快用完了。","v61/quiz.2.why":"快用完了就是 running out of。","v62/meanings.0":"減速 · 放慢","v62/meanings.1":"(把忙碌的生活)放慢步調","v62/why":"slow(慢的) + down(降低 · 向下) → 把速度的刻度往下調 = 放慢。把忙碌生活的速度調低，就是「放慢步調」。","v62/object":"單獨使用，或用 slow down the car ○ · slow it down ○","v62/examples.0.scene":"對走很快的朋友說","v62/examples.0.ko":"慢一點！我跟不上。","v62/examples.1.scene":"在駕駛座旁","v62/examples.1.ko":"減速。這裡有學校。","v62/examples.2.scene":"對只顧著工作的朋友說","v62/examples.2.ko":"你得放慢步調，好好休息一下。","v62/similar":"take it easy (放輕鬆)","v62/opposite":"speed up (加速)","v62/quiz.0.options.0":"減速！你開太快了。","v62/quiz.0.options.1":"下去！你開太快了。","v62/quiz.0.options.2":"坐下！你開太快了。","v62/quiz.0.options.3":"回去！你開太快了。","v62/quiz.0.why":"這是把速度往下調的 slow down。","v62/quiz.1.ko":"可以說慢一點嗎？我聽不懂。","v62/quiz.1.why":"放慢就是 slow down。","v62/quiz.2.ko":"醫生叫他放慢步調、好好休息。","v62/quiz.2.why":"slow down 要當成一個整體。","v63/meanings.0":"(開車)載到某處放下","v63/meanings.1":"(把東西)送過去 · 交給","v63/meanings.2":"打瞌睡","v63/why":"drop(使落下) + off(離開) → 讓人從車上下來、放在某處 = 載到某處放下。把東西丟在某個地方，就是「送過去」。和 pick up(接人，片語動詞第 1 個)相反。","v63/examples.0.scene":"上班路上對朋友說","v63/examples.0.ko":"我載你到車站。","v63/examples.1.scene":"在洗衣店前","v63/examples.1.ko":"我有衣服要送去乾洗。","v63/examples.2.scene":"在沙發上看電視時","v63/examples.2.ko":"我看電影看到睡著了。","v63/similar":"leave (留下)","v63/opposite":"pick up (接人 · 取回)","v63/quiz.0.options.0":"你可以載我到公司嗎？","v63/quiz.0.options.1":"你可以在公司把我丟下嗎？","v63/quiz.0.options.2":"你可以到公司來接我嗎？","v63/quiz.0.options.3":"你可以讓我辭掉公司嗎？","v63/quiz.0.why":"這是從車上放人下來的 drop off。","v63/quiz.1.ko":"我會把包裹送到郵局。","v63/quiz.1.why":"把東西送過去就是 drop off。","v63/quiz.2.q":"「我載你到車站。」用英文怎麼說？","v63/quiz.2.why":"代名詞 you 要放在 drop 和 off 之間。","v64/meanings.0":"(炫耀地)賣弄 · 愛現","v64/meanings.1":"(讓人更顯眼地)展現出來","v64/why":"show(給人看) + off(脫離出來) → 從眾人之中跳出來，顯眼地亮給人看 = 炫耀。單獨使用就是「愛現」。","v64/object":"單獨使用就是愛現 (Stop showing off!)。東西則是 show off his new car ○ · show it off ○","v64/examples.0.scene":"對帶著新吉他來的朋友說","v64/examples.0.ko":"你是在炫耀你的新吉他嗎？","v64/examples.1.scene":"對在泳池跳水的弟弟說","v64/examples.1.ko":"不要再愛現了！","v64/examples.2.scene":"服飾店店員說","v64/examples.2.ko":"這件洋裝真的很能襯托您的風格。","v64/similar":"brag (吹噓)","v64/quiz.0.options.0":"他老是愛現。","v64/quiz.0.options.1":"他老是很晚才出現。","v64/quiz.0.options.2":"他老是把電視關掉。","v64/quiz.0.options.3":"他老是很親切。","v64/quiz.0.why":"單獨使用的 show off 就是愛現。","v64/quiz.1.ko":"她向每個人炫耀她的新戒指。","v64/quiz.1.why":"炫耀就是 show off。","v64/quiz.2.ko":"別再愛現了。沒有人在意。","v64/quiz.2.why":"show off 要當成一個整體。","v65/meanings.0":"(衣服 · 鞋子)脫下","v65/meanings.1":"(飛機)起飛","v65/meanings.2":"(事情)突然順利起來","v65/why":"take(拿走) + off(離開) → 從身上拿下來 = 脫下。飛機離開地面就是「起飛」，事業一下子往上衝，就是「突然順利起來」。","v65/object":"脫下是 take off your shoes ○ · take them off ○ · take off them ✕。起飛不接受詞。","v65/examples.0.scene":"對走進家門的客人說","v65/examples.0.ko":"請把鞋子脫掉。","v65/examples.1.scene":"機場廣播","v65/examples.1.ko":"飛機將在十分鐘後起飛。","v65/examples.2.scene":"朋友的店生意大好時","v65/examples.2.ko":"她的事業今年突然大紅大紫了。","v65/similar":"remove (脫下 · 移除) · depart (出發)","v65/opposite":"put on (穿上) · land (降落)","v65/quiz.0.options.0":"我們的飛機準時起飛了。","v65/quiz.0.options.1":"我們的飛機準時脫掉了。","v65/quiz.0.options.2":"我們的飛機準時降落了。","v65/quiz.0.options.3":"我們的飛機準時熄滅了。","v65/quiz.0.why":"離開地面的 take off 就是起飛。","v65/quiz.1.ko":"好熱。你可以把外套脫掉。","v65/quiz.1.why":"脫下就是 take off。","v65/quiz.2.q":"「(指著鞋子)把它脫掉。」用英文怎麼說？","v65/quiz.2.why":"代名詞 them 要放在 take 和 off 之間。","v66/meanings.0":"(從公車 · 火車 · 飛機)下車","v66/meanings.1":"下班 (get off work)","v66/why":"get(變成 · 去) + off(離開) → 從原本搭乘的地方離開 = 下車。從工作中脫身出來，就是「下班」。用 on 搭上去的東西(公車 · 火車 · 飛機，on ⑥)，就用 off 下來。","v66/object":"get off the bus ○ · get off at the next stop ○。從汽車 · 計程車下來則是 get out of the car。","v66/examples.0.scene":"在公車上","v66/examples.0.ko":"我在下一站下車。","v66/examples.1.scene":"問朋友下班時間時","v66/examples.1.ko":"你幾點下班？","v66/examples.2.scene":"結束漫長的飛行後","v66/examples.2.ko":"下飛機的時候我累壞了。","v66/similar":"leave (離開)","v66/opposite":"get on (上車)","v66/quiz.0.options.0":"她在紐約下了飛機。","v66/quiz.0.options.1":"她在紐約搭上了飛機。","v66/quiz.0.options.2":"她在紐約錯過了飛機。","v66/quiz.0.options.3":"她在紐約把飛機關掉了。","v66/quiz.0.why":"這是從搭乘的地方離開的 get off。","v66/quiz.1.ko":"從計程車下來吧。到了。","v66/quiz.1.why":"計程車 · 汽車用 get out of。公車 · 火車用 get off。","v66/quiz.2.ko":"我通常六點下班。","v66/quiz.2.why":"下班就是 get off work。","v67/meanings.0":"坐下","v67/meanings.1":"(為了談話)面對面坐下","v67/why":"sit(坐) + down(向下) → 身體往下放而坐下。只說 sit 也可以，但加上 down 就更清楚是「從站著到坐下的動作」。","v67/object":"不接受詞。Sit down, please. / Let's sit down and talk.","v67/examples.0.scene":"對客人說","v67/examples.0.ko":"請坐。","v67/examples.1.scene":"要提起重要的事時","v67/examples.1.ko":"我們坐下來聊聊吧。","v67/examples.2.scene":"站了很久之後","v67/examples.2.ko":"我腳好痛。我得坐一下。","v67/similar":"take a seat · have a seat (請坐，比較有禮貌的說法)","v67/opposite":"stand up (站起來)","v67/quiz.0.options.0":"你要不要坐一下？","v67/quiz.0.options.1":"你要不要下去一下？","v67/quiz.0.options.2":"你要不要躺一下？","v67/quiz.0.options.3":"你要不要起來一下？","v67/quiz.0.why":"這是身體往下放的 sit down。","v67/quiz.1.ko":"請坐。電影要開始了。","v67/quiz.1.why":"坐下就是 sit down。","v67/quiz.2.q":"(有禮貌地) Please have a ___.","v67/quiz.2.ko":"請坐。","v67/quiz.2.why":"有禮貌的說法是 have a seat。","v68/meanings.0":"外出 · 出去玩","v68/meanings.1":"(和人)交往 (go out with)","v68/meanings.2":"(燈)熄滅","v68/why":"go(去) + out(到外面) → 走出家門 = 外出。兩個人老是一起出去，就是「交往」；火光跑到外面不見了，就是「熄滅」。","v68/object":"不接受詞。交往的對象用 go out with + 人。","v68/examples.0.scene":"對星期五晚上的室友說","v68/examples.0.ko":"你今晚要出去玩嗎？","v68/examples.1.scene":"媽媽對女兒說","v68/examples.1.ko":"你和 Noah 在交往嗎？","v68/examples.2.scene":"在暴風雨的夜晚","v68/examples.2.ko":"突然停電了。","v68/similar":"hang out (出去玩) · date (約會)","v68/quiz.0.options.0":"他們兩個交往多久了？","v68/quiz.0.options.1":"他們兩個出去多久了？","v68/quiz.0.options.2":"他們兩個關燈多久了？","v68/quiz.0.options.3":"他們兩個吵架多久了？","v68/quiz.0.why":"兩個人一起出去的 go out 就是交往。","v68/quiz.1.ko":"我們今晚出去吃晚餐吧。","v68/quiz.1.why":"外出就是 go out。","v68/quiz.2.ko":"她在跟誰交往？","v68/quiz.2.why":"跟誰交往要用 go out with。","v69/meanings.0":"(忍受不喜歡的事)忍耐 · 容忍","v69/why":"put up(舉起放著) + with(一起) → 舉著沉重的東西一起過日子 = 忍受。有種雖然不喜歡但還是接受、撐下去的感覺。","v69/object":"put up with + 人 · 事。不拆開用：put up with it ○ · put it up with ✕","v69/examples.0.scene":"談到吵鬧的鄰居時","v69/examples.0.ko":"我再也受不了那些噪音了。","v69/examples.1.scene":"老夫老妻笑著說","v69/examples.1.ko":"你是怎麼忍受我的？","v69/examples.2.scene":"談到每天遲到的同事時","v69/examples.2.ko":"為什麼我們得忍受這種事？","v69/similar":"stand (忍受，多用於否定句：I can't stand it) · tolerate (容忍)","v69/quiz.0.options.0":"我再也受不了他的笑話了。","v69/quiz.0.options.1":"我沒辦法把他的笑話往上抬。","v69/quiz.0.options.2":"我沒辦法一起說他的笑話。","v69/quiz.0.options.3":"我再也聽不下去他的笑話，所以笑了。","v69/quiz.0.why":"這是忍受討厭事物的 put up with。","v69/quiz.1.ko":"她在以前的公司忍受了很大的壓力。","v69/quiz.1.why":"忍耐就是 put up with。","v69/quiz.2.ko":"你是怎麼忍受那些噪音的？","v69/quiz.2.why":"put up with 要當成一個整體。","v70/meanings.0":"(事情 · 問題)突然發生","v70/meanings.1":"(話題)被提起","v70/meanings.2":"(太陽)升起 · (日子)逼近","v70/why":"come(來) + up(向上浮現出現) → 看不見的東西突然浮上來 = 發生 · 被提起。太陽升起也是 come up。與 come up with(想出來，片語動詞第 20 個)成對。","v70/object":"不接受詞。Something came up.(有事情發生了) / Your name came up in the meeting.","v70/examples.0.scene":"取消約定時","v70/examples.0.ko":"抱歉，臨時有事。我們明天見面可以嗎？","v70/examples.1.scene":"會議後對同事說","v70/examples.1.ko":"會議上有人提到你的名字。","v70/examples.2.scene":"在清晨的海邊","v70/examples.2.ko":"看！太陽升起來了。","v70/similar":"happen (發生) · arise (出現)","v70/quiz.0.options.0":"公司出了點事。","v70/quiz.0.options.1":"公司裡有東西浮了上來。","v70/quiz.0.options.2":"公司來了一個人。","v70/quiz.0.options.3":"公司往上升了。","v70/quiz.0.why":"突然浮現的 come up 就是發生。","v70/quiz.1.ko":"我今晚去不了。有事情發生了。","v70/quiz.1.why":"有事發生就是 come up。","v70/quiz.2.ko":"你的生日快到了！","v70/quiz.2.why":"日子逼近用 coming up。","v71/meanings.0":"讓人失望","v71/meanings.1":"(辜負期望)","v71/why":"let(任由) + down(向下) → 任由對方的期待往下掉 = 讓人失望。像原本鼓起的心情往下洩氣的感覺。","v71/object":"人要放在中間。let me down ○ · let down me ✕。如果是自己感到失望，就說 I feel let down.","v71/examples.0.scene":"重要的事情在即時","v71/examples.0.ko":"我不想讓團隊失望。","v71/examples.1.scene":"對失約的朋友說","v71/examples.1.ko":"你說過會來的。我真的對你很失望。","v71/examples.2.scene":"聽到結果後","v71/examples.2.ko":"聽到那個消息，我好失望。","v71/similar":"disappoint (使失望) ↔ come through (不負所望)","v71/quiz.0.options.0":"不要讓我失望。","v71/quiz.0.options.1":"不要把我放下來。","v71/quiz.0.options.2":"不要把我掉下去。","v71/quiz.0.options.3":"別管我。","v71/quiz.0.why":"讓期待落空的 let down 就是讓人失望。","v71/quiz.1.ko":"我答應過要幫忙，所以不會讓你失望的。","v71/quiz.1.why":"讓人失望就是 let down。","v71/quiz.2.ko":"他忘了她的生日，她很失望。","v71/quiz.2.why":"感到失望要用 feel let down。","v72/meanings.0":"(商店 · 公司 · 服務)關門 · 停止營運","v72/meanings.1":"(電腦 · 機器)關機","v72/why":"shut(關上) + down(降低 · 變弱) → 把運作降到零、完全關閉 = 關門 · 停止營運。把電腦完全關掉也是 shut down。","v72/object":"受詞放中間或後面。shut down the app ○ · shut the app down ○ · shut it down ○。也可以不接受詞：The factory shut down.","v72/examples.0.scene":"在會議室裡","v72/examples.0.ko":"客戶想結束這個應用程式的營運。","v72/examples.1.scene":"在社區的商店前","v72/examples.1.ko":"我最喜歡的書店去年關門了。","v72/examples.2.scene":"對下班的同事說","v72/examples.2.ko":"別忘了把電腦關機。","v72/similar":"close (關閉) · turn off (關掉，片語動詞第 10 個) ↔ start up (啟動)","v72/quiz.0.options.0":"那間餐廳上個月關門了。","v72/quiz.0.options.1":"那間餐廳上個月搬家了。","v72/quiz.0.options.2":"那間餐廳上個月客人很多。","v72/quiz.0.options.3":"那間餐廳上個月整修了。","v72/quiz.0.why":"停止營運的 shut down 就是關門。","v72/quiz.1.ko":"如果什麼都沒改變，他們會把應用程式關掉。","v72/quiz.1.why":"停止營運就是 shut down。","v72/quiz.2.ko":"離開前請把筆電關機。","v72/quiz.2.why":"把電腦關掉是 shut down。shut up 是「閉嘴」。","v73/meanings.0":"逐一查看 · 檢查","v73/meanings.1":"(經歷困難的事)經歷","v73/meanings.2":"(東西)翻找","v73/why":"go(去) + through(從頭到尾) → 把文件或清單從頭到尾走過一遍 = 逐一查看。從頭到尾走過一段艱難時期，就是「經歷」。get through(熬過去，片語動詞第 38 個)則有走到終點的感覺。","v73/object":"受詞只放在 through 後面。go through the list ○ · go the list through ✕","v73/examples.0.scene":"開會開始時","v73/examples.0.ko":"我們快速逐一檢視這些問題吧。","v73/examples.1.scene":"安慰朋友時","v73/examples.1.ko":"我知道你正在經歷一段辛苦的時光。","v73/examples.2.scene":"看到包包開著時","v73/examples.2.ko":"你翻過我的包包嗎？","v73/similar":"look over · review (檢閱) · experience (經歷)","v73/quiz.0.options.0":"她去年經歷了很多辛苦的事。","v73/quiz.0.options.1":"她去年旅行了很多地方。","v73/quiz.0.options.2":"她去年過去了很多。","v73/quiz.0.options.3":"她去年通過了很多考試。","v73/quiz.0.why":"從頭到尾走過一遍的 go through 就是經歷。","v73/quiz.1.ko":"我們一起把報告逐項看一遍吧。","v73/quiz.1.why":"從頭到尾查看的 go through。","v73/quiz.2.ko":"他失去工作後，正在經歷一段辛苦的時期。","v73/quiz.2.why":"經歷困難就是 go through。","v74/meanings.0":"出去 · 離開","v74/meanings.1":"(從車 · 計程車)下車","v74/meanings.2":"Get out! 不會吧！(驚訝)","v74/why":"get(移動 · 變成) + out(向外) → 從裡面往外移動出去。走出車子就是「下車」，聽到驚人的事說 Get out!，就是「不會吧！」。公車 · 火車用 get off(片語動詞第 66 個)，汽車 · 計程車用 get out of。","v74/object":"地點放在 of 後面。Get out of my kitchen! / get out of the car","v74/examples.0.scene":"在廚房裡，爸爸說","v74/examples.0.ko":"從我的廚房出去！去坐著。","v74/examples.1.scene":"計程車停下時","v74/examples.1.ko":"我們在這裡下車吧。走過去就好。","v74/examples.2.scene":"聽到驚喜的消息時","v74/examples.2.ko":"你中樂透了？不會吧！","v74/similar":"leave (離開) · exit (出去) ↔ get in (進去 · 上車)","v74/quiz.0.options.0":"請從車上下來。","v74/quiz.0.options.1":"請上車。","v74/quiz.0.options.2":"請把車開走。","v74/quiz.0.options.3":"請把車修好。","v74/quiz.0.why":"走出車外的 get out of 就是下車。","v74/quiz.1.ko":"我們得趕快離開這裡！","v74/quiz.1.why":"往外出去的 get out of。","v74/quiz.2.ko":"她從計程車下來，跑了進去。","v74/quiz.2.why":"從計程車下來要用 get out of。","v75/meanings.0":"讓人壓力很大 · 感到壓力","v75/meanings.1":"(be stressed out) 壓力大到精疲力竭","v75/why":"stress(施加壓力) + out(全部流光見底) → 因為壓力而元氣全被抽乾 = 壓力大到筋疲力盡。比單純的 stressed 看起來累得多。","v75/object":"人要放在中間：It stresses me out. 通常像 I'm stressed out. 這樣用。Don't stress out.(不要太有壓力)","v75/examples.0.scene":"訂婚典禮當天早上","v75/examples.0.ko":"我壓力好大。什麼都還沒準備好！","v75/examples.1.scene":"對快要考試的朋友說","v75/examples.1.ko":"不要太有壓力。你已經很努力念書了。","v75/examples.2.scene":"在上班路上的車裡","v75/examples.2.ko":"塞車讓我壓力好大。","v75/similar":"worry (擔心) · freak out (嚇壞，片語動詞第 15 個) ↔ relax (放鬆)","v75/quiz.0.options.0":"工作讓我壓力很大。","v75/quiz.0.options.1":"因為工作我正在往外走。","v75/quiz.0.options.2":"工作全部都做完了。","v75/quiz.0.options.3":"工作太簡單了。","v75/quiz.0.why":"讓人元氣流光的 stress out 就是讓人有壓力。","v75/quiz.1.ko":"別緊張。還有時間。","v75/quiz.1.why":"感到壓力就是 stress out。","v75/quiz.2.ko":"你看起來壓力真大。要不要喝杯茶？","v75/quiz.2.why":"壓力大到疲憊的狀態是 stressed out。","v76/meanings.0":"(衣服 · 鞋子)試穿","v76/why":"try(試試) + on(貼在表面，on ①) → 把衣服貼在身上試試看 = 試穿。put on(穿上，片語動詞第 39 個)是真的穿上，try on 是試試看合不合適。","v76/object":"受詞放中間或後面。try on this dress ○ · try this dress on ○ · try it on ○ · try on it ✕","v76/examples.0.scene":"媽媽拿出舊韓服時","v76/examples.0.ko":"穿穿看。這是媽媽三十年前穿過的。","v76/examples.1.scene":"在服飾店","v76/examples.1.ko":"我可以試穿這條牛仔褲嗎？","v76/examples.2.scene":"在鞋店","v76/examples.2.ko":"我試穿了五雙，沒有一雙合腳。","v76/similar":"put on (穿上，片語動詞第 39 個) · fit (合身)","v76/quiz.0.options.0":"我可以試穿這個嗎？","v76/quiz.0.options.1":"我可以試開這個嗎？","v76/quiz.0.options.2":"我可以把這個帶走嗎？","v76/quiz.0.options.3":"我可以繼續這個嗎？","v76/quiz.0.why":"貼在身上試試看的 try on 就是試穿。","v76/quiz.1.ko":"我可以在哪裡試穿這件襯衫？","v76/quiz.1.why":"試穿就是 try on。","v76/quiz.2.ko":"這件洋裝好漂亮。要不要試穿看看？","v76/quiz.2.why":"it 要放在 try 和 on 之間。","v77/meanings.0":"(模糊的東西)勉強辨認出來 · 聽出來","v77/meanings.1":"(意思)理解","v77/why":"make(使成為) + out(顯現出來) → 把模糊的形狀 · 聲音弄得清楚顯現 = 勉強辨認出來 · 聽出來。多半和 can't · couldn't 一起用。","v77/object":"受詞放中間或後面。make out the words ○ · make it out ○。也可以接句子：I can't make out what he's saying.","v77/examples.0.scene":"說明新設計時","v77/examples.0.ko":"年長的使用者不太認得出原來的按鈕。","v77/examples.1.scene":"在吵鬧的派對上","v77/examples.1.ko":"我完全聽不清楚你在說什麼！","v77/examples.2.scene":"在起霧的海邊","v77/examples.2.ko":"那邊隱約看得到一艘船。","v77/similar":"see · hear clearly (看清楚 · 聽清楚) · figure out (弄清楚，片語動詞第 12 個)","v77/quiz.0.options.0":"我看不清楚他的字跡。","v77/quiz.0.options.1":"我沒辦法照著描他的字跡。","v77/quiz.0.options.2":"我沒辦法把他的字跡擦掉。","v77/quiz.0.options.3":"我不喜歡他的字跡。","v77/quiz.0.why":"讓模糊的東西顯現出來的 make out 就是辨認出來。","v77/quiz.1.ko":"太暗了，我看不清楚路標。","v77/quiz.1.why":"勉強辨認出來就是 make out。","v77/quiz.2.ko":"你聽得出她在說什麼嗎？","v77/quiz.2.why":"聽出來就是 make out。make up 是「捏造」。","v78/meanings.0":"退後 · 往後退","v78/meanings.1":"別再逼了 · 不要干涉","v78/why":"back(往後) + off(離開) → 往後退開 = 退後。對一直用話逼人的人說 Back off!，就是「別再逼我了！ · 別管我！」。","v78/object":"不接受詞。Back off! / 要說對象時用 from：back off from the plan(放棄計畫)","v78/examples.0.scene":"對一直提結婚話題的媽媽說","v78/examples.0.ko":"媽，拜託你別再說了。","v78/examples.1.scene":"狗在低吼時","v78/examples.1.ko":"慢慢往後退。不要跑。","v78/examples.2.scene":"在會議上，上司說","v78/examples.2.ko":"好，我退出，你來決定。","v78/similar":"step back (退後) · leave alone (別管他) ↔ push (逼迫)","v78/quiz.0.options.0":"別再逼我了！這是我要決定的事。","v78/quiz.0.options.1":"待在後面！我決定好了。","v78/quiz.0.options.2":"回來！我來決定。","v78/quiz.0.options.3":"看看你背後！已經決定好了。","v78/quiz.0.why":"要人往後退開的 Back off! 就是別再逼了。","v78/quiz.1.ko":"我生氣了，他就退開了。","v78/quiz.1.why":"退後就是 back off。","v78/quiz.2.ko":"媽，可以別再管我了嗎？我已經二十八歲了！","v78/quiz.2.why":"不再干涉就是 back off。","v79/meanings.0":"(改變想法)接受 · 轉念","v79/meanings.1":"(到家裡)順道拜訪","v79/meanings.2":"(日子)再度來臨","v79/why":"come(來) + around(繞一圈) → 繞一圈來到這一邊。原本反對的人把想法轉了一圈來到這一邊，就是「接受」；繞到朋友家去，就是「順道拜訪」；每年同一天又回來，就是「再度來臨」。","v79/object":"不接受詞。She'll come around. / 想法用 to：come around to the idea","v79/examples.0.scene":"聽到客戶改變心意的消息時","v79/examples.0.ko":"我就知道那位最後會接受的。","v79/examples.1.scene":"對朋友說","v79/examples.1.ko":"你回來以後來吃晚餐吧。","v79/examples.2.scene":"年底接近時","v79/examples.2.ko":"聖誕節每年都來得好快。","v79/similar":"change your mind (改變心意) · come over (來玩，片語動詞第 51 個)","v79/quiz.0.options.0":"爸爸本來討厭那個想法，但最後接受了。","v79/quiz.0.options.1":"爸爸討厭那個想法，就離開家了。","v79/quiz.0.options.2":"爸爸聽到那個想法，轉了一圈。","v79/quiz.0.options.3":"爸爸聽到那個想法，沒有回來。","v79/quiz.0.why":"把想法轉過來的 come around 就是接受。","v79/quiz.1.ko":"別擔心。她很快就會改變想法的。","v79/quiz.1.why":"轉念就是 come around。","v79/quiz.2.ko":"我的生日又到了。我又老了一歲！","v79/quiz.2.why":"日子再度來臨就是 come around。","v80/meanings.0":"(計畫 · 活動)取消 · 中止","v80/why":"call(喊) + off(離開 · 停止) → 喊一聲「停！」讓進行中止 = 取消。用在已經定好的活動 · 比賽 · 計畫要作罷的時候。機票 · 訂位通常用 cancel。","v80/object":"受詞放中間或後面。call off the meeting ○ · call the meeting off ○ · call it off ○","v80/examples.0.scene":"轉達客戶的消息時","v80/examples.0.ko":"客戶取消了結束應用程式營運的決定。","v80/examples.1.scene":"在下雨的運動場上","v80/examples.1.ko":"比賽因為下雨取消了。","v80/examples.2.scene":"社區傳聞","v80/examples.2.ko":"聽說那兩個人取消婚禮了。","v80/similar":"cancel (取消) · put off (延後，片語動詞第 25 個)","v80/quiz.0.options.0":"會議取消了。","v80/quiz.0.options.1":"我被叫去開會了。","v80/quiz.0.options.2":"會議結束了。","v80/quiz.0.options.3":"會議延期了。","v80/quiz.0.why":"讓進行中止的 call off 就是取消。延期是 put off。","v80/quiz.1.ko":"我們不得不取消野餐。","v80/quiz.1.why":"取消就是 call off。","v80/quiz.2.ko":"派對要取消嗎？只有兩個人會來。","v80/quiz.2.why":"取消活動就是 call off。","v81/meanings.0":"(努力)有成果 · 得到回報","v81/meanings.1":"(債)還清","v81/why":"pay(付出代價) + off(卸掉 · 脫離) → 付清錢、卸下債務 = 還清。投入的努力把代價全付清、換回成果，就是「得到回報」。","v81/object":"「得到回報」不接受詞：Your hard work paid off. / 「還清」受詞放中間或後面：pay off the loan ○ · pay it off ○","v81/examples.0.scene":"在機場迎接時","v81/examples.0.ko":"你的辛苦都有回報了！","v81/examples.1.scene":"繳完最後一期後","v81/examples.1.ko":"我終於還清學貸了。","v81/examples.2.scene":"對正在練習的弟弟說","v81/examples.2.ko":"繼續練習。總有一天會有成果的。","v81/similar":"work out (順利解決，片語動詞第 7 個) · succeed (成功)","v81/quiz.0.options.0":"她的努力有了回報。","v81/quiz.0.options.1":"她付了辛苦工作的錢。","v81/quiz.0.options.2":"她辭掉了工作。","v81/quiz.0.options.3":"她的努力消失了。","v81/quiz.0.why":"努力付出代價後換回成果的 pay off 就是得到回報。","v81/quiz.1.ko":"我花了十年才還清房貸。","v81/quiz.1.why":"把債務卸下的 pay off。","v81/quiz.2.ko":"那些練習全都有成果了！","v81/quiz.2.why":"有成果就是 pay off。","v82/meanings.0":"(空格 · 文件)填寫","v82/meanings.1":"(fill someone in) 詳細告知","v82/meanings.2":"(fill in for) 代班","v82/why":"fill(填滿) + in(裡面) → 把空的地方裡面填滿。把文件的空格填上就是「填寫」，把對方腦中的空白補上就是「詳細告知」，把空缺的位置補上就是「代班」。","v82/object":"受詞放中間或後面。fill in the form ○ · fill it in ○。要告知的人放中間：Fill me in. 代替某人則用 for：fill in for Dana","v82/examples.0.scene":"在晚餐餐桌上","v82/examples.0.ko":"來，快告訴我詳情。Mr. Han 的想法是什麼？","v82/examples.1.scene":"在醫院櫃檯","v82/examples.1.ko":"請填寫姓名和地址。","v82/examples.2.scene":"代替生病的同事","v82/examples.2.ko":"你今天可以幫我代 Jake 的班嗎？","v82/similar":"fill out (把文件填完，out ③) · tell (告訴) · cover for (代班)","v82/quiz.0.options.0":"你可以跟我說明一下會議內容嗎？","v82/quiz.0.options.1":"你可以幫我把會議室填滿嗎？","v82/quiz.0.options.2":"你可以把我的名字加進會議資料嗎？","v82/quiz.0.options.3":"你可以讓我加入會議嗎？","v82/quiz.0.why":"把腦中空白補上的 fill in 就是詳細告知。","v82/quiz.1.ko":"請填寫空格。","v82/quiz.1.why":"把空格裡面填滿的 fill in。","v82/quiz.2.ko":"我上週不在。你可以告訴我發生了什麼事嗎？","v82/quiz.2.why":"人要放在 fill 和 in 之間。","v83/meanings.0":"閒晃 · 胡鬧","v83/meanings.1":"(mess around with) 亂動","v83/why":"mess(弄亂) + around(到處) → 沒事做、到處弄得亂七八糟 = 閒晃 · 胡鬧。亂翻別人的東西，就是「亂動」。與 mess up(搞砸，片語動詞第 23 個)成對。","v83/object":"不接受詞。Stop messing around! / 東西放在 with 後面：mess around with the coffee machine","v83/examples.0.scene":"在咖啡廳，Leo 說","v83/examples.0.ko":"Jake，別再亂動我的機器了！","v83/examples.1.scene":"回顧週末時","v83/examples.1.ko":"我們整個週末都在閒晃。","v83/examples.2.scene":"上課時","v83/examples.2.ko":"別再胡鬧了，專心聽。","v83/similar":"fool around (閒晃) · goof off (摸魚)","v83/quiz.0.options.0":"別再閒晃了，去寫作業。","v83/quiz.0.options.1":"別再弄亂了，把作業拿來。","v83/quiz.0.options.2":"不要把作業到處亂放。","v83/quiz.0.options.3":"不要把作業搞砸。","v83/quiz.0.why":"到處弄亂的 mess around 就是閒晃。","v83/quiz.1.ko":"孩子們在公園裡玩鬧。","v83/quiz.1.why":"胡鬧就是 mess around。","v83/quiz.2.ko":"別亂動我的電腦！","v83/quiz.2.why":"和 with 一起用，「亂動」就是 mess around。","v84/meanings.0":"逃跑 · 逃走","v84/meanings.1":"(離開家)出走 · 離家出走","v84/why":"run(跑) + away(遠離) → 跑著遠離 = 逃跑。從問題中跑得遠遠的，就是「逃避」。","v84/object":"不接受詞。逃避的對象用 from：run away from your problems","v84/examples.0.scene":"在辦公室裡，Jake 說","v84/examples.0.ko":"你們不能就這樣逃回首爾啊！","v84/examples.1.scene":"在公園裡","v84/examples.1.ko":"狗聽到雷聲就跑掉了。","v84/examples.2.scene":"勸朋友時","v84/examples.2.ko":"不要逃避問題。","v84/similar":"escape (逃脫) · get away (逃離)","v84/quiz.0.options.0":"他十六歲時離家出走了。","v84/quiz.0.options.1":"他十六歲時跑回家了。","v84/quiz.0.options.2":"他十六歲時買了房子。","v84/quiz.0.options.3":"他十六歲時回家了。","v84/quiz.0.why":"從家裡跑得遠遠的 run away from home 就是離家出走。","v84/quiz.1.ko":"警察來之前，小偷就逃走了。","v84/quiz.1.why":"逃走就是 run away。","v84/quiz.2.ko":"你不能一直逃避真相。","v84/quiz.2.why":"逃避~就是 run away from。","v85/meanings.0":"(疼痛 · 擔憂)消失","v85/meanings.1":"(人)走開 · 離去","v85/why":"go(去) + away(遠離消失) → 走遠到看不見。人這樣就是「走開」，疼痛 · 擔憂這樣就是「消失」。想要獨處時會說 Go away!(走開！)。","v85/object":"不接受詞。The pain went away. / Go away!","v85/examples.0.scene":"遞上頭痛藥時","v85/examples.0.ko":"吃這個。頭痛會消失的。","v85/examples.1.scene":"對敲房門的弟弟說","v85/examples.1.ko":"走開！我很忙。","v85/examples.2.scene":"對正在擔心的朋友說","v85/examples.2.ko":"假裝不知道，這種感覺也不會消失。","v85/similar":"disappear (消失) · leave (離開) ↔ come back (回來，片語動詞第 35 個)","v85/quiz.0.options.0":"疼痛終於消失了。","v85/quiz.0.options.1":"疼痛終於開始了。","v85/quiz.0.options.2":"因為疼痛，終於離開了。","v85/quiz.0.options.3":"疼痛終於回來了。","v85/quiz.0.why":"遠離到看不見的 go away 就是消失。","v85/quiz.1.ko":"拜託你走開。我想一個人靜一靜。","v85/quiz.1.why":"走開就是 go away。","v85/quiz.2.ko":"別擔心。感冒幾天就會好了。","v85/quiz.2.why":"病痛消失就是 go away。","v86/meanings.0":"回來 · 回去","v86/meanings.1":"拿回來 · 取回","v86/meanings.2":"(get back to) 之後再聯絡","v86/why":"get(去 · 得到) + back(回到原來的位置) → 回到原本待的地方 = 回來。把屬於我的東西拿回原處是「拿回來」,回到先前的話題再聯絡就是「再聯絡」。","v86/object":"「回來」不接受詞:When did you get back? / 「拿回來」放中間或後面:get my money back ○ · get back my money ○","v86/examples.0.scene":"Rosa 在屋頂上","v86/examples.0.ko":"你什麼時候從 Frank 伯伯家回來的?","v86/examples.1.scene":"想要回借出去的書","v86/examples.1.ko":"我想把我的書拿回來。","v86/examples.2.scene":"開會時對客戶說","v86/examples.2.ko":"我確認一下,再回覆您。","v86/similar":"return (回來 · 取回) · come back (回來,片語動詞第35個)","v86/quiz.0.options.0":"我明天再聯絡你。","v86/quiz.0.options.1":"我明天回到你那裡去。","v86/quiz.0.options.2":"我明天把你追回來。","v86/quiz.0.options.3":"我明天在後面等你。","v86/quiz.0.why":"回到先前話題的 get back to 是「再聯絡」。","v86/quiz.1.ko":"你昨晚幾點回來的?","v86/quiz.1.why":"「回來」是 get back。","v86/quiz.2.ko":"我借了他 50 美元,最後都沒拿回來。","v86/quiz.2.why":"「拿回來」是 get back。","v87/meanings.0":"(把說過的話)收回 · 撤回","v87/meanings.1":"(把東西)退貨","v87/why":"take(拿走) + back(拿回 · 退回) → 把送出去的東西再拿回自己這邊。把說出口的話收回來是「收回」,把買的東西退回店裡是「退貨」。I take it back.(我收回那句話)道歉時很常用。","v87/object":"受詞放中間或後面。take back what I said ○ · take it back ○","v87/examples.0.scene":"吵架之後","v87/examples.0.ko":"對不起,那句話我收回。","v87/examples.1.scene":"鞋子不合腳","v87/examples.1.ko":"這雙鞋我得拿去店裡退。","v87/examples.2.scene":"對朋友說","v87/examples.2.ko":"說出口的話是收不回來的。","v87/similar":"return (退貨) · apologize (道歉)","v87/quiz.0.options.0":"我收回我說的話。","v87/quiz.0.options.1":"我再把我說的話說一次。","v87/quiz.0.options.2":"我把我說的話帶走。","v87/quiz.0.options.3":"我再聽一次我說的話。","v87/quiz.0.why":"把說過的話拿回來的 take back 是「收回」。","v87/quiz.1.ko":"你太過分了。把那句話收回去!","v87/quiz.1.why":"「收回說過的話」是 take back。","v87/quiz.2.ko":"這件襯衫太小了。我明天去退貨。","v87/quiz.2.why":"it 要放在 take 和 back 中間。","v88/meanings.0":"(痛苦 · 失望)克服 · 放下","v88/meanings.1":"(從病中)康復","v88/why":"get(去) + over(越過) → 越過擋在前面的牆 = 克服。越過痛苦 · 分手 · 感冒,就是「克服 · 痊癒」。也可以說 Get over it.(別再放在心上了)。","v88/object":"受詞只放在 over 後面。get over it ○ · get it over ✕(意思不同)","v88/examples.0.scene":"Leo 談起往事","v88/examples.0.ko":"我花了一年才放下那件事。","v88/examples.1.scene":"對感冒的朋友說","v88/examples.1.ko":"你的感冒有好一點了嗎?","v88/examples.2.scene":"對剛分手的朋友說","v88/examples.2.ko":"你會忘掉他的。我保證。","v88/similar":"recover (康復) · overcome (克服) · move on (放下往前走,片語動詞第17個)","v88/quiz.0.options.0":"她始終沒能忘記初戀。","v88/quiz.0.options.1":"她從來沒越過初戀的家。","v88/quiz.0.options.2":"她沒能再見到初戀。","v88/quiz.0.options.3":"她替初戀蓋上了東西。","v88/quiz.0.why":"越過牆的 get over 是「克服 · 忘掉」。","v88/quiz.1.ko":"我花了好幾週才從流感中康復。","v88/quiz.1.why":"「從病中康復」是 get over。","v88/quiz.2.ko":"他現在很難過,但他會撐過去的。","v88/quiz.2.why":"「克服」是 get over。","v89/meanings.0":"回頭看 · 轉過身","v89/meanings.1":"(讓情況)好轉 · 起死回生","v89/why":"turn(轉) + around(繞一圈) → 把身體轉半圈 = 轉身。把愈變愈糟的情況轉向相反的方向,就是「好轉 · 起死回生」。","v89/object":"「轉身」不接受詞:Turn around. / 「起死回生」通常放中間:turn the company around","v89/examples.0.scene":"在雨中喊 Mina","v89/examples.0.ko":"Mina!回頭看!","v89/examples.1.scene":"談起公司狀況","v89/examples.1.ko":"新老闆讓公司起死回生了。","v89/examples.2.scene":"走錯路了","v89/examples.2.ko":"走錯路了!掉頭!","v89/similar":"look back (回頭看) · improve (改善)","v89/quiz.0.options.0":"我回頭一看,他已經走了。","v89/quiz.0.options.1":"我轉了一圈時,他跌倒了。","v89/quiz.0.options.2":"我回來時,他正在睡覺。","v89/quiz.0.options.3":"我低下頭時,他走了。","v89/quiz.0.why":"把身體轉一圈的 turn around 是「回頭看」。","v89/quiz.1.ko":"轉過去。讓我看看你的背。","v89/quiz.1.why":"「轉身」是 turn around。","v89/quiz.2.ko":"她的新計畫讓事業起死回生了。","v89/quiz.2.why":"「讓情況好轉」是 turn around。","v90/meanings.0":"等一下","v90/meanings.1":"抓緊 · 撐住","v90/why":"hang(掛著) + on(貼住) → 手不放開,一直掛在上面。所以是「抓緊 · 撐住」,也能抓住說到一半的話,變成「等一下!」。和 hold on(片語動詞第4個)幾乎一樣。","v90/object":"不接受詞。Hang on a second. / 抓住的對象用 to:hang on to the rail","v90/examples.0.scene":"突然想到什麼","v90/examples.0.ko":"等一下。我有個好主意。","v90/examples.1.scene":"在雲霄飛車上","v90/examples.1.ko":"抓緊了!","v90/examples.2.scene":"鼓勵辛苦的朋友","v90/examples.2.ko":"再撐一下。會好起來的。","v90/similar":"hold on (等一下 · 抓緊,片語動詞第4個) · wait (等待)","v90/quiz.0.options.0":"等一下,我馬上回來。","v90/quiz.0.options.1":"掛在那裡,我馬上回來。","v90/quiz.0.options.2":"把電話掛掉,我馬上回來。","v90/quiz.0.options.3":"掛起來,我馬上回來。","v90/quiz.0.why":"要你先抓住手上事情的 hang on 是「等一下」。","v90/quiz.1.ko":"等一下。我去拿一下鑰匙。","v90/quiz.1.why":"「等一下」是 hang on。hang up 是掛電話。","v90/quiz.2.ko":"抓緊扶手。公車要開了。","v90/quiz.2.why":"「抓緊」是 hang on。","v91/meanings.0":"掛電話","v91/meanings.1":"(把衣服)掛起來","v91/why":"hang(掛) + up(往上) → 掛到上面。以前的電話是把話筒往上掛回牆上的掛鉤來結束通話,所以是「掛電話」。把衣服掛到衣架上也是 hang up。","v91/object":"掛電話時不接受詞:Don't hang up! / 對方用 on:She hung up on me.(她直接掛我電話) / 衣服放中間或後面:hang up your coat ○ · hang it up ○","v91/examples.0.scene":"對正要結束通話的主管說","v91/examples.0.ko":"先別掛電話!","v91/examples.1.scene":"吵架時","v91/examples.1.ko":"她氣得直接掛了我的電話。","v91/examples.2.scene":"在玄關","v91/examples.2.ko":"把外套掛好再進來。","v91/similar":"end the call (結束通話) ↔ pick up (接電話,片語動詞第1個)","v91/quiz.0.options.0":"不要掛我電話!","v91/quiz.0.options.1":"不要黏著我!","v91/quiz.0.options.2":"不要把我掛起來!","v91/quiz.0.options.3":"不要丟下我上樓!","v91/quiz.0.why":"把話筒掛回去的 hang up 是「掛電話」。","v91/quiz.1.ko":"我得走了。我要掛電話了。","v91/quiz.1.why":"「掛電話」是 hang up。","v91/quiz.2.ko":"請把外套掛在衣櫃裡。","v91/quiz.2.why":"「把衣服掛起來」是 hang up。","v92/meanings.0":"(最後)讓步 · 屈服","v92/meanings.1":"(被誘惑)禁不住","v92/why":"give(給) + in(進去) → 把自己堅持的立場交到對方手裡 = 最後讓步 · 屈服。在蛋糕前忍了半天終於破功,也是 give in。give up(放棄,片語動詞第13個)是自己停手,give in 是向對方認輸。","v92/object":"不接受詞。Okay, I give in. / 對象 · 誘惑放在 to 後面:give in to pressure","v92/examples.0.scene":"視訊會議中的 Mr. Han (CEO)","v92/examples.0.ko":"好吧,我認輸。我們就試試看。","v92/examples.1.scene":"看著吵著要東西的孩子","v92/examples.1.ko":"不要每次孩子一哭就讓步。","v92/examples.2.scene":"減肥中","v92/examples.2.ko":"忍了又忍,結果還是把蛋糕全吃光了。","v92/similar":"agree (同意) · surrender (投降) · give up (放棄,片語動詞第13個)","v92/quiz.0.options.0":"她一直纏著我,最後我讓步了。","v92/quiz.0.options.1":"她一直問,我就走進去了。","v92/quiz.0.options.2":"她一直問,我就給了她一份禮物。","v92/quiz.0.options.3":"她一直問,我就把答案交給她了。","v92/quiz.0.why":"把堅持交給對方的 give in 是「最後讓步」。","v92/quiz.1.ko":"好啦,我認輸。最後一塊餅乾給你吃。","v92/quiz.1.why":"「認輸讓步」是 give in。","v92/quiz.2.ko":"不要向他們的壓力屈服。","v92/quiz.2.why":"「向~屈服」是 give in to。","v93/meanings.0":"(從睡夢中)起床","v93/meanings.1":"(從坐著)站起來","v93/why":"get(變成 · 移動) + up(往上) → 身體往上升起 = 起來。從床上撐起身子,或從椅子 · 地上站起來,都是 get up。wake up(醒來,片語動詞第58個)是睜開眼睛,get up 是離開床。","v93/object":"不接受詞。What time do you get up? / 叫別人起來時放中間:get him up","v93/examples.0.scene":"在屋頂上偷偷準備","v93/examples.0.ko":"Rosa 每個星期六都五點起床。","v93/examples.1.scene":"對跪著的朋友說","v93/examples.1.ko":"Jake,起來!還不是時候!","v93/examples.2.scene":"星期一早上","v93/examples.2.ko":"我太晚起床,錯過了公車。","v93/similar":"wake up (醒來,片語動詞第58個) · stand up (站起來)","v93/quiz.0.options.0":"我六點醒了,但到七點才下床。","v93/quiz.0.options.1":"我六點起身,站到了七點。","v93/quiz.0.options.2":"我六點醒來,七點又睡著了。","v93/quiz.0.options.3":"我六點起床,七點上樓了。","v93/quiz.0.why":"wake up 是睜開眼睛,get up 是撐起身體。","v93/quiz.1.ko":"你通常幾點起床?","v93/quiz.1.why":"「起床」是 get up。","v93/quiz.2.ko":"你坐了一整天了。起來伸展一下!","v93/quiz.2.why":"「從坐著站起來」是 get up。","v94/meanings.0":"(眼淚 · 情緒)忍住","v94/meanings.1":"猶豫 · 有所保留","v94/meanings.2":"(不讓往前)擋住","v94/why":"hold(抓住) + back(回原位) → 把想往前冒出來的東西抓回後面。對眼淚 · 笑意這樣做是「忍住」,對自己這樣做就是「有所保留」。Don't hold back!(別保留,全部展現出來!)","v94/object":"受詞放中間或後面。hold back tears ○ · hold them back ○ / 不接受詞:Don't hold back.","v94/examples.0.scene":"被求婚時","v94/examples.0.ko":"我忍不住眼淚。","v94/examples.1.scene":"在歌唱比賽中","v94/examples.1.ko":"別保留。用全部的心去唱!","v94/examples.2.scene":"談起夢想","v94/examples.2.ko":"恐懼正拖住你。","v94/similar":"control (抑制) · hesitate (猶豫)","v94/quiz.0.options.0":"她努力忍住眼淚。","v94/quiz.0.options.1":"她想把眼淚收回去。","v94/quiz.0.options.2":"她從後面抓住了眼淚。","v94/quiz.0.options.3":"她讓眼淚傾瀉而出。","v94/quiz.0.why":"把想冒出來的東西抓回去的 hold back 是「忍住」。","v94/quiz.1.ko":"全都告訴我。別有所保留。","v94/quiz.1.why":"「有所保留」是 hold back。","v94/quiz.2.ko":"我忍不住笑出來。","v94/quiz.2.why":"「忍住笑」是 hold back。","v95/meanings.0":"過世 (die 的委婉說法)","v95/why":"pass(經過) + away(遠去消失) → 生命流逝、消失在遠方 = 過世。不方便直接說 die 的時候,可以用這個委婉而有禮貌的說法。","v95/object":"不接受詞。My grandfather passed away last year.","v95/examples.0.scene":"Leo 談起父親","v95/examples.0.ko":"我父親過世前,對我說過一些話。","v95/examples.1.scene":"安慰對方","v95/examples.1.ko":"聽到您的奶奶過世了,我很難過。","v95/examples.2.scene":"聊起老街坊","v95/examples.2.ko":"以前的老屋主幾年前過世了。","v95/similar":"die (死亡) · lose someone (失去某人)","v95/quiz.0.options.0":"她的爺爺去年春天過世了。","v95/quiz.0.options.1":"她的爺爺去年春天搬到很遠的地方了。","v95/quiz.0.options.2":"她的爺爺去年春天考上了考試。","v95/quiz.0.options.3":"她的爺爺去年春天出發去旅行了。","v95/quiz.0.why":"生命遠去的 pass away 是「過世」。","v95/quiz.1.ko":"我十二歲的時候,我的狗死了。","v95/quiz.1.why":"把「死」說得委婉就是 pass away。","v95/quiz.2.ko":"聽到你叔叔過世,我很遺憾。","v95/quiz.2.why":"「過世」是 pass away。pass out 是昏倒。","v96/meanings.0":"(對話中)插嘴","v96/meanings.1":"(闖進建築物)闖入","v96/meanings.2":"(把新鞋)穿到合腳","v96/why":"break(打破) + in(進去) → 打破阻礙後進到裡面。對房子這樣做是「闖入」,打斷別人的對話闖進去是「插嘴」,把硬邦邦的新鞋磨到合腳就是「穿到合腳」。","v96/object":"插嘴 · 闖入不接受詞:Sorry to break in. / Someone broke in. 穿到合腳放中間或後面:break in new shoes ○ · break them in ○","v96/examples.0.scene":"衝進會議室","v96/examples.0.ko":"抱歉打斷一下,是 Ms. Hill (CEO) 打來的電話!","v96/examples.1.scene":"對警察說","v96/examples.1.ko":"我們不在的時候有人闖進來了。","v96/examples.2.scene":"穿著新鞋","v96/examples.2.ko":"這雙新鞋我得先穿到合腳。","v96/similar":"interrupt (打斷) · break into (闖入~)","v96/quiz.0.options.0":"抱歉插嘴,我現在得走了。","v96/quiz.0.options.1":"抱歉把門撞壞了,我現在得走了。","v96/quiz.0.options.2":"抱歉在休息時間打擾,我現在得走了。","v96/quiz.0.options.3":"抱歉弄破了東西,我現在得走了。","v96/quiz.0.why":"打破對話闖進去的 break in 是「插嘴」。","v96/quiz.1.ko":"有小偷闖進來,拿走了我的筆電。","v96/quiz.1.why":"「闖入」是 break in。","v96/quiz.2.ko":"這雙靴子太硬了。我得把它穿到合腳。","v96/quiz.2.why":"them 要放在 break 和 in 中間。","v97/meanings.0":"逃離 · 脫身","v97/meanings.1":"(get away with) 沒被發現而逃過一劫","v97/meanings.2":"(短暫)出去度假","v97/why":"get(去) + away(遠離) → 離開現在所在的地方 = 逃離。做了壞事還能遠遠脫身,就是「逃過一劫」(get away with);暫時遠離日常生活,就是「出去度假」。","v97/object":"不接受詞。沒被發現的事放在 with 後面:get away with it","v97/examples.0.scene":"在驚喜歡送會上","v97/examples.0.ko":"你以為可以不辦派對就溜走嗎?","v97/examples.1.scene":"對又遲到的朋友說","v97/examples.1.ko":"這次你可沒那麼容易過關。","v97/examples.2.scene":"規劃週末行程","v97/examples.2.ko":"週末我們出去玩一下吧。","v97/similar":"escape (逃脫) · run away (逃跑,片語動詞第84個)","v97/quiz.0.options.0":"他違反了規定,卻平安無事。","v97/quiz.0.options.1":"他違反規定後逃到很遠的地方。","v97/quiz.0.options.2":"他因為違反規定被趕了出去。","v97/quiz.0.options.3":"他違反規定後去度假了。","v97/quiz.0.why":"get away with 是「沒被發現而逃過一劫」。","v97/quiz.1.ko":"我得離開城市幾天。","v97/quiz.1.why":"「遠離」是 get away。","v97/quiz.2.ko":"做了這種事,別以為你能沒事!","v97/quiz.2.why":"「平安逃過」是 get away with。","v98/meanings.0":"(背著戀人 · 配偶)劈腿","v98/meanings.1":"(開玩笑地)去別家","v98/meanings.2":"(考試中)作弊","v98/why":"cheat(欺騙) + on(倚靠 · 依賴,on ③) → 欺騙倚靠、信任我的人 = 劈腿。開玩笑說不去熟悉的店、跑去別家時也能用。考試作弊是 cheat on a test。","v98/object":"被騙的對象放在 on 後面。cheat on someone / cheat on a test","v98/examples.0.scene":"Leo 在機場說","v98/examples.0.ko":"別為了喝首爾的咖啡就背叛我的咖啡!","v98/examples.1.scene":"看著連續劇","v98/examples.1.ko":"那個男的劈腿了?我就知道!","v98/examples.2.scene":"在學校","v98/examples.2.ko":"千萬不要在考試中作弊。","v98/similar":"be unfaithful (不忠) · betray (背叛)","v98/quiz.0.options.0":"你是在對我劈腿去別家咖啡廳嗎?","v98/quiz.0.options.1":"你是在別家咖啡廳等我嗎?","v98/quiz.0.options.2":"你是坐在別家咖啡廳上面嗎?","v98/quiz.0.options.3":"你是在別家咖啡廳考試嗎?","v98/quiz.0.why":"丟下信任的對象跑去別處的 cheat on 是「劈腿」。","v98/quiz.1.ko":"他考試作弊被抓到了。","v98/quiz.1.why":"考試作弊是 cheat on a test。","v98/quiz.2.ko":"她發現他劈腿了。","v98/quiz.2.why":"「劈腿」是 cheat on。","v99/meanings.0":"(電器 · 機器)打開","v99/meanings.1":"(突然)翻臉 · 撲向","v99/why":"turn(轉) + on(運作中,on ⑤) → 轉動開關讓它運作 = 打開。和 turn off(關掉,片語動詞第10個)相反。對人突然轉過身撲上去,就是「翻臉 · 撲向」。","v99/object":"「打開」的受詞放中間或後面:turn on the screen ○ · turn the screen on ○ · turn it on ○ / 撲向人時放在 on 後面:The dog turned on him.","v99/examples.0.scene":"第一次團隊會議","v99/examples.0.ko":"可以幫我開一下大螢幕嗎?","v99/examples.1.scene":"走進黑漆漆的房間","v99/examples.1.ko":"你可以幫我開燈嗎?","v99/examples.2.scene":"連續劇中的背叛場面","v99/examples.2.ko":"他最好的朋友對他翻臉了。","v99/similar":"switch on (打開) ↔ turn off (關掉,片語動詞第10個)","v99/quiz.0.options.0":"把電視打開。比賽要開始了。","v99/quiz.0.options.1":"把電視轉過去。比賽要開始了。","v99/quiz.0.options.2":"把電視關掉。比賽要開始了。","v99/quiz.0.options.3":"把電視放到上面。比賽要開始了。","v99/quiz.0.why":"轉動讓它運作的 turn on 是「打開」。","v99/quiz.1.ko":"好暗。把燈打開。","v99/quiz.1.why":"「打開」是 turn on。","v99/quiz.2.ko":"這台電腦要怎麼開機?","v99/quiz.2.why":"「開機」是 turn on。","v100/meanings.0":"(撐過困難 · 疾病)挺過去 · 熬過來","v100/why":"pull(拉) + through(從頭到尾) → 把自己從艱難的隧道裡從頭拉到尾 = 撐到最後。在度過重病或危機時很常用。和 get through(度過,片語動詞第38個)很像。","v100/object":"不接受詞。He'll pull through. / 讓人撐下去的東西當主詞:Your support pulled me through.","v100/examples.0.scene":"在橋上回顧這一年","v100/examples.0.ko":"我們今年撐過了很多事。","v100/examples.1.scene":"在醫院走廊","v100/examples.1.ko":"醫生說他會挺過來的。","v100/examples.2.scene":"完成一個困難的專案後","v100/examples.2.ko":"多虧你的支持,我才能撐到最後。","v100/similar":"get through (度過,片語動詞第38個) · survive (存活)","v100/quiz.0.options.0":"那一年很辛苦,但我們撐到了最後。","v100/quiz.0.options.1":"那一年很辛苦,但我們一路被拖著走。","v100/quiz.0.options.2":"那一年很辛苦,但我們沒能通過。","v100/quiz.0.options.3":"那一年很辛苦,但我們走過了隧道。","v100/quiz.0.why":"從頭到尾拉出隧道的 pull through 是「熬過來」。","v100/quiz.1.ko":"別擔心。Frank 很堅強。他會挺過去的。","v100/quiz.1.why":"「撐到最後」是 pull through。","v100/quiz.2.ko":"多虧了希望,我才熬過了那段艱難的時光。","v100/quiz.2.why":"pull + 人 + through = 讓人撐到最後。","cast/mina/ko":"Mina","cast/mina/about":"28 歲,來自首爾的 UX 設計師。被派到紐約的公司工作一年","cast/jake/ko":"Jake","cast/jake/about":"同組的工程師。愛開玩笑,對咖啡非常認真","cast/dana/ko":"Dana","cast/dana/about":"組長。忙碌又嚴格,但很公正","cast/rosa/ko":"Rosa","cast/rosa/about":"Mina 的室友。是醫院護理師,所以多半上夜班","cast/leo/ko":"Leo","cast/leo/about":"樓下咖啡廳的老闆。在這條街開了將近 30 年的咖啡廳,什麼街坊消息都知道","cast/guard/ko":"警衛","cast/guard/about":"公司大樓的警衛","cast/daniel/ko":"Daniel","cast/daniel/about":"在公司待了很久的藝術總監。剛結束長假回來","cast/noah/ko":"Noah","cast/noah/about":"Jake 的朋友,也是廚師。原來他是咖啡廳老闆 Leo 的兒子","cast/hill/ko":"Ms. Hill (CEO)","cast/hill/about":"芝加哥客戶公司的負責人。一絲不苟,但看到好東西馬上就能認出來","cast/han/ko":"Mr. Han (CEO)","cast/han/about":"Mina 任職的首爾公司的負責人。收購了紐約的工作室","cast/agent/ko":"房仲","cast/agent/about":"帶人看公寓的房仲","cast/mom/ko":"媽媽","cast/mom/about":"住在首爾的 Mina 的媽媽。最近在學英文","cast/frank/ko":"Frank","cast/frank/about":"Daniel 的父親。戰勝病魔後,迷上了園藝","cast/yoon/ko":"Ms. Yoon (director)","cast/yoon/about":"首爾客戶公司的董事。在多倫多長大,在公司也說英文。嚴格,但錯了就會認錯","cast/dad/ko":"爸爸","cast/dad/about":"Mina 的爸爸。退休後開始學做菜和英文","cast/minsu/ko":"Minsu","cast/minsu/about":"Mina 的弟弟。即將和 Grace 訂婚","cast/grace/ko":"Grace","cast/grace/about":"Minsu 的未婚妻。在洛杉磯長大的韓裔美國人,所以韓文不太流利","e1/title":"抵達","e1/scene.ko":"紐約正下著雨。Mina 提著兩個大行李箱站在入境大廳。電話正在響。","e1/scene.gloss.0.1":"入境大廳","e1/scene.gloss.1.1":"行李箱","e1/lines.0.ko":"Mina!我是公司的 Jake。你在哪裡?","e1/lines.1.ko":"嗨,Jake!我站在入境大廳,咖啡店旁邊。","e1/lines.2.ko":"好。我現在過去接你。你穿什麼?","e1/lines.2.note":"pick you up:受詞是 you,所以放在 pick 和 up 中間。","e1/lines.3.ko":"黃色雨衣。還有我拿著兩個超大的行李箱。","e1/lines.4.ko":"啊,我看到你了!我正在揮手。看左邊!","e1/lines.5.ko":"Jake!嗨!謝謝你來。","e1/lines.6.ko":"不客氣。車停在停車場大樓裡。走吧。","e1/lines.7.ko":"這裡一直都這樣下雨嗎?","e1/lines.8.ko":"只有新來的人到的時候才會。歡迎來到紐約!","e1/quiz.0.why":"對方問你穿什麼,就要用衣服來回答。","e1/quiz.1.ko":"車停在停車場大樓裡。","e1/quiz.1.why":"停車場大樓是四面封閉的空間,所以用 in。","e1/quiz.2.options.0":"我現在過去接你。","e1/quiz.2.options.1":"我現在要把你舉起來。","e1/quiz.2.options.2":"我現在去接電話。","e1/quiz.2.options.3":"我現在去挑你。","e1/quiz.2.why":"I'm coming 是正在過去,pick you up 是去接人。","e1/next":"Mina 在紐約的第一天上班。辦公室裡有人在等她。","e2/title":"第一天上班","e2/prev":"Mina 在下雨的紐約抵達了,公司同事 Jake 到機場來接她。","e2/scene.ko":"星期一早上 8 點 55 分。Mina 和 Jake 走進辦公室。每個人看起來都很忙。一位留著灰色短髮的女士朝兩人揮手。","e2/scene.gloss.0.1":"走進~","e2/scene.gloss.1.1":"看起來很忙","e2/lines.0.ko":"你是 Mina 吧?我是組長 Dana。歡迎!","e2/lines.1.ko":"很高興認識你,Dana。","e2/lines.2.ko":"好,我們工作是這樣的。九點開始,團隊每天早上會開個簡短的會。","e2/lines.3.ko":"還有,咖啡通常是我帶來的。","e2/lines.4.ko":"因為我不喝辦公室的咖啡。喝起來有水的味道。","e2/lines.5.ko":"我記住了。今天有什麼要準備的嗎?","e2/lines.6.ko":"今天沒有。不過三月有一個大客戶要來訪,所以我們常常加班到很晚。","e2/lines.7.ko":"原來如此。老實說,我有點緊張。","e2/lines.8.ko":"別擔心。第一週大家都手忙腳亂。","e2/lines.9.ko":"來吧,Mina。我帶你去你的座位。視野最棒了!","e2/lines.9.note":"Come on:這裡是「來吧 · 走吧」的輕鬆催促。","e2/quiz.0.why":"對方問有什麼要準備的,所以接著說「今天沒有」。","e2/quiz.1.ko":"大客戶三月要來訪。","e2/quiz.1.why":"一個月是有長度的時間容器,所以用 in。","e2/quiz.2.ko":"Dana 不喝辦公室的咖啡。","e2/quiz.2.why":"Dana 是 she,所以用 doesn't + 原形 drink。","e2/next":"週末,Mina 在新家拆箱整理。可是室友的房門還關著。","e3/title":"室友","e3/prev":"第一天上班,Mina 見到了組長 Dana。三月有大客戶要來訪,所以團隊很忙。","e3/scene.ko":"星期六下午 1 點。Mina 週末通常會睡晚一點,但今天在拆箱子。室友的房門還關著。","e3/scene.gloss.0.1":"拆箱整理(行李)","e3/scene.gloss.1.1":"室友、同住的人","e3/lines.0.dir.ko":"打著哈欠","e3/lines.0.ko":"啊,嗨。你就是 Mina 吧。","e3/lines.1.ko":"嗨!抱歉,我是不是太吵了?","e3/lines.2.ko":"沒關係。我在醫院上夜班,所以白天都在睡覺。","e3/lines.3.ko":"天啊。我現在才知道這裡為什麼這麼安靜。","e3/lines.3.note":"understand 是狀態動詞,所以不會說 I'm understanding。","e3/lines.4.ko":"別擔心。反正我也該起床了。我的班五個小時後開始。","e3/lines.5.ko":"我正在煮咖啡。你要喝一點嗎?","e3/lines.6.ko":"好,謝謝。那,你喜歡這間房子嗎?","e3/lines.7.ko":"超喜歡。可是我在這附近還一個人都不認識。","e3/lines.8.ko":"去找樓下咖啡廳的老闆聊聊吧。關於這條街的事,你都可以從他那裡打聽到。他知道每個人的祕密!","e3/lines.9.ko":"每個人的祕密?好,跟他說話得小心一點了。","e3/lines.9.note":"think 如果是「認為」的意思,就不用進行式。","e3/quiz.0.why":"對方問你要喝嗎,所以接著說「好,謝謝」。","e3/quiz.1.ko":"我的班五個小時後開始。","e3/quiz.1.why":"是從現在起算五小時後,所以用 in。","e3/quiz.2.ko":"關於這條街的事,你都可以從他那裡打聽到。","e3/quiz.2.why":"查出不知道的事實是 find out。","e3/next":"樓下咖啡廳的老闆真的知道每個人的祕密嗎?","e4/title":"咖啡廳老闆","e4/prev":"室友 Rosa 是上夜班的護理師。Rosa 說樓下咖啡廳的老闆知道這條街所有的祕密。","e4/scene.ko":"星期天早上。樓下的咖啡廳飄著剛出爐的麵包香。一位留著白色小鬍子的老先生站在櫃檯後面。","e4/scene.gloss.0.1":"小鬍子","e4/scene.gloss.1.1":"櫃檯","e4/lines.0.ko":"早安!你就是樓上新搬來的小姐吧?Rosa 跟我說過了。","e4/lines.1.ko":"對,我是 Mina。上週搬來的。","e4/lines.2.ko":"歡迎!我是 Leo。我 1998 年開了這間咖啡廳。","e4/lines.3.ko":"哇。那這裡的人您都認識嗎?","e4/lines.4.ko":"都認識啊。就拿你朋友 Jake 來說吧。上星期五他急急忙忙衝進來。","e4/lines.5.ko":"等一下。您認識 Jake?","e4/lines.6.ko":"當然。他買了兩杯咖啡,還有一大束花。","e4/lines.7.ko":"花?要送給誰?","e4/lines.8.ko":"他沒說。不過相信我,那小子戀愛了。","e4/lines.9.ko":"Jake 戀愛了?我現在真的需要一杯咖啡了。","e4/quiz.0.why":"對方問送給誰,所以接著說「他沒說」。","e4/quiz.1.ko":"那小子戀愛了。","e4/quiz.1.why":"戀愛是一種狀態的容器,所以用 in。","e4/quiz.2.ko":"Rosa 跟我說過你的事。","e4/quiz.2.why":"是過去的事,所以用過去式。tell 的過去式是 told(不規則)。","e4/next":"Mina 很好奇那束花是送給誰的。午餐時間她能向 Jake 問出來嗎?","e5/title":"午餐時間","e5/prev":"咖啡廳老闆 Leo 說上星期五 Jake 買了一束花。他說 Jake 戀愛了。","e5/scene.ko":"星期二中午 12 點 30 分。Mina 和 Jake 在墨西哥捲餅餐車前排隊。Mina 正在用韓文寫筆記。","e5/scene.gloss.0.1":"排隊","e5/scene.gloss.1.1":"賣墨西哥捲餅的餐車","e5/lines.0.ko":"你在寫什麼?","e5/lines.1.ko":"只是待辦清單。我都用韓文寫。","e5/lines.2.ko":"好酷。對了,我早上在找你。你在做什麼?","e5/lines.3.ko":"我在跟 Dana 討論 logo。怎麼了?","e5/lines.4.ko":"沒什麼事。啊,輪到我們了。請給我兩個墨西哥捲餅。可以付現嗎?","e5/lines.5.ko":"不過 Jake……星期天 Leo 跟我說了一個抱著一大堆花的男人的事。","e5/lines.6.dir.ko":"嗆到","e5/lines.6.ko":"Leo 說的?那個老先生話也太多了!","e5/lines.7.ko":"真的有這回事!那個幸運的人是誰?","e5/lines.8.ko":"嗯……有點複雜。對了,我們幾個人每週五都會去酒吧玩。這週你要一起來嗎?","e5/lines.9.ko":"我知道你在轉移話題。不過好啊,我會去!","e5/quiz.0.why":"對方問你早上在做什麼,所以用當時在做的事來回答。","e5/quiz.1.ko":"可以付現嗎?","e5/quiz.1.why":"現金是裝錢的容器,所以是 in cash。","e5/quiz.2.ko":"我們幾個人每週五都在酒吧聚會玩樂。","e5/quiz.2.why":"一起混、一起玩是 hang out。","e5/next":"週五晚上的約會,Mina 真的去得成嗎?","e6/title":"螢幕上的便條","e6/prev":"午餐時間,Jake 避開花束的話題,邀請 Mina 參加週五的聚會。","e6/scene.ko":"星期一早上。Mina 的螢幕上貼著一張黃色便條。Jake 走向 Mina 的座位。","e6/scene.gloss.0.1":"便利貼","e6/scene.gloss.1.1":"朝~的方向","e6/lines.0.ko":"喂!你星期五沒來耶!我等了你一個小時!","e6/lines.1.ko":"真的很抱歉!我看電影看到睡著了。","e6/lines.2.ko":"我就知道。那下次要來喔。不過你螢幕上貼的那個是什麼?","e6/lines.3.ko":"不知道。我來的時候就已經貼在那裡了。","e6/lines.4.ko":"我看看。\\"logo 做得真好。—D.\\"","e6/lines.5.ko":"D?Dana?","e6/lines.6.ko":"不可能啦。Dana 絕對不會寫便條。她只會半夜 12 點寄 email。","e6/lines.7.ko":"那會是誰?我去拿咖啡的時候,有誰在我座位附近嗎?","e6/lines.8.ko":"嗯。我經過的時候有個人站在這裡。高個子男生,灰色外套。","e6/lines.9.ko":"穿灰色外套的高個子男生?好。如果他再出現,告訴我喔!","e6/quiz.0.why":"對方問你為什麼沒來,就用道歉和理由來回答。","e6/quiz.1.ko":"你螢幕上貼的那個是什麼?","e6/quiz.1.why":"貼在螢幕表面上,所以用 on。","e6/quiz.2.ko":"我看電影看到睡著了。","e6/quiz.2.why":"while 後面接正在做的事。I 要用 was watching。","e6/next":"留下便條的 D 是誰?不過 Mina 又把門禁卡弄丟了。","e7/title":"遺失的門禁卡","e7/prev":"Mina 的螢幕上貼著一張寫著 \\"logo 做得真好。—D.\\" 的便條。聽說有個穿灰色外套的高個子男生待在 Mina 的座位附近。","e7/scene.ko":"星期三早上 9 點 10 分。Mina 站在辦公室門口,每個口袋都翻遍了。警衛在一旁看著她。","e7/scene.gloss.0.1":"翻找 · 搜尋","e7/scene.gloss.1.1":"警衛","e7/lines.0.ko":"早安。需要幫忙嗎?","e7/lines.1.ko":"我好像把門禁卡弄丟了。到處都找不到。","e7/lines.2.ko":"您檢查過包包了嗎?","e7/lines.3.ko":"檢查了兩次。慘了,我星期四要給 Dana 看新 logo 耶!","e7/lines.4.dir.ko":"走過來","e7/lines.4.ko":"Mina?怎麼了?","e7/lines.5.ko":"我的門禁卡不見了。這是我第一次在公司弄丟東西!","e7/lines.6.ko":"冷靜點。我光今年就弄丟三次了。警衛室會幫你重做一張。","e7/lines.7.ko":"對啊。只要十分鐘。","e7/lines.8.ko":"真的嗎?太好了。抱歉,我剛剛嚇壞了。","e7/lines.9.ko":"你看吧,事情總是會順利解決的。咦,你看那邊。那個穿灰色外套的高個子男生,是不是他?","e7/quiz.0.why":"對方問有沒有檢查包包,所以用「兩次」來回答。","e7/quiz.1.ko":"我星期四要給 Dana 看新 logo。","e7/quiz.1.why":"星期幾是月曆上的一格,所以用 on。","e7/quiz.2.ko":"我弄丟了門禁卡。我找不到。","e7/quiz.2.why":"弄丟了,所以現在沒有,表示結果,要用 have lost。","e7/next":"還沒來得及跟上那個穿灰色外套的男生,大截止日就逼近了。","e8/title":"截止日前一天","e8/prev":"Mina 弄丟門禁卡後領了新的。這時又看到了那個穿灰色外套的高個子男生。","e8/scene.ko":"星期三下午 6 點。辦公室幾乎空了。Jake 瞪著螢幕,抓著自己的頭髮。","e8/scene.gloss.0.1":"瞪著~ · 盯著看","e8/scene.gloss.1.1":"抓頭髮","e8/lines.0.ko":"Jake,你還好嗎?","e8/lines.1.ko":"不好!後天就要 demo 了,app 剛剛又當掉了!","e8/lines.2.ko":"冷靜點。你有存檔嗎?","e8/lines.3.ko":"有,但 bug 還沒修好。而且整個 demo 都靠這個功能耶。","e8/lines.4.ko":"好。我已經把 logo 做完了,所以有時間。給我看看。","e8/lines.5.ko":"真的嗎?你懂程式碼?","e8/lines.6.ko":"懂一點。我在首爾的團隊裡沒有工程師。","e8/lines.7.ko":"Mina 你真是救了我一命。Dana 最倚重的就是這場 demo。","e8/lines.8.ko":"那就來修吧。還有,Jake?你可以相信我。","e8/lines.9.ko":"謝謝你,Mina。呃……Dana 的辦公室裡是誰?燈剛剛亮了。","e8/lines.9.note":"come on 也有「(燈)亮起來」的意思(片語動詞第2個)。","e8/quiz.0.why":"對方問有沒有存檔,所以用「有,不過……」來回答。","e8/quiz.1.ko":"整個 demo 都靠這個功能。","e8/quiz.1.why":"重量壓在這個功能上的畫面,所以用 depend on。","e8/quiz.2.ko":"我 bug 還沒修好。","e8/quiz.2.why":"否定句句尾的「還」用 yet。","e8/next":"深夜裡,在 Dana 辦公室開燈的人是誰?","e9/title":"D 的真面目","e9/prev":"demo 前夕,Mina 幫 Jake 一起修了 bug。這時 Dana 辦公室的燈亮了。","e9/scene.ko":"星期四早上。整個團隊聚在會議室。一位穿灰色外套的高個子男生站在 Dana 旁邊。","e9/scene.gloss.0.1":"會議室","e9/scene.gloss.1.1":"在~旁邊","e9/lines.0.ko":"各位,這位是藝術總監 Daniel。他剛結束長假回來。","e9/lines.1.ko":"大家好。Mina,我們還是第一次見面。對了,logo 做得真好。","e9/lines.2.ko":"等一下……你就是 \\"D\\"?留便條的人!","e9/lines.3.ko":"被你抓到了。星期一我提早來看你的作品。","e9/lines.4.ko":"Daniel 從 2014 年就在這裡工作了。關於這個品牌,他沒有不知道的事。","e9/lines.5.ko":"我離開了六個月,所以請告訴我。客戶專案進行得怎麼樣了?","e9/lines.6.ko":"demo 明天就要開始了。昨晚多虧 Mina,我們把一個大 bug 修好了。","e9/lines.7.ko":"太棒了。Mina,下週我有一場關於色彩的短講,你可以幫我嗎?","e9/lines.8.ko":"好啊!我一直很想向資深設計師學習。","e9/lines.9.ko":"太好了。那我們繼續開會吧?","e9/quiz.0.why":"對方問你是不是留便條的人,所以回答「被你抓到了」。","e9/quiz.1.ko":"下週我有一場關於色彩的短講。","e9/quiz.1.why":"講座的主題用 on。","e9/quiz.2.ko":"Daniel 從 2014 年就在這裡工作了。","e9/quiz.2.why":"2014 是起點,所以用 since。","e9/next":"為了準備 Daniel 的講座,Mina 在辦公室待到很晚。","e10/title":"亮著的燈","e10/prev":"\\"D\\" 是藝術總監 Daniel。Daniel 請 Mina 幫忙準備下週的色彩講座。","e10/scene.ko":"星期四晚上 11 點。辦公室一片黑暗。只有一盞檯燈還亮著。Mina 吃完晚餐後就一直在做 Daniel 的投影片。","e10/scene.gloss.0.1":"檯燈 · 燈","e10/scene.gloss.1.1":"簡報投影片","e10/lines.0.ko":"Mina?你還在嗎?","e10/lines.1.ko":"哇!Daniel。我在修色票。快好了。","e10/lines.2.ko":"你坐在這裡幾個小時了?","e10/lines.3.ko":"從七點開始嗎?我都沒發覺時間過去了。","e10/lines.4.ko":"你的眼睛都紅了。你整晚都在盯著螢幕嗎?","e10/lines.5.ko":"好像是。不過我想讓投影片完美一點。","e10/lines.6.ko":"已經很棒了。回家吧。這是命令。","e10/lines.7.ko":"好啦,好啦。我把電腦關掉。","e10/lines.8.ko":"檯燈也關掉。Dana 不喜歡燈整晚開著。","e10/lines.9.dir.ko":"笑著","e10/lines.9.ko":"知道了。不過 Daniel……你為什麼這麼晚還在?","e10/quiz.0.why":"對方問坐了多久,所以用「從七點開始」來回答。","e10/quiz.1.ko":"Dana 不喜歡燈整晚開著。","e10/quiz.1.why":"開著的狀態用 on。","e10/quiz.2.ko":"我把電腦關掉。","e10/quiz.2.why":"是為了回家而關機,所以用 turn off。","e10/next":"深夜還留在辦公室的 Daniel,看起來也有自己的苦衷。","e11/title":"公車上遇到的人","e11/prev":"深夜的辦公室裡,Daniel 叫 Mina 回家。Mina 問了 Daniel 為什麼這麼晚還在。","e11/scene.ko":"星期五早上 8 點。Mina 在通勤公車上。公車很擠。有人輕輕拍了拍 Mina 的肩膀。","e11/scene.gloss.0.1":"擁擠的","e11/scene.gloss.1.1":"輕拍","e11/lines.0.ko":"Mina!沒想到會在這裡遇到你。","e11/lines.1.ko":"Daniel!早安。你昨晚有睡一下嗎?","e11/lines.2.ko":"睡了一點。昨晚你問了我問題,我沒有回答,對吧。","e11/lines.3.ko":"啊,您不用說也沒關係……","e11/lines.4.ko":"沒關係。去年我父親生病了。所以我休息了六個月。","e11/lines.5.ko":"天啊。他現在好一點了嗎?","e11/lines.6.ko":"好多了。不過我已經習慣在晚上工作了。因為很安靜。","e11/lines.7.ko":"我懂。我光是這個星期就加班到很晚三次了!","e11/lines.7.note":"this week 是還沒結束的期間,所以用現在完成式。","e11/lines.8.ko":"哈哈!別告訴 Dana。你看,Jake 在公車站耶。他一邊講電話一邊笑得像小孩一樣。","e11/lines.9.ko":"他這個星期一直都這樣。我大概知道為什麼了。","e11/quiz.0.why":"對方問父親現在怎麼樣,所以用「好多了」來回答。","e11/quiz.1.ko":"他一邊講電話一邊笑得像小孩一樣。","e11/quiz.1.why":"電話是話語來回傳遞的平台,所以用 on the phone。","e11/quiz.2.ko":"去年我父親生病了。","e11/quiz.2.why":"last year 是已經結束的時間,所以用過去式。","e11/next":"demo 當天早上。客戶已經到了,投影機卻出問題。","e12/title":"Demo Day","e12/prev":"在通勤公車上,Daniel 說出了父親的事。公車站的 Jake 正一邊講電話一邊笑。","e12/scene.ko":"星期五早上 10 點。Mina 到的時候,客戶已經在了。Dana 在會議室門口等著。","e12/scene.gloss.0.1":"客戶","e12/scene.gloss.1.1":"會議室","e12/lines.0.ko":"你來了!客戶在我到之前就已經到了。","e12/lines.1.ko":"對不起。公車每一站都停。","e12/lines.2.ko":"各位,出問題了。投影機不能用。","e12/lines.3.ko":"什麼?客戶來之前我還測試過耶!","e12/lines.4.ko":"我都試過了。我不知道是哪裡有問題。","e12/lines.5.ko":"我看看。啊!有人把線拔掉了。","e12/lines.6.ko":"你五秒就找出來了!","e12/lines.7.ko":"好。那麼,大家請就座。Jake,你到前面來。","e12/lines.8.dir.ko":"demo 結束後","e12/lines.8.ko":"完美結束了!在今天之前,我從來沒有在客戶面前做過 demo。","e12/lines.9.ko":"你做得真好。咦,你手機有訊息。\\"今晚在 Leo 的店見 ♥ R.\\" R 是誰?","e12/quiz.0.why":"接著是對 Mina 立刻找出問題的驚嘆。","e12/quiz.1.ko":"Dana 在門口等著。","e12/quiz.1.why":"門口是一個定點,所以用 at。","e12/quiz.2.ko":"Mina 到的時候,客戶已經在了。","e12/quiz.2.why":"這件事發生在 Mina 到達之前,所以用 had come。","e12/next":"\\"♥ R\\" 是誰?Mina 當晚前往 Leo 的咖啡廳。","e13/title":"被拆穿的祕密","e13/prev":"demo 順利結束了。Jake 的手機跳出一則訊息:\\"今晚在 Leo 的店見 ♥ R\\"。","e13/scene.ko":"星期五晚上 7 點。Mina 走進 Leo 的咖啡廳。Jake 和 Rosa 手牽著手並肩坐著。","e13/scene.gloss.0.1":"走進~","e13/scene.gloss.1.1":"牽手","e13/lines.0.ko":"Rosa?Jake?你們兩個?!","e13/lines.1.ko":"Mina!其實……我來解釋。","e13/lines.2.ko":"Mina 你搬來的時候,我們已經交往兩個月了。","e13/lines.3.ko":"兩個月?那那束花……還有半夜 12 點的電話……","e13/lines.4.ko":"對不起。我幾個星期前就想跟你說了。","e13/lines.5.ko":"那為什麼沒說?","e13/lines.6.ko":"我們很怕。因為我們連公司的人都瞞著。","e13/lines.7.dir.ko":"在櫃檯","e13/lines.7.ko":"我說過了吧,Mina!我說那小子戀愛了!","e13/lines.8.dir.ko":"笑著","e13/lines.8.ko":"好啦,好啦。我沒生氣。不過從現在起不准再有祕密了,好嗎?","e13/lines.9.ko":"說好了!還有,我們的週五聚會可別放棄。下週五八點。這次不要睡著喔!","e13/quiz.0.why":"對方問為什麼沒說,所以用理由來回答。","e13/quiz.1.ko":"下週五八點。","e13/quiz.1.why":"時刻是一個點,所以用 at。","e13/quiz.2.ko":"Mina 你搬來的時候,我們已經交往兩個月了。","e13/quiz.2.why":"這是持續到搬來那個過去時間點的事,所以用 had been dating。","e13/next":"祕密揭曉的下一週,Daniel 的色彩講座準備正式展開。","e14/title":"講座準備","e14/prev":"Jake 和 Rosa 一直在偷偷交往。Mina 約定從現在起不再有祕密,並替兩人加油。","e14/scene.ko":"星期一早上。Daniel 正在牆上貼行程表。Mina 仔細地看著。","e14/scene.gloss.0.1":"用圖釘釘上","e14/scene.gloss.1.1":"行程表","e14/lines.0.ko":"你看這個。講座星期三下午開始,明天有彩排。","e14/lines.1.ko":"明天?明天早上我要跟 Dana 見面談客戶的 logo。","e14/lines.2.ko":"沒關係。彩排是吃完午餐後開始。還有,別忘了後半段是由 Mina 你來報告。","e14/lines.3.dir.ko":"經過時","e14/lines.3.ko":"你們在準備那場有名的色彩講座嗎?聽說大家都會來。","e14/lines.4.ko":"大家?我現在緊張起來了。如果大家看到我的投影片笑我怎麼辦?","e14/lines.5.ko":"相信我,你的投影片真的很漂亮。","e14/lines.6.ko":"而且我很期待免費的披薩。","e14/lines.6.note":"look forward to 後面要接名詞或 -ing。","e14/lines.7.ko":"沒有披薩,Jake。","e14/lines.8.ko":"什麼?那我為什麼要去?","e14/lines.9.dir.ko":"笑著","e14/lines.9.ko":"當然是去幫我加油啊!老實說,我很期待星期三。","e14/quiz.0.why":"接著是安撫擔心的 Mina 的話。","e14/quiz.1.ko":"如果大家看到我的投影片笑我怎麼辦?","e14/quiz.1.why":"笑的對象像靶心,所以用 at。","e14/quiz.2.ko":"我明天早上要跟 Dana 見面。","e14/quiz.2.why":"這是跟人約好的事,所以用現在進行式。","e14/next":"彩排當天,投影片的顏色看起來怪怪的。","e15/title":"彩排","e15/prev":"Daniel 的講座在星期三。後半段由 Mina 報告。","e15/scene.ko":"星期二下午 2 點。彩排的房間很暗。在這種亮度下,Mina 的投影片看起來怪怪的。","e15/scene.gloss.0.1":"彩排、預演","e15/scene.gloss.1.1":"亮度","e15/lines.0.ko":"天啊。顏色一團亂!Daniel,我崩潰了。","e15/lines.1.ko":"別慌。只是投影機現在只開一半亮度而已。","e15/lines.2.ko":"明天之前修得好嗎?","e15/lines.3.ko":"當然。我現在就打給技術組。","e15/lines.4.dir.ko":"走進來","e15/lines.4.ko":"等一下,我認得這台投影機。我來吧。給我兩分鐘。","e15/lines.5.ko":"好了。現在是最大亮度。","e15/lines.6.ko":"哇,好多了!謝謝你,Jake。明天午餐我請你。","e15/lines.7.ko":"好啊。還有別擔心。Mina 你的報告一定會很棒。","e15/lines.8.ko":"Jake 說得對。大家一定會很喜歡你的投影片。","e15/lines.9.ko":"希望如此。你們兩個可以坐在第一排嗎?","e15/quiz.0.why":"對方問修不修得好,就當場決定要做的事來回答。","e15/quiz.1.ko":"投影機現在只開一半亮度。","e15/quiz.1.why":"亮度刻度上的一個點,所以用 at。","e15/quiz.2.ko":"別慌。很容易修好的。","e15/quiz.2.why":"叫人不要嚇得失控,是 Don't freak out。","e15/next":"終於到了講座當天。Mina 的手在發抖。","e16/title":"講座當天","e16/prev":"彩排時投影機出了問題,但 Jake 修好了。","e16/scene.ko":"星期三下午。講座三點在 3 樓 5 號室舉行。座無虛席。","e16/scene.gloss.0.1":"樓層","e16/scene.gloss.1.1":"座位","e16/lines.0.ko":"準備好了嗎?我先從色彩的歷史開始,接著 Mina 你來展示 logo。","e16/lines.1.ko":"好。天啊,我的手在發抖。我覺得我要昏倒了。","e16/lines.2.ko":"你不會昏倒的。我去幫你拿水。","e16/lines.3.dir.ko":"講座結束後","e16/lines.3.ko":"你們兩位都很棒。客戶一定會很喜歡。","e16/lines.4.ko":"謝謝!我剛剛超緊張。","e16/lines.5.ko":"還有個消息。從下週開始,為了客戶專案,我們要分成兩個團隊。","e16/lines.6.ko":"等一下,我跟 Mina 不是同一組嗎?我們要分手了嗎?","e16/lines.6.note":"這是把「拆分團隊」的 break up 故意說成「分手」的玩笑。","e16/lines.7.dir.ko":"笑著","e16/lines.7.ko":"Jake,我們根本沒交往過啊!","e16/lines.8.ko":"我知道。不過我會想念我最愛的 bug 剋星的。","e16/lines.9.ko":"冷靜點。我們會坐在隔壁。好了,有誰要喝咖啡?我請客。","e16/quiz.0.why":"對方說快昏倒了,就用安撫的話和當下能幫上的事來回答。","e16/quiz.1.ko":"講座在 3 樓 5 號室,三點開始。","e16/quiz.1.why":"樓層是地板那一面,所以用 on。","e16/quiz.2.ko":"從下週開始,我們要分成兩個團隊。","e16/quiz.2.why":"把一個整體拆開,是 break up。","e16/next":"團隊分成兩組後,Mina 要和 Dana 一起準備去芝加哥出差。","e17/title":"前往芝加哥","e17/prev":"講座很成功。Dana 說從下週起要把團隊分成兩組。","e17/scene.ko":"星期四晚上。Mina 正在收拾一個小行李箱。下週一,她要和 Dana 飛去芝加哥。","e17/scene.gloss.0.1":"打包行李","e17/scene.gloss.1.1":"行李箱","e17/lines.0.ko":"所以下週二你就會在見大客戶了吧?","e17/lines.1.ko":"對!而且到週五左右,我應該已經把設計全部完成了。","e17/lines.2.ko":"看看你!一個月前你還怕搭地鐵呢。","e17/lines.3.dir.ko":"笑著","e17/lines.3.ko":"現在還是會怕。咦,這是什麼?啊……是以前的手機。","e17/lines.4.ko":"照片裡那個人是誰?","e17/lines.5.ko":"Minho。我們去年分手了。他因為工作搬到釜山去了。","e17/lines.6.ko":"你還好嗎?你已經放下了嗎?","e17/lines.7.ko":"應該吧。我來紐約也有一部分是因為這個。我需要忘掉過去、重新開始。","e17/lines.8.ko":"嗯,明年的這個時候,你大概就在跟我聊某個帥氣的紐約人了。","e17/lines.9.ko":"哈!到那時候我已經回首爾了。","e17/quiz.0.why":"對方問你放下了嗎,所以用「應該吧」來回答。","e17/quiz.1.ko":"他因為工作搬到釜山去了。","e17/quiz.1.why":"搬家後抵達的地方,所以用 to。","e17/quiz.2.ko":"到週五左右,我應該已經把設計全部完成了。","e17/quiz.2.why":"這是到 by Friday 就會完成的事,所以用未來完成式。","e17/next":"抵達芝加哥的 Mina 接到 Jake 的緊急電話。","e18/title":"來自芝加哥的電話","e18/prev":"正在收拾去芝加哥出差行李的 Mina 看到了前男友 Minho 的照片。Mina 是為了重新開始才來紐約的。","e18/scene.ko":"星期一下午 6 點。Mina 和 Dana 在芝加哥搭計程車。Mina 的電話響了。是 Jake。","e18/scene.gloss.0.1":"計程車","e18/scene.gloss.1.1":"(電話)響起","e18/lines.0.ko":"Mina!平安到了嗎?我們得談談檔案的事。","e18/lines.1.ko":"剛到。我可以再回電給你嗎?我跟 Dana 在計程車上。","e18/lines.1.note":"call you back:代名詞要放在 call 和 back 中間。","e18/lines.2.ko":"當然。不過到了之後檢查一下 email。我寄了新的 logo。","e18/lines.3.ko":"知道了。一到我就看。","e18/lines.4.ko":"是 Jake 嗎?跟他說客戶想要更深的顏色。","e18/lines.5.ko":"Jake,Dana 說客戶想要更深的顏色。你今晚可以把修改版寄給 Dana 嗎?","e18/lines.6.ko":"我試試看。改好之後再傳訊息給你。","e18/lines.7.ko":"謝謝。我辦完入住會再打給你。","e18/lines.8.dir.ko":"微笑著","e18/lines.8.ko":"你們兩個很有默契呢。","e18/lines.9.ko":"是啊。啊!Dana,我忘了把這個給您。這是 Daniel 寫給您的信。","e18/quiz.0.why":"對方叫你檢查 email,所以回答一到就會看。","e18/quiz.1.ko":"你今晚可以把修改版寄給 Dana 嗎?","e18/quiz.1.why":"修改版是送到 Dana 手上,是接收的人,所以用 to。","e18/quiz.2.ko":"一到我就看。","e18/quiz.2.why":"as soon as 後面,未來的事也用現在式。","e18/next":"Daniel 寫給 Dana 的信裡寫了什麼呢?","e19/title":"Daniel 的信","e19/prev":"抵達芝加哥的 Mina 和 Jake 談了修改版的事。接著她把 Daniel 的信交給了 Dana。","e19/scene.ko":"星期二早上。Mina 和 Dana 在飯店吃早餐。Dana 正在讀 Daniel 的信。","e19/scene.gloss.0.1":"早餐","e19/scene.gloss.1.1":"信","e19/lines.0.ko":"你還好嗎?你看起來有心事。","e19/lines.1.ko":"Daniel 想改成兼職。只上九點到一點。","e19/lines.2.ko":"為什麼?是因為他父親嗎?","e19/lines.3.ko":"對。他現在沒辦法待到很晚了。下午他得陪在父親身邊。","e19/lines.4.ko":"客戶專案做得完嗎?","e19/lines.5.ko":"我希望可以。我進公司的時候,Daniel 一個小時就能設計出一個 logo。他是傳奇。","e19/lines.6.ko":"他現在還是傳奇。而且這個專案我會陪您做到最後。","e19/lines.7.ko":"謝謝你,Mina。好,我們十點前得在飯店退房。","e19/lines.8.ko":"這麼快?我在芝加哥什麼都還沒看到耶!","e19/lines.9.dir.ko":"微笑著","e19/lines.9.ko":"飛機是晚上的。開完會你可以去逛逛河濱步道。","e19/quiz.0.why":"對方問是不是因為父親,所以用「對」和原因來回答。","e19/quiz.1.ko":"只上九點到一點。","e19/quiz.1.why":"from A to B,範圍的終點,所以用 to。","e19/quiz.2.ko":"我在芝加哥什麼都沒看到!","e19/quiz.2.why":"是過去沒能做到的事,所以用 wasn't able to。","e19/next":"芝加哥客戶的回覆來了。但那是令所有人驚訝的消息。","e20/title":"浮現的點子","e20/prev":"Daniel 因為父親的緣故,決定只上上午的班。Mina 說她會陪這個專案做到最後。","e20/scene.ko":"星期四。回到紐約的團隊聚在會議室。出乎大家意料,客戶說他們不喜歡更深的顏色。","e20/scene.gloss.0.1":"驚訝","e20/scene.gloss.1.1":"更深 · 更暗","e20/lines.0.ko":"好,各位。下週一前我們需要新的點子。有誰想得到什麼嗎?","e20/lines.1.ko":"我們可以重寫第一版。","e20/lines.2.ko":"不行,那個他們也不喜歡。","e20/lines.3.ko":"這個如何?我們可以問問 Daniel。他以前的草圖裡說不定有點子。","e20/lines.4.dir.ko":"視訊通話中","e20/lines.4.ko":"其實我昨晚就想到一個了。","e20/lines.5.ko":"我就知道會這樣。","e20/lines.6.ko":"如果 logo 會動呢?就像隨著音樂跳舞一樣。","e20/lines.7.ko":"嗯。說不定可行。","e20/lines.8.ko":"太棒了!這個週末我可以做動畫。","e20/lines.9.ko":"連我都很驚訝,但我真的很喜歡。就這麼做吧!","e20/quiz.0.why":"對於新點子,用「說不定可行」來回應。","e20/quiz.1.ko":"連我都很驚訝,但我真的很喜歡。","e20/quiz.1.why":"結果是抵達了驚訝這個狀態,所以用 To my surprise。","e20/quiz.2.ko":"有誰想得到什麼嗎?","e20/quiz.2.why":"「想出」是 come up with。","e20/next":"會動的 logo,Mina 能在週末內做出來嗎?","e21/title":"週末趕工","e21/prev":"芝加哥客戶不喜歡更深的顏色。Daniel 想到了隨著音樂動起來的 logo,Mina 決定週末來做。","e21/scene.ko":"星期一早上 9 點。Mina 的眼睛下面一片黑。整個團隊都在等 Mina 按下播放鍵。","e21/scene.gloss.0.1":"眼睛下的黑眼圈","e21/scene.gloss.1.1":"按下播放鍵","e21/lines.0.ko":"哇。你一定累壞了。有睡一下嗎?","e21/lines.1.ko":"沒什麼睡。最後整個週末都在趕工。","e21/lines.2.ko":"好,我們就是在等這個。給我們看吧。","e21/lines.3.dir.ko":"按下播放鍵","e21/lines.3.ko":"請看。","e21/lines.4.ko":"不會吧。那怎麼可能是同一個 logo!","e21/lines.5.dir.ko":"視訊通話中","e21/lines.5.ko":"就是同一個 logo。而且很完美。Mina,你一定很驕傲。","e21/lines.6.ko":"謝謝。老實說,我現在只想找紐約最濃的咖啡。","e21/lines.7.ko":"是 Leo 的店吧。濃到一定是違法的。","e21/lines.8.ko":"咖啡晚點再說。先把這個寄給客戶。Jake,請他們在星期三前給我們回饋。","e21/lines.9.ko":"馬上辦。Mina,你不可能是人。誰會整個週末都在工作?","e21/quiz.0.why":"對方問有沒有睡,所以用「沒什麼睡」和原因來回答。","e21/quiz.1.ko":"我們就是在等這個。","e21/quiz.1.why":"期待它到來而等待,用 wait for。","e21/quiz.2.ko":"那怎麼可能是同一個 logo!","e21/quiz.2.why":"確信不可能的事,用 can't。","e21/next":"客戶什麼時候會回覆?Mina 焦急地等著。","e22/title":"等待","e22/prev":"團隊所有人都為 Mina 週末做出的動態 logo 讚嘆。Jake 請客戶給回饋。","e22/scene.ko":"星期三下午。客戶還沒有回信。Mina 一直在看手機。","e22/scene.gloss.0.1":"還在","e22/scene.gloss.1.1":"一直~","e22/lines.0.ko":"已經三點了。他們可能不喜歡。","e22/lines.1.ko":"或者他們說不定還在一遍又一遍地看。","e22/lines.2.ko":"你這樣說是想讓我打起精神吧。","e22/lines.3.ko":"有效嗎?來,這是買給你的。","e22/lines.4.ko":"是 Leo 的咖啡!太棒了。","e22/lines.5.ko":"別擔心,Mina。客戶本來就慢。說不定要到星期五才會回覆。","e22/lines.6.ko":"星期五?在那之前我可能就瘋了。","e22/lines.7.ko":"那今晚來做點有趣的事吧。Rosa 說要幫我們做晚餐。","e22/lines.8.ko":"Rosa 要下廚?這說不定是我今天聽到最棒的主意。","e22/lines.9.ko":"而且她說還在烤蛋糕,幫 Mina 打氣。","e22/quiz.0.why":"對方問是不是想讓人打起精神,所以用「有效嗎?」回敬。","e22/quiz.1.ko":"來,這是買給你的。","e22/quiz.1.why":"是為了 Mina 買的,所以用 for。","e22/quiz.2.ko":"他們可能不喜歡。","e22/quiz.2.why":"表示「說不定」,用 might + 原形。","e22/next":"隔天早上,Mina 的動畫檔案不見了。","e23/title":"消失的檔案","e23/prev":"在焦急等候客戶回覆的 Mina 身邊,Jake 和 Rosa 準備了晚餐為她加油。","e23/scene.ko":"星期四早上。Mina 打開團隊資料夾。動畫檔案不見了。","e23/scene.gloss.0.1":"資料夾","e23/scene.gloss.1.1":"不見","e23/lines.0.ko":"Jake!動畫檔案不見了!","e23/lines.1.ko":"什麼?昨晚還在的。一定是有人把它移走了。","e23/lines.2.ko":"我做了三天耶。三天!","e23/lines.3.ko":"冷靜點。想想看。昨晚誰用過伺服器?","e23/lines.4.ko":"只有新來的實習生 Ben。說不定是他不小心刪掉了。","e23/lines.5.ko":"Ben?不可能是 Ben。他已經生病在家兩天了。","e23/lines.6.ko":"那是誰把伺服器弄亂的?","e23/lines.7.dir.ko":"走進來","e23/lines.7.ko":"是我。對不起,是我搞錯了。早上我把它移到舊的封存資料夾去了。","e23/lines.8.ko":"所以它沒有永遠消失?啊,太好了。","e23/lines.9.ko":"你看吧。我就說一定是有人把它移走了。我是天才。","e23/quiz.0.why":"對方問是誰,所以 Daniel 出來說「是我」。","e23/quiz.1.ko":"我做了三天。","e23/quiz.1.why":"three days 是一段長度,所以用 for。","e23/quiz.2.ko":"一定是有人把它移走了。","e23/quiz.2.why":"對過去的事很確定,用 must have + 過去分詞。","e23/next":"客戶的回信終於來了。好消息和壞消息一起來。","e24/title":"好消息,壞消息","e24/prev":"以為消失的動畫檔案,其實是 Daniel 不小心移走的。","e24/scene.ko":"星期四下午 1 點。客戶的 email 終於來了。Dana 大聲唸出來。","e24/scene.gloss.0.1":"終於","e24/scene.gloss.1.1":"出聲地","e24/lines.0.ko":"有好消息,也有壞消息。他們非常喜歡會跳舞的 logo。","e24/lines.1.ko":"耶!那壞消息是什麼?","e24/lines.2.ko":"他們還想要三個版本。而且週一前就要寄出。","e24/lines.3.ko":"週一?我為了找那個檔案,整個早上都白費了!","e24/lines.4.ko":"那是我的錯。我會補回來。第一個版本今晚由我來畫。","e24/lines.5.ko":"真的嗎?Daniel 也一定要休息喔。","e24/lines.6.ko":"我會的。謝謝你的關心。","e24/lines.7.ko":"好,我去買咖啡。Leo 的店兩大杯咖啡只收一杯的錢。","e24/lines.8.ko":"真的嗎?為什麼?","e24/lines.9.ko":"因為我每次去都得聽他講釣魚的故事。很公平的交易吧。","e24/quiz.0.why":"對方問壞消息是什麼,所以用客戶的額外要求來回答。","e24/quiz.1.ko":"謝謝你的關心。","e24/quiz.1.why":"感謝的原因用 Thanks for。","e24/quiz.2.ko":"週一前就要寄出。","e24/quiz.2.why":"因客戶的時程而必須做的事,用 have to。we 要搭配 have。","e24/next":"截止日逼近,週五的聚會會怎麼樣呢?","e25/title":"贊成?反對?","e25/prev":"客戶很喜歡跳舞的 logo,但要求週一前再做三個版本。Daniel 接下了第一個版本。","e25/scene.ko":"星期五早上 10 點。大家看起來都很累。Dana 站到白板前。","e25/scene.gloss.0.1":"疲倦的","e25/scene.gloss.1.1":"白板","e25/lines.0.ko":"我們快速投個票。要不要延後週五聚會,今晚來工作?贊成的人?","e25/lines.1.ko":"我反對!我們不需要今晚就全部做完。還有週末啊。","e25/lines.2.ko":"我也同意 Jake。Daniel 已經寄出第一個版本了。不用慌張。","e25/lines.3.ko":"好。贊成加班的人?沒有人嗎?了解了。","e25/lines.4.ko":"不過有一條規則。沒有我的允許,不准寄任何東西給客戶。","e25/lines.5.ko":"了解。那聚會照常舉行對吧?","e25/lines.6.ko":"對。還有,Mina,這次不可以睡著喔。","e25/lines.7.dir.ko":"笑著","e25/lines.7.ko":"我保證。我需要帶什麼嗎?","e25/lines.8.ko":"什麼都不用帶。啊,還有我朋友 Noah 也會來。他是廚師。","e25/lines.9.ko":"廚師?那這場聚會我無條件贊成。","e25/quiz.0.why":"對方問要帶什麼,所以用「什麼都不用帶」來回答。","e25/quiz.1.ko":"贊成的人?","e25/quiz.1.why":"贊成是 for。","e25/quiz.2.ko":"沒有我的允許,不准寄任何東西給客戶。","e25/quiz.2.why":"這是不可以做的禁止,所以用 must not。","e25/next":"週五晚上,Mina 煩惱要穿什麼去。Rosa 也有自己的小盤算。","e26/title":"星期五晚上","e26/prev":"團隊投票決定星期五的聚會照常舉行。Jake 的廚師朋友 Noah 也會來。","e26/scene.ko":"星期五晚上七點半。Mina 站在鏡子前。Rosa 正準備出門去醫院。","e26/scene.gloss.0.1":"鏡子","e26/scene.gloss.1.1":"前往～","e26/lines.0.ko":"Rosa，哪一件？藍色洋裝還是黑色的？","e26/lines.1.ko":"藍色的。而且我們得快點了，聚會八點開始。","e26/lines.2.ko":"等一下。Jake 說了很奇怪的話，他想把我和他朋友 Noah 湊成一對。","e26/lines.3.ko":"我知道啊，是我叫他這麼做的！去見見他吧，他人很好。","e26/lines.4.ko":"妳也有份嗎？Rosa！","e26/lines.5.dir.ko":"笑著","e26/lines.5.ko":"被抓包了。不過說真的，妳不能每個週末都待在家裡。","e26/lines.6.ko":"我該告訴他明年我要回首爾嗎？","e26/lines.7.ko":"第一天就別說啦！好好玩就好。好了，我得走了，要去搭地鐵。","e26/lines.8.dir.ko":"獨自喃喃自語","e26/lines.8.ko":"好吧，Mina，放輕鬆。只是吃個晚餐而已。","e26/quiz.0.why":"針對「該說嗎？」的提問，回答 \\"第一天就別說！\\"。","e26/quiz.1.ko":"Rosa 正要前往醫院。","e26/quiz.1.why":"朝著那個方向出發，用 leave for。","e26/quiz.2.ko":"我們得快點了。聚會八點開始。","e26/quiz.2.why":"不趕快就會遲到，所以用 'd better + 原形動詞。","e26/next":"前往約定地點的路上，Mina 又遇到了新狀況。","e27/title":"原來如此","e27/prev":"Rosa 和 Jake 想把 Mina 介紹給 Jake 的朋友 Noah。Mina 穿著藍色洋裝出門了。","e27/scene.ko":"星期五晚上八點四十分。Mina 終於走進酒吧，已經遲到四十分鐘了。一位繫著廚師圍裙的高個子男生正在和 Jake 聊天。","e27/scene.gloss.0.1":"圍裙","e27/scene.gloss.1.1":"遲到的","e27/lines.0.ko":"真的很抱歉！我搭錯地鐵了。早知道就該搭計程車的。","e27/lines.1.ko":"終於來了！Mina，這位是 Noah。Noah，這位是從首爾來的我的同事 Mina。","e27/lines.2.ko":"妳好，Mina。別擔心，我也是下班直接趕過來的，圍裙都還沒脫呢。","e27/lines.3.ko":"聽說 Jake 說你是廚師？你在哪裡工作？","e27/lines.4.ko":"離這裡十分鐘路程的一家小咖啡館，是我爸爸開的。","e27/lines.5.ko":"等一下……是那間有白鬍子爺爺的咖啡館嗎？Leo？","e27/lines.6.ko":"沒錯。我爸爸提過妳，說有個不睡覺的年輕女生。","e27/lines.7.ko":"天哪。所以原來 Leo 也早就知道我的事了。","e27/lines.8.ko":"我早該先告訴妳的。抱歉啦！","e27/lines.9.dir.ko":"微笑著","e27/lines.9.ko":"嗯，結果還是很順利啊。多虧這樣，我終於見到妳了。","e27/quiz.0.why":"針對「是 Leo 嗎？」的提問，回答 \\"沒錯\\"。","e27/quiz.1.ko":"這位是從首爾來的我的同事 Mina。","e27/quiz.1.why":"來自某處、出發點用 from。","e27/quiz.2.ko":"我搭錯地鐵了。早知道就該搭計程車的。","e27/quiz.2.why":"對過去的事感到後悔，用 should have + 過去分詞 taken。","e27/next":"Mina 和 Noah 面對面坐在安靜的桌邊。Noah 的童年故事要開始了。","e28/title":"Noah 的故事","e28/prev":"在星期五的聚會上，Mina 遇見了 Noah。原來 Noah 是咖啡館老闆 Leo 的兒子。","e28/scene.ko":"星期五晚上十點。其他人都在跳舞。Mina 和 Noah 坐在安靜的桌邊，分著吃一盤餃子。","e28/scene.gloss.0.1":"分享","e28/scene.gloss.1.1":"餃子","e28/lines.0.ko":"這個餃子真的很好吃。是你自己做的嗎？","e28/lines.1.ko":"對，是跟奶奶學的食譜。奶奶以前每個星期天都會做給我吃。","e28/lines.2.ko":"你是在哪裡長大的？","e28/lines.3.ko":"就在這裡的布魯克林。我在咖啡館樓上長大的。","e28/lines.4.ko":"那 Leo 以前每天晚上都會講故事給你聽嗎？","e28/lines.5.dir.ko":"笑著","e28/lines.5.ko":"每天晚上。而且每講一次，就會多誇大一點。","e28/lines.6.ko":"我以前不喜歡做菜，但吃了這個，我想學了。","e28/lines.7.ko":"我來教妳。醬汁是用醬油和蜂蜜，再加一樣祕密材料做的。","e28/lines.8.ko":"祕密？你以前會把所有祕密都告訴你爸爸嗎？","e28/lines.9.ko":"絕對不會。那是我爸爸教我的第一件事：絕對不要告訴 Leo 祕密！","e28/quiz.0.why":"針對「在哪裡長大」的提問，用地點回答。","e28/quiz.1.ko":"醬汁是用醬油和蜂蜜做的。","e28/quiz.1.why":"材料混合後形態改變，所以用 made from。","e28/quiz.2.ko":"奶奶以前每個星期天都會做給我吃。","e28/quiz.2.why":"以前常做、現在不做了，所以用 used to。","e28/next":"星期一，Dana 對 Mina 提出了出乎意料的請求。","e29/title":"請妳來簡報","e29/prev":"Noah 端出用奶奶食譜做的餃子，並說了和 Leo 一起長大的故事。","e29/scene.ko":"星期一早上。Dana 把 Mina 叫進自己的辦公室。螢幕上有三個新的 logo 版本。","e29/scene.gloss.0.1":"叫進～","e29/scene.gloss.1.1":"版本","e29/lines.0.ko":"Mina，星期三妳可以向客戶簡報這些嗎？","e29/lines.1.ko":"我嗎？簡報通常都是 Dana 做的啊。","e29/lines.2.ko":"logo 是妳設計的。妳完全沒有理由不能簡報。","e29/lines.3.ko":"好的。那麼可以先和我一起檢查一下投影片嗎？","e29/lines.4.ko":"當然。今天下午一起看吧。","e29/lines.5.dir.ko":"站在門口","e29/lines.5.ko":"抱歉打斷一下。Mina，星期五晚上怎麼樣？聽說妳跟 Noah 聊了一整夜！","e29/lines.6.ko":"Jake，別提這個。我在工作。","e29/lines.7.ko":"Noah？Leo 的兒子？星期三的客戶午餐要不要請他來做？","e29/lines.8.ko":"好主意！Mina，打給他吧。","e29/lines.9.ko":"你們兩個真是沒救了。好吧，不過請別讓 Leo 靠近客戶！","e29/quiz.0.why":"被請求簡報後，接著說出驚訝的話。","e29/quiz.1.ko":"請別讓 Leo 靠近客戶！","e29/quiz.1.why":"讓人遠離，用 keep away from。","e29/quiz.2.ko":"可以和我一起檢查投影片嗎？","e29/quiz.2.why":"mind 後面接 -ing。","e29/next":"終於到了星期三。Mina 在客戶面前的第一次簡報要開始了。","e30/title":"第一次簡報","e30/prev":"Dana 把客戶簡報交給了 Mina。客戶午餐決定請 Noah 準備。","e30/scene.ko":"星期三上午十一點。客戶中午會到。Noah 正在帶大家的午餐過來，Mina 則在把最終版投影片寄給 Dana。","e30/scene.gloss.0.1":"中午","e30/scene.gloss.1.1":"最終的","e30/lines.0.ko":"Dana，如果客戶拒絕這個 logo 怎麼辦？","e30/lines.1.ko":"如果被拒絕，就再做一次，很簡單。","e30/lines.2.dir.ko":"抱著箱子抵達","e30/lines.2.ko":"午餐來了！我幫團隊做了三明治，還特別幫 Mina 做了一個。","e30/lines.3.ko":"我的嗎？謝謝你，Noah。","e30/lines.4.ko":"特別的三明治？我也想吃！","e30/lines.5.ko":"如果你幫忙搬箱子，我就做一個給你。","e30/lines.6.ko":"大家專心。Mina，把遙控器給我。我先開始，之後再交給妳。","e30/lines.7.ko":"好的。如果我忘了什麼，請幫幫我。","e30/lines.8.dir.ko":"透過視訊通話","e30/lines.8.ko":"妳不會忘的。緊張的時候，就想想那個跳舞的 logo。","e30/lines.9.ko":"來了。準備好了嗎，Mina？","e30/quiz.0.why":"針對「被拒絕怎麼辦」的提問，回答 \\"再做一次就好\\"。","e30/quiz.1.ko":"我特別幫 Mina 做了一個三明治。","e30/quiz.1.why":"是為了 Mina 而做的，所以用 for。","e30/quiz.2.ko":"如果你幫忙，我就做一個給你。","e30/quiz.2.why":"if 條件句的結果用 will。","e30/next":"客戶會從三個 logo 中選哪一個呢？Noah 的特製三明治裡又夾了什麼？","e31/title":"客戶的選擇","e31/prev":"在 Mina 第一次向客戶簡報的這天，Noah 準備了午餐。客戶終於到了。","e31/scene.ko":"星期三中午。客戶 Hill 執行長看著三個 logo。其中一個在大螢幕上跳著舞。","e31/scene.gloss.0.1":"客戶","e31/scene.gloss.1.1":"螢幕","e31/lines.0.ko":"每一個都很出色。不過我只能選其中一個。","e31/lines.1.ko":"如果我是您，我會選第二個。它的動態最自然。","e31/lines.2.ko":"很有意思。不過我想指出一點：紅色有點太亮了。","e31/lines.3.ko":"您說得對。如果改用更深的紅色，看起來會更沉穩。","e31/lines.4.ko":"那動作再慢一點呢？","e31/lines.5.ko":"這很簡單。只要給我們一天，兩個都能修好。","e31/lines.6.ko":"一天？我合作過的大多數公司都要一週。","e31/lines.7.ko":"我們可不是那種公司。","e31/lines.8.dir.ko":"笑著","e31/lines.8.ko":"我喜歡這個團隊。Mina，如果每次簡報都這麼清楚，我的工作就輕鬆多了。","e31/lines.9.dir.ko":"站在門口","e31/lines.9.ko":"午餐隨時都準備好了！","e31/quiz.0.why":"聽到「只能選一個」後，Mina 給出了推薦。","e31/quiz.1.ko":"我只能選其中一個。","e31/quiz.1.why":"在多個之中的一個，用 one of。","e31/quiz.2.ko":"如果我是您，我會選第二個。","e31/quiz.2.why":"If I were you 是固定說法。","e31/next":"在客戶做出選擇的這天晚上，Mina 向 Rosa 吐露了祕密。","e32/title":"如果當初","e32/prev":"客戶 Hill 執行長選了第二個 logo，並要求一天內修好。Mina 的第一次簡報很成功。","e32/scene.ko":"星期三晚上。Mina 和 Rosa 坐在大樓屋頂上，望著城市的燈光。","e32/scene.gloss.0.1":"屋頂","e32/scene.gloss.1.1":"燈光","e32/lines.0.ko":"所以呢？重要的一天過得怎麼樣？","e32/lines.1.ko":"太棒了。客戶超喜歡。要不是 Daniel 提了那個點子，我們就丟掉這個專案了。","e32/lines.2.ko":"Noah 的午餐呢？","e32/lines.3.ko":"大家都很愛。他還特地幫我做了一個我們 logo 形狀的特製三明治！","e32/lines.4.dir.ko":"微笑著","e32/lines.4.ko":"Mina……妳是不是在迷上 Noah 了？","e32/lines.5.ko":"什麼？才沒有！好啦……有一點。","e32/lines.6.ko":"我就知道！如果妳沒去那個聚會，就不會遇到 Noah 了。","e32/lines.7.ko":"而且如果我沒來紐約，我就一個人都遇不到了。","e32/lines.8.ko":"不過要小心喔。Noah 是說到做到的人，可是妳明年就要走了。","e32/lines.9.ko":"我知道。我正努力不要陷得太快。","e32/quiz.0.why":"被說迷上 Noah 後，先否認再承認。","e32/quiz.1.ko":"她們在看著城市的燈光。","e32/quiz.1.why":"是屬於城市的燈光，所以用 of。","e32/quiz.2.ko":"如果妳沒去那個聚會，就不會遇到 Noah 了。","e32/quiz.2.why":"與過去相反的假設，其結果用 would have + 過去分詞。","e32/next":"星期六，Noah 的廚房裡開了一堂烹飪課。","e33/title":"烹飪課","e33/prev":"在屋頂上，Mina 向 Rosa 坦白自己開始喜歡 Noah。Rosa 擔心 Mina 明年就要離開。","e33/scene.ko":"星期六下午。咖啡館樓上 Noah 的廚房。有一袋麵粉、一碗雞蛋，還有超級緊張的 Mina。","e33/scene.gloss.0.1":"麵粉","e33/scene.gloss.1.1":"碗","e33/lines.0.ko":"今天我們要做餃子。先放一杯麵粉和一點水。","e33/lines.1.ko":"這樣嗎？糟了。變得像漿糊一樣！","e33/lines.2.dir.ko":"笑著","e33/lines.2.ko":"再加一小撮麵粉。對，就這樣。現在開始揉。","e33/lines.3.ko":"真希望我能像 Noah 一樣會做菜。","e33/lines.4.ko":"我才希望我能像妳一樣會設計。妳的 logo 出現在辦公室的每個螢幕上呢。","e33/lines.5.ko":"你看！我的麵團變成真正的餃子了！","e33/lines.6.ko":"真的……好美。像現代藝術一樣。","e33/lines.7.dir.ko":"笑著","e33/lines.7.ko":"真希望我媽媽能看到這個。她一直說我絕對不會做菜。","e33/lines.8.ko":"那我們拍照寄給她吧。還有 Mina……我希望妳明年不要走。","e33/lines.9.dir.ko":"輕聲地","e33/lines.9.ko":"我也是。真希望我們有更多時間。","e33/quiz.0.why":"被稱讚廚藝後，用稱讚設計來回應。","e33/quiz.1.ko":"先放一杯麵粉和一點水。","e33/quiz.1.why":"是杯子裡裝的內容物，所以用 of。","e33/quiz.2.ko":"真希望我們有更多時間。","e33/quiz.2.why":"是與現實不同的願望，所以用 wish + 過去式 had。","e33/next":"Noah 的話一直留在 Mina 心上。Rosa 察覺到了這樣的 Mina。","e34/title":"Rosa 的建議","e34/prev":"在跟 Noah 學做菜的那天，Noah 說希望 Mina 明年不要離開。","e34/scene.ko":"星期天晚上。Rosa 正準備去上夜班。Mina 坐在沙發上，一句話也不說。","e34/scene.gloss.0.1":"夜班","e34/scene.gloss.1.1":"沙發","e34/lines.0.ko":"妳一整天都好安靜。怎麼了？","e34/lines.1.ko":"我怕自己會受傷。Noah 說希望我不要走。","e34/lines.2.ko":"啊，Mina。只要不隱藏自己的心意，妳就不會受傷。","e34/lines.3.ko":"那如果不順利怎麼辦？","e34/lines.4.ko":"只要彼此誠實，就沒事的。","e34/lines.5.ko":"妳什麼時候變這麼有智慧了？","e34/lines.6.ko":"我是上夜班的啊。凌晨三點的醫院會讓人變聰明。想聊的話就傳訊息給我。","e34/lines.7.dir.ko":"笑著","e34/lines.7.ko":"我以妳為榮，Rosa。而且我永遠都相信妳。","e34/lines.8.ko":"一直都是。還有 Noah 呢？他是好人。妳也可以相信他。","e34/lines.9.ko":"希望如此。我真的受夠害怕了。","e34/quiz.0.why":"針對「不順利怎麼辦」的擔憂，用條件句來安慰。","e34/quiz.1.ko":"我怕自己會受傷。","e34/quiz.1.why":"害怕的對象用 afraid of。","e34/quiz.2.ko":"想聊的話就傳訊息給我。","e34/quiz.2.why":"為了以防萬一需要，所以用 in case。","e34/next":"星期一早上，辦公室送來一個超大的蛋糕。","e35/title":"Daniel 回來了","e35/prev":"Mina 害怕自己對 Noah 動了心，但 Rosa 說只要彼此誠實就沒事。","e35/scene.ko":"星期一早上。Leo 咖啡館做的超大蛋糕被送到辦公室。Daniel 和整個團隊站在一起。","e35/scene.gloss.0.1":"送達","e35/scene.gloss.1.1":"全體的","e35/lines.0.ko":"各位，有好消息！Daniel 要回來正常上班了！","e35/lines.1.ko":"真的嗎？那你爸爸呢？","e35/lines.2.ko":"他上星期出院了，現在很好。","e35/lines.3.ko":"真是好消息！你回來我好開心。","e35/lines.4.ko":"謝謝。能再和這個團隊一起工作，我也很高興。","e35/lines.5.ko":"還有一件事。今天早上最終版 logo 通過了！","e35/lines.6.ko":"太棒了！而且這個蛋糕是 Leo 那邊做的吧？聞起來好香。","e35/lines.7.ko":"Daniel，等一下和我喝杯咖啡吧。我有東西想給你看。","e35/lines.8.ko":"當然。對了，我聽說星期六做出了很有藝術感的餃子。","e35/lines.9.dir.ko":"臉紅了","e35/lines.9.ko":"Leo 話也太多了吧！","e35/quiz.0.why":"針對「爸爸怎麼樣」的提問，用出院的消息回答。","e35/quiz.1.ko":"能再和這個團隊一起工作，我很高興。","e35/quiz.1.why":"是一起工作，所以用 with。","e35/quiz.2.ko":"今天早上最終版 logo 通過了。","e35/quiz.2.why":"logo 是被通過的，所以用 was + 過去分詞。","e35/next":"不過辦公室裡開始流傳奇怪的傳聞。","e36/title":"傳聞","e36/prev":"Daniel 回來正常上班了，最終版 logo 也通過了。","e36/scene.ko":"星期三下午。會議室正在粉刷油漆。Jake 把 Mina 拉進茶水間。","e36/scene.gloss.0.1":"粉刷油漆","e36/scene.gloss.1.1":"茶水間 · 廚房","e36/lines.0.ko":"Mina，妳聽說了嗎？我們公司要被賣掉了。","e36/lines.1.ko":"什麼？誰要買？","e36/lines.2.ko":"不知道。但聽說文件已經簽好了。有一家大公司下個月要收購。","e36/lines.3.ko":"你怎麼知道的？","e36/lines.4.ko":"我看到 Dana 的備忘錄了。而且所有新專案都停了。","e36/lines.5.ko":"Jake，你怎麼可以看別人的備忘錄！","e36/lines.6.ko":"我沒有看！它就放在咖啡機上啊！","e36/lines.7.ko":"好，冷靜點。我們的團隊會有變動嗎？","e36/lines.8.ko":"沒有人知道。說不定他們全部收購，然後把我們全部開除。","e36/lines.9.dir.ko":"走進來","e36/lines.9.ko":"你們兩個都冷靜點。還沒有任何決定。還有，別用咖啡杯去碰牆。油漆還沒乾。","e36/quiz.0.why":"針對「誰要買」的提問，用 \\"不知道，不過……\\" 回答。","e36/quiz.1.ko":"別用咖啡杯去碰牆。","e36/quiz.1.why":"是手上拿著的東西，所以用 with。","e36/quiz.2.ko":"還沒有任何決定。","e36/quiz.2.why":"是完成式被動語態 has been + 過去分詞。nothing 是單數。","e36/next":"一位灰髮的陌生男子從 Dana 的辦公室走了出來。","e37/title":"誰要收購","e37/prev":"Jake 聽到了公司要被賣掉的傳聞。聽說有一家大公司下個月要收購。","e37/scene.ko":"星期四早上。一位灰髮、穿深色西裝的男子從 Dana 的辦公室走出來。","e37/scene.gloss.0.1":"西裝","e37/scene.gloss.1.1":"從～走出來","e37/lines.0.ko":"剛剛那是誰？那個戴著昂貴手錶的男人。","e37/lines.1.ko":"不知道。不過我昨晚收到這封電子郵件，是從首爾寄來的。","e37/lines.2.ko":"首爾的公司嗎？上面寫了什麼？","e37/lines.3.ko":"\\"我們會在星期五告訴各位一切。請保密。\\"","e37/lines.4.ko":"好奇怪。去查查那個男人的公司。他的包包上有名字。","e37/lines.5.ko":"我正在查。是一家法律事務所……這裡還有一頁新聞。天哪。","e37/lines.6.ko":"怎麼了？快告訴我！","e37/lines.7.ko":"\\"首爾的設計公司將收購紐約工作室。\\"就是我們公司。","e37/lines.8.ko":"等一下。所以 Mina 是被派來這裡監視我們的嗎？不然根本說不通啊！","e37/lines.9.ko":"不是的！我什麼都沒聽說，Jake。真的。","e37/quiz.0.why":"針對「電子郵件上寫了什麼」的提問，唸出內容。","e37/quiz.1.ko":"那個戴著昂貴手錶的男人是誰？","e37/quiz.1.why":"是身上帶著的特徵，所以用 with。","e37/quiz.2.ko":"我們會在星期五告訴各位一切。","e37/quiz.2.why":"will 後面的被動語態是 be + 過去分詞。","e37/next":"Mina 知道了一切。但 Jake 的眼神變了。","e38/title":"撐過去","e38/prev":"收購工作室的原來是 Mina 在首爾的公司。Jake 懷疑 Mina 是被故意派來的。","e38/scene.ko":"星期四晚上。Leo 的咖啡館。Mina 眼眶含淚，獨自坐著。Noah 端來一杯茶。","e38/scene.gloss.0.1":"獨自","e38/scene.gloss.1.1":"眼淚","e38/lines.0.ko":"嘿。發生什麼事了？","e38/lines.1.ko":"首爾的公司要收購我們的工作室。而且 Jake 以為我早就知道。","e38/lines.2.ko":"妳早就知道嗎？","e38/lines.3.ko":"沒有！我只是被派來這裡學新技術而已，就這樣。","e38/lines.4.dir.ko":"在收銀台","e38/lines.4.ko":"聽說新老闆很嚴格。有位客人這麼說的。","e38/lines.5.ko":"爸！現在不要說這個。","e38/lines.6.dir.ko":"微微一笑","e38/lines.6.ko":"沒關係。我明天要去見他。我不知道自己撐不撐得過去。","e38/lines.7.ko":"妳會撐過去的。Dana 和 Daniel 都相信妳。Jake 也會理解的。","e38/lines.8.ko":"你怎麼知道？","e38/lines.9.ko":"因為我剛收到他的訊息。他超級抱歉的。他現在肯定正羞得滿臉通紅。","e38/quiz.0.why":"針對「不知道撐不撐得過去」，用 \\"妳會撐過去的\\" 來鼓勵。","e38/quiz.1.ko":"Mina 眼眶含淚，獨自坐著。","e38/quiz.1.why":"「帶著～的狀態」用 with + 名詞。","e38/quiz.2.ko":"我明天要去見他。","e38/quiz.2.why":"已安排好的事用 be supposed to。","e38/next":"要見新老闆的那天早上，Mina 去了美髮沙龍。","e39/title":"美髮沙龍","e39/prev":"Mina 在 Leo 的咖啡館得到了 Noah 的安慰。Jake 也傳訊息道歉了。","e39/scene.ko":"星期五上午八點。辦公室附近的小美髮沙龍。Mina 坐在窗邊。Rosa 坐在她旁邊。","e39/scene.gloss.0.1":"美髮沙龍","e39/scene.gloss.1.1":"在～旁邊","e39/lines.0.ko":"妳好美喔。為什麼偏偏今天剪頭髮？","e39/lines.1.ko":"因為新老闆要來了啊。我想在開會前剪好。","e39/lines.2.ko":"也對。那套西裝呢？","e39/lines.3.ko":"昨天送去洗衣店了。我到辦公室再換上。","e39/lines.4.ko":"好。別忘了擦口紅。妳每次都忘。","e39/lines.5.dir.ko":"看著窗外","e39/lines.5.ko":"等一下。那是 Jake 嗎？站在門邊的那個？","e39/lines.6.dir.ko":"走進來","e39/lines.6.ko":"Mina。昨天的事真的很抱歉。是我不對。","e39/lines.7.ko":"沒關係。換作是我，也會這麼想的。","e39/lines.8.ko":"我買了咖啡來。而且妳看，我也剪頭髮了！團隊精神吧。","e39/lines.9.dir.ko":"笑著","e39/lines.9.ko":"你們兩個真是的。快走吧，新老闆在等了。","e39/quiz.0.why":"站在門邊的 Jake 走進來道歉。","e39/quiz.1.ko":"Mina 坐在窗邊。","e39/quiz.1.why":"就在窗戶旁邊，所以用 by。","e39/quiz.2.ko":"我昨天把西裝送去洗了。","e39/quiz.2.why":"請人代辦的事用 had + 物品 + 過去分詞。","e39/next":"新老闆終於走進會議室了。","e40/title":"新老闆","e40/prev":"Mina 在見新老闆之前剪了頭髮。Jake 也道了歉，還剪了頭髮來。","e40/scene.ko":"星期五上午十點。整個團隊聚在會議室。Mina 首爾公司的 Han 執行長昨晚搭飛機抵達。","e40/scene.gloss.0.1":"上司 · 執行長","e40/scene.gloss.1.1":"搭飛機","e40/lines.0.ko":"大家好。還有，嗨，Mina。妳看起來很驚訝。","e40/lines.1.ko":"Han 執行長！我完全不知道您會來。","e40/lines.2.ko":"抱歉。這筆交易一直是保密的。我會全部說明。","e40/lines.3.dir.ko":"會議結束後","e40/lines.3.ko":"所以……他說了什麼？我太緊張，一個字都沒聽進去。","e40/lines.4.ko":"他說沒有人會丟掉工作。","e40/lines.5.ko":"他還說已經關注我們的工作室好幾年了。","e40/lines.6.ko":"他還說希望我成為連接首爾和紐約的橋樑。","e40/lines.7.ko":"橋樑？那 Mina 要待更久嗎？我們相處得不是挺好的嗎。","e40/lines.8.ko":"也許吧。他說會用電子郵件寄詳細內容給我。","e40/lines.9.ko":"嗯，他說希望我們都能相處愉快。而且我覺得我們會的。","e40/quiz.0.why":"針對「他說了什麼」的提問，轉述 Han 執行長的話。","e40/quiz.1.ko":"他說會用電子郵件寄詳細內容給我。","e40/quiz.1.why":"溝通方式用 by。","e40/quiz.2.ko":"他說沒有人會丟掉工作。","e40/quiz.2.why":"轉述時 will 要往前一個時態，變成 would。","e40/next":"連接首爾與紐約的橋樑，Mina 會在紐約待更久嗎？","e41/title":"再一年？","e41/prev":"首爾的公司收購了紐約工作室。Han 執行長請 Mina 成為連接首爾和紐約的橋樑。","e41/scene.ko":"星期六早上。Mina 在餐桌前讀電子郵件。是 Han 執行長親自寫的郵件。","e41/scene.gloss.0.1":"餐桌","e41/scene.gloss.1.1":"親自 · 本人","e41/lines.0.ko":"妳那封郵件應該讀了十遍了吧。上面寫什麼？","e41/lines.1.ko":"說我可以在紐約再待一年。","e41/lines.2.ko":"再一年？太酷了！等等，那妳為什麼一臉擔心？","e41/lines.3.ko":"我媽說她想我。而且首爾是我的家啊。","e41/lines.3.note":"媽媽現在還是想念，所以保留了 misses。","e41/lines.4.ko":"Noah 怎麼說？","e41/lines.5.ko":"我還沒跟他說。我得先好好想一想。","e41/lines.6.ko":"也對。還有誰知道？","e41/lines.7.ko":"只有 Dana。聽說這個提議是 Han 執行長親自提的，不是人資部門。","e41/lines.8.ko":"哇。那他是真的很信任妳。慢慢好好想吧。","e41/lines.9.ko":"我會的。不過拜託別告訴 Jake。他守不住祕密。","e41/quiz.0.why":"針對「郵件上寫什麼」的提問，轉達內容。","e41/quiz.1.ko":"這個提議是 Han 執行長親自提的。","e41/quiz.1.why":"被動語態中的行為者用 by。","e41/quiz.2.ko":"別告訴 Jake。","e41/quiz.2.why":"後面直接接人（Jake），所以用 tell。","e41/next":"Mina 決定把想問的事一件一件問 Dana。","e42/title":"到什麼時候？","e42/prev":"Han 執行長說 Mina 可以在紐約再待一年。Mina 決定好好想一想。","e42/scene.ko":"星期一早上。Mina 敲了敲 Dana 辦公室的門。她有很多事想問。","e42/scene.gloss.0.1":"敲～","e42/scene.gloss.1.1":"辦公室 · 房間","e42/lines.0.ko":"Dana，有空嗎？妳知道我得在什麼時候之前決定嗎？","e42/lines.1.ko":"Han 執行長希望本月底前得到答覆。","e42/lines.2.ko":"月底？可以告訴我我會做什麼工作嗎？","e42/lines.3.ko":"妳會帶領首爾與紐約之間的專案。我不確定妳是否知道這是多大的機會。","e42/lines.4.ko":"我知道。可是我不知道家人會怎麼想。","e42/lines.5.ko":"妳跟 Noah 談過了嗎？","e42/lines.6.ko":"還沒。我不敢提這件事。","e42/lines.7.ko":"早點說吧。Noah 也有資格知道妳在想什麼。","e42/lines.8.ko":"沒錯。我星期五前會跟 Noah 說。","e42/lines.9.ko":"很好。還有，Mina？不管妳決定什麼，我都會支持妳。","e42/quiz.0.why":"針對「要在什麼時候之前決定」的提問，用期限回答。","e42/quiz.1.ko":"我星期五前會跟 Noah 說。","e42/quiz.1.why":"最晚到那時為止的截止時間，用 by。","e42/quiz.2.ko":"可以告訴我我會做什麼工作嗎？","e42/quiz.2.why":"句子裡面的問句，順序是主詞 + 動詞。","e42/next":"Leo 的咖啡館貼出了新價目表。Jake 氣壞了。","e43/title":"漲價","e43/prev":"Mina 得在月底前答覆。Dana 要她趕快去跟 Noah 談。","e43/scene.ko":"星期三上午八點。Leo 的咖啡館貼出了新告示：\\"咖啡漲價一美元\\"。Jake 心情很差。","e43/scene.gloss.0.1":"告示 · 標示牌","e43/scene.gloss.1.1":"價格","e43/lines.0.ko":"Leo！你把價格漲了一整塊錢嗎？","e43/lines.1.ko":"現在什麼都貴了，老弟。牛奶漲了兩成呢。","e43/lines.2.ko":"那我要求打折。我每天都來耶！","e43/lines.3.dir.ko":"笑著","e43/lines.3.ko":"Rosa 說不要再給你打折了。","e43/lines.4.ko":"叛徒！","e43/lines.5.dir.ko":"走進來","e43/lines.5.ko":"早安！Leo，Noah 在嗎？","e43/lines.6.ko":"他去市場了。不過他要我轉告妳：\\"下班後來廚房一趟。\\"","e43/lines.7.ko":"下班後？好的。可以請你告訴他等我一下嗎？我可能會晚一點。","e43/lines.8.ko":"當然。還有，Mina？妳的咖啡還是舊價格。別告訴 Jake。","e43/lines.9.ko":"我都聽到了！","e43/quiz.0.why":"針對「要求打折」，Leo 轉述 Rosa 說的話。","e43/quiz.1.ko":"Leo 把價格漲了一美元。","e43/quiz.1.why":"漲了多少的差額用 by。","e43/quiz.2.ko":"Rosa 說不要再給你打折了。","e43/quiz.2.why":"是 told + 人 + not to + 原形動詞。","e43/next":"下班後在 Noah 的廚房，Mina 終於開口了。","e44/title":"誰說的？","e44/prev":"Noah 透過 Leo 轉告，請 Mina 下班後到廚房一趟。","e44/scene.ko":"星期三晚上八點。Noah 的廚房。餐桌上擺著兩碗麵。Mina 想談那個提議。","e44/scene.gloss.0.1":"麵","e44/scene.gloss.1.1":"提議","e44/lines.0.ko":"所以，怎麼了？我爸說妳看起來很緊張。","e44/lines.1.ko":"我有重要的事要說。公司提議讓我在這裡再工作一年。","e44/lines.2.ko":"再一年？是誰提議的？","e44/lines.3.ko":"Han 執行長。他希望我在首爾和紐約之間工作。","e44/lines.4.ko":"太棒了！妳怎麼回答的？","e44/lines.5.ko":"我還沒說什麼。我擔心家人。還有……我們。","e44/lines.6.ko":"我們？Mina，誰說要擔心我們了？","e44/lines.7.ko":"沒有人。只是……我喜歡 Noah。很喜歡。","e44/lines.8.dir.ko":"微笑著","e44/lines.8.ko":"我也喜歡妳。所以我的想法是這樣：如果妳想做這份工作，就去試試吧。","e44/lines.9.ko":"真的嗎？如果你是我，你會怎麼做？","e44/quiz.0.why":"針對「誰提議的」的提問，用人來回答。","e44/quiz.1.ko":"我有重要的事要說。","e44/quiz.1.why":"談話的主題用 about。","e44/quiz.2.ko":"誰說要擔心我們了？","e44/quiz.2.why":"who 是主詞，所以不用 did，直接用 told。","e44/next":"Mina 向在紐約住了很久的 Daniel 尋求建議。","e45/title":"這座城市裡的某種東西","e45/prev":"Mina 向 Noah 坦白了再留一年的提議和自己的心意。Noah 說想做就去試試。","e45/scene.ko":"星期四下午一點。Mina 和 Daniel 坐在辦公室附近小公園的長椅上吃午餐。","e45/scene.gloss.0.1":"長椅","e45/scene.gloss.1.1":"在～附近","e45/lines.0.ko":"我們好一陣子沒聊了。來聊聊近況吧。妳過得怎麼樣？","e45/lines.1.ko":"老實說嗎？我很混亂。你有想過離開紐約嗎？","e45/lines.2.ko":"好多次了。不過這座城市有種東西，讓我總是會回來。","e45/lines.3.ko":"不會太吵、太貴嗎？","e45/lines.4.ko":"當然。不過我喜歡這座城市的，是這裡的人。每天都能遇見新的人。","e45/lines.5.ko":"沒錯。我也是在這裡遇到你們所有人的。","e45/lines.6.ko":"如果留在這裡，妳不會想念首爾嗎？","e45/lines.7.ko":"會，我會很想念。非常想念。不過我也會想念紐約。","e45/lines.7.note":"對 Aren't you going to miss…? 回答「會想念」時，實際上是 Yes, I am.。","e45/lines.8.ko":"要不要再試一年看看？","e45/lines.9.ko":"也許吧。謝謝你，Daniel。我們以後多聊聊吧。","e45/quiz.0.why":"是「會想念」這個事實，所以用 Yes, I am。","e45/quiz.1.ko":"這座城市有某種東西。","e45/quiz.1.why":"籠罩在某物身上的感覺用 about。","e45/quiz.2.ko":"你有想過離開紐約嗎？","e45/quiz.2.why":"過去事情的否定疑問句用 Didn't。","e45/next":"星期五晚上，Jake 和 Rosa 準備了一個驚喜消息。","e46/title":"驚喜消息","e46/prev":"午餐時，Daniel 說這座城市有某種東西，並勸 Mina 再試一年。","e46/scene.ko":"星期五晚上九點左右。Jake、Rosa 和 Mina 在 Leo 的店吃晚餐。Jake 興奮得好像快要爆炸了。","e46/scene.gloss.0.1":"爆炸","e46/scene.gloss.1.1":"興奮","e46/lines.0.ko":"好，我再也忍不住了。我和 Rosa 有消息要宣布！","e46/lines.1.ko":"你們要養小狗嗎？","e46/lines.2.ko":"差不多。我們決定住在一起了！","e46/lines.3.ko":"不會吧！真的嗎？太棒了！","e46/lines.3.note":"這裡的 Shut up! 是「不會吧！」的開心驚訝。如果是生氣的語氣，就變成「閉嘴」，要小心。","e46/lines.4.ko":"別擔心。我們今晚不會走。下個月才搬，才隔兩個街區而已。","e46/lines.5.ko":"真的恭喜你們。不過我還是會想你們的。","e46/lines.6.ko":"我也是。","e46/lines.7.ko":"可是我不想讓 Mina 一個人住。","e46/lines.8.ko":"我也不想。Mina，妳明年還會在紐約嗎？","e46/lines.9.ko":"我想會的。其實我正準備要告訴大家。","e46/quiz.0.why":"對 I'm going to miss you 回答「我也是」，要用 be 動詞接話，所以是 So am I。","e46/quiz.1.ko":"我正準備要告訴大家。","e46/quiz.1.why":"剛要做某事，用 be about to。","e46/quiz.2.ko":"我不想讓 Mina 一個人住。——我也不想。","e46/quiz.2.why":"前面是 don't，所以用 Neither do I。","e46/next":"發表派對前一天，辦公室一片忙亂。","e47/title":"發表準備","e47/prev":"Jake 和 Rosa 決定下個月開始住在一起。Mina 坦白說自己可能會留在紐約。","e47/scene.ko":"星期一早上。logo 發表派對就在明天。Mina 正用膠帶貼海報。這是市區一家店印的海報。","e47/scene.gloss.0.1":"發表派對","e47/scene.gloss.1.1":"貼 · 掛","e47/lines.0.ko":"派對明天六點，對吧？","e47/lines.1.ko":"對。而且 Hill 執行長也會來，對吧？","e47/lines.2.ko":"她會來。今天早上她用電子郵件回覆了。","e47/lines.3.ko":"有個小問題。大螢幕上的影片播不出來。","e47/lines.4.ko":"Jake 可以解決的，對吧？","e47/lines.5.ko":"當然。我用我的筆電來修。給我十分鐘。","e47/lines.6.ko":"你沒忘記蛋糕吧，對吧？","e47/lines.7.ko":"沒忘。Noah 現在正在做。","e47/lines.8.dir.ko":"十分鐘後","e47/lines.8.ko":"好了！全部解決了。","e47/lines.9.ko":"太好了。我們一起把它變成完美的夜晚，好嗎？","e47/quiz.0.why":"針對「能解決吧」的確認，用 \\"當然\\" 加上方法來回答。","e47/quiz.1.ko":"她用電子郵件回覆了。","e47/quiz.1.why":"溝通方式用 by。","e47/quiz.2.ko":"派對明天六點，對吧？","e47/quiz.2.why":"前面是 is（肯定句），所以用 isn't it。","e47/next":"發表派對終於到了。Hill 執行長抵達，Noah 捧著蛋糕進場。","e48/title":"發表派對","e48/prev":"為發表派對忙碌的一天。Jake 解決了影片問題，Noah 正在做蛋糕。","e48/scene.ko":"星期二晚上六點。舞台上掛著巨大的布條。新 logo 在螢幕上跳著舞。房間裡擠滿了人。","e48/scene.gloss.0.1":"布條","e48/scene.gloss.1.1":"舞台","e48/lines.0.ko":"Mina，我真的很喜歡這個 logo。在大螢幕上看更棒。","e48/lines.1.ko":"謝謝您！我們真的很用心做的。","e48/lines.2.dir.ko":"站在喇叭前","e48/lines.2.ko":"把音樂開大聲點吧！","e48/lines.3.ko":"別太大聲啦，Jake。Hill 執行長在這裡耶。","e48/lines.4.dir.ko":"笑著","e48/lines.4.ko":"哎呀，我超愛吵鬧的音樂。開大聲吧！","e48/lines.5.dir.ko":"捧著大蛋糕","e48/lines.5.ko":"借過一下！大家小心！","e48/lines.6.ko":"Noah，小心！別被電線絆倒了！","e48/lines.7.ko":"別擔心，我不會跌……啊！","e48/lines.8.ko":"跌倒了！不過蛋糕沒事！","e48/lines.9.dir.ko":"站起來笑著","e48/lines.9.ko":"我沒事！有人要吃蛋糕嗎？","e48/quiz.0.why":"針對「別跌倒」的提醒，用 won't 簡短回應。","e48/quiz.1.ko":"舞台上掛著巨大的布條。","e48/quiz.1.why":"像覆蓋在舞台上方一樣掛著，所以用 over。","e48/quiz.2.ko":"我真的很喜歡這個 logo！","e48/quiz.2.why":"強調 I 的時候用 do + 原形動詞。","e48/next":"派對接近尾聲時，出現了令人驚訝的數字。","e49/title":"派對結束後","e49/prev":"在發表派對上，Hill 執行長非常喜歡這個 logo。Noah 捧著蛋糕跌倒了，但蛋糕沒事。","e49/scene.ko":"星期二晚上十一點。派對快結束了。來了超過 150 個人。Jake 躺在沙發上。","e49/scene.gloss.0.1":"躺在～上","e49/scene.gloss.1.1":"沙發","e49/lines.0.ko":"我累死了。快暈倒了。","e49/lines.1.ko":"你跳了超過三個小時的舞耶！","e49/lines.2.ko":"我剛剛是跟誰跳舞的？我想不起來了。","e49/lines.3.dir.ko":"笑著","e49/lines.3.ko":"跟我啊。還有 Hill 執行長。還有 Leo。","e49/lines.4.ko":"Leo？誰邀請他的？他來做什麼？","e49/lines.5.dir.ko":"站在門口","e49/lines.5.ko":"當然是來吃免費蛋糕的！","e49/lines.6.dir.ko":"笑著","e49/lines.6.ko":"Noah，你在看什麼？","e49/lines.7.ko":"網路留言。發表影片的觀看次數已經超過一萬了。","e49/lines.8.ko":"一萬？這下該暈倒的人是我了。","e49/lines.9.ko":"在有人暈倒之前，這最後一塊蛋糕是誰的？","e49/quiz.0.why":"針對「在看什麼」的提問，用正在看的東西回答。","e49/quiz.1.ko":"影片的觀看次數已經超過一萬了。","e49/quiz.1.why":"超過的數量用 over。","e49/quiz.2.ko":"這最後一塊蛋糕是誰的？","e49/quiz.2.why":"因為是 a cake for someone，所以 for 留在句尾。","e49/next":"派對隔天早上，Mina 拿著一封信去找 Dana。","e50/title":"決定","e50/prev":"發表派對大成功。發表影片的觀看次數在一天內就超過了一萬。","e50/scene.ko":"星期三上午九點。派對結束了。Mina 手裡拿著一封信，敲了敲 Dana 辦公室的門。","e50/scene.gloss.0.1":"信","e50/scene.gloss.1.1":"拿在手上","e50/lines.0.ko":"進來吧，Mina。那就是答覆嗎？","e50/lines.1.ko":"對。我都想清楚了。我想在紐約再待一年。","e50/lines.2.ko":"真的嗎？是什麼改變了妳的心意？","e50/lines.3.ko":"我喜歡和這個團隊一起工作。而且我現在無法想像離開。","e50/lines.4.ko":"我真的很高興。老實說，我一直希望妳會答應。","e50/lines.5.ko":"謝謝。我媽一開始有點失落，但她說今年夏天會來看我。","e50/lines.6.ko":"太好了。那妳準備好暫時在這裡安頓下來了嗎？","e50/lines.7.ko":"我想是的。我甚至在考慮養一隻貓。","e50/lines.8.dir.ko":"笑著","e50/lines.8.ko":"那就正式了。舊計畫結束了。我們用新計畫重新開始吧。","e50/lines.9.dir.ko":"走出辦公室，自言自語","e50/lines.9.ko":"再一年。是安頓下來的時候了……也是告訴 Noah 的時候了。","e50/quiz.0.why":"針對「是什麼改變了心意」的提問，用理由回答。","e50/quiz.1.ko":"派對結束了。","e50/quiz.1.why":"一路過到盡頭，所以用 over。","e50/quiz.2.ko":"我現在無法想像離開。","e50/quiz.2.why":"imagine 後面接 -ing。","e50/next":"Mina 決定在紐約再待一年。接下來該告訴 Noah 了。100 天已經過了一半！","e51/title":"一起吃晚餐","e51/prev":"Mina 決定在紐約再待一年。接下來該告訴 Noah 了。","e51/scene.ko":"星期三晚上。Noah 請 Mina 來吃晚餐。兩人邊吃義大利麵邊聊天。","e51/scene.gloss.0.1":"盤子","e51/scene.gloss.1.1":"義大利麵","e51/lines.0.ko":"謝謝妳來。所以，妳說有話要對我說，對吧？","e51/lines.1.ko":"對。我決定在紐約再待一年。","e51/lines.2.ko":"真的嗎？這……是最棒的消息！","e51/lines.3.ko":"我想親口告訴你。","e51/lines.4.ko":"我真的好開心。我一直希望能聽到這句話。","e51/lines.5.ko":"不過我得找新家。Rosa 下星期就要搬出去了。","e51/lines.6.ko":"我來幫妳。我絕對不會選吵鬧酒吧樓上的房子，我保證。","e51/lines.7.dir.ko":"笑著","e51/lines.7.ko":"好。啊，對了，我媽打算今年夏天來。","e51/lines.8.ko":"那我想煮飯給伯母吃。她會想嚐嚐我做的餃子嗎？","e51/lines.9.ko":"她一定會超愛的。這件事我們邊吃甜點邊聊吧。","e51/quiz.0.why":"針對「有什麼話要說」的提問，說出決定。","e51/quiz.1.ko":"這件事我們邊吃甜點邊聊吧。","e51/quiz.1.why":"一邊吃東西一邊聊天用 over。","e51/quiz.2.ko":"我決定留在紐約。","e51/quiz.2.why":"decide 後面接 to + 原形動詞。","e51/next":"星期四，首爾的 Han 執行長透過視訊會議發表新專案。","e52/title":"首爾專案","e52/prev":"Mina 告訴 Noah 她決定再留一年。Noah 決定幫 Mina 找房子。","e52/scene.ko":"星期四早上。Han 執行長從首爾透過視訊通話連線進來。整個團隊都在聽。","e52/scene.gloss.0.1":"視訊通話","e52/scene.gloss.1.1":"聽","e52/lines.0.ko":"大家好。今天我們要啟動首爾與紐約的第一個專案。","e52/lines.1.ko":"我希望這個專案由 Mina 來帶領。","e52/lines.2.ko":"我嗎？這是我的榮幸。不過預算是由 Dana 管理的，對吧？","e52/lines.3.ko":"沒錯。不過我期待創意上的決定由 Mina 來做。","e52/lines.4.ko":"另外，我希望 Daniel 給予建議。","e52/lines.5.ko":"我很樂意。不過設計的最終決定由 Mina 做。","e52/lines.6.ko":"那我呢？App 由我來做嗎？","e52/lines.7.ko":"當然，Jake。我還聽說你操作咖啡機的功夫也很厲害。","e52/lines.8.ko":"是誰說的啊？","e52/lines.9.ko":"我們就從星期一的團隊午餐開始吧。我會請 Dana 訂位。","e52/quiz.0.why":"被委以專案時，又驚訝又開心。","e52/quiz.1.ko":"Dana 掌管預算。","e52/quiz.1.why":"在上面掌握控制權，用 control over。","e52/quiz.2.ko":"我期待創意上的決定由 Mina 來做。","e52/quiz.2.why":"是 expect + 人 + to。","e52/next":"Rosa 搬家的日子快到了。打包行李時，回憶湧了出來。","e53/title":"整理行李","e53/prev":"首爾與紐約的第一個專案啟動了，Han 執行長把專案交給了 Mina。","e53/scene.ko":"星期六下午。到處都是箱子。Rosa 正在打包行李。Mina 正往床底下看。","e53/scene.gloss.0.1":"箱子","e53/scene.gloss.1.1":"打包行李","e53/lines.0.ko":"這些舊雜誌要丟掉嗎？","e53/lines.1.ko":"對，丟掉。咦，我在床底下找到這個了！妳以前的醫院員工證。","e53/lines.2.ko":"哈！我記得它之前弄丟過。我到處都找遍了。","e53/lines.3.ko":"還有這張照片。記得是什麼時候拍的嗎？我們當室友的第一個星期。","e53/lines.4.dir.ko":"眼眶含淚","e53/lines.4.ko":"別說了。我要哭了。","e53/lines.5.ko":"不要哭！對了，別忘了帶走盆栽。就在窗戶下面。","e53/lines.6.ko":"知道了。唉，這個箱子蓋不起來。","e53/lines.7.ko":"妳坐上去試試。","e53/lines.8.dir.ko":"坐到箱子上","e53/lines.8.ko":"好了！欸，我們要不要先吃點東西再繼續？我餓死了。","e53/lines.9.ko":"好啊。不過在那之前，先把這雙舊鞋丟掉吧。味道太誇張了。","e53/quiz.0.why":"針對「箱子蓋不起來」，建議了一個方法。","e53/quiz.1.ko":"我在床底下找到這個了！","e53/quiz.1.why":"就在床的正下方，所以用 under。","e53/quiz.2.ko":"別忘了帶走盆栽。","e53/quiz.2.why":"是提醒別忘了接下來要做的事，所以用 to。","e53/next":"Mina 也得找新家。她和 Noah 一起去看房子。","e54/title":"找房子","e54/prev":"Rosa 一邊打包搬家的行李，一邊和 Mina 聊起舊回憶。","e54/scene.ko":"星期天早上。Noah 和 Mina 來看房子。租金每個月不到 2,000 美元。","e54/scene.gloss.0.1":"租金","e54/scene.gloss.1.1":"每個月","e54/lines.0.ko":"歡迎！請隨意參觀。","e54/lines.1.ko":"雖然小，不過走到地鐵站不用十分鐘。","e54/lines.2.ko":"還不錯。不過我比較喜歡安靜的街道，而不是熱鬧的街道。","e54/lines.3.ko":"隔兩個街區還有一間。更安靜，而且還在預算之內。","e54/lines.4.ko":"妳想看那間嗎？還是想再多看看別的？","e54/lines.5.ko":"現在就去看吧。我不喜歡浪費時間。","e54/lines.6.dir.ko":"不久後，在第二間房子","e54/lines.6.ko":"就是這裡。啊，還有，樓下剛剛有一對年輕情侶簽約了。好像是 Jake 和 Rosa？","e54/lines.7.ko":"不會吧！Jake 和 Rosa？Noah，你早就知道了嗎？","e54/lines.8.dir.ko":"微笑著","e54/lines.8.ko":"也許吧。比起解釋，我更喜歡給人驚喜。","e54/lines.9.ko":"你真是沒救了。好吧，我再看一次。我覺得就是這裡了。","e54/quiz.0.why":"針對「要不要再看別的」的詢問，回答現在就去看。","e54/quiz.1.ko":"走到地鐵站不用十分鐘。","e54/quiz.1.why":"低於標準、未滿，用 under。","e54/quiz.2.ko":"我比較喜歡安靜的街道，而不是熱鬧的街道。","e54/quiz.2.why":"是 prefer A to B。","e54/next":"首爾專案的第一個截止日將至，Mina 承受著巨大的壓力。","e55/title":"壓力","e55/prev":"Mina 找到了 Jake 和 Rosa 要搬進的那棟大樓樓上的房子。","e55/scene.ko":"星期一下午四點。首爾專案承受著巨大的壓力。第一份初稿明天就要交。印表機剛剛發出了奇怪的聲音。","e55/scene.gloss.0.1":"初稿","e55/scene.gloss.1.1":"到期的","e55/lines.0.ko":"糟了。印表機又壞了。","e55/lines.1.ko":"現在不行！我下班前得把初稿印出來。","e55/lines.2.ko":"冷靜點。不要印，用螢幕展示就好。","e55/lines.3.ko":"抱歉。我不太擅長帶領這麼大的專案。壓力太大了。","e55/lines.4.ko":"妳做得比妳以為的好。身為領導者，承受壓力是很正常的。","e55/lines.5.dir.ko":"聲音顫抖","e55/lines.5.ko":"我只是……不想讓大家失望。","e55/lines.6.ko":"嘿。偶爾崩潰一下也沒關係。不過別還沒試就放棄。","e55/lines.7.ko":"而且初稿沒事。我修好檔案之後存起來了。","e55/lines.8.ko":"謝謝你們兩個。好。我們用螢幕看吧。","e55/lines.9.ko":"對。妳看，一切都在掌控之中。","e55/quiz.0.why":"針對「印表機壞了」的消息，接著是 Mina 焦急的回應。","e55/quiz.1.ko":"壓力太大了。","e55/quiz.1.why":"被壓力壓在底下，所以用 under。","e55/quiz.2.ko":"我不太擅長帶領這麼大的專案。","e55/quiz.2.why":"介系詞 at 後面接 -ing。","e55/next":"終於到了 Mina 搬家的日子。新家就在 Jake 和 Rosa 家的正樓上。","e56/title":"樓上，樓下","e56/prev":"在巨大的壓力下，Mina 差點崩潰，但 Daniel 和 Jake 一直陪在她身邊。","e56/scene.ko":"星期六。搬家日。Mina 的新家就在 Jake 和 Rosa 家的正樓上。","e56/scene.gloss.0.1":"搬家日","e56/scene.gloss.1.1":"家","e56/lines.0.dir.ko":"在樓下大喊","e56/lines.0.ko":"Mina！聽得到我的聲音嗎？","e56/lines.1.ko":"聽得到！地板好薄喔。我得習慣聽到你們兩個的聲音了。","e56/lines.2.dir.ko":"走上樓","e56/lines.2.ko":"抱歉！Jake 洗澡時會唱歌。妳很快就會習慣的。","e56/lines.3.ko":"Rosa，我習慣和妳住在一起了。一個人住好奇怪。","e56/lines.4.ko":"妳不是一個人啊。我就在樓下一層而已。","e56/lines.5.dir.ko":"和 Jake 一起搬沙發","e56/lines.5.ko":"這張沙發進得了門嗎？","e56/lines.6.ko":"轉過來！轉！好……進去了！","e56/lines.7.ko":"嘿，把它放在那幅大畫下面吧。","e56/lines.8.ko":"完美。妳知道嗎，我覺得 Mina 很適合這棟大樓。","e56/lines.9.ko":"希望如此。我還是不習慣當新來的。","e56/quiz.0.why":"針對「什麼聲音都聽得到」，Rosa 道歉。","e56/quiz.1.ko":"Mina 的家就在 Jake 和 Rosa 家的正樓上。","e56/quiz.1.why":"有一段距離的樓上，用 above。","e56/quiz.2.ko":"我習慣和妳住在一起了。","e56/quiz.2.why":"be used to 後面接 -ing。","e56/next":"在佈置新家的這天，黃色油漆惹出了麻煩。","e57/title":"黃色的牆","e57/prev":"Mina 搬到了 Jake 和 Rosa 家的正樓上。","e57/scene.ko":"星期天。Mina 正在把新家的客廳漆成黃色。Noah 扛著書架穿過走廊。","e57/scene.gloss.0.1":"書架","e57/scene.gloss.1.1":"走廊","e57/lines.0.ko":"小心！油漆還沒乾。","e57/lines.1.ko":"知道了。我提早來幫忙搬書架。","e57/lines.2.ko":"謝謝。你可以從臥室門把它抬進去嗎？","e57/lines.3.ko":"當然。把窗戶打開，讓油漆味散掉吧。","e57/lines.4.ko":"好主意。我正把這面牆漆成黃色，讓房間更明亮。","e57/lines.5.dir.ko":"提著袋子站在門口","e57/lines.5.ko":"外送來囉！我帶了三明治，免得你們兩個餓肚子。","e57/lines.6.ko":"爸！小心濕的牆！","e57/lines.7.dir.ko":"看著被染黃的袖子","e57/lines.7.ko":"太遲了。嗯，現在我和房間很搭了。","e57/lines.8.dir.ko":"笑著","e57/lines.8.ko":"Leo，請進。您喜歡這個顏色嗎？為了找這個顏色，我跑了三家店。","e57/lines.9.ko":"完美。陽光會直接從那扇窗戶照進來呢。","e57/quiz.0.why":"針對「小心」的提醒，回答 \\"知道了\\"。","e57/quiz.1.ko":"陽光會直接從那扇窗戶照進來。","e57/quiz.1.why":"穿過窗戶進來，所以用 through。","e57/quiz.2.ko":"把窗戶打開，讓油漆味散掉吧。","e57/quiz.2.why":"後面接 主詞 + can，所以用 so that。","e57/next":"在新家的第一個夜晚，不知從哪裡傳來吉他聲。","e58/title":"第一個夜晚","e58/prev":"Noah 和 Leo 幫忙整理 Mina 的新家。Leo 的袖子沾滿了黃色油漆。","e58/scene.ko":"星期一上午七點。Mina 在新家的第一個早晨。她沒睡好。整夜都聽到吉他聲。","e58/scene.gloss.0.1":"吉他","e58/scene.gloss.1.1":"整夜","e58/lines.0.dir.ko":"敲門","e58/lines.0.ko":"早安！睡得好嗎？","e58/lines.1.ko":"不太好。我醒了五次。有人在彈吉他。","e58/lines.2.ko":"天哪。那是 Jake。我也聽到他整晚在練習。","e58/lines.3.ko":"Jake 會彈吉他？","e58/lines.4.ko":"他在學。不管我怎麼做都阻止不了他。","e58/lines.5.dir.ko":"在樓下大喊","e58/lines.5.ko":"我都聽到了！Mina，我彈一首給妳聽！","e58/lines.6.ko":"拜託不要！沒喝咖啡之前不要。","e58/lines.7.ko":"好。我會叫他只在週末練習。星期一到星期五禁止彈吉他。","e58/lines.8.ko":"謝謝。明天七點可以叫我起床嗎？我的鬧鐘還在箱子裡。","e58/lines.9.ko":"當然。不然我就叫 Jake 唱歌。這樣誰都會醒的。","e58/quiz.0.why":"針對「Jake 會彈吉他嗎」的提問，說明情況。","e58/quiz.1.ko":"星期一到星期五禁止彈吉他。","e58/quiz.1.why":"從頭到尾（包含星期五），用 through。","e58/quiz.2.ko":"不管我怎麼做都阻止不了他。","e58/quiz.2.why":"是 make + 人 + 原形動詞。","e58/next":"週末下午，Rosa 帶著一個蠕動的箱子來了。","e59/title":"新成員","e59/prev":"在新家的第一個夜晚，Mina 被 Jake 的吉他聲吵得沒睡好。","e59/scene.ko":"星期六下午。Rosa 把一個小箱子帶到 Mina 家。裡面有東西在喵喵叫。","e59/scene.gloss.0.1":"喵喵叫","e59/scene.gloss.1.1":"在裡面","e59/lines.0.ko":"驚喜！我們醫院的護理師發現了這個孩子。我是透過朋友聽說的。","e59/lines.1.ko":"是小貓！天哪，好小喔！","e59/lines.2.ko":"妳說過想養貓吧。妳能好好照顧牠嗎？","e59/lines.3.ko":"當然！可是我一點貓食都沒有。能讓貓爬的家具也不多。","e59/lines.4.ko":"別擔心。我帶了一包貓食和幾個玩具來。","e59/lines.5.ko":"妳最棒了。有什麼建議嗎？我是第一次養寵物。","e59/lines.6.ko":"給牠乾淨的水，不要給牛奶。還有要給牠很多愛。","e59/lines.7.ko":"要取什麼名字呢？","e59/lines.8.ko":"取個韓國名字怎麼樣？","e59/lines.9.ko":"Kimchi！小小的，卻很辣。而且我出差的時候，Noah 可以幫忙照顧牠。","e59/quiz.0.why":"針對「能照顧嗎」的提問，用 \\"當然\\" 和煩惱來回答。","e59/quiz.1.ko":"我是透過朋友聽說的。","e59/quiz.1.why":"經由某個人，用 through。","e59/quiz.2.ko":"有什麼建議嗎？","e59/quiz.2.why":"advice 不可數，所以疑問句中用 any。","e59/next":"把 Kimchi 留在家裡，Mina 和 Noah 出門過橋散步。","e60/title":"走過橋","e60/prev":"Rosa 帶來了一隻小貓，Mina 為牠取名叫 Kimchi。","e60/scene.ko":"星期天傍晚。Mina 和 Noah 正走路過橋前往曼哈頓。太陽正在下山。","e60/scene.gloss.0.1":"橋","e60/scene.gloss.1.1":"（太陽）下山","e60/lines.0.ko":"我真不敢相信妳從來沒走路過這座橋。","e60/lines.1.ko":"如果停下來拍照，大概要走一個小時。","e60/lines.2.ko":"你看！有位畫家正在畫夕陽。","e60/lines.3.ko":"我去年碰巧遇到他。他每週會來這裡兩次。","e60/lines.4.dir.ko":"接起電話","e60/lines.4.ko":"喔，是我媽。媽，嗨！","e60/lines.5.dir.ko":"電話中","e60/lines.5.ko":"嗨，Mina！媽媽在練習英文。現在每個星期二都去上英文課了！","e60/lines.6.ko":"哇，媽！妳英文很好耶。七月會來，對吧？","e60/lines.7.ko":"當然！機票訂好了。妳旁邊是 Noah 嗎？那位廚師？","e60/lines.8.ko":"您好，伯母！我真的很期待為您下廚的那一天。","e60/lines.9.ko":"哎呀，真是紳士！我在網路上無意間看到那間咖啡館，真的好漂亮。","e60/quiz.0.why":"針對「第一次走過這座橋」的話，告知所需的時間。","e60/quiz.1.ko":"Mina 和 Noah 正走路過橋。","e60/quiz.1.why":"橫越橋的上方，所以用 across。","e60/quiz.2.ko":"大概要走一個小時。","e60/quiz.2.why":"hour 以母音發音開頭，所以用 an。","e60/next":"七月媽媽就要來紐約了。在那之前，首爾專案能順利完成嗎？","e61/title":"都吃光了","e61/prev":"Mina 和 Noah 走路過橋散步，媽媽決定七月來紐約。","e61/scene.ko":"星期一早上六點。Kimchi 在廚房喵喵叫。飯碗是空的。","e61/scene.gloss.0.1":"飯碗","e61/scene.gloss.1.1":"空的","e61/lines.0.dir.ko":"睡眼惺忪","e61/lines.0.ko":"Kimchi，現在是早上六點耶。怎麼了？","e61/lines.1.ko":"糟了。貓食吃完了。","e61/lines.2.dir.ko":"穿著護理師制服站在門口","e61/lines.2.ko":"早安！我隔著地板聽到貓在叫。","e61/lines.3.ko":"抱歉！貓食用完了。這附近有寵物店嗎？","e61/lines.4.ko":"有，對面有一家小店。那家七點開門。","e61/lines.5.ko":"七點？Kimchi 等不到那時候。","e61/lines.6.ko":"給。我包包裡有一些貓零食。給牠吃這個，牠就會安靜了。","e61/lines.7.ko":"妳是我的救命恩人。等等，不過妳為什麼會帶貓零食？","e61/lines.8.ko":"給醫院的貓吃的。是住在庭院的那隻。這座城市的貓都認得我。","e61/lines.9.dir.ko":"笑著","e61/lines.9.ko":"我就知道。","e61/quiz.0.why":"針對「有沒有店」的提問，用位置來回答。","e61/quiz.1.ko":"對面有一家小寵物店。","e61/quiz.1.why":"橫越馬路的對面，所以用 across。","e61/quiz.2.ko":"貓食吃完了。","e61/quiz.2.why":"用完、耗盡是 run out of。","e61/next":"平日的傍晚，Mina 和 Noah 沿著河邊散步。","e62/title":"沿著河邊","e62/prev":"Kimchi 的貓食吃完了，但 Rosa 用包包裡的零食度過了危機。","e62/scene.ko":"星期三傍晚。Mina 和 Noah 下班後沿著河邊散步。太陽正在下山。","e62/scene.gloss.0.1":"河","e62/scene.gloss.1.1":"（太陽）下山","e62/lines.0.ko":"Noah，慢一點！你走太快了。","e62/lines.1.ko":"抱歉。廚師總是很忙。現在好一點了嗎？","e62/lines.2.ko":"好多了。你看，月亮已經出來了。","e62/lines.3.ko":"好美。這裡是這座城市最棒的散步路線。","e62/lines.4.ko":"你常來這裡嗎？","e62/lines.5.ko":"每個星期天都來。沿著水邊走，一邊想新的食譜。","e62/lines.6.ko":"等等，有人在演奏音樂嗎？","e62/lines.7.ko":"對，有位老爺爺每天傍晚都在這裡拉小提琴。他把收到的錢捐給窮人。","e62/lines.8.ko":"真棒。我們可以慢慢走，聽一下嗎？","e62/lines.9.ko":"當然。對了，妳知道我以前彈過鋼琴嗎？","e62/quiz.0.why":"針對「慢一點」的要求，道歉並說明原因。","e62/quiz.1.ko":"我們正沿著河邊走。","e62/quiz.1.why":"順著河流走，所以用 along。","e62/quiz.2.ko":"你看，月亮已經出來了。","e62/quiz.2.why":"月亮只有一個，所以用 the。","e62/next":"Daniel 邀請 Mina 參加一場特別的派對。","e63/title":"要一起去嗎？","e63/prev":"沿著河邊散步的那個傍晚，Noah 說他以前彈過鋼琴。","e63/scene.ko":"星期五下午五點。Daniel 走到 Mina 的座位旁。他今天提早下班。","e63/scene.gloss.0.1":"順道拜訪","e63/scene.gloss.1.1":"提早","e63/lines.0.ko":"Mina，今晚是我爸爸的生日。我們在家辦個小派對。要一起來嗎？","e63/lines.1.ko":"真的嗎？好啊。我可以帶 Noah 一起去嗎？","e63/lines.2.ko":"當然可以。我爸爸喜歡好吃的食物。","e63/lines.3.ko":"伯父最近怎麼樣？","e63/lines.4.ko":"好很多了。他雖然很早睡，但晚餐後還是會講很長的故事。","e63/lines.5.ko":"跟 Leo 一樣呢！","e63/lines.6.dir.ko":"笑著","e63/lines.6.ko":"爸爸們好像都一樣。派對結束後我送妳回家。","e63/lines.7.ko":"謝謝。不過我得先回家餵 Kimchi。","e63/lines.8.ko":"沒關係。那我七點去接妳。","e63/lines.9.ko":"好。還有，伯父的新花園還順利嗎？我好想看看。","e63/quiz.0.why":"被邀請一起去時，開心地回答。","e63/quiz.1.ko":"我可以帶 Noah 一起去嗎？","e63/quiz.1.why":"一起帶著去，用 bring along。","e63/quiz.2.ko":"我得先回家。","e63/quiz.2.why":"home 前面不用冠詞，也不用 to。","e63/next":"在 Daniel 爸爸家，大家圍坐在大餐桌旁。","e64/title":"圍坐一桌","e64/prev":"Daniel 邀請 Mina 和 Noah 參加他爸爸的生日派對。","e64/scene.ko":"星期五晚上八點。Daniel 爸爸的家。房間裡到處都擺著花。兩隻老狗在壁爐邊睡覺。","e64/scene.gloss.0.1":"到處 · 圍繞","e64/scene.gloss.1.1":"在壁爐邊","e64/lines.0.ko":"歡迎！大家圍著餐桌坐吧。Daniel 常提到妳呢，Mina。","e64/lines.1.ko":"Frank，生日快樂！我帶了這個要送給您。","e64/lines.2.ko":"是花耶！我超愛花的。而且我們花園裡的花終於開了。","e64/lines.3.ko":"我做了一些餃子。希望您喜歡韓國料理。","e64/lines.4.ko":"我超愛的！Daniel，別再炫耀你的蛋糕了。Noah 才是真正的廚師。","e64/lines.5.ko":"我才沒有炫耀！我只是覺得那是個好蛋糕而已。","e64/lines.6.dir.ko":"笑著","e64/lines.6.ko":"Frank，那兩隻狗是您的狗嗎？","e64/lines.7.ko":"對。牠們是 Max 和 Lucy。有時候狗比人還好。","e64/lines.8.ko":"我養貓。我覺得貓比較好養。","e64/lines.9.ko":"哈！這家的狗會反對的。好了，開動吧！","e64/quiz.0.why":"針對「是 Frank 的狗嗎」的提問，告知牠們的名字。","e64/quiz.1.ko":"大家圍著餐桌坐吧。","e64/quiz.1.why":"繞著餐桌圍成一圈坐，所以用 around。","e64/quiz.2.ko":"有時候狗比人還好。","e64/quiz.2.why":"指狗這種動物的泛稱，所以不用冠詞，用複數。","e64/next":"媽媽來之前，Mina 列了一份紐約遊覽清單。","e65/title":"遊覽清單","e65/prev":"在 Daniel 爸爸的生日派對上，大家圍坐一桌，度過了愉快的時光。","e65/scene.ko":"星期天下午。Mina 在 Leo 的咖啡館列清單。媽媽的班機星期五從首爾起飛。","e65/scene.gloss.0.1":"清單","e65/scene.gloss.1.1":"起飛","e65/lines.0.ko":"那是什麼清單啊，Mina？","e65/lines.1.ko":"是要帶我媽去參觀的地方。","e65/lines.2.ko":"我看看。自由女神像、中央公園、時代廣場……選得不錯。","e65/lines.3.ko":"還有哈德遜河遊船。","e65/lines.4.ko":"別忘了布魯克林！全美國最好吃的披薩就在這附近。","e65/lines.5.dir.ko":"笑著","e65/lines.5.ko":"那是真的，還是只是 Leo 您自己的想法？","e65/lines.6.ko":"兩者都是。妳媽媽的班機什麼時候起飛？","e65/lines.7.ko":"首爾時間星期五早上。星期五晚上會抵達 JFK 機場。","e65/lines.8.ko":"那我和 Noah 來幫她準備歡迎晚餐。我也會帶她逛逛附近。","e65/lines.9.ko":"謝謝您，Leo。只是……請別把我的祕密全都說出來。","e65/quiz.0.why":"針對「是什麼清單」的提問，說出清單的內容。","e65/quiz.1.ko":"我也會帶她逛逛附近。","e65/quiz.1.why":"帶人到處參觀，用 show around。","e65/quiz.2.ko":"全美國最好吃的披薩就在這裡。","e65/quiz.2.why":"含有 States 的國名要加 the。","e65/next":"星期五晚上，Mina 在機場等媽媽。媽媽帶來了一個大消息。","e66/title":"媽媽抵達","e66/prev":"Mina 列了要帶媽媽參觀的紐約景點清單。Leo 和 Noah 決定準備歡迎晚餐。","e66/scene.ko":"星期五晚上十點左右。JFK 機場。Mina 和 Noah 在入境大廳等候。","e66/scene.gloss.0.1":"入境大廳出口","e66/scene.gloss.1.1":"機場","e66/lines.0.ko":"班機大約二十分鐘前就到了。她很快就會出來。","e66/lines.1.ko":"我好緊張。我大概四個月沒見到我媽了。","e66/lines.2.dir.ko":"揮手","e66/lines.2.ko":"Mina！Mina！","e66/lines.3.ko":"媽！歡迎來到紐約！飛行還好嗎？","e66/lines.4.ko":"好長啊！下飛機後腿好僵硬。而且我的眼鏡在包包裡不知道哪裡。","e66/lines.5.ko":"您好，伯母。我是 Noah。行李我來拿吧。","e66/lines.6.ko":"哎呀，謝謝！還有 Mina，我有個大消息。是關於妳弟弟的。他要結婚了！","e66/lines.7.ko":"什麼？Minsu 要結婚了？！","e66/lines.8.dir.ko":"笑著","e66/lines.8.ko":"恭喜！車子停在外面。這裡的警察對違規停車管得很嚴。","e66/lines.9.ko":"那我們快點吧！啊，還有，我在飛機上吃太多機上餐，牛仔褲變緊了。","e66/quiz.0.why":"針對「飛行怎麼樣」的提問，回答 \\"好長啊！\\"。","e66/quiz.1.ko":"班機大約二十分鐘前就到了。","e66/quiz.1.why":"大約的時間用 around。","e66/quiz.2.ko":"這裡的警察對違規停車管得很嚴。","e66/quiz.2.why":"police 是複數，所以用 are。","e66/next":"過了午夜，媽媽沉重的行李箱裡裝了什麼呢？","e67/title":"媽媽的行李","e67/prev":"媽媽抵達了紐約。她還帶來了弟弟 Minsu 要結婚的大消息。","e67/scene.ko":"星期五午夜。Mina 的家。Noah 提著媽媽的行李箱走上樓梯。","e67/scene.gloss.0.1":"行李箱","e67/scene.gloss.1.1":"樓梯","e67/lines.0.ko":"呼！行李箱真的好重。裡面裝了什麼？","e67/lines.1.ko":"泡菜、辣椒醬，還有 Mina 最愛的餅乾。","e67/lines.2.ko":"媽，我養了一隻叫 Kimchi 的貓。看到真的泡菜，牠說不定會搞混。","e67/lines.3.dir.ko":"笑著","e67/lines.3.ko":"牠在哪裡？哎呀，往上看！在書架頂上呢。","e67/lines.4.ko":"媽，您先坐一下吧。搭了十四小時的飛機，一定很累了。","e67/lines.5.ko":"沒關係！我想全部都看看。這是妳的咖啡杯嗎？好可愛。","e67/lines.6.ko":"伯母，請坐下休息一下。我來泡茶給您。","e67/lines.7.ko":"真是個好青年。Mina，Leo 的咖啡館在這附近嗎？","e67/lines.8.ko":"走路五分鐘。明天早上去吧。現在先睡一下。","e67/lines.9.dir.ko":"打著呵欠","e67/lines.9.ko":"好。不過在那之前，讓我抱抱我的孫女 Kimchi！","e67/quiz.0.why":"針對「裡面裝了什麼」的提問，用內容物回答。","e67/quiz.1.ko":"往上看！牠在書架頂上。","e67/quiz.1.why":"抬頭向上看，用 look up。","e67/quiz.2.ko":"搭了十四小時的飛機，您一定很累了。","e67/quiz.2.why":"放在名詞前面修飾的「數字 + 名詞」用單數。","e67/next":"隔天早上，廚房飄來香味。接著媽媽提出了問題。","e68/title":"媽媽的問題","e68/prev":"媽媽的沉重行李箱裡裝滿了泡菜、辣椒醬，還有 Mina 愛吃的餅乾。","e68/scene.ko":"星期六早上。媽媽一個人在 Mina 的廚房做早餐。她把火開得很大。","e68/scene.gloss.0.1":"早餐","e68/scene.gloss.1.1":"火 · 熱度","e68/lines.0.dir.ko":"睡醒","e68/lines.0.ko":"媽？您在做菜嗎？","e68/lines.1.ko":"對啊。坐下來盡量吃。媽媽全部都是自己做的。","e68/lines.2.ko":"哇，是泡菜鍋！小心喔，媽，別燙到了。","e68/lines.3.ko":"媽媽做了三十年的菜了。可以把音樂開大聲一點嗎？我喜歡一邊做菜一邊跳舞。","e68/lines.4.ko":"所以，Mina……妳和 Noah 在交往嗎？","e68/lines.5.ko":"媽！我們只是……偶爾出去吃晚餐而已。","e68/lines.6.ko":"大聲點說！音樂太吵聽不到。","e68/lines.7.dir.ko":"更大聲","e68/lines.7.ko":"好啦好啦！對，我們在交往！這樣可以了吧？","e68/lines.7.note":"go out 可以是「外出」，也可以是「交往」。媽媽問的是有沒有在交往。","e68/lines.8.ko":"太好了！妳只要照顧好自己。還有，今天晚上帶他來。","e68/lines.9.ko":"媽，您請自便……啊，您已經自便了呢。","e68/quiz.0.why":"被問到有沒有在交往，慌張地搪塞。","e68/quiz.1.ko":"大聲點說！我聽不到。","e68/quiz.1.why":"把聲音放大，用 speak up。","e68/quiz.2.ko":"媽媽全部都是自己做的。","e68/quiz.2.why":"強調親自做的，用 myself。","e68/next":"媽媽終於要去 Leo 的咖啡館了。","e69/title":"在 Leo 的咖啡店","e69/prev":"媽媽問 Mina 是不是在和 Noah 交往，Mina 最後承認了。","e69/scene.ko":"週六中午。Leo 的咖啡店。媽媽正在喝咖啡。Leo 一如往常話很多。","e69/scene.gloss.0.1":"一如往常","e69/scene.gloss.1.1":"正午","e69/lines.0.ko":"阿姨，歡迎歡迎！Mina 的朋友就是我的朋友嘛。","e69/lines.1.ko":"謝謝你。這咖啡真好喝。是老闆你的獨門祕方嗎？","e69/lines.2.ko":"是我自己的小祕密啦。我每天早上都親自烘豆子。","e69/lines.3.ko":"Mina，快點喝完。我們今天很忙。","e69/lines.4.dir.ko":"從廚房走出來","e69/lines.4.ko":"阿姨！您喝完了嗎？我又拿了蛋糕來。","e69/lines.5.ko":"Noah，你人真好。你怎麼能整天和你爸爸一起工作呢？","e69/lines.6.dir.ko":"微笑著","e69/lines.6.ko":"我忍受我爸的故事，我爸忍受我的音樂。","e69/lines.7.ko":"沒錯。他還在廚房放吵死人的搖滾樂。","e69/lines.8.ko":"Mina 的爸爸和我也一樣。我們彼此忍耐了三十年呢！","e69/lines.9.ko":"媽！好了，走吧。再不走，我們整天都要耗在這裡了。","e69/quiz.0.why":"被問到怎麼和爸爸一起工作，他回答說彼此忍耐。","e69/quiz.1.ko":"Mina，快點喝完。我們今天很忙。","e69/quiz.1.why":"喝到最後一滴是 drink up。","e69/quiz.2.ko":"Mina 的朋友就是我的朋友嘛。","e69/quiz.2.why":"of 後面要接所有格代名詞 mine。","e69/next":"度過愉快一週的星期日夜晚，Mina 的手機跳出一則訊息。","e70/title":"有事發生了","e70/prev":"媽媽在 Leo 的咖啡店和 Leo、Noah 度過了愉快的時光。","e70/scene.ko":"星期日傍晚。Mina 和媽媽搭遊船回來。夜晚很溫暖。突然，Mina 的手機跳出一則訊息。","e70/scene.gloss.0.1":"搭船 · 遊船","e70/scene.gloss.1.1":"突然跳出","e70/lines.0.ko":"是誰啊？出了什麼問題嗎？","e70/lines.1.ko":"是 Mr. Han。他說首爾那邊出事了。","e70/lines.2.ko":"是什麼事？","e70/lines.3.ko":"首爾的客戶出了問題。他要我下週過去首爾。","e70/lines.4.ko":"下週？可是那是媽媽在這裡的最後一週耶！","e70/lines.5.ko":"我知道。時間點糟透了。","e70/lines.6.ko":"等等。那我們一起回去不就好了？而且星期六還有你弟弟的訂婚儀式！","e70/lines.7.ko":"媽媽真是天才。可是 Kimchi 怎麼辦？Noah 呢？","e70/lines.8.dir.ko":"突然出現在門口","e70/lines.8.ko":"沒打電話就突然跑來，抱歉。我帶了甜點來。發生什麼事了嗎？","e70/lines.9.ko":"Noah……我剛剛有很多事要處理。下週你可以幫我照顧 Kimchi 嗎？","e70/quiz.0.why":"被問到是什麼事，她說出了發生的問題。","e70/quiz.1.ko":"沒打電話就突然跑來，抱歉。","e70/quiz.1.why":"「出現」是 show up。","e70/quiz.2.ko":"首爾的客戶出了問題。","e70/quiz.2.why":"告知有某個東西存在時用 There's。","e70/next":"要和媽媽一起去首爾？Mina 突如其來的首爾之行就此展開。","e71/title":"在飛機上","e71/prev":"首爾的客戶出了問題，Mina 要和媽媽一起去首爾。Kimchi 由 Noah 照顧。","e71/scene.ko":"星期二下午。Mina 和媽媽搭上飛往首爾的飛機。Mina 往下看著紐約。它越變越小。","e71/scene.gloss.0.1":"在下方","e71/scene.gloss.1.1":"越來越小","e71/lines.0.ko":"你有口香糖嗎？我耳朵好痛。","e71/lines.1.ko":"包包裡有一些。給您。","e71/lines.2.ko":"往下看！那條河像一條小緞帶。","e71/lines.3.dir.ko":"輕聲地","e71/lines.3.ko":"嗯。很漂亮。","e71/lines.4.ko":"怎麼了？你連一塊餅乾都沒吃。","e71/lines.5.ko":"我很擔心，媽。如果解決不了這件事，我會讓大家失望的。","e71/lines.6.ko":"你從來沒讓人失望過。還記得學校的話劇嗎？你忘了一些台詞。","e71/lines.7.ko":"然後大家都笑了！","e71/lines.8.ko":"對啊，因為那是喜劇。完美極了。","e71/lines.9.dir.ko":"笑著","e71/lines.9.ko":"謝謝媽。現在把書放下，睡一下吧。","e71/quiz.0.why":"被問到怎麼了，她說出了自己的擔憂。","e71/quiz.1.ko":"往下看！那條河像一條小緞帶。","e71/quiz.1.why":"從飛機上往下看，所以是 down。","e71/quiz.2.ko":"你連一塊餅乾都沒吃。","e71/quiz.2.why":"這是否定句，所以用 any。","e71/next":"抵達首爾的 Mina。在辦公室裡，Mr. Han 說出了問題。","e72/title":"首爾辦公室","e72/prev":"在飛往首爾的飛機上，Mina 擔心會讓大家失望，但媽媽給了她勇氣。","e72/scene.ko":"星期四上午九點。首爾辦公室。Mr. Han 和 Mina 在會議室。螢幕上可以看到紐約的 Dana 和 Jake。那裡是晚上八點。","e72/scene.gloss.0.1":"會議室","e72/scene.gloss.1.1":"螢幕","e72/lines.0.ko":"謝謝你這麼快趕來，Mina。問題是這樣的：更新之後，註冊人數減少了百分之四十。","e72/lines.1.ko":"百分之四十？測試的時候不是都沒問題嗎？","e72/lines.2.ko":"我整天都在檢查程式碼。沒有任何問題。","e72/lines.3.ko":"沒有人找得到註冊按鈕。而且年長的使用者，沒有人能翻過第一頁。","e72/lines.4.ko":"客戶改了什麼嗎？","e72/lines.5.ko":"對。他們把按鈕改得更小、顏色更淡。而且他們說，如果沒有任何改變，下個月就要關閉這個應用程式。","e72/lines.6.ko":"關閉應用程式？我們可是做了三個月耶？","e72/lines.7.dir.ko":"壓低聲音","e72/lines.7.ko":"抱歉。Rosa 在隔壁房間睡覺。我會小聲一點。","e72/lines.8.ko":"這是設計問題，所以是我的問題。我們沒有時間拖延了。今天可以和客戶見面嗎？","e72/lines.9.dir.ko":"微笑著","e72/lines.9.ko":"就是今天下午。所以我才找你來。","e72/quiz.0.why":"針對測試沒問題這句話，Jake 說程式碼沒有問題。","e72/quiz.1.ko":"更新之後，註冊人數減少了百分之四十。","e72/quiz.1.why":"數字減少了，所以是 down。","e72/quiz.2.ko":"沒有人找得到註冊按鈕。","e72/quiz.2.why":"「沒有人」是 No one。本身已是否定，所以不用 can't。","e72/next":"那天下午，Mina 去見難搞的客戶董事。","e73/title":"我來記下來","e73/prev":"更新之後，註冊人數減少了百分之四十。客戶說如果沒有任何改變，就要關閉應用程式。","e73/scene.ko":"星期四下午。Mina 前往客戶的辦公室。Ms. Yoon 在多倫多長大，在公司也總是說英語。她看起來很疲倦。","e73/scene.gloss.0.1":"董事","e73/scene.gloss.1.1":"長大","e73/lines.0.ko":"Kim 設計師，我的時間不多。我們快一點，一個一個把問題理清楚。","e73/lines.1.ko":"當然。上週有多少使用者打電話到客服中心？","e73/lines.2.ko":"太多了。超過兩千人。其中只有少數幾個人滿意。","e73/lines.3.dir.ko":"翻開筆記本","e73/lines.3.ko":"我可以把這些寫下來嗎？","e73/lines.4.ko":"請便。全部寫下來。我們老闆星期一前要答覆。","e73/lines.5.ko":"我們可以一起一頁一頁看註冊頁面嗎？一個小小的改變，就可能帶來很大的不同。","e73/lines.6.ko":"設計是你們團隊做的啊。為什麼要我來改？","e73/lines.7.ko":"其實，在我們的設計裡，這個按鈕比較大。請看。","e73/lines.8.dir.ko":"沉默了好一會兒","e73/lines.8.ko":"……那是我的想法。我以為這樣看起來會更簡潔。","e73/lines.9.ko":"看起來確實簡潔。但年長的人看不清楚。如果今天敲定計畫，星期一前我就把新設計交給您。","e73/quiz.0.why":"被問到為什麼要改，她拿出了原本的設計。","e73/quiz.1.ko":"我們今天把計畫敲定吧。","e73/quiz.1.why":"把計畫牢牢釘住固定下來，所以是 nail down。","e73/quiz.2.ko":"有多少使用者打電話到客服中心？","e73/quiz.2.why":"users 是可數的複數，所以用 many。","e73/next":"星期五傍晚，Mina 久違地回到爸媽家。爸爸站在廚房裡。","e74/title":"爸爸的廚房","e74/prev":"Ms. Yoon 承認把按鈕改小的人是自己。Mina 答應星期一前交出新設計。","e74/scene.ko":"星期五傍晚。首爾，Mina 爸媽的家。爸爸正在做菜。今晚全家人都說英語，是為了 Minsu 的未婚妻 Grace 而練習。","e74/scene.gloss.0.1":"未婚妻","e74/scene.gloss.1.1":"練習","e74/lines.0.ko":"姊！歡迎回家！妳看起來好累。","e74/lines.1.ko":"Minsu！恭喜你！你怎麼不先打電話給我？","e74/lines.2.ko":"我想讓媽媽親口告訴妳。我們大家都超興奮的。","e74/lines.3.dir.ko":"走進廚房","e74/lines.3.ko":"爸，您在煮飯嗎？我來幫忙。","e74/lines.4.ko":"不用，不用。給我離開我的廚房！去坐著。","e74/lines.5.ko":"別難過。爸爸會叫每個人都出去。他煮的菜大多是……很有個人特色。","e74/lines.6.ko":"我都聽到了！我每天早上都出去散步，還順便練英語呢。","e74/lines.7.ko":"Grace 為了明天緊張得要命。她家人有幾位完全不會說韓語。","e74/lines.8.ko":"原來媽媽是因為這樣才在學英語！","e74/lines.9.ko":"當然囉。好了，Mina，妳可以把垃圾拿出去放嗎？然後我們就開飯。","e74/quiz.0.why":"針對說要幫忙，爸爸叫她離開廚房。","e74/quiz.1.ko":"妳可以把垃圾拿出去放嗎？","e74/quiz.1.why":"拿到屋外去放，所以是 out。","e74/quiz.2.ko":"她家人有幾位完全不會說韓語。","e74/quiz.2.why":"是 her family 這個特定群體中的一部分，所以用 Some of。","e74/next":"訂婚儀式當天早上，Minsu 緊張得不得了。終於要見到 Grace 了。","e75/title":"訂婚當天早上","e75/prev":"爸爸退休後開始下廚，全家人為了 Minsu 的未婚妻 Grace 練習英語。","e75/scene.ko":"星期六早上。訂婚儀式就在今晚。Minsu 在客廳裡繞圈子。","e75/scene.gloss.0.1":"訂婚儀式","e75/scene.gloss.1.1":"繞圈圈","e75/lines.0.ko":"我壓力超大。印表機的墨水用完了，名牌還沒印好。","e75/lines.1.ko":"冷靜點。Grace 在哪裡？","e75/lines.2.dir.ko":"抱著花走進來","e75/lines.2.ko":"我在這裡！妳是 Mina 姊姊吧？我聽過好多關於妳的事！","e75/lines.3.ko":"Grace！歡迎加入我們家。Minsu 說你們兩個都喜歡登山。","e75/lines.4.ko":"對啊！可是我們兩個都很不會準備派對。妳看他。","e75/lines.5.dir.ko":"拿著手機","e75/lines.5.ko":"剛剛麵包店打電話來。我們的蛋糕都賣完了！","e75/lines.6.ko":"別有壓力。巧克力或草莓，隨便買一個就好。我兩種都喜歡。","e75/lines.7.dir.ko":"在廚房裡","e75/lines.7.ko":"天啊！燈剛剛熄了！","e75/lines.8.ko":"別擔心。我來修。我什麼都會修。","e75/lines.9.dir.ko":"握住 Minsu 的手","e75/lines.9.ko":"看吧？今晚只要有我們兩個，就會很完美。","e75/quiz.0.why":"針對蛋糕賣完了，Grace 說要買別的蛋糕。","e75/quiz.1.ko":"我們的蛋糕都賣完了！","e75/quiz.1.why":"賣光了、沒有了，所以是 sold out。","e75/quiz.2.ko":"我們兩個都很不會準備派對。","e75/quiz.2.why":"兩個都不是，所以用 Neither。要搭配單數動詞 is。","e75/next":"終於到了訂婚儀式。媽媽把一件舊韓服交給 Mina。","e76/title":"訂婚儀式","e76/prev":"訂婚當天早上，蛋糕賣完了，連燈都熄了，但 Grace 說只要有兩個人就很完美。","e76/scene.ko":"星期六下午五點。首爾的一間小餐廳。訂婚儀式前，媽媽在裡面的房間把一件舊韓服交給 Mina。","e76/scene.gloss.0.1":"裡面的房間","e76/scene.gloss.1.1":"韓服","e76/lines.0.ko":"穿穿看。這是媽媽訂婚時穿的韓服。","e76/lines.1.dir.ko":"幾分鐘後","e76/lines.1.ko":"媽，我穿了，剛剛好！您一直都保存著嗎？","e76/lines.2.ko":"保存了三十年。我就知道會有這一天。","e76/lines.3.dir.ko":"在訂婚儀式現場","e76/lines.3.ko":"姊，妳好美！全家人都來了。奶奶也從釜山過來了。","e76/lines.4.dir.ko":"緊張地站起來","e76/lines.4.ko":"各位，請聽我把話說完。我的英語很慢。","e76/lines.5.ko":"我每天都練習這段致詞。Grace，歡迎加入我們家。Minsu 是個幸運的傢伙。說完了。","e76/lines.6.ko":"爸，這就是全部的致詞嗎？","e76/lines.7.ko":"我寫了十次才寫完的。短才是最好的。","e76/lines.8.dir.ko":"看著手機","e76/lines.8.ko":"Noah 傳了照片來。Kimchi 為了派對繫上了小蝴蝶結！","e76/lines.9.dir.ko":"笑著","e76/lines.9.ko":"連貓都打扮起來了！來，我們吃飯吧。媽媽累壞了。","e76/quiz.0.why":"針對致詞就這樣嗎，爸爸說短才是最好的。","e76/quiz.1.ko":"各位，請聽我把話說完。","e76/quiz.1.why":"一直聽到最後，所以是 hear out。","e76/quiz.2.ko":"我每天都練習這段致詞。","e76/quiz.2.why":"「每天」是 every day。all day 是「整天」。","e76/next":"星期一早上，Mina 把新設計拿給 Ms. Yoon 看。","e77/title":"新設計","e77/prev":"在 Minsu 和 Grace 的訂婚儀式上，爸爸做了很短的致詞，媽媽的韓服 Mina 穿起來剛剛好。","e77/scene.ko":"星期一上午十點。客戶的辦公室。Mina 把新的註冊頁面拿給 Ms. Yoon 看。Mr. Han 也在場。","e77/scene.gloss.0.1":"註冊頁面","e77/scene.gloss.1.1":"也","e77/lines.0.ko":"這就是新設計啊。改了哪些地方？","e77/lines.1.ko":"每個按鈕都變大了，字體也變得更粗。年長的使用者之前認不太出舊的按鈕。","e77/lines.2.ko":"認不出來？它明明就在那裡啊。","e77/lines.3.ko":"對您和我來說是這樣。我們星期日找了二十位使用者做測試。每位使用者兩個版本都用過。","e77/lines.4.ko":"今天早上結果出來了。沒有一個例外，大家都更快找到新按鈕。","e77/lines.5.dir.ko":"沉默了好一會兒","e77/lines.5.ko":"我雖然不想承認，但 Kim 設計師說得對。","e77/lines.6.ko":"Kim 設計師，我得向妳道歉。每次見面我都很無禮。","e77/lines.7.ko":"您承受了很多壓力。我能理解。","e77/lines.8.ko":"我們老闆聽到這個消息會非常高興。我們星期五上線吧。","e77/lines.9.dir.ko":"微笑著","e77/lines.9.ko":"辛苦了，Mina。你看，總算雨過天晴了。星期四來找我一下。我有個想法。","e77/quiz.0.why":"針對改了哪些地方，她說出了改變的部分。","e77/quiz.1.ko":"今天早上結果出來了。","e77/quiz.1.why":"結果公諸於世，所以是 come out。","e77/quiz.2.ko":"年長的人認不太出舊的按鈕。","e77/quiz.2.why":"勉強辨認出來是 make out。","e77/next":"星期二傍晚，Mina 和媽媽去了老街區的路邊攤。媽媽的嘮叨開始了。","e78/title":"在路邊攤","e78/prev":"新設計的測試大獲成功。Ms. Yoon 道了歉，Mr. Han 說星期四有話要談。","e78/scene.ko":"星期二傍晚。Mina 和媽媽在 Mina 以前就讀的高中附近的路邊攤吃辣炒年糕。","e78/scene.gloss.0.1":"路邊攤 · 小吃攤","e78/scene.gloss.1.1":"高中","e78/lines.0.ko":"這就是妳高中時最愛的路邊攤。還記得嗎？","e78/lines.1.ko":"當然記得！這裡的老闆到現在還記得我。","e78/lines.2.ko":"對了，Mrs. Park 的兒子在銀行上班。聽說他還是單身。","e78/lines.3.ko":"媽！我有一個住在紐約的男朋友啊！","e78/lines.4.ko":"紐約太遠了。這就是媽媽擔心的問題。","e78/lines.5.dir.ko":"夾起最後一塊年糕","e78/lines.5.ko":"媽，拜託別再說了。我二十八歲了。","e78/lines.6.ko":"喂，手別碰我的年糕！……好啦，好啦。我不說了。","e78/lines.7.dir.ko":"輕聲地","e78/lines.7.ko":"我只是想妳。連 Minsu 也離開的話，一向吵吵鬧鬧的家就會變得安靜了。","e78/lines.8.ko":"啊，媽……","e78/lines.9.dir.ko":"擦著眼角","e78/lines.9.ko":"好了啦。年糕從筷子上掉下去了。看看妳的襯衫！","e78/quiz.0.why":"針對叫她別再說了，媽媽說好啦。","e78/quiz.1.ko":"手別碰我的年糕！","e78/quiz.1.why":"把手從年糕上移開，所以是 off。","e78/quiz.2.ko":"我有一個住在紐約的男朋友。","e78/quiz.2.why":"前面是人 boyfriend，所以用 who。","e78/next":"首爾的夜晚，紐約的早晨。Mina 和 Noah 視訊通話。","e79/title":"視訊通話","e79/prev":"媽媽希望 Mina 能住得離首爾近一點。她說連 Minsu 也離開的話，家裡會太安靜。","e79/scene.ko":"首爾是星期三晚上十一點，紐約是上午十點。Mina 在以前的房間裡和 Noah 視訊通話。","e79/scene.gloss.0.1":"視訊通話","e79/scene.gloss.1.1":"臥室 · 房間","e79/lines.0.ko":"嗨！我馬上就要去咖啡店了，但我想看看妳的臉。","e79/lines.1.ko":"你傳來的照片我超喜歡。繫著蝴蝶結的 Kimchi！","e79/lines.2.ko":"Kimchi 很討厭那個。今天早上它咬著蝴蝶結跑掉了。","e79/lines.3.ko":"哈！對了，我之前說的那位客戶超愛新設計。","e79/lines.4.ko":"是 Ms. Yoon 嗎？我就知道她最後會接受的。","e79/lines.5.ko":"她甚至還道歉了。星期五上線，我星期六回去。","e79/lines.6.ko":"太好了。星期日過來吃晚餐吧。我煮妳愛喝的湯給妳。","e79/lines.7.dir.ko":"猶豫著","e79/lines.7.ko":"Noah……Mr. Han 說明天要找我談。他說他有個想法。","e79/lines.8.ko":"想法？聽起來是件大事。","e79/lines.9.ko":"我知道。不管怎樣，時間也晚了。快去吧！還有，把我放在架子上的零食拿給 Kimchi。","e79/quiz.0.why":"針對客戶喜歡新設計，Noah 說他早就料到了。","e79/quiz.1.ko":"我馬上就要去咖啡店了。","e79/quiz.1.why":"離開所在的地方出發，所以是 I'm off。","e79/quiz.2.ko":"你傳來的照片我超喜歡。","e79/quiz.2.why":"是 the photo (that) you sent。不要再重複用 it。","e79/next":"星期四，Mr. Han 向 Mina 提出了一個意想不到的提議。","e80/title":"Mr. Han 的提議","e80/prev":"Ms. Yoon 接受了新設計。Mina 告訴 Noah，Mr. Han 說明天要找她談。","e80/scene.ko":"星期四下午五點。Mr. Han 的辦公室。會議結束了。Mr. Han 關掉螢幕，把門關上。","e80/scene.gloss.0.1":"辦公室 · 房間","e80/scene.gloss.1.1":"關上","e80/lines.0.ko":"先說好消息。客戶取消了關閉應用程式的決定。新設計明天公開。","e80/lines.1.ko":"真的嗎？太棒了！","e80/lines.2.ko":"還有，Ms. Yoon 想在明年做一個更大的專案。而且她點名要你。","e80/lines.3.ko":"我嗎？可是我會在紐約啊。","e80/lines.4.ko":"這就是我的想法。我想在首爾成立新的設計團隊。就在你第一次開始工作的這間辦公室。","e80/lines.5.ko":"這個團隊要做出會有數百萬人使用的成果。我希望從九月起由你來帶領。","e80/lines.6.dir.ko":"嚇了一跳","e80/lines.6.ko":"可是……我才剛決定要在紐約再待一年。我的家、Kimchi、Noah……","e80/lines.7.ko":"我知道。如果你拒絕，我就把整個計畫收起來。不要有壓力。","e80/lines.8.ko":"不要有壓力？Mr. Han，這壓力可大了！","e80/lines.9.dir.ko":"笑著","e80/lines.9.ko":"慢慢想吧。回紐約後，把手機關機一天，好好想一想。也聽聽對你重要的人怎麼說。","e80/quiz.0.why":"針對說自己會在紐約，Mr. Han 提起了首爾新團隊的事。","e80/quiz.1.ko":"把手機關機一天，好好想一想。","e80/quiz.1.why":"切斷電源關掉，所以是 off。","e80/quiz.2.ko":"這裡就是你第一次開始工作的辦公室。","e80/quiz.2.why":"在地點 office 後面接「在那裡……的」，所以用 where。","e80/next":"留在首爾，還是回紐約？Mina 帶著大大的煩惱搭上飛往紐約的班機。","e81/title":"回到紐約","e81/prev":"Mr. Han 請 Mina 從九月起帶領首爾的新設計團隊。Mina 決定回紐約後再想一想。","e81/scene.ko":"星期六晚上。JFK 機場。Noah 在入境大廳舉著寫有「歡迎回來，Mina」的紙牌等她。","e81/scene.gloss.0.1":"牌子 · 紙","e81/scene.gloss.1.1":"入境大廳出口","e81/lines.0.ko":"歡迎回來！Jake 給我看了數字。妳的辛苦都有了成果！","e81/lines.1.ko":"謝謝。一開始很討厭我的 Ms. Yoon，今天早上送了花給我。","e81/lines.2.ko":"你看，我說過會有成果的。家人都好嗎？","e81/lines.3.ko":"都很好。爸爸的致詞只有四句話，大家卻都哭了。","e81/lines.4.ko":"哈！我已經開始喜歡你爸爸了。不過你看起來累壞了。明天好好休息吧。","e81/lines.5.ko":"星期日本來就是休息日。星期一你也休息。Dana 堅持要這樣。","e81/lines.6.ko":"太好了。超想念你的 Kimchi 正在家裡等你。","e81/lines.7.dir.ko":"輕聲地","e81/lines.7.ko":"Noah……我有話要跟你說。是關於 Mr. Han 的想法。","e81/lines.8.ko":"是壞消息嗎？","e81/lines.9.ko":"不是壞事。只是……很重大。明天晚餐時可以聊聊嗎？","e81/quiz.0.why":"針對是不是壞消息，她說不是壞事，只是很重大。","e81/quiz.1.ko":"你看起來累壞了。明天好好休息吧。","e81/quiz.1.why":"從工作中抽出一天休息，所以是 off。","e81/quiz.2.ko":"一開始很討厭我的 Ms. Yoon 送了花給我。","e81/quiz.2.why":"逗號後面接的是人，所以用 who。不能用 that。","e81/next":"星期日傍晚，Noah 的家。Mina 終於說出 Mr. Han 的提議。","e82/title":"晚餐餐桌","e82/prev":"Mina 回到紐約了。但她還沒告訴 Noah Mr. Han 的提議。","e82/scene.ko":"星期日傍晚。Noah 的家。Mina 走進廚房。Noah 正把湯倒進兩個碗裡。","e82/scene.gloss.0.1":"倒","e82/scene.gloss.1.1":"碗","e82/lines.0.ko":"來得正好。坐吧。這就是我們第一次一起吃晚餐的那張餐桌。","e82/lines.1.dir.ko":"笑著","e82/lines.1.ko":"\\"At which\\"？你幹嘛說得像教科書一樣？","e82/lines.2.ko":"因為我很緊張。好了，仔細告訴我吧。Mr. Han 的想法是什麼？","e82/lines.3.ko":"他要我去首爾帶領一個新團隊。從九月開始。","e82/lines.4.dir.ko":"放下湯匙","e82/lines.4.ko":"九月？那就是……兩個月後。","e82/lines.5.ko":"我還沒答應。我想先和你談談。我需要的是你真實的想法。","e82/lines.6.ko":"說實話？我希望的是你能幸福。","e82/lines.7.ko":"那不算是回答吧，Noah。","e82/lines.8.ko":"我知道。給我一點時間。還有，請一點都不要漏掉，全部告訴我。團隊也好，工作也好，通通都說。","e82/lines.9.dir.ko":"點點頭","e82/lines.9.ko":"好。先吃吧。湯要涼了。","e82/quiz.0.why":"針對請她仔細說，她說出了 Mr. Han 的提議。","e82/quiz.1.ko":"Noah 正把湯倒進兩個碗裡。","e82/quiz.1.why":"是倒進碗裡面的動作，所以用 into。","e82/quiz.2.ko":"我希望的是你能幸福。","e82/quiz.2.why":"「……的事」是 What。","e82/next":"星期一早上，Leo 的咖啡店。Leo 透露了 Noah 的一個祕密。","e83/title":"口袋裡的夢想","e83/prev":"Mina 對 Noah 說出了 Mr. Han 的提議。Noah 說想要一些時間思考。","e83/scene.ko":"星期一早上。Leo 的咖啡店。Jake 正在擺弄新的咖啡機。Mina 坐在吧檯前。","e83/scene.gloss.0.1":"咖啡機","e83/scene.gloss.1.1":"吧檯","e83/lines.0.ko":"Jake，別再亂動我的機器了！","e83/lines.1.ko":"我沒有亂動啦。我是在升級。","e83/lines.2.dir.ko":"對 Mina 說","e83/lines.2.ko":"對了，Noah 都跟我說了。聽說是首爾？","e83/lines.3.ko":"您消息真靈通。Noah 很難過嗎？","e83/lines.4.ko":"難過？妳看這個。這是韓國廚師寫的書。他每天晚上都在讀。","e83/lines.5.ko":"Noah 迷上韓國料理了嗎？","e83/lines.6.ko":"迷得不得了。還有，妳看，這是每年秋天在首爾舉辦的烹飪課程。他還特地圈起來了。","e83/lines.7.ko":"他一次也沒跟我說過。","e83/lines.8.ko":"我兒子就是會把夢想放在口袋裡的人。站在我機器後面的那個傢伙也一樣。他帶著戒指兩個星期了。","e83/lines.9.dir.ko":"臉紅了","e83/lines.9.ko":"老闆！那是祕密耶！……Mina，別告訴 Rosa。","e83/quiz.0.why":"針對是否迷上韓國料理，Leo 說他迷得不得了。","e83/quiz.1.ko":"Noah 迷上韓國料理了。","e83/quiz.1.why":"沉迷於某件事，所以是 be into。","e83/quiz.2.ko":"妳看，這是每年秋天在首爾舉辦的烹飪課程。","e83/quiz.2.why":"課程是被舉辦的一方，所以用過去分詞 held。","e83/next":"隔天在辦公室。聽到首爾的提議，Jake 氣炸了。","e84/title":"妳是要逃跑嗎？","e84/prev":"Leo 告訴 Mina，Noah 迷上韓國料理，甚至在查首爾的烹飪課程。Jake 已經帶著戒指兩個星期了。","e84/scene.ko":"星期二早上。辦公室。Mina 向 Dana、Jake 和 Daniel 說起這個提議。Jake 一臉震驚。","e84/scene.gloss.0.1":"提議","e84/scene.gloss.1.1":"震驚的","e84/lines.0.ko":"等一下。妳要離開？這個消息太震撼了。","e84/lines.1.ko":"我還沒決定。我現在好混亂。","e84/lines.2.ko":"說實話我並不意外。Mr. Han 一直都很欣賞你的工作。","e84/lines.3.ko":"可是首爾離這裡有七千英里遠耶！妳不能就這樣逃去首爾！","e84/lines.4.ko":"我不是逃跑，Jake。這是一份正式的工作。","e84/lines.5.ko":"Jake，把手機收起來，聽我說。","e84/lines.6.ko":"我年輕的時候也去過倫敦三年。那是一段很令人興奮的時光。","e84/lines.7.ko":"然後呢？","e84/lines.8.ko":"然後我就回來了。門是永遠不會關上的。","e84/lines.9.dir.ko":"輕聲地","e84/lines.9.ko":"對不起，Mina。我不是生氣。只是沒有妳，公司會變得很無聊。","e84/quiz.0.why":"針對不能逃去首爾，她說那是一份正式的工作。","e84/quiz.1.ko":"首爾離這裡有七千英里遠！","e84/quiz.1.why":"是離這裡的距離，所以用 away。","e84/quiz.2.ko":"我好混亂。我不知道該怎麼辦。","e84/quiz.2.why":"人感受到混亂，所以是 confused。","e84/next":"頭痛欲裂的 Mina。Daniel 帶她去爸爸的花園。","e85/title":"Frank 的花園","e85/prev":"辦公室的人聽到 Mina 的首爾提議都很驚訝。Daniel 說門是永遠不會關上的。","e85/scene.ko":"星期三傍晚。Frank 的花園。番茄紅透了，玫瑰香氣甜美。太陽正慢慢隱沒在樹後。","e85/scene.gloss.0.1":"玫瑰","e85/scene.gloss.1.1":"慢慢消失","e85/lines.0.ko":"Mina！Daniel 說妳頭痛。坐下來，慢慢呼吸。","e85/lines.1.ko":"謝謝你，Frank。這座花園真漂亮。","e85/lines.2.ko":"蒔花弄草是一帖好藥。我生病的時候，煩惱在這裡都融化不見了。","e85/lines.3.ko":"我希望我的頭痛也能消失。","e85/lines.4.ko":"會消失的。我聽 Daniel 說了首爾的事。聽說妳在那裡表現得很好。","e85/lines.5.ko":"可是現在我必須做選擇。不管選哪一個，都會有人難過。","e85/lines.6.ko":"要慎重考慮。不過別等著沉重的心情自己消失。它不會消失的。","e85/lines.7.dir.ko":"端著茶過來","e85/lines.7.ko":"我爸給的建議好得不得了。種的紅蘿蔔卻差勁透了。","e85/lines.8.ko":"喂！那是兔子的錯，不是我的錯！","e85/lines.9.dir.ko":"笑著","e85/lines.9.ko":"謝謝你們兩位。你們真的很會聆聽。","e85/quiz.0.why":"針對希望頭痛消失，Frank 說會消失的。","e85/quiz.1.ko":"煩惱在這裡融化不見了。","e85/quiz.1.why":"融化而消失，所以是 melt away。","e85/quiz.2.ko":"妳在首爾表現得很好。","e85/quiz.2.why":"修飾動詞 did，所以用副詞 well。","e85/next":"星期四夜晚，屋頂。值完夜班的 Rosa 來找 Mina。","e86/title":"在屋頂上","e86/prev":"Frank 說，不要等著沉重的心情消失，要慎重考慮。","e86/scene.ko":"星期四夜晚。Mina 住的大樓屋頂。Rosa 一小時前下班回來。她端來了兩杯茶。","e86/scene.gloss.0.1":"屋頂","e86/scene.gloss.1.1":"一小時前","e86/lines.0.ko":"妳什麼時候從 Frank 家回來的？","e86/lines.1.ko":"大概九點。Rosa，我可以問妳一件事嗎？首爾會比紐約好嗎？","e86/lines.2.ko":"這問題好奇怪。首爾比較安全。紐約比較貴。","e86/lines.3.ko":"而且首爾的食物比較便宜。不過披薩還是這裡好吃多了。","e86/lines.4.dir.ko":"笑著","e86/lines.4.ko":"妳在比披薩嗎？這又不是真正的問題。","e86/lines.5.ko":"我知道。真正的問題是……如果我去了，還回得來嗎？","e86/lines.6.ko":"當然可以。人們本來就是來來去去的。","e86/lines.7.ko":"不過 Mina，不要選比較輕鬆的路。選讓妳更幸福的那條。","e86/lines.8.ko":"妳什麼時候變得這麼有智慧了？","e86/lines.9.ko":"都是夜班的功勞。我有很多時間可以思考。好了，我們進去吧。好冷。","e86/quiz.0.why":"針對還回得來嗎，她說當然可以。","e86/quiz.1.ko":"如果我去了，還回得來嗎？","e86/quiz.1.why":"回到原來的地方，所以是 back。","e86/quiz.2.ko":"紐約比首爾更貴。","e86/quiz.2.why":"expensive 是長單字，所以用 more expensive。","e86/next":"星期五夜晚，Mina 和 Noah。壓抑已久的情緒爆發了。","e87/title":"爭吵","e87/prev":"Rosa 說，不要選輕鬆的路，要選讓自己更幸福的路。","e87/scene.ko":"星期五晚上九點。已打烊的 Leo 的咖啡店。Mina 今天傳了三則訊息給 Noah，但他都沒回。","e87/scene.gloss.0.1":"打烊後","e87/scene.gloss.1.1":"傳訊息","e87/lines.0.ko":"Noah，我傳了三則訊息耶。你為什麼不回？","e87/lines.1.dir.ko":"擦著吧檯","e87/lines.1.ko":"我很忙。","e87/lines.2.ko":"你沒有看起來那麼忙吧。","e87/lines.3.ko":"好啦。我越想首爾的事，就越害怕。這樣可以了嗎？","e87/lines.4.ko":"那就告訴我啊！不要藏著。","e87/lines.5.ko":"妳想聽我說什麼？去吧，Mina。反正妳本來就想去。","e87/lines.6.dir.ko":"一臉受傷","e87/lines.6.ko":"這不公平。","e87/lines.7.dir.ko":"沉默了好一會兒","e87/lines.7.ko":"妳說得對。對不起。我收回那句話。","e87/lines.8.ko":"那種話不是這麼輕易就能收回的。我會受傷的。","e87/lines.9.dir.ko":"走向門口","e87/lines.9.ko":"我去吹吹風。晚安，Noah。","e87/quiz.0.why":"針對為什麼不回，Noah 推說自己很忙。","e87/quiz.1.ko":"你為什麼不回？","e87/quiz.1.why":"回覆收到的訊息，所以是 write back。","e87/quiz.2.ko":"我越想首爾的事，就越害怕。","e87/quiz.2.why":"是 the + 比較級，the + 比較級。","e87/next":"隔天早上，Leo 對 Mina 說起三十年前的故事。","e88/title":"Leo 的故事","e88/prev":"Mina 和 Noah 第一次大吵一架。Noah 收回了那句話，但 Mina 的心還是很痛。","e88/scene.ko":"星期六早上。Leo 的咖啡店很安靜。Leo 為 Mina 沖了咖啡，坐到她對面。","e88/scene.gloss.0.1":"安靜的","e88/scene.gloss.1.1":"在……的對面","e88/lines.0.ko":"來。這是布魯克林最濃的咖啡。我看妳需要。","e88/lines.1.ko":"謝謝你，Leo。Noah 反對我去首爾嗎？","e88/lines.2.ko":"他不是反對。他是害怕。這兩件事不一樣。","e88/lines.3.ko":"三十年前，我有機會去羅馬工作。那是我人生中最大的機會。","e88/lines.4.ko":"後來怎麼樣了？","e88/lines.5.ko":"Noah 的媽媽反對。所以我留下來了。我花了一年才放下這件事。","e88/lines.6.ko":"您後悔嗎？","e88/lines.7.ko":"有時候會。不過因為留下來，我才有了這間咖啡店和 Noah。那是我做過最好的決定……也是最難的決定。","e88/lines.8.ko":"Noah 需要時間克服恐懼。不要放棄他。","e88/lines.9.dir.ko":"微微一笑","e88/lines.9.ko":"Leo 是紐約最有智慧的咖啡大叔，您知道嗎？","e88/quiz.0.why":"針對 Noah 是否反對，Leo 說他是害怕。","e88/quiz.1.ko":"Noah 的媽媽反對。所以我留下來了。","e88/quiz.1.why":"是反對，所以用 against。","e88/quiz.2.ko":"那是我人生中最大的機會。","e88/quiz.2.why":"big → biggest。要多加一個 g。","e88/next":"那天夜裡下起了雨。有人在 Mina 家門前等著。","e89/title":"在雨中","e89/prev":"Leo 說起三十年前沒去羅馬的故事。Noah 需要時間克服恐懼。","e89/scene.ko":"星期六夜晚。雨下得很大。雨滴敲打著窗戶。Mina 撐著傘走路回家。","e89/scene.gloss.0.1":"敲打","e89/scene.gloss.1.1":"雨傘","e89/lines.0.dir.ko":"從後面","e89/lines.0.ko":"Mina！回頭看！","e89/lines.1.dir.ko":"嚇了一跳","e89/lines.1.ko":"Noah？你全身都濕透了！你等多久了？","e89/lines.2.ko":"一個小時。我像悲情電影的男主角一樣，靠在你們大樓旁邊站著。","e89/lines.3.ko":"你從來不等任何人。你還老是說等人是浪費時間。","e89/lines.4.ko":"我知道。我常常會說些莫名其妙的話。像昨晚那樣。","e89/lines.5.ko":"對不起，Mina。我因為害怕，把你推開了。我有時候是個膽小鬼。","e89/lines.6.ko":"常常是啊。不過你還是來了。","e89/lines.7.ko":"我從來沒對任何人有過這種感覺。就算你去首爾，我們也會找到辦法的。","e89/lines.8.dir.ko":"又哭又笑","e89/lines.8.ko":"到我的傘下來。你會感冒的。","e89/lines.9.ko":"等一下。進去之前回頭看看。看看那座橋。在雨中真的好美。","e89/quiz.0.why":"針對等了多久，他用時間來回答。","e89/quiz.1.ko":"我靠在你們大樓旁邊站著。","e89/quiz.1.why":"靠在建築物上、把重量倚上去，所以是 against。","e89/quiz.2.ko":"你從來不等任何人。","e89/quiz.2.why":"never 放在一般動詞 wait 前面。不要再用 not。","e89/next":"星期日早上，Mina 決定打電話給 Mr. Han。但在那之前，她想到了一個點子。","e90/title":"等一下！","e90/prev":"Noah 在雨中道了歉。就算 Mina 去首爾，兩人也決定要找出辦法。","e90/scene.ko":"星期日早上。Mina 的家。窗外，在晴朗的藍天襯托下，那座橋看得很清楚。Noah 正在煎鬆餅。","e90/scene.gloss.0.1":"清晰的","e90/scene.gloss.1.1":"晴朗的","e90/lines.0.ko":"妳現在決定了嗎？","e90/lines.1.ko":"還沒。我還是不知道。","e90/lines.2.ko":"妳打給 Mr. Han 了嗎？","e90/lines.3.ko":"一個小時後再打。首爾已經是星期日晚上了。","e90/lines.4.ko":"那妳先吃點東西。豐盛的早餐是防止做出壞決定的最佳盾牌。","e90/lines.5.dir.ko":"笑著","e90/lines.5.ko":"這是廚師的規矩嗎？","e90/lines.6.ko":"是我的規矩。而且我已經有計畫了。妳去的話，我每個月都去。說不定我還會去上首爾的烹飪課。","e90/lines.7.dir.ko":"突然","e90/lines.7.ko":"等一下。再說一次。","e90/lines.8.ko":"我每個月都去？","e90/lines.9.ko":"來來去去……就像橋一樣。等一下！Mr. Han 以前說過我是連接首爾和紐約的橋。我好像有個好點子了！","e90/quiz.0.why":"針對決定了嗎，她回答還沒。","e90/quiz.1.ko":"在晴朗的藍天襯托下，那座橋看得很清楚。","e90/quiz.1.why":"緊貼著背景而顯得突出，所以是 against。","e90/quiz.2.ko":"我還是不知道該怎麼辦。","e90/quiz.2.why":"「仍然一直」是 still。要放在 not 前面。","e90/next":"Mina 想成為連接首爾與紐約的橋。Mr. Han 會怎麼說呢？","e91/title":"我來當橋","e91/prev":"Mina 從 Noah 的話中想到了連接首爾與紐約的「橋」這個點子。","e91/scene.ko":"紐約是星期日上午十點，首爾是晚上十一點。Mina 正在和 Mr. Han 視訊通話。Noah 在廚房裡聽著。","e91/scene.gloss.0.1":"視訊通話","e91/scene.gloss.1.1":"聽","e91/lines.0.ko":"Mina，這裡已經是深夜了。妳決定了嗎？","e91/lines.1.ko":"我有一個想法。如果新團隊在首爾和紐約之間工作，您覺得怎麼樣？","e91/lines.2.ko":"在兩個城市之間？那太複雜了。","e91/lines.3.ko":"不會的。兩邊的辦公室都有足夠的優秀人才。我可以三個月待在首爾，三個月待在紐約。","e91/lines.4.ko":"那時差呢？十三個小時太大了。","e91/lines.5.ko":"那正是優點。首爾睡覺的時候，紐約在工作。專案就不會停下來。","e91/lines.6.dir.ko":"想了一下","e91/lines.6.ko":"嗯。我今晚太累了，沒辦法做決定。我明天再打給妳。","e91/lines.7.ko":"先別掛！再說一件事就好。您以前說過我是連接首爾和紐約的橋。","e91/lines.8.dir.ko":"微笑著","e91/lines.8.ko":"……我有說過嗎？好吧。星期三前把完整的計畫書寄給我。時間夠嗎？","e91/lines.9.dir.ko":"通話結束後","e91/lines.9.ko":"Noah！電話是掛了，但他沒說不行！","e91/quiz.0.why":"針對太複雜，她回答說優秀的人才足夠。","e91/quiz.1.ko":"如果團隊在首爾和紐約之間工作，您覺得怎麼樣？","e91/quiz.1.why":"是明確的兩個城市之間，所以是 between。","e91/quiz.2.ko":"我今晚太累了，沒辦法做決定。","e91/quiz.2.why":"表示「太……而無法……」的是 too … to。","e91/next":"星期三，所有人齊聚視訊會議。Mr. Han 的答覆會是什麼？","e92/title":"Mr. Han 的答覆","e92/prev":"Mina 提議組成往返首爾與紐約的團隊。Mr. Han 要她在星期三前寄出計畫書。","e92/scene.ko":"星期三晚上八點。紐約辦公室。Dana、Daniel、Jake 和 Mina 在會議室。Mr. Han 出現在大螢幕上。","e92/scene.gloss.0.1":"會議室","e92/scene.gloss.1.1":"大螢幕","e92/lines.0.ko":"我把計畫書讀了三遍。老實說，這真是個很瘋狂的想法。","e92/lines.1.dir.ko":"緊張地","e92/lines.1.ko":"我知道。不過這也是個相當聰明的想法，對吧？","e92/lines.2.ko":"問題就在這裡。我的設計師當中，沒有一個人會想到這種點子。","e92/lines.3.ko":"Mr. Han，這裡的團隊也很興奮。紐約這邊可以交給 Daniel 負責。","e92/lines.4.ko":"我很樂意。我們當中有很多人才。","e92/lines.5.dir.ko":"沉默了好一會兒","e92/lines.5.ko":"……好吧。我輸了。我們來試試看。","e92/lines.6.ko":"真的嗎？您這麼輕易就答應了？","e92/lines.7.ko":"輕易？我跟自己搏鬥了三天！不過有個條件。第一個月，Jake 也要一起去首爾。","e92/lines.8.ko":"我？首爾？太興奮了！等等……Rosa 會殺了我的。","e92/lines.9.dir.ko":"笑著","e92/lines.9.ko":"謝謝您，Mr. Han。您真是個好老闆。","e92/quiz.0.why":"針對說來試試看，Mina 驚訝地反問。","e92/quiz.1.ko":"我們當中有很多人才。","e92/quiz.1.why":"是在多人混在一起的群體之中，所以是 among。","e92/quiz.2.ko":"老實說，這真是個很瘋狂的想法。","e92/quiz.2.why":"在 a + 形容詞 + 名詞前面，所以用 such。","e92/next":"星期六傍晚，屋頂。Jake 終於決定拿出戒指。","e93/title":"屋頂作戰","e93/prev":"Mr. Han 接受了 Mina 的計畫。第一個月 Jake 也會一起去首爾。","e93/scene.ko":"星期六下午四點三十分。Mina 住的大樓屋頂。到處擺著蠟燭和花。雖然天色陰陰的，景色依然很美。","e93/scene.gloss.0.1":"蠟燭","e93/scene.gloss.1.1":"陰天的","e93/lines.0.ko":"好。Rosa 每個星期六都五點起床。還剩三十分鐘。","e93/lines.1.ko":"三十分鐘？進度落後了！燈打不開。","e93/lines.2.ko":"就算有雲，夕陽還是會很美。別擔心。","e93/lines.3.dir.ko":"拿著蛋糕","e93/lines.3.ko":"蛋糕帶來了。雖然沒人要我帶。","e93/lines.4.dir.ko":"單膝跪下","e93/lines.4.ko":"我來練習一下。Rosa，妳願意和我……","e93/lines.5.ko":"Jake，起來！還沒啦！如果被 Rosa 看到怎麼辦？","e93/lines.6.ko":"我練習了整整一個星期，還是忘詞了。","e93/lines.7.ko":"就說出你心裡想的吧。這樣就夠了。","e93/lines.8.ko":"來了！大家躲到花盆後面！","e93/lines.9.dir.ko":"打開門","e93/lines.9.ko":"Jake？你為什麼傳訊息叫我上屋頂？還有，Leo 叔叔為什麼躲在那個花盆後面？","e93/quiz.0.why":"大家剛躲好，Rosa 就打開了屋頂的門。","e93/quiz.1.ko":"進度落後了！","e93/quiz.1.why":"落後於預定進度，所以是 behind schedule。","e93/quiz.2.ko":"就算有雲，夕陽還是會很美。","e93/quiz.2.why":"後面接名詞（the clouds），所以用 In spite of。","e93/next":"屋頂上的 Jake 和 Rosa。Rosa 的答覆會是什麼？","e94/title":"答覆","e94/prev":"Jake 在屋頂準備了求婚。大家躲在花盆後面，卻被 Rosa 發現了。","e94/scene.ko":"星期六下午五點十分。屋頂。雲散開了，太陽露出臉來。Jake 單膝跪著。","e94/scene.gloss.0.1":"單膝跪著","e94/scene.gloss.1.1":"雲散開","e94/lines.0.ko":"Rosa，我緊張得把要說的話都忘了。所以我就直接說吧。","e94/lines.1.ko":"妳讓我的每一天都變得更美好。妳願意嫁給我嗎？","e94/lines.2.dir.ko":"摀住嘴","e94/lines.2.ko":"Jake……我忍不住眼淚。我願意！好！","e94/lines.3.ko":"真的嗎？妳在哭耶。是因為我嗎？","e94/lines.4.ko":"當然是因為你啊，傻瓜！","e94/lines.5.dir.ko":"從花盆後面跳出來","e94/lines.5.ko":"恭喜！大家不要忍，盡情歡呼吧！","e94/lines.6.ko":"Rosa，我們大家都支持你們兩個。永遠都是。","e94/lines.7.ko":"謝謝。等等，你們大家都知道嗎？這是誰策劃的？","e94/lines.8.ko":"大家一起。不過大部分是 Jake。他帶著那枚戒指好幾個星期了。","e94/lines.9.dir.ko":"笑著","e94/lines.9.ko":"因為害怕，所以我一直等。可是要去首爾待一個月，我就再也等不下去了！","e94/quiz.0.why":"面對求婚，Rosa 忍不住流淚並答應了。","e94/quiz.1.ko":"Rosa，我們大家都支持你們兩個。","e94/quiz.1.why":"在背後支持著，所以是 behind。","e94/quiz.2.ko":"是因為我嗎？","e94/quiz.2.why":"在代名詞 me 前面，所以用 because of。","e94/next":"Leo 和 Noah，父親與兒子。Leo 說起了埋藏已久的往事。","e95/title":"超越那一步","e95/prev":"Rosa 接受了 Jake 的求婚。大家都為兩人道賀。","e95/scene.ko":"星期一夜晚。已打烊的 Leo 的咖啡店。Noah 又在用手機看烹飪課程的頁面。","e95/scene.gloss.0.1":"頁面","e95/scene.gloss.1.1":"又","e95/lines.0.ko":"那個頁面你至少看了一百遍了吧。直接報名啊。","e95/lines.1.ko":"我不能讓爸一個人在廚房撐三個月。","e95/lines.2.ko":"我在你這個年紀的時候，也對我爸說過一模一樣的話。","e95/lines.3.ko":"我爸過世前對我說過：「不要讓你的世界在前門就結束。」","e95/lines.4.ko":"爺爺說過這種話嗎？你從來沒告訴過我。","e95/lines.5.ko":"我拖到太晚才聽進去。我爸過世後，我就留在這裡，再也沒離開過。","e95/lines.6.ko":"去超越這間咖啡店吧，兒子。去看看布魯克林之外的世界。","e95/lines.7.ko":"那我在首爾的時候，誰來煮菜？","e95/lines.8.dir.ko":"微笑著","e95/lines.8.ko":"你爸我還很能幹呢。好了，趁我還沒改變心意，快去報名。","e95/lines.9.dir.ko":"按下按鈕","e95/lines.9.ko":"好啦。我報名了。首爾，等我！","e95/quiz.0.why":"針對誰來煮菜，Leo 說他還很能幹。","e95/quiz.1.ko":"去看看布魯克林之外的世界。","e95/quiz.1.why":"越過界線到更遠的地方，所以是 beyond。","e95/quiz.2.ko":"我在首爾的時候，誰來煮菜？","e95/quiz.2.why":"後面接句子的「在……的時候」是 while。","e95/next":"在辦公室規劃新團隊的日子。一通意外的電話打了進來。","e96/title":"第三個城市","e96/prev":"Leo 說起自己父親的故事，要 Noah 走出去看看世界。Noah 報名了首爾的烹飪課程。","e96/scene.ko":"星期二早上。辦公室。Dana 在白板上畫著計畫。上面寫著「Bridge 團隊」。","e96/scene.gloss.0.1":"白板","e96/scene.gloss.1.1":"畫","e96/lines.0.ko":"好。Mina 從九月到十一月，三個月都會待在首爾。","e96/lines.1.ko":"Mina 在首爾的期間，紐約這邊由 Daniel 負責。","e96/lines.2.ko":"然後在兩個城市的時間重疊的時段，每天都在線上碰面。","e96/lines.3.ko":"必須在預算之內完成。Mr. Han 講得很清楚。","e96/lines.4.ko":"當然。而且第一版設計必須在兩週內完成。","e96/lines.5.dir.ko":"跑進來","e96/lines.5.ko":"抱歉打斷一下，是 Ms. Hill 的電話！她聽說了 Bridge 團隊的事。","e96/lines.6.ko":"Jake，你總是挑剛剛好的時機打斷。她想要什麼？","e96/lines.7.ko":"她說下一個專案想讓芝加哥團隊也一起參與。","e96/lines.8.dir.ko":"笑著","e96/lines.8.ko":"首爾、紐約，現在又加上芝加哥。一個星期就變成三個城市了！","e96/lines.9.ko":"有三個端點的橋？看來我們需要更多咖啡了。","e96/quiz.0.why":"針對 Jake 的打斷，Dana 說他總是挑剛剛好的時機。","e96/quiz.1.ko":"第一版設計必須在兩週內完成。","e96/quiz.1.why":"在兩週這個範圍之內，所以是 within。","e96/quiz.2.ko":"我會在首爾待三個月。","e96/quiz.2.why":"在表示數字的期間前面，所以用 for。","e96/next":"八月的最後一個星期五。Mina 想安安靜靜地離開，可是……","e97/title":"歡送會","e97/prev":"Bridge 團隊的計畫擬定好了。Ms. Hill 的芝加哥團隊也加入了。","e97/scene.ko":"八月的最後一個星期五。Mina 走進 Leo 的咖啡店，想安靜地道別。突然燈亮了。驚喜！","e97/scene.gloss.0.1":"道別","e97/scene.gloss.1.1":"突然","e97/lines.0.ko":"妳真以為可以連派對都沒有，就這樣溜走嗎？","e97/lines.1.ko":"Rosa！大家！我本來想安靜地離開的。","e97/lines.2.ko":"想得美。哪有這麼容易就讓妳溜掉。我們要跳舞跳到午夜！","e97/lines.3.ko":"到午夜？我的班機是九點。我六點前就得到 JFK 了！","e97/lines.4.dir.ko":"穿著西裝","e97/lines.4.ko":"Kim 設計師，這是我十年來第一次不穿制服來。","e97/lines.5.ko":"您好帥！謝謝您來。","e97/lines.6.ko":"Mina，沒有妳，這間咖啡店就不一樣了。沒有 Noah 也是。","e97/lines.7.ko":"還有別擔心 Kimchi。它會跟我們待到十二月。","e97/lines.8.dir.ko":"努力忍住不哭","e97/lines.8.ko":"謝謝大家。不久前，我在這座城市還一個人都不認識。","e97/lines.9.ko":"現在妳全都認識了。連警衛大哥的名字都知道。來，跳舞吧！","e97/quiz.0.why":"面對驚喜派對，Mina 驚訝地說她本來想安靜地離開。","e97/quiz.1.ko":"沒有妳，這間咖啡店就不一樣了。","e97/quiz.1.why":"「沒有」是 without。","e97/quiz.2.ko":"我六點前就得到 JFK 了！","e97/quiz.2.why":"是最晚六點前的期限，所以用 by。","e97/next":"九月一日早晨，JFK 機場。飛往首爾的班機正等著。","e98/title":"出發","e98/prev":"咖啡店的大家為 Mina 辦了驚喜歡送會。Kimchi 到十二月前由 Rosa 和 Jake 照顧。","e98/scene.ko":"九月一日上午六點。JFK 機場。Mina、Noah 和 Jake 拿著大行李箱。Leo 和 Rosa 來送行。","e98/scene.gloss.0.1":"送行","e98/scene.gloss.1.1":"行李箱","e98/lines.0.ko":"飛機是九點吧？進安檢之前，我們去喝杯咖啡。","e98/lines.1.ko":"爸，首爾也有咖啡啦。","e98/lines.2.ko":"那又不像我的咖啡。別為了喝首爾的咖啡就背叛我的咖啡！","e98/lines.3.dir.ko":"擁抱父親","e98/lines.3.ko":"我絕對不會背叛的，爸。","e98/lines.4.ko":"Jake，每天早上上班前和每天晚上下班後都要打電話給我。","e98/lines.5.ko":"只有一個月而已，Rosa。我十月一日就回來。","e98/lines.6.ko":"我知道。還有，婚禮是在春天，所以不要愛上首爾喔！","e98/lines.7.ko":"Leo、Rosa……謝謝你們。十二月見。","e98/lines.8.ko":"還有 Mina，我兒子就麻煩妳多照顧了。沒有我，他什麼都找不到。","e98/lines.9.ko":"爸！……嗯，這倒是事實。走吧。首爾在等我們！","e98/quiz.0.why":"針對別背叛我的咖啡，Noah 說絕對不會。","e98/quiz.1.ko":"每天晚上下班後都要打電話給我。","e98/quiz.1.why":"是工作結束之後，所以是 after。","e98/quiz.2.ko":"我十月一日就回來。","e98/quiz.2.why":"日期要用 on。","e98/next":"在首爾辦公室舉行的 Bridge 團隊第一次會議。有位受歡迎的客人來了。","e99/title":"第一次會議","e99/prev":"Mina、Noah 和 Jake 出發前往首爾。Leo 和 Rosa 到機場送行。","e99/scene.ko":"星期三上午八點。首爾辦公室十二樓。新的 Bridge 團隊第一次齊聚會議室。","e99/scene.gloss.0.1":"樓層","e99/scene.gloss.1.1":"第一次","e99/lines.0.ko":"大家早安！Jake，可以幫我開大螢幕嗎？紐約團隊要連線進來了。","e99/lines.1.ko":"好的。……嗨，紐約！看得到我們嗎？","e99/lines.2.dir.ko":"在螢幕裡","e99/lines.2.ko":"看得很清楚！我們都在辦公室。這裡是晚上七點。","e99/lines.3.dir.ko":"在螢幕裡","e99/lines.3.ko":"而且 Ms. Hill 在芝加哥。她會一起連線進來。","e99/lines.4.dir.ko":"在螢幕裡","e99/lines.4.ko":"晚安……不對，早安！Mina，請開一下鏡頭。我看不到妳的臉。","e99/lines.5.ko":"抱歉！好了。那麼，第一件事——","e99/lines.6.dir.ko":"在門口","e99/lines.6.ko":"打擾了！我走錯兩次房間了。這裡是 Bridge 團隊嗎？我帶了紫菜飯捲來！","e99/lines.7.dir.ko":"猛然站起來","e99/lines.7.ko":"是紫菜飯捲！阿姨，您最棒了！啊，糟了。我把咖啡灑到襯衫上了。","e99/lines.8.dir.ko":"在螢幕裡","e99/lines.8.ko":"Jake 還是老樣子。Mina，我看妳帶著首爾最棒的團隊呢。","e99/lines.9.dir.ko":"笑著","e99/lines.9.ko":"是啊。媽，請進來。現在媽媽也是團隊的一員了。","e99/quiz.0.why":"面對請她開螢幕的要求，他回答說好的。","e99/quiz.1.ko":"我把咖啡灑到襯衫上了。","e99/quiz.1.why":"是灑落到襯衫表面上的動作，所以用 onto。","e99/quiz.2.ko":"我們都在辦公室。","e99/quiz.2.why":"公司是一個點，所以用 at。","e99/next":"最後一集。在漢江的橋上，Mina 和 Noah 回顧走過的日子。","e100/title":"在橋上","e100/prev":"Bridge 團隊的第一次會議召開了。首爾、紐約和芝加哥透過螢幕連在一起，媽媽帶著紫菜飯捲來了。","e100/scene.ko":"星期六夜晚。Mina 和 Noah 正走過漢江上的橋。城市的燈光在水面上閃爍。","e100/scene.gloss.0.1":"漢江","e100/scene.gloss.1.1":"閃耀","e100/lines.0.ko":"夜晚的首爾好像紐約。","e100/lines.1.ko":"還記得我們走過布魯克林大橋的那次散步嗎？感覺就像昨天。","e100/lines.2.ko":"那你在紐約的第一天呢？你跟我說過。下雨、兩個大行李箱……","e100/lines.3.ko":"而且一個朋友也沒有。現在我有兩個家了。今年感覺像活了兩次人生。","e100/lines.4.ko":"我們撐過了很多事。你的壓力、我的恐懼、咖啡店裡的那場爭吵……","e100/lines.5.ko":"而且就像你在雨中說的，我們找到了辦法。","e100/lines.6.dir.ko":"在橋中央停下腳步","e100/lines.6.ko":"你知道嗎？你就像這座橋。你把一切連在一起。","e100/lines.7.ko":"那你就是河。總是流動著，卻總是在我身邊。","e100/lines.8.dir.ko":"笑著","e100/lines.8.ko":"這也太肉麻了吧。","e100/lines.9.ko":"我知道。不過不管接下來發生什麼事，我們都會撐過去的。一起。","e100/quiz.0.why":"針對說她像橋，Mina 回答說 Noah 像河。","e100/quiz.1.ko":"Mina 和 Noah 正走過橋。","e100/quiz.1.why":"橫越橋面走過去，所以是 across。","e100/quiz.2.ko":"今年感覺像活了兩次人生。","e100/quiz.2.why":"「彷彿……一樣」+ 句子，是 as if。","e100/next":"Mina 的故事就到這裡。謝謝你陪伴這 100 天！"}`;export{e as default};